    fn lowerGeneratedTagEncoderInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        shape_type: Plan.CheckedTypeIdentity,
        value_type: Plan.CheckedTypeIdentity,
        value: LIR.LocalId,
        state: LIR.LocalId,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const variants = try self.generatedEncoderTagVariants(proc, shape_type, false);
        defer self.allocator.free(variants);
        const bodies = try self.allocator.alloc(LIR.CFStmtId, variants.len);
        defer self.allocator.free(bodies);
        for (variants, bodies) |variant, *body| {
            const payloads = self.plan.childSlice(variant.variant.payloads);
            body.* = if (payloads.len == 0)
                try self.lowerGeneratedUnitTagEncoderInto(proc, source, variant, state, target, next)
            else
                try self.lowerGeneratedPayloadTagEncoderInto(
                    proc,
                    source,
                    shape_type,
                    value_type,
                    value,
                    variant,
                    state,
                    target,
                    next,
                );
        }
        return try self.lowerGeneratedEncoderTagDispatch(proc, value, variants, bodies);
    }

    fn lowerGeneratedUnitTagEncoderInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        variant: GeneratedParserTagVariant,
        state: LIR.LocalId,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const caller = proc.worker_layout.worker;
        const encoding_type = source.capture_type orelse
            boxyLowerInvariant("generated unit-tag encoder had no encoding type");
        const call = proc.generatedCodecCallPlanForMethod(caller, encoding_type, "encode_str");
        const tag_name = try proc.addFrameLocal(.str);
        const continuation = try self.lowerGeneratedCodecCallLocalsInto(
            proc,
            call,
            target,
            &.{ tag_name, state },
            next,
        );
        return try proc.assignStringBytesLiteral(tag_name, proc.tagVariantNameText(variant.variant), continuation);
    }

    fn lowerGeneratedPayloadTagEncoderInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        shape_type: Plan.CheckedTypeIdentity,
        value_type: Plan.CheckedTypeIdentity,
        value: LIR.LocalId,
        _: GeneratedParserTagVariant,
        state: LIR.LocalId,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const caller = proc.worker_layout.worker;
        const contract_worker = source.contract_worker orelse caller;
        const encoding_type = source.capture_type orelse
            boxyLowerInvariant("generated payload-tag encoder had no encoding type");
        const call = proc.generatedCodecCallPlan(caller, encoding_type, "encode_record", null);
        const arg_types = self.plan.generatedCodecCallTypeSlice(call.arg_types);
        if (arg_types.len != 3) boxyLowerInvariant("generated tag encode_record call did not have three arguments");
        const callback_source = Plan.GeneratedCodecSource{
            .kind = .encoder_tag_field,
            .shape = shape_type,
            .value_type = value_type,
            .capture_type = encoding_type,
            .contract_worker = contract_worker,
            .contract_expr = source.contract_expr,
        };
        const callback_worker = self.plan.workerForSourceType(
            .{ .generated_codec = callback_source },
            arg_types[2],
        ) orelse boxyLowerInvariant("generated tag encoder had no planned field callback");
        const callback = try proc.addFrameLocalForRep(proc.repForTypeRef(arg_types[2]));
        const count = try proc.addFrameLocal(.u64);
        const name_captures = self.generatedEncoderNameCaptureLocals(proc, contract_worker);
        const capture_values = try self.allocator.alloc(LIR.LocalId, 2 + name_captures.len);
        defer self.allocator.free(capture_values);
        capture_values[0] = proc.erased_capture_locals.items[0];
        capture_values[1] = value;
        @memcpy(capture_values[2..], name_captures);

        var continuation = try self.lowerGeneratedCodecCallLocalsInto(
            proc,
            call,
            target,
            &.{ state, count, callback },
            next,
        );
        continuation = try self.packGeneratedCodecCallable(
            proc,
            callback,
            proc.repForTypeRef(arg_types[2]),
            callback_worker,
            capture_values,
            continuation,
        );
        return try proc.assignIntLiteral(count, 1, continuation);
    }

    fn generatedEncoderTagVariants(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        shape_type: Plan.CheckedTypeIdentity,
        payload_only: bool,
    ) Allocator.Error![]GeneratedParserTagVariant {
        const tag_rep = proc.tagVariantRepForBoundary(proc.repForTypeRef(shape_type)) orelse
            boxyLowerInvariant("generated tag encoder shape had no closed tag representation");
        const rep = self.plan.representations.items[@intFromEnum(tag_rep)];
        if (rep.kind != .tag_union) {
            boxyLowerInvariant("generated structural tag encoder required a concrete tag representation");
        }
        for (self.plan.childSlice(rep.children)) |child| {
            if (child.role == .tag_ext) {
                var extension = child.rep;
                var depth: u16 = 0;
                while (true) {
                    if (depth == 1024) boxyLowerInvariant("generated tag encoder extension wrapper chain exceeded limit");
                    depth += 1;
                    const extension_rep = self.plan.representations.items[@intFromEnum(extension)];
                    if (extension_rep.kind == .alias) {
                        extension = proc.repQuery().requiredSingleChild(extension, .alias_backing).rep;
                    } else if (extension_rep.kind == .nominal) {
                        extension = proc.repQuery().requiredSingleChild(extension, .nominal_backing).rep;
                    } else if (extension_rep.kind == .empty_tag_union) {
                        break;
                    } else {
                        boxyLowerInvariant("generated tag encoder required a flattened closed tag row");
                    }
                }
            }
        }
        const planned = self.plan.tagVariantSlice(rep.tag_variants);
        var count: usize = 0;
        for (planned) |variant| {
            if (!payload_only or self.plan.childSlice(variant.payloads).len != 0) count += 1;
        }
        if (count == 0) boxyLowerInvariant("generated tag encoder dispatch had no applicable variants");
        const variants = try self.allocator.alloc(GeneratedParserTagVariant, count);
        var out_index: usize = 0;
        for (planned, 0..) |variant, index| {
            if (payload_only and self.plan.childSlice(variant.payloads).len == 0) continue;
            if (index > std.math.maxInt(u16)) boxyLowerInvariant("generated tag encoder variant index exceeded LIR range");
            variants[out_index] = .{
                .tag_rep = tag_rep,
                .owner_rep = tag_rep,
                .index = @intCast(index),
                .variant = variant,
            };
            out_index += 1;
        }
        return variants;
    }

    fn lowerGeneratedEncoderTagDispatch(
        _: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: LIR.LocalId,
        variants: []const GeneratedParserTagVariant,
        bodies: []const LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (variants.len != bodies.len or variants.len == 0) {
            boxyLowerInvariant("generated tag encoder dispatch metadata was invalid");
        }
        if (variants.len == 1) return bodies[0];
        return try proc.generatedParserTagDispatch(
            source,
            variants[0].tag_rep,
            variants[0 .. variants.len - 1],
            bodies[0 .. bodies.len - 1],
            bodies[bodies.len - 1],
        );
    }

    fn generatedEncoderNameCaptureLocals(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        contract_worker: Plan.WorkerPlanId,
    ) []const LIR.LocalId {
        var count: usize = 0;
        for (self.plan.generated_parser_field_captures.items) |capture| {
            if (capture.worker == contract_worker) count += 1;
        }
        const worker = self.plan.workers.items[@intFromEnum(proc.worker_layout.worker)];
        var captured_value_count: usize = 0;
        for (self.plan.erasedCaptureSlice(worker.erased_captures)) |capture| {
            if (capture.kind == .captured_value) captured_value_count += 1;
        }
        if (captured_value_count < count or proc.erased_capture_locals.items.len < captured_value_count) {
            boxyLowerInvariant("generated encoder field-name captures exceeded bound captures");
        }
        return proc.erased_capture_locals.items[captured_value_count - count .. captured_value_count];
    }

    fn generatedEncoderRecordFields(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        contract_worker: Plan.WorkerPlanId,
        shape_type: Plan.CheckedTypeIdentity,
    ) Allocator.Error![]GeneratedEncoderRecordField {
        const shape_rep = proc.repForTypeRef(shape_type);
        const record_rep_id = proc.recordRepForBoundary(shape_rep);
        if (record_rep_id == null) {
            if (self.plan.representations.items[@intFromEnum(shape_rep)].kind != .empty_record) {
                boxyLowerInvariant("generated encoder record shape had no record representation");
            }
            return try self.allocator.alloc(GeneratedEncoderRecordField, 0);
        }
        const record = self.plan.representations.items[@intFromEnum(record_rep_id.?)];
        const children = self.plan.childSlice(record.children);
        var field_count: usize = 0;
        for (children) |child| {
            if (child.role == .record_field) {
                field_count += 1;
            } else if (child.role == .record_ext) {
                proc.requireEmptyRecordExtension(child.rep);
            } else {
                boxyLowerInvariant("generated encoder record representation had a non-record child");
            }
        }
        const fields = try self.allocator.alloc(GeneratedEncoderRecordField, field_count);
        const record_view = procedureModuleById(self.modules, record.source_type.module);
        const name_captures = self.generatedEncoderNameCaptureLocals(proc, contract_worker);

        var out_index: usize = 0;
        for (children) |child| {
            if (child.role == .record_ext) continue;
            if (child.role != .record_field) unreachable;
            const label = child.role.record_field;
            var capture_index: usize = 0;
            var renamed: ?LIR.LocalId = null;
            var field_capture: ?Plan.GeneratedParserFieldCapture = null;
            for (self.plan.generated_parser_field_captures.items) |capture| {
                if (capture.worker != contract_worker) continue;
                if (capture_index >= name_captures.len) {
                    boxyLowerInvariant("generated encoder field capture exceeded bound names");
                }
                const capture_view = procedureModuleById(self.modules, capture.field_module);
                if (planTypeRefEql(capture.record_type, shape_type) and
                    Plan.recordFieldNameMatches(viewNames(record_view), label, viewNames(capture_view), capture.field_name))
                {
                    if (renamed != null) boxyLowerInvariant("generated encoder record field had duplicate renamed captures");
                    renamed = name_captures[capture_index];
                    field_capture = capture;
                }
                capture_index += 1;
            }
            const capture = field_capture orelse
                boxyLowerInvariant("generated encoder record field had no checked capture metadata");
            fields[out_index] = .{
                .source_type = child.source_type,
                .encode_type = capture.parse_type,
                .rep = child.rep,
                .renamed = renamed orelse boxyLowerInvariant("generated encoder record field had no renamed capture"),
                .index = out_index,
                .optional_error_type = capture.optional_error_type,
                .optional_missing = capture.optional_missing,
                .optional_null = capture.optional_null,
            };
            out_index += 1;
        }
        return fields;
    }

    fn packGeneratedCodecCallable(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        worker_id: Plan.WorkerPlanId,
        capture_values: []const LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const worker = self.plan.workers.items[@intFromEnum(worker_id)];
        const captures = self.plan.erasedCaptureSlice(worker.erased_captures);
        const all_capture_values = try self.generatedCodecCaptureValues(proc, captures, capture_values);
        defer self.allocator.free(all_capture_values);
        const function = proc.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("generated codec callback worker was not callable");
        const worker_layout = self.layout_plan.workerLayoutFor(worker_id);
        const erased_proc = try self.emitErasedWorker(worker_id);
        const boundary = try self.generatedCallablePackBoundary(proc, target, target_rep, function, next);
        const result_desc = try proc.exactCallResultDescriptorRef(function.ret);
        const entry = try proc.packGeneratedErasedCallable(
            boundary.target,
            erased_proc,
            function.rep,
            function.ret,
            result_desc,
            captures,
            all_capture_values,
            worker_layout.erased_capture_layout,
            boundary.next,
        );
        try self.finishGeneratedCallablePackBoundary(proc, boundary);
        return entry;
    }

    const GeneratedCallableAdapterBoundary = struct {
        target: LIR.LocalId,
        target_function: ProcBodyBuilder.FunctionChildren,
        source_function: ProcBodyBuilder.FunctionChildren,
        next: LIR.CFStmtId,
        placeholder: LIR.CFStmtId,
    };

    const GeneratedCallablePackBoundary = struct {
        target: LIR.LocalId,
        next: LIR.CFStmtId,
        adapter: ?GeneratedCallableAdapterBoundary,
    };

    fn generatedCallablePackBoundary(
        _: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_function: ProcBodyBuilder.FunctionChildren,
        next: LIR.CFStmtId,
    ) Allocator.Error!GeneratedCallablePackBoundary {
        const target_function = proc.functionChildrenForRep(target_rep) orelse
            boxyLowerInvariant("generated callable target representation was not callable");
        const needs_adapter = try proc.callableBoundaryNeedsAdapter(target_function, source_function);
        if (!needs_adapter) {
            return .{ .target = target, .next = next, .adapter = null };
        }

        const raw_target = try proc.addFrameLocalForRep(source_function.rep);
        const placeholder = try proc.parent.result.store.addCFStmt(.runtime_error);
        return .{
            .target = raw_target,
            .next = placeholder,
            .adapter = .{
                .target = target,
                .target_function = target_function,
                .source_function = source_function,
                .next = next,
                .placeholder = placeholder,
            },
        };
    }

    fn finishGeneratedCallablePackBoundary(
        _: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        boundary: GeneratedCallablePackBoundary,
    ) Allocator.Error!void {
        const adapter = boundary.adapter orelse return;
        const adapted = try proc.assignErasedCallableBoundary(
            adapter.target,
            boundary.target,
            adapter.target_function,
            adapter.source_function,
            adapter.next,
        );
        proc.parent.result.store.getCFStmtPtr(adapter.placeholder).* = proc.parent.result.store.getCFStmt(adapted);
    }

    fn generatedCodecCaptureValues(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        captures: []const Plan.ErasedCapture,
        captured_values: []const LIR.LocalId,
    ) Allocator.Error![]LIR.LocalId {
        const values = try self.allocator.alloc(LIR.LocalId, captures.len);
        errdefer self.allocator.free(values);

        var value_index: usize = 0;
        for (captures, values) |capture, *value| {
            switch (capture.kind) {
                .captured_value => {
                    if (value_index >= captured_values.len) {
                        boxyLowerInvariant("generated codec callable had fewer value captures than its worker");
                    }
                    value.* = captured_values[value_index];
                    value_index += 1;
                    if (self.result.store.getLocal(value.*).layout_idx != proc.workerRuntimeLayoutForRep(capture.rep).layoutIdx()) {
                        boxyLowerInvariant("generated codec callable value capture layout disagreed with its worker");
                    }
                },
                .hidden_desc => {
                    const desc = capture.desc orelse
                        boxyLowerInvariant("generated codec callable descriptor capture had no requirement");
                    value.* = proc.descriptorLocalForRequirementAndRepOrNull(desc, capture.rep) orelse
                        boxyLowerInvariant("generated codec callable descriptor capture had no bound input");
                },
                .hidden_dict => boxyLowerInvariant("generated codec callable unexpectedly required a dictionary capture"),
            }
        }
        if (value_index != captured_values.len) {
            boxyLowerInvariant("generated codec callable had more value captures than its worker");
        }
        return values;
    }

    fn lowerGeneratedEncoderRecordFieldsInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const worker = self.plan.workers.items[@intFromEnum(proc.worker_layout.worker)];
        const function = proc.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("generated encoder record callback was not callable");
        if (function.arg_count != 2 or proc.arg_locals.items.len < 2 or proc.erased_capture_locals.items.len < 2) {
            boxyLowerInvariant("generated encoder record callback had invalid arguments or captures");
        }
        const children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(function.rep)].children);
        const args = children[function.args_start..][0..function.arg_count];
        const contract_worker = source.contract_worker orelse
            boxyLowerInvariant("generated encoder record callback had no contract worker");
        const fields = try self.generatedEncoderRecordFields(proc, contract_worker, source.shape);
        defer self.allocator.free(fields);
        return try self.lowerGeneratedEncoderRecordFieldsFrom(
            proc,
            source,
            fields,
            0,
            proc.erased_capture_locals.items[1],
            proc.arg_locals.items[0],
            args[0].rep,
            proc.arg_locals.items[1],
            args[1].rep,
            function.ret,
            target,
            next,
        );
    }

    fn lowerGeneratedEncoderRecordFieldsFrom(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        fields: []const GeneratedEncoderRecordField,
        field_index: usize,
        record_value: LIR.LocalId,
        state: LIR.LocalId,
        state_rep: Plan.TypeRepId,
        field_writer: LIR.LocalId,
        field_writer_rep: Plan.TypeRepId,
        target_rep: Plan.TypeRepId,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (field_index == fields.len) {
            const ok = proc.generatedParserTagVariant(target_rep, "Ok");
            const payloads = self.plan.childSlice(ok.variant.payloads);
            if (payloads.len != 1) boxyLowerInvariant("generated encoder Ok did not have one state payload");
            return try proc.assignGeneratedParserTag(target, target_rep, ok, state, payloads[0].rep, next);
        }

        const field = fields[field_index];
        const writer_fn = proc.functionChildrenForRep(field_writer_rep) orelse
            boxyLowerInvariant("generated encoder field writer was not callable");
        const writer_children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(writer_fn.rep)].children);
        const writer_args = writer_children[writer_fn.args_start..][0..writer_fn.arg_count];
        if (writer_args.len != 3) boxyLowerInvariant("generated encoder field writer had an unexpected arity");
        const thunk_type = writer_args[2].source_type;
        const contract_worker = source.contract_worker orelse
            boxyLowerInvariant("generated encoder record callback had no contract worker");
        const thunk_source = Plan.GeneratedCodecSource{
            .kind = .encoder_value_thunk,
            .shape = field.encode_type,
            .value_type = if (field.optional_error_type != null) field.source_type else null,
            .optional_missing = field.optional_missing,
            .optional_null = field.optional_null,
            .capture_type = source.capture_type,
            .contract_worker = contract_worker,
            .contract_expr = source.contract_expr,
        };
        const thunk_worker = self.plan.workerForSourceType(.{ .generated_codec = thunk_source }, thunk_type) orelse
            boxyLowerInvariant("generated encoder field had no planned value thunk");
        const field_value = try proc.addFrameLocalForRep(field.rep);
        const thunk_rep = proc.repForTypeRef(thunk_type);
        const thunk = try proc.addFrameLocalForRep(thunk_rep);
        const result = try proc.addFrameLocalForRepWithRequiredFreshDescriptor(target_rep);
        const ok = proc.generatedParserTagVariant(target_rep, "Ok");
        const ok_payload = try proc.generatedParserSingleTagPayloadLocal(ok);

        var success = try self.lowerGeneratedEncoderRecordFieldsFrom(
            proc,
            source,
            fields,
            field_index + 1,
            record_value,
            ok_payload.local,
            ok_payload.child.rep,
            field_writer,
            field_writer_rep,
            target_rep,
            target,
            next,
        );
        success = try proc.generatedParserReadTagPayload(result, ok, ok_payload, success);
        const err = try proc.assignRepresentationBoundary(target, result, target_rep, target_rep, next);
        const variants = [_]GeneratedParserTagVariant{ok};
        const bodies = [_]LIR.CFStmtId{success};
        var continuation = try proc.generatedParserTagDispatch(result, target_rep, &variants, &bodies, err);
        continuation = try proc.lowerErasedCallLocalsInto(
            result,
            target_rep,
            field_writer_rep,
            field_writer,
            &.{ state, field.renamed, thunk },
            &.{ state_rep, writer_args[1].rep, thunk_rep },
            continuation,
        );

        const name_captures = self.generatedEncoderNameCaptureLocals(proc, contract_worker);
        const capture_values = try self.allocator.alloc(LIR.LocalId, 2 + name_captures.len);
        defer self.allocator.free(capture_values);
        capture_values[0] = proc.erased_capture_locals.items[0];
        capture_values[1] = field_value;
        @memcpy(capture_values[2..], name_captures);
        continuation = try self.packGeneratedCodecCallable(proc, thunk, thunk_rep, thunk_worker, capture_values, continuation);
        if (field.optional_missing) {
            const skipped = try self.lowerGeneratedEncoderRecordFieldsFrom(
                proc,
                source,
                fields,
                field_index + 1,
                record_value,
                state,
                state_rep,
                field_writer,
                field_writer_rep,
                target_rep,
                target,
                next,
            );
            const field_ok = proc.generatedParserTagVariant(field.rep, "Ok");
            const field_err = proc.generatedParserTagVariant(field.rep, "Err");
            const err_payload = try proc.generatedParserSingleTagPayloadLocal(field_err);
            const missing = proc.generatedParserTagVariant(err_payload.child.rep, "Missing");
            const err_dispatch = if (field.optional_null) blk: {
                const null_variant = proc.generatedParserTagVariant(err_payload.child.rep, "Null");
                const error_variants = [_]GeneratedParserTagVariant{ missing, null_variant };
                const error_bodies = [_]LIR.CFStmtId{ skipped, continuation };
                const impossible = try self.result.store.addCFStmt(.runtime_error);
                break :blk try proc.generatedParserTagDispatch(
                    err_payload.local,
                    err_payload.child.rep,
                    &error_variants,
                    &error_bodies,
                    impossible,
                );
            } else skipped;
            const err_body = try proc.generatedParserReadTagPayload(field_value, field_err, err_payload, err_dispatch);
            const optional_variants = [_]GeneratedParserTagVariant{ field_ok, field_err };
            const optional_bodies = [_]LIR.CFStmtId{ continuation, err_body };
            const impossible = try self.result.store.addCFStmt(.runtime_error);
            continuation = try proc.generatedParserTagDispatch(
                field_value,
                field.rep,
                &optional_variants,
                &optional_bodies,
                impossible,
            );
        }
        return try self.result.store.addCFStmt(.{ .assign_ref = .{
            .target = field_value,
            .op = .{ .field = .{ .source = record_value, .field_idx = @intCast(field.index) } },
            .next = continuation,
        } });
    }

    fn lowerGeneratedEncoderSequenceElementsInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const worker = self.plan.workers.items[@intFromEnum(proc.worker_layout.worker)];
        const function = proc.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("generated encoder sequence callback was not callable");
        if (function.arg_count != 2 or proc.arg_locals.items.len < 2 or proc.erased_capture_locals.items.len < 2) {
            boxyLowerInvariant("generated encoder sequence callback had invalid arguments or captures");
        }
        const children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(function.rep)].children);
        const args = children[function.args_start..][0..function.arg_count];
        const shape_rep = proc.repForTypeRef(source.shape);
        if (proc.listRepForBoundary(shape_rep)) |list_rep| {
            return try self.lowerGeneratedEncoderListElementsInto(
                proc,
                source,
                list_rep,
                proc.erased_capture_locals.items[1],
                proc.arg_locals.items[0],
                args[0].rep,
                proc.arg_locals.items[1],
                args[1].rep,
                function.ret,
                target,
                next,
            );
        }
        const items = try self.generatedParserTupleItems(proc, shape_rep);
        defer self.allocator.free(items);
        return try self.lowerGeneratedEncoderSequenceElementsFrom(
            proc,
            source,
            items,
            0,
            proc.erased_capture_locals.items[1],
            proc.arg_locals.items[0],
            args[0].rep,
            proc.arg_locals.items[1],
            args[1].rep,
            function.ret,
            target,
            next,
        );
    }

    fn lowerGeneratedEncoderSequenceElementsFrom(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        items: []const GeneratedParserTupleItem,
        item_index: usize,
        sequence_value: LIR.LocalId,
        state: LIR.LocalId,
        state_rep: Plan.TypeRepId,
        element_writer: LIR.LocalId,
        element_writer_rep: Plan.TypeRepId,
        target_rep: Plan.TypeRepId,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (item_index == items.len) {
            const ok = proc.generatedParserTagVariant(target_rep, "Ok");
            const payloads = self.plan.childSlice(ok.variant.payloads);
            if (payloads.len != 1) boxyLowerInvariant("generated sequence encoder Ok did not have one state payload");
            return try proc.assignGeneratedParserTag(target, target_rep, ok, state, payloads[0].rep, next);
        }

        const writer_fn = proc.functionChildrenForRep(element_writer_rep) orelse
            boxyLowerInvariant("generated encoder element writer was not callable");
        const writer_children = self.plan.childSlice(self.plan.representations.items[@intFromEnum(writer_fn.rep)].children);
        const writer_args = writer_children[writer_fn.args_start..][0..writer_fn.arg_count];
        if (writer_args.len != 2) boxyLowerInvariant("generated encoder element writer had an unexpected arity");
        const thunk_type = writer_args[1].source_type;
        const contract_worker = source.contract_worker orelse
            boxyLowerInvariant("generated encoder sequence callback had no contract worker");
        const item = items[item_index];
        const thunk_source = Plan.GeneratedCodecSource{
            .kind = .encoder_value_thunk,
            .shape = item.source_type,
            .capture_type = source.capture_type,
            .contract_worker = contract_worker,
            .contract_expr = source.contract_expr,
        };
        const thunk_worker = self.plan.workerForSourceType(.{ .generated_codec = thunk_source }, thunk_type) orelse
            boxyLowerInvariant("generated encoder element had no planned value thunk");
        const item_value = try proc.addFrameLocalForRep(item.rep);
        const thunk_rep = proc.repForTypeRef(thunk_type);
        const thunk = try proc.addFrameLocalForRep(thunk_rep);
        const result = try proc.addFrameLocalForRepWithRequiredFreshDescriptor(target_rep);
        const ok = proc.generatedParserTagVariant(target_rep, "Ok");
        const ok_payload = try proc.generatedParserSingleTagPayloadLocal(ok);

        var success = try self.lowerGeneratedEncoderSequenceElementsFrom(
            proc,
            source,
            items,
            item_index + 1,
            sequence_value,
            ok_payload.local,
            ok_payload.child.rep,
            element_writer,
            element_writer_rep,
            target_rep,
            target,
            next,
        );
        success = try proc.generatedParserReadTagPayload(result, ok, ok_payload, success);
        const err = try proc.assignRepresentationBoundary(target, result, target_rep, target_rep, next);
        const variants = [_]GeneratedParserTagVariant{ok};
        const bodies = [_]LIR.CFStmtId{success};
        var continuation = try proc.generatedParserTagDispatch(result, target_rep, &variants, &bodies, err);
        continuation = try proc.lowerErasedCallLocalsInto(
            result,
            target_rep,
            element_writer_rep,
            element_writer,
            &.{ state, thunk },
            &.{ state_rep, thunk_rep },
            continuation,
        );

        const name_captures = self.generatedEncoderNameCaptureLocals(proc, contract_worker);
        const capture_values = try self.allocator.alloc(LIR.LocalId, 2 + name_captures.len);
        defer self.allocator.free(capture_values);
        capture_values[0] = proc.erased_capture_locals.items[0];
        capture_values[1] = item_value;
        @memcpy(capture_values[2..], name_captures);
        continuation = try self.packGeneratedCodecCallable(proc, thunk, thunk_rep, thunk_worker, capture_values, continuation);
        if (item_index > std.math.maxInt(u16)) {
            boxyLowerInvariant("generated encoder tuple element index exceeded LIR range");
        }
        return try proc.lowerTupleFieldReadInto(
            item_value,
            sequence_value,
            proc.repForTypeRef(source.shape),
            @intCast(item_index),
            continuation,
        );
    }

    fn lowerGeneratedEncoderListElementsInto(
        self: *ProcedureBuilder,
        proc: *ProcBodyBuilder,
        source: Plan.GeneratedCodecSource,
        list_rep: Plan.TypeRepId,
        list_value: LIR.LocalId,
        initial_state: LIR.LocalId,
        state_rep: Plan.TypeRepId,
        element_writer: LIR.LocalId,
