        const len = try proc.addFrameLocal(.u64);
        const index = try proc.addFrameLocal(.u64);
        const state = try proc.addFrameLocal(self.result.store.getLocal(initial_state).layout_idx);
        const zero = try proc.addFrameLocal(.u64);
        const join_id = proc.freshJoinPointId();
        const body = try self.lowerGeneratedEncoderListLoop(
            proc,
            source,
            elem,
            list_value,
            len,
            index,
            state,
            state_rep,
            element_writer,
            element_writer_rep,
            target_rep,
            target,
            join_id,
            next,
        );
        var initial = try self.result.store.addCFStmt(.{ .jump = .{ .target = join_id } });
        initial = try proc.setLocalInitializeJoinParamFromRep(state, initial_state, state_rep, initial);
        initial = try proc.setLocalInitializeJoinParam(index, zero, initial);
        initial = try proc.assignIntLiteral(zero, 0, initial);
        initial = try proc.assignUnaryLowLevel(len, .list_len, list_value, initial);
        return try self.result.store.addCFStmt(.{ .join = .{
            .id = join_id,
            .params = try proc.joinParamSpan(&.{ index, state }),
            .body = body,
            .remainder = initial,
        } });
