                dispatcher_rep_id,
                params.items,
                .worker_hidden_params,
                &owner_descriptor_sources,
                &seen,
            );
        }

        var pending = std.ArrayList(Plan.DirectCallHiddenDescriptorArg).empty;
        errdefer pending.deinit(self.parent.allocator);
        var seen_reps = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen_reps.deinit();
        var seen_descriptor_reps = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen_descriptor_reps.deinit();
        var next_param: usize = 0;

        const method_children = self.parent.plan.childSlice(self.parent.plan.representations.items[@intFromEnum(method_function.rep)].children);
        const method_args = method_children[method_function.args_start..][0..method_function.arg_count];
        for (method_args, arg_types, operand_arg_reps, 0..) |method_arg, arg_type, operand_arg_rep, arg_index| {
            const call_arg_rep = self.repForTypeRef(arg_type);
            try self.collectDictionaryCallHiddenDescriptorArgs(
                method_arg.rep,
                call_arg_rep,
                operand_arg_rep,
                @intCast(arg_index),
                params.items,
                &next_param,
                &pending,
                &seen_reps,
                &seen_descriptor_reps,
            );
        }
        const ret_rep = self.repForTypeRef(ret_type);
        try self.collectDictionaryCallHiddenDescriptorArgs(
            method_function.ret,
            ret_rep,
            ret_rep,
            null,
            params.items,
            &next_param,
            &pending,
            &seen_reps,
            &seen_descriptor_reps,
        );

        if (next_param != params.items.len or pending.items.len != params.items.len) {
            boxyLowerInvariant("boxy dictionary call hidden descriptor mapping did not cover every method descriptor param");
        }

        if (dispatcher_arg_index) |raw_index| {
            const index: usize = @intCast(raw_index);
            const dispatcher_arg_rep = operand_arg_reps[index];
            const descriptor_rep = self.repQuery().descriptorArgumentIdentityRep(dispatcher_arg_rep);
            const descriptor_source_type = self.parent.plan.representations.items[@intFromEnum(descriptor_rep)].source_type;
            for (pending.items) |*arg| {
                if (owner_descriptor_sources.get(arg.worker_desc) == null) continue;
                arg.source_type = descriptor_source_type;
                arg.rep = descriptor_rep;
                arg.source_arg_index = raw_index;
                arg.source_value_rep = dispatcher_arg_rep;
            }
        }

        return try pending.toOwnedSlice(self.parent.allocator);
    }

    fn dictionaryMethodFunctionRepForCall(
        self: *ProcBodyBuilder,
        callable_ty: checked.CheckedTypeId,
    ) Plan.TypeRepId {
        return self.repForType(callable_ty);
    }

    fn collectHiddenDescriptorParamsForFunction(
        self: *ProcBodyBuilder,
        function: FunctionChildren,
        pending: *std.ArrayList(Plan.HiddenDescriptorParam),
    ) Allocator.Error!void {
        return try self.collectHiddenDescriptorParamsForFunctionParts(function, pending, true);
    }

    fn collectHiddenDescriptorParamsForFunctionParts(
        self: *ProcBodyBuilder,
        function: FunctionChildren,
        pending: *std.ArrayList(Plan.HiddenDescriptorParam),
        include_return: bool,
    ) Allocator.Error!void {
        var seen_reps = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen_reps.deinit();
        var seen_descs = collections.DenseMap(Plan.DescriptorRequirementId, void).init(self.parent.allocator);
        defer seen_descs.deinit();

        const children = self.parent.plan.childSlice(self.parent.plan.representations.items[@intFromEnum(function.rep)].children);
        for (children[function.args_start..][0..function.arg_count]) |child| {
            try self.collectRuntimeHiddenDescriptorParamsForRep(child.rep, pending, &seen_reps, &seen_descs);
        }
        if (include_return) {
            try self.collectRuntimeHiddenDescriptorParamsForRep(function.ret, pending, &seen_reps, &seen_descs);
        }
    }

    fn collectRuntimeHiddenDescriptorParamsForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        pending: *std.ArrayList(Plan.HiddenDescriptorParam),
        seen_reps: *collections.DenseMap(Plan.TypeRepId, void),
        seen_descs: *collections.DenseMap(Plan.DescriptorRequirementId, void),
    ) Allocator.Error!void {
        const rep_entry = try seen_reps.getOrPut(rep_id);
        if (rep_entry.found_existing) return;

        const rep = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        if (rep.descriptor) |desc| {
            const identity_rep = self.repQuery().descriptorArgumentIdentityRep(rep_id);
            const identity_desc = self.parent.plan.representations.items[@intFromEnum(identity_rep)].descriptor orelse desc;
            const desc_entry = try seen_descs.getOrPut(identity_desc);
            if (!desc_entry.found_existing) {
                try pending.append(self.parent.allocator, .{
                    .source_type = rep.source_type,
                    .rep = rep_id,
                    .desc = desc,
                });
            }
        }

        if (rep.kind == .erased_callable) return;
        for (self.parent.plan.childSlice(rep.children)) |child| {
            if (!Plan.childCarriesRuntimeDescriptor(child.role)) continue;
            try self.collectRuntimeHiddenDescriptorParamsForRep(child.rep, pending, seen_reps, seen_descs);
        }
    }

    fn collectHiddenDescriptorParamsForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        pending: *std.ArrayList(Plan.HiddenDescriptorParam),
        seen_reps: *collections.DenseMap(Plan.TypeRepId, void),
        seen_descs: *collections.DenseMap(Plan.DescriptorRequirementId, void),
    ) Allocator.Error!void {
        const rep_entry = try seen_reps.getOrPut(rep_id);
        if (rep_entry.found_existing) return;

        const rep = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        if (rep.descriptor) |desc| {
            const identity_rep = self.repQuery().descriptorArgumentIdentityRep(rep_id);
            const identity_desc = self.parent.plan.representations.items[@intFromEnum(identity_rep)].descriptor orelse desc;
            const desc_entry = try seen_descs.getOrPut(identity_desc);
            if (!desc_entry.found_existing) {
                try pending.append(self.parent.allocator, .{
                    .source_type = rep.source_type,
                    .rep = rep_id,
                    .desc = desc,
                });
            }
        }

        for (self.parent.plan.childSlice(rep.children)) |child| {
            try self.collectHiddenDescriptorParamsForRep(child.rep, pending, seen_reps, seen_descs);
        }
    }

    fn collectAllHiddenDescriptorParamsForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        pending: *std.ArrayList(Plan.HiddenDescriptorParam),
    ) Allocator.Error!void {
        var seen_reps = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen_reps.deinit();
        var seen_descs = collections.DenseMap(Plan.DescriptorRequirementId, void).init(self.parent.allocator);
        defer seen_descs.deinit();
        try self.collectHiddenDescriptorParamsForRep(rep_id, pending, &seen_reps, &seen_descs);
    }

    fn collectDictionaryCallHiddenDescriptorArgs(
        self: *ProcBodyBuilder,
        worker_rep_id: Plan.TypeRepId,
        call_rep_id: Plan.TypeRepId,
        source_value_rep: Plan.TypeRepId,
        source_arg_index: ?u32,
        params: []const Plan.HiddenDescriptorParam,
        next_param: *usize,
        pending: *std.ArrayList(Plan.DirectCallHiddenDescriptorArg),
        seen_reps: *collections.DenseMap(Plan.TypeRepId, void),
        seen_descriptor_reps: *collections.DenseMap(Plan.TypeRepId, void),
    ) Allocator.Error!void {
        const rep_entry = try seen_reps.getOrPut(worker_rep_id);
        if (rep_entry.found_existing) return;

        const worker_rep = self.parent.plan.representations.items[@intFromEnum(worker_rep_id)];
        const call_rep = self.parent.plan.representations.items[@intFromEnum(call_rep_id)];

        if (worker_rep.descriptor) |worker_desc| {
            const worker_identity = self.repQuery().descriptorArgumentIdentityRep(worker_rep_id);
            const identity_entry = try seen_descriptor_reps.getOrPut(worker_identity);
            if (!identity_entry.found_existing) {
                if (next_param.* >= params.len or params[next_param.*].desc != worker_desc) {
                    boxyLowerInvariant("boxy dictionary call hidden descriptor order disagreed with method descriptor params");
                }
                next_param.* += 1;
                const desc_arg_rep_id = self.repQuery().descriptorArgumentIdentityRep(call_rep_id);
                const desc_arg_rep = self.parent.plan.representations.items[@intFromEnum(desc_arg_rep_id)];
                try pending.append(self.parent.allocator, .{
                    .worker_desc = worker_desc,
                    .worker_rep = worker_rep_id,
                    .source_type = desc_arg_rep.source_type,
                    .rep = desc_arg_rep_id,
                    .source_arg_index = source_arg_index,
                    .source_value_rep = source_value_rep,
                });
            }
        }

        if (worker_rep.kind == .erased_callable) return;

        if (worker_rep.children.len == 0) return;

        if (call_rep.kind == .empty_tag_union) {
            for (self.parent.plan.childSlice(worker_rep.children)) |worker_child| {
                if (!Plan.childCarriesRuntimeDescriptor(worker_child.role)) continue;
                if (!try self.repQuery().repSubtreeHasDescriptor(worker_child.rep)) continue;
                try self.collectDictionaryCallHiddenDescriptorArgs(worker_child.rep, call_rep_id, source_value_rep, source_arg_index, params, next_param, pending, seen_reps, seen_descriptor_reps);
            }
            return;
        }

        const worker_children = self.parent.plan.childSlice(worker_rep.children);
        const call_children = self.parent.plan.childSlice(call_rep.children);
        for (worker_children) |worker_child| {
            if (!Plan.childCarriesRuntimeDescriptor(worker_child.role)) continue;
            if (!try self.repQuery().repSubtreeHasDescriptor(worker_child.rep)) continue;
            if (self.namedQuery().findMatchingChildByRole(call_children, worker_child)) |call_child| {
                try self.collectDictionaryCallHiddenDescriptorArgs(worker_child.rep, call_child.rep, source_value_rep, source_arg_index, params, next_param, pending, seen_reps, seen_descriptor_reps);
                continue;
            }
            if (self.repQuery().structuralWrapperBackingRep(call_rep_id)) |call_backing| {
                const backing_children = self.parent.plan.childSlice(self.parent.plan.representations.items[@intFromEnum(call_backing)].children);
                if (self.namedQuery().findMatchingChildByRole(backing_children, worker_child)) |call_child| {
                    try self.collectDictionaryCallHiddenDescriptorArgs(worker_child.rep, call_child.rep, source_value_rep, source_arg_index, params, next_param, pending, seen_reps, seen_descriptor_reps);
                    continue;
                }
            }
            if (try self.namedQuery().findMatchingTagPayloadInRowExtension(call_children, worker_child)) |call_child| {
                try self.collectDictionaryCallHiddenDescriptorArgs(worker_child.rep, call_child.rep, source_value_rep, source_arg_index, params, next_param, pending, seen_reps, seen_descriptor_reps);
                continue;
            }
            if (try self.repQuery().findMatchingChildBySourceType(call_children, worker_child)) |call_child| {
                try self.collectDictionaryCallHiddenDescriptorArgs(worker_child.rep, call_child.rep, source_value_rep, source_arg_index, params, next_param, pending, seen_reps, seen_descriptor_reps);
                continue;
            }
            if (try self.repQuery().workerChildCanMatchUnwrappedCallRep(worker_rep_id, worker_child)) {
                try self.collectDictionaryCallHiddenDescriptorArgs(worker_child.rep, call_rep_id, source_value_rep, source_arg_index, params, next_param, pending, seen_reps, seen_descriptor_reps);
                continue;
            }
            if (worker_child.role == .tag_ext and call_children.len == 0 and call_rep.descriptor != null) {
                try self.collectDictionaryCallHiddenDescriptorArgs(worker_child.rep, call_rep_id, source_value_rep, source_arg_index, params, next_param, pending, seen_reps, seen_descriptor_reps);
                continue;
            }
            boxyLowerInvariant("boxy dictionary call hidden descriptor mapping saw mismatched child roles");
        }
    }

    fn lowerDirectCallHiddenDescriptorArgs(
        self: *ProcBodyBuilder,
        hidden_args: []const Plan.DirectCallHiddenDescriptorArg,
        call_arg_types: []const Plan.CheckedTypeIdentity,
        source_args: []const LIR.LocalId,
        source_arg_reps: []const Plan.TypeRepId,
        descriptor_args: ?[]const LIR.LocalId,
        descriptor_arg_reps: ?[]const Plan.RepChild,
        pre_arg_descriptor_initializers: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error![]DescriptorArgLocal {
        if (call_arg_types.len != source_args.len or source_arg_reps.len != source_args.len) {
            boxyLowerInvariant("boxy direct call hidden descriptor source metadata length mismatch");
        }
        if ((descriptor_args == null) != (descriptor_arg_reps == null)) {
            boxyLowerInvariant("boxy direct call descriptor value and representation plans disagreed");
        }
        if (descriptor_args) |args| {
            if (args.len != source_args.len or descriptor_arg_reps.?.len != source_args.len) {
                boxyLowerInvariant("boxy direct call adapted descriptor source arity disagreed with operands");
            }
        }
        const lowered = try self.parent.allocator.alloc(DescriptorArgLocal, hidden_args.len);
        errdefer self.parent.allocator.free(lowered);

        for (hidden_args, lowered) |arg, *local| {
            if (try self.sourceValueDescriptorLocalForHiddenArg(
                arg,
                call_arg_types,
                source_args,
                source_arg_reps,
                descriptor_args,
                descriptor_arg_reps,
                pre_arg_descriptor_initializers,
            )) |source_desc| {
                local.* = source_desc;
                continue;
            }
            if (self.directCallHiddenDescriptorUsesCallShape(arg)) {
                if (try self.descriptorLocalForMatchingSourceArg(arg, call_arg_types, source_args, pre_arg_descriptor_initializers)) |desc_local| {
                    local.* = desc_local;
                    continue;
                }
                const identity_rep = self.descriptorStorageRep(arg.rep);
                const rep = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
                const desc = rep.descriptor orelse {
                    local.* = .{ .local = try self.addFrameLocal(.opaque_ptr) };
                    continue;
                };
                if (self.descriptorLocalForRequirementAndRepOrNull(desc, identity_rep)) |desc_local| {
                    if (self.localIsReadOnlyDescriptorInput(desc_local)) {
                        if (self.parent.result.store.getLocal(desc_local).layout_idx != .opaque_ptr) {
                            boxyLowerInvariant("boxy read-only hidden descriptor local was not opaque_ptr");
                        }
                        local.* = .{ .local = desc_local };
                        continue;
                    }
                }
                if (self.descriptorBindingIsBoundForRep(identity_rep)) {
                    const desc_local = self.descriptorLocalForRequirementAndRepOrNull(desc, identity_rep) orelse
                        boxyLowerInvariant("bound boxy hidden descriptor arg had no matching local");
                    if (self.parent.result.store.getLocal(desc_local).layout_idx != .opaque_ptr) {
                        boxyLowerInvariant("boxy hidden descriptor local was not opaque_ptr");
                    }
                    local.* = .{ .local = desc_local };
                    continue;
                }
            }
            local.* = .{ .local = try self.addFrameLocal(.opaque_ptr) };
        }

        const snapshot = try self.snapshotDescriptorBindings();
        defer snapshot.deinit(self.parent.allocator);
        defer self.restoreDescriptorBindings(snapshot);
        try self.bindDirectCallHiddenDescriptorLocals(hidden_args, lowered, false);

        for (hidden_args, lowered) |arg, *local| {
            if (local.from_source_value) continue;
            if (self.localIsReadOnlyDescriptorInput(local.local)) continue;

            if (local.materialize == null and self.directCallHiddenDescriptorUsesCallShape(arg)) {
                const identity_call_rep = self.descriptorStorageRep(arg.rep);
                const call_rep = self.parent.plan.representations.items[@intFromEnum(identity_call_rep)];
                if (call_rep.descriptor) |desc| {
                    if (self.descriptorSnapshotBoundLocalForRep(snapshot, desc, identity_call_rep)) |bound_local| {
                        if (bound_local != local.local) {
                            local.materialize = .{ .local = bound_local };
                        }
                        continue;
                    }
                }
                const materialization = try self.descriptorMaterializationForKnownRepExcludingLocal(
                    identity_call_rep,
                    local.local,
                );
                local.materialize = materialization.desc;
                local.captures = materialization.captures;
                continue;
            }

            if (local.materialize == null and !self.directCallHiddenDescriptorUsesCallShape(arg)) {
                const identity_worker_rep = self.descriptorStorageRep(arg.worker_rep);
                const materialization = try self.descriptorMaterializationForKnownRepExcludingLocal(
                    identity_worker_rep,
                    local.local,
                );
                local.materialize = materialization.desc;
                local.captures = materialization.captures;
                continue;
            }

            if (local.materialize == null) {
                const identity_rep = self.descriptorStorageRep(arg.rep);
                local.materialize = try self.parent.staticDescRefForRep(identity_rep);
            }
        }

        return lowered;
    }

    fn sourceValueDescriptorLocalForHiddenArg(
        self: *ProcBodyBuilder,
        hidden_arg: Plan.DirectCallHiddenDescriptorArg,
        arg_types: []const Plan.CheckedTypeIdentity,
        source_args: []const LIR.LocalId,
        source_arg_reps: []const Plan.TypeRepId,
        descriptor_args: ?[]const LIR.LocalId,
        descriptor_arg_reps: ?[]const Plan.RepChild,
        pre_arg_descriptor_initializers: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!?DescriptorArgLocal {
        const source_arg_index = hidden_arg.source_arg_index orelse return null;
        const index: usize = @intCast(source_arg_index);
        if (index >= arg_types.len or index >= source_args.len or index >= source_arg_reps.len) {
            boxyLowerInvariant("boxy direct call hidden descriptor source argument index exceeded call arity");
        }

        if (hidden_arg.source_value_rep == null) {
            boxyLowerInvariant("boxy hidden descriptor argument source had no planned value representation");
        }
        const source = if (descriptor_args) |args| args[index] else source_args[index];
        const source_rep = if (descriptor_arg_reps) |reps| reps[index].rep else source_arg_reps[index];
        const hidden_rep = if (descriptor_arg_reps != null) hidden_arg.worker_rep else hidden_arg.rep;
        const identity_source_rep = self.descriptorStorageRep(source_rep);
        const identity_hidden_rep = self.descriptorStorageRep(hidden_rep);
        if (identity_source_rep != identity_hidden_rep) {
            // A planned source argument's live descriptor is authoritative for
            // descriptor-bearing children stored in that value. Its local
            // environment can also contain bindings for other values that
            // share the same generic representation.
            if (try self.sourceNestedDescriptorLocalForHiddenArg(source, source_rep, hidden_rep)) |projected| {
                return projected;
            }
        }
        if (self.localDescriptorEnvironmentForLocal(source)) |env| {
            const call_identity_rep = self.descriptorStorageRep(hidden_arg.rep);
            try self.bindLocalDescriptorEnvironment(source);
            const source_template = try self.descriptorMaterializationForKnownRep(call_identity_rep);
            for (env.bindings) |binding| {
                if (self.descriptorStorageRep(binding.rep) != call_identity_rep) continue;
                if (identity_hidden_rep == call_identity_rep) {
                    return .{ .local = binding.local, .from_source_value = true };
                }

                const adapted = try self.adapterDescriptorForCallBoundary(
                    identity_hidden_rep,
                    call_identity_rep,
                    .{
                        .desc = .{ .local = binding.local },
                        .template = source_template,
                    },
                    pre_arg_descriptor_initializers,
                );
                if (adapted.prerequisite) |prerequisite| {
                    try pre_arg_descriptor_initializers.append(self.parent.allocator, prerequisite);
                }
                const adapted_desc = adapted.desc orelse
                    boxyLowerInvariant("boxy hidden descriptor representation adapter produced no descriptor");
                if (adapted.materialize) |materialize| {
                    if (adapted_desc.localOrNull() != materialize.local) {
                        boxyLowerInvariant("boxy hidden descriptor adapter materialization did not produce its result descriptor");
                    }
                    return materialize;
                }
                return .{
                    .local = try self.addFrameLocal(.opaque_ptr),
                    .materialize = adapted_desc,
                };
            }
        }
        if (identity_source_rep != identity_hidden_rep) {
            return null;
        }

        // The source value's live descriptor describes it in the concrete
        // call-site representation. When the worker receives the argument as
        // aggregate storage whose runtime layout differs from that concrete
        // source, a generic child was boxed as the value crossed the call
        // boundary, and the concrete descriptor lacks the nested descriptors
        // the worker navigates. The worker representation must then supply the
        // descriptor, so defer to the worker-rep path. Tag unions (which
        // reshape by row extension, not child boxing) and whole-value boxing
        // into an opaque worker scalar both keep the concrete source
        // descriptor.
        const worker_canonical_rep = self.parent.plan.representations.items[@intFromEnum(self.descriptorStorageRep(hidden_arg.worker_rep))];
        const worker_uses_aggregate_storage = worker_canonical_rep.tag_variants.len == 0 and switch (worker_canonical_rep.kind) {
            .record, .record_unbound, .tuple, .nominal, .list, .box => true,
            .in_progress, .dynamic, .primitive, .bool_tag_union, .erased_callable, .alias, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => false,
        };
        if (worker_uses_aggregate_storage) {
            const source_layout = self.parent.result.store.getLocal(source).layout_idx;
            const worker_layout = self.workerRuntimeLayoutForRep(hidden_arg.worker_rep);
            if (source_layout != worker_layout.layoutIdx()) {
                return null;
            }
        }
        if (self.parent.result.store.getLocal(source).boxy_desc) |existing| {
            if (existing.localOrNull()) |existing_local| {
                // The producer that assigned `source` also assigned this
                // descriptor local. It is the exact metadata for the live
                // value and must cross the call boundary unchanged.
                return .{ .local = existing_local, .from_source_value = true };
            }

            if (worker_uses_aggregate_storage) {
                return null;
            }
        }

        const materialization = try self.descriptorMaterializationForSourceStorageLocalRep(source, source_rep);
        const local = try self.addFrameLocal(.opaque_ptr);
        return .{
            .local = local,
            .materialize = materialization.desc,
            .captures = materialization.captures,
            .from_source_value = true,
        };
    }

    fn sourceNestedDescriptorLocalForHiddenArg(
        self: *ProcBodyBuilder,
        source: LIR.LocalId,
        source_rep: Plan.TypeRepId,
        hidden_rep: Plan.TypeRepId,
    ) Allocator.Error!?DescriptorArgLocal {
        const read_path = try self.descriptorReadPathForNestedRep(source_rep, hidden_rep) orelse return null;
        const source_desc = if (self.parent.result.store.getLocal(source).boxy_desc) |existing|
            DescriptorMaterialization{ .desc = existing }
        else
            try self.descriptorMaterializationForSourceRep(source_rep);
        return .{
            .local = try self.addFrameLocal(.opaque_ptr),
            .materialize = source_desc.desc,
            .read_path = read_path,
            .captures = source_desc.captures,
            .from_source_value = true,
        };
    }

    fn descriptorReadPathForNestedRep(
        self: *ProcBodyBuilder,
        source_rep: Plan.TypeRepId,
        nested_rep: Plan.TypeRepId,
    ) Allocator.Error!?Plan.Span {
        var read_path = std.ArrayList(DescriptorReadStep).empty;
        defer read_path.deinit(self.parent.allocator);
        var active = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer active.deinit();

        if (!try self.findDescriptorReadPath(
            source_rep,
            self.descriptorStorageRep(nested_rep),
            &read_path,
            &active,
        )) return null;
        if (read_path.items.len == 0) return null;
        return try self.parent.addDescriptorReadPath(read_path.items);
    }

    fn findDescriptorReadPath(
        self: *ProcBodyBuilder,
        current_rep_id: Plan.TypeRepId,
        target_rep_id: Plan.TypeRepId,
        read_path: *std.ArrayList(DescriptorReadStep),
        active: *collections.DenseMap(Plan.TypeRepId, void),
    ) Allocator.Error!bool {
        const current_rep_identity = self.descriptorStorageRep(current_rep_id);
        if (current_rep_identity == target_rep_id) return true;

        const active_entry = try active.getOrPut(current_rep_identity);
        if (active_entry.found_existing) return false;
        defer _ = active.remove(current_rep_identity);

        if (self.tagVariantRepForBoundary(current_rep_identity)) |tag_rep_id| {
            const tag_rep = self.parent.plan.representations.items[@intFromEnum(tag_rep_id)];
            const variants = self.parent.plan.tagVariantSlice(tag_rep.tag_variants);
            const descriptor_layout = self.parent.descriptorPayloadLayoutForRep(current_rep_identity);
            const descriptor_layout_value = self.parent.result.layouts.getLayout(descriptor_layout);
            const tag_layout = switch (descriptor_layout_value.tag) {
                .tag_union => descriptor_layout_value,
                .box => self.parent.result.layouts.getLayout(descriptor_layout_value.getIdx()),
                .zst => null,
                .scalar, .box_of_zst, .erased_box, .list, .list_of_zst, .struct_, .closure, .erased_callable, .ptr => boxyLowerInvariant("boxy descriptor read_path tag had a non-tag payload layout"),
            };

            if (tag_layout) |layout_value| {
                if (layout_value.tag != .tag_union) {
                    boxyLowerInvariant("boxy descriptor read_path tag box had a non-tag payload");
                }
                const tag_info = self.parent.result.layouts.getTagUnionInfo(layout_value);
                if (tag_info.variants.len < variants.len) {
                    boxyLowerInvariant("boxy descriptor read_path tag layout had too few variants");
                }
                for (variants, 0..) |variant, variant_index| {
                    if (try self.findDescriptorReadPathInTagPayloads(
                        variant,
                        tag_info.variants.get(variant_index).payload_layout,
                        target_rep_id,
                        read_path,
                        active,
                    )) return true;
                }
            } else {
                if (variants.len != 1) {
                    boxyLowerInvariant("boxy zero-sized tag descriptor read_path had multiple variants");
                }
                if (try self.findDescriptorReadPathInTagPayloads(
                    variants[0],
                    .zst,
                    target_rep_id,
                    read_path,
                    active,
                )) return true;
            }

            for (self.parent.plan.childSlice(tag_rep.children)) |child| {
                if (child.role != .tag_ext) continue;
                const ext_identity = self.descriptorStorageRep(child.rep);
                const ext_rep = self.parent.plan.representations.items[@intFromEnum(ext_identity)];
                if (ext_identity == tag_rep_id or ext_rep.kind == .empty_tag_union) continue;
                try read_path.append(self.parent.allocator, .tag_ext);
                if (try self.findDescriptorReadPath(child.rep, target_rep_id, read_path, active)) return true;
                read_path.items.len -= 1;
            }
            return false;
        }

        const current_rep = self.parent.plan.representations.items[@intFromEnum(current_rep_identity)];
        const payload_layout = self.parent.descriptorPayloadLayoutForRep(current_rep_identity);
        var nested_index: u32 = 0;
        if (current_rep.declared_fields.len != 0) {
            for (self.parent.plan.declaredFieldSlice(current_rep.declared_fields)) |field| {
                const field_layout = self.parent.recordPayloadFieldLayout(payload_layout, field.index);
                const nested = self.nestedDescriptorRepForStorage(
                    field.rep,
                    field_layout,
                    self.parent.layoutIsBoxStorage(field_layout),
                ) orelse continue;
                try read_path.append(self.parent.allocator, .{ .nested = nested_index });
                if (try self.findDescriptorReadPath(nested, target_rep_id, read_path, active)) return true;
                read_path.items.len -= 1;
                nested_index += 1;
            }
            return false;
        }

        var record_field_index: u32 = 0;
        for (self.parent.plan.childSlice(current_rep.children)) |child| {
            if (child.role == .tag_ext) continue;
            const field_layout = switch (child.role) {
                .record_field => blk: {
                    const layout_idx = self.parent.recordPayloadFieldLayout(payload_layout, record_field_index);
                    record_field_index += 1;
                    break :blk layout_idx;
                },
                .tuple_elem => |index| self.parent.recordPayloadFieldLayout(payload_layout, index),
                .box_payload => self.parent.descriptorPayloadLayoutForRep(child.rep),
                .list_elem => self.parent.listElementLayout(payload_layout),
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_ext, .function_arg, .function_ret, .tag_payload, .tag_ext => continue,
            };
            const nested = self.nestedDescriptorRepForStorage(
                child.rep,
                field_layout,
                child.role == .box_payload or self.parent.layoutIsBoxStorage(field_layout),
            ) orelse continue;
            try read_path.append(self.parent.allocator, .{ .nested = nested_index });
            if (try self.findDescriptorReadPath(nested, target_rep_id, read_path, active)) return true;
            read_path.items.len -= 1;
            nested_index += 1;
        }
        return false;
    }

    fn findDescriptorReadPathInTagPayloads(
        self: *ProcBodyBuilder,
        variant: Plan.TagVariant,
        variant_payload_layout: layout.Idx,
        target_rep_id: Plan.TypeRepId,
        read_path: *std.ArrayList(DescriptorReadStep),
        active: *collections.DenseMap(Plan.TypeRepId, void),
    ) Allocator.Error!bool {
        const payloads = self.parent.plan.childSlice(variant.payloads);
        for (payloads, 0..) |payload, payload_index| {
            const field_layout = self.parent.tagVariantPayloadFieldLayout(
                variant_payload_layout,
                payload_index,
                payloads.len,
            );
            const payload_rep = self.parent.tagPayloadStorageDescRepForLayout(
                payload.rep,
                field_layout,
                true,
            ) orelse continue;
            try read_path.append(self.parent.allocator, .{ .tag_payload = .{
                .tag_name = try self.lirTagNameForVariant(variant),
                .payload_index = @intCast(payload_index),
            } });
            if (try self.findDescriptorReadPath(payload_rep, target_rep_id, read_path, active)) return true;
            read_path.items.len -= 1;
        }
        return false;
    }

    fn immediateNestedDescriptorIndexForRep(
        self: *ProcBodyBuilder,
        parent_rep_id: Plan.TypeRepId,
        nested_rep_id: Plan.TypeRepId,
    ) ?u32 {
        const parent_rep = self.parent.plan.representations.items[@intFromEnum(parent_rep_id)];
        const payload_layout = self.parent.descriptorPayloadLayoutForRep(parent_rep_id);
        const target_rep = self.descriptorStorageRep(nested_rep_id);
        var desc_index: u32 = 0;

        if (parent_rep.declared_fields.len != 0) {
            for (self.parent.plan.declaredFieldSlice(parent_rep.declared_fields)) |field| {
                const field_layout = self.parent.recordPayloadFieldLayout(payload_layout, field.index);
                const force_field = self.parent.layoutIsBoxStorage(field_layout);
                const desc_rep = self.nestedDescriptorRepForStorage(field.rep, field_layout, force_field) orelse continue;
                if (self.descriptorStorageRep(desc_rep) == target_rep) return desc_index;
                desc_index += 1;
            }
            return null;
        }

        var record_field_index: u32 = 0;
        for (self.parent.plan.childSlice(parent_rep.children)) |child| {
            if (child.role == .tag_ext) continue;
            const field_layout = switch (child.role) {
                .record_field => blk: {
                    const field_layout = self.parent.recordPayloadFieldLayout(payload_layout, record_field_index);
                    record_field_index += 1;
                    break :blk field_layout;
                },
                .tuple_elem => |index| self.parent.recordPayloadFieldLayout(payload_layout, index),
                .box_payload => self.parent.descriptorPayloadLayoutForRep(child.rep),
                .list_elem => self.parent.listElementLayout(payload_layout),
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_ext, .function_arg, .function_ret, .tag_payload, .tag_ext => continue,
            };
            const force_desc = child.role == .box_payload or self.parent.layoutIsBoxStorage(field_layout);
            const desc_rep = self.nestedDescriptorRepForStorage(child.rep, field_layout, force_desc) orelse continue;
            if (self.descriptorStorageRep(desc_rep) == target_rep) return desc_index;
            desc_index += 1;
        }

        return null;
    }

    fn nestedDescriptorRepForStorage(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        storage_layout: layout.Idx,
        force: bool,
    ) ?Plan.TypeRepId {
        if (!force and !self.parent.layoutNeedsNestedBoxyDesc(storage_layout)) return null;
        return self.parent.tagPayloadStorageDescRepForLayout(rep_id, storage_layout, force);
    }

    fn descriptorLocalForMatchingSourceArg(
        self: *ProcBodyBuilder,
        hidden_arg: Plan.DirectCallHiddenDescriptorArg,
        arg_types: []const Plan.CheckedTypeIdentity,
        source_args: []const LIR.LocalId,
        pre_arg_descriptor_initializers: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!?DescriptorArgLocal {
        if (!self.directCallHiddenDescriptorUsesCallShape(hidden_arg)) return null;
        for (arg_types, source_args) |arg_type, source| {
            if (!planTypeRefEql(arg_type, hidden_arg.source_type)) continue;
            const arg_rep = self.repForTypeRef(arg_type);
            const identity_arg_rep = self.descriptorStorageRep(arg_rep);
            const identity_hidden_rep = self.descriptorStorageRep(hidden_arg.rep);
            if (identity_arg_rep != identity_hidden_rep) continue;
            const desc_ref = self.parent.result.store.getLocal(source).boxy_desc orelse continue;
            if (desc_ref.localOrNull()) |desc_local| {
                if (!self.localIsReadOnlyDescriptorInput(desc_local)) {
                    const materialization = try self.descriptorMaterializationForSourceRep(identity_arg_rep);
                    try pre_arg_descriptor_initializers.append(self.parent.allocator, .{
                        .local = desc_local,
                        .materialize = materialization.desc,
                        .captures = materialization.captures,
                    });
                }
                return .{ .local = desc_local, .from_source_value = true };
            }
            return .{
                .local = try self.addFrameLocal(.opaque_ptr),
                .materialize = desc_ref,
                .from_source_value = true,
            };
        }
        return null;
    }

    fn directCallResultDescriptorRef(
        self: *ProcBodyBuilder,
        result_rep: Plan.TypeRepId,
        hidden_args: []const Plan.DirectCallHiddenDescriptorArg,
        hidden_locals: []const DescriptorArgLocal,
    ) Allocator.Error!ResultDescriptorSource {
        const identity_rep = self.parent.descriptorIdentityRep(result_rep);
        const rep = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
        if (rep.descriptor == null) return .{};
        if (rep.descriptor) |desc| {
            if (hidden_args.len != hidden_locals.len) {
                boxyLowerInvariant("boxy direct call result descriptor saw mismatched hidden descriptor locals");
            }
            for (hidden_args, hidden_locals) |arg, hidden| {
                if (arg.worker_desc == desc) return .{ .desc = .{ .local = hidden.local } };
            }
        }

        const snapshot = try self.snapshotDescriptorBindings();
        defer snapshot.deinit(self.parent.allocator);
        defer self.restoreDescriptorBindings(snapshot);

        try self.bindDirectCallHiddenDescriptorLocals(hidden_args, hidden_locals, true);
        const materialization = try self.descriptorMaterializationForSourceRep(identity_rep);
        if (materialization.captures.len == 0) {
            return .{ .desc = materialization.desc };
        }

        const local = try self.addFrameLocal(.opaque_ptr);
        return .{
            .desc = .{ .local = local },
            .materialize = .{
                .local = local,
                .materialize = materialization.desc,
                .captures = materialization.captures,
            },
        };
    }

    fn dictionaryCallResultDescriptorRef(
        self: *ProcBodyBuilder,
        result_rep: Plan.TypeRepId,
        hidden_args: []const Plan.DirectCallHiddenDescriptorArg,
        hidden_locals: []const DescriptorArgLocal,
    ) Allocator.Error!ResultDescriptorSource {
        const snapshot = try self.snapshotDescriptorBindings();
        defer snapshot.deinit(self.parent.allocator);
        defer self.restoreDescriptorBindings(snapshot);

        try self.bindDirectCallHiddenDescriptorLocals(hidden_args, hidden_locals, true);
        return try self.exactCallResultDescriptorRef(result_rep);
    }

    fn descriptorSnapshotBoundLocalForRep(
        self: *const ProcBodyBuilder,
        snapshot: DescriptorBindingsSnapshot,
        desc: Plan.DescriptorRequirementId,
        rep_id: Plan.TypeRepId,
    ) ?LIR.LocalId {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const desc_index = @intFromEnum(desc);
        if (desc_index < snapshot.bound.len and
            snapshot.bound[desc_index] and
            desc_index < snapshot.local_reps.len and
            snapshot.local_reps[desc_index] == identity_rep)
        {
            if (desc_index >= snapshot.locals.len) {
                boxyLowerInvariant("boxy descriptor snapshot bound state had no local slot");
            }
            return snapshot.locals[desc_index] orelse
                boxyLowerInvariant("boxy descriptor snapshot marked a missing local as bound");
        }
        for (snapshot.rep_bindings) |binding| {
            if (binding.desc == desc and binding.rep == identity_rep and binding.bound) return binding.local;
        }
        return null;
    }

    fn exactCallResultDescriptorRef(
        self: *ProcBodyBuilder,
        result_rep: Plan.TypeRepId,
    ) Allocator.Error!ResultDescriptorSource {
        const materialization = try self.descriptorMaterializationForExactResultRep(result_rep);
        if (materialization.captures.len == 0) {
            return .{ .desc = materialization.desc };
        }

        const local = try self.addFrameLocal(.opaque_ptr);
        return .{
            .desc = .{ .local = local },
            .materialize = .{
                .local = local,
                .materialize = materialization.desc,
                .captures = materialization.captures,
            },
        };
    }

    fn descriptorMaterializationForExactResultRep(
        self: *ProcBodyBuilder,
        result_rep: Plan.TypeRepId,
    ) Allocator.Error!DescriptorMaterialization {
        const identity_rep = self.descriptorStorageRep(result_rep);
        return if (self.repIsBareDynamic(identity_rep))
            try self.descriptorMaterializationForSourceRep(identity_rep)
        else
            try self.descriptorMaterializationForExactRep(result_rep);
    }

    fn erasedCallResultDescriptorRef(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        result_rep: Plan.TypeRepId,
        out_desc: ?LIR.LocalId,
    ) Allocator.Error!ResultDescriptorSource {
        if (out_desc) |local| {
            if (self.descriptorTemplateForLocal(local)) |template| {
                return try self.adapterDescriptorFromMaterialization(template);
            }
            const exact = try self.exactCallResultDescriptorRef(result_rep);
            if (exact.desc) |desc| {
                if (desc.localOrNull() == local) {
                    boxyLowerInvariant("erased-call result descriptor aliased its output without an immutable template");
                }
            }
            return exact;
        }
        if (self.parent.result.store.getLocal(target).boxy_desc) |target_desc| {
            return .{ .desc = target_desc };
        }
        return try self.exactCallResultDescriptorRef(result_rep);
    }

    fn erasedCallResultCanUseTarget(
        self: *const ProcBodyBuilder,
        target_rep: Plan.TypeRepId,
        result_rep: Plan.TypeRepId,
    ) bool {
        const target_identity = self.descriptorStorageRep(target_rep);
        const result_identity = self.descriptorStorageRep(result_rep);
        if (target_identity != result_identity) return false;
        if (target_rep == result_rep) return true;
        return self.repIsFullyConcrete(target_identity);
    }

    fn callResultOutputDescriptorLocal(
        self: *const ProcBodyBuilder,
        target: LIR.LocalId,
    ) ?LIR.LocalId {
        const desc = self.parent.result.store.getLocal(target).boxy_desc orelse return null;
        const local = desc.localOrNull() orelse return null;
        return if (self.localIsReadOnlyDescriptorInput(local)) null else local;
    }

    fn resultDescriptorForCallTarget(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        info: ResultDescriptorSource,
    ) ResultDescriptorSource {
        const desc = info.desc orelse return info;
        const target_desc = self.parent.result.store.getLocal(target).boxy_desc orelse return info;
        if (std.meta.eql(desc, target_desc)) return info;

        var result = info;
        result.desc = target_desc;
        const target_desc_local = target_desc.localOrNull() orelse {
            result.preserves_source_desc = false;
            return result;
        };
        if (std.mem.findScalar(LIR.LocalId, self.runtime_initialized_descriptor_locals.items, target_desc_local) != null) {
            result.materialize = null;
            result.preserves_source_desc = false;
            return result;
        }
        if (self.localIsReadOnlyDescriptorInput(target_desc_local)) {
            result.materialize = null;
            result.preserves_source_desc = false;
            return result;
        }
        if (info.materialize) |materialize| {
            const materialized_desc = materialize.materialize orelse
                boxyLowerInvariant("boxy call result descriptor materialization had no descriptor");
            const materialized_ref = LIR.BoxyDescRef{ .local = materialize.local };
            result.materialize = .{
                .local = target_desc_local,
                .materialize = if (std.meta.eql(desc, materialized_ref)) materialized_desc else desc,
                .read_path = if (std.meta.eql(desc, materialized_ref)) materialize.read_path else .{},
                .nested_index = if (std.meta.eql(desc, materialized_ref)) materialize.nested_index else null,
                .tag_ext = std.meta.eql(desc, materialized_ref) and materialize.tag_ext,
                .tag_residual_for = if (std.meta.eql(desc, materialized_ref)) materialize.tag_residual_for else null,
                .captures = if (std.meta.eql(desc, materialized_ref)) materialize.captures else LIR.LocalSpan.empty(),
            };
        } else {
            result.materialize = .{
                .local = target_desc_local,
                .materialize = desc,
            };
        }
        return result;
    }

    fn descriptorForConstructedTarget(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        constructed_desc: LIR.BoxyDescRef,
    ) Allocator.Error!ResultDescriptorSource {
        const existing = self.parent.result.store.getLocal(target).boxy_desc orelse {
            self.parent.result.store.setLocalBoxyDesc(target, constructed_desc);
            return .{ .desc = constructed_desc };
        };
        if (std.meta.eql(existing, constructed_desc)) {
            return .{ .desc = existing };
        }
        if (existing.localOrNull()) |existing_local| {
            if (!self.localIsReadOnlyDescriptorInput(existing_local)) {
                try self.recordDescriptorLocalTemplate(existing_local, .{ .desc = constructed_desc });
                return .{
                    .desc = existing,
                    .materialize = .{
                        .local = existing_local,
                        .materialize = constructed_desc,
                    },
                };
            }
        }
        return .{ .desc = existing };
    }

    fn descriptorForConstructedTargetMaterialization(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        materialization: DescriptorMaterialization,
    ) Allocator.Error!ResultDescriptorSource {
        if (materialization.captures.len == 0) {
            return try self.descriptorForConstructedTarget(target, materialization.desc);
        }

        if (self.parent.result.store.getLocal(target).boxy_desc) |existing| {
            if (existing.localOrNull()) |existing_local| {
                if (!self.localIsReadOnlyDescriptorInput(existing_local)) {
                    try self.recordDescriptorLocalTemplate(existing_local, materialization);
                    return .{
                        .desc = existing,
                        .materialize = .{
                            .local = existing_local,
                            .materialize = materialization.desc,
                            .captures = materialization.captures,
                        },
                    };
                }
            }
            return .{ .desc = existing };
        }

        const desc_local = try self.addFrameLocal(.opaque_ptr);
        const desc_ref = LIR.BoxyDescRef{ .local = desc_local };
        self.parent.result.store.setLocalBoxyDesc(target, desc_ref);
        try self.recordDescriptorLocalTemplate(desc_local, materialization);
        return .{
            .desc = desc_ref,
            .materialize = .{
                .local = desc_local,
                .materialize = materialization.desc,
                .captures = materialization.captures,
            },
        };
    }

    fn stableDescriptorForConstructedValue(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!ResultDescriptorSource {
        const rep = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        if (rep.descriptor == null and !rep.contains_dynamic and
            self.parent.result.store.getLocal(target).boxy_desc == null) return .{};

        const materialization = try self.descriptorMaterializationForConstructedRep(rep_id);
        return try self.descriptorForConstructedTargetMaterialization(target, materialization);
    }

    fn constructedListDescriptorForElementLocal(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        elem_desc_local: LIR.LocalId,
    ) Allocator.Error!ResultDescriptorSource {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const rep = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
        if (rep.descriptor == null and
            self.parent.result.store.getLocal(target).boxy_desc == null) return .{};

        const elem_desc_ref = LIR.BoxyDescRef{ .local = elem_desc_local };
        const nested_start: u32 = @intCast(self.parent.result.boxy_desc_refs.items.len);
        try self.parent.result.boxy_desc_refs.append(self.parent.allocator, elem_desc_ref);

        const desc_id: LIR.BoxyTypeDescId = @enumFromInt(@as(u32, @intCast(self.parent.result.boxy_type_descs.items.len)));
        const payload_layout = self.parent.result.store.getLocal(target).layout_idx;
        const layout_value = self.parent.result.layouts.getLayout(payload_layout);
        if (!layoutIsList(layout_value)) {
            boxyLowerInvariant("constructed list descriptor target did not have list storage");
        }
        try self.parent.result.boxy_type_descs.append(self.parent.allocator, .{
            .payload_layout = payload_layout,
            .contains_refcounted = self.parent.result.layouts.layoutContainsRefcounted(layout_value) or rep.contains_dynamic,
            .nested_descs = .{ .start = nested_start, .len = 1 },
            .tag_variants = try self.parent.staticTagVariantsForRep(identity_rep, payload_layout),
            .tag_ext_desc = try self.parent.staticTagExtDescForRep(identity_rep),
            .field_names = try self.parent.staticFieldNamesForRep(identity_rep),
            .inspect_opaque = self.parent.repInspectsOpaque(identity_rep),
            .debug_checked_type = rep.source_type.ty,
        });
        const captures = [_]LIR.LocalId{elem_desc_local};
        return try self.descriptorForConstructedTargetMaterialization(target, .{
            .desc = .{ .static = desc_id },
            .captures = try self.parent.result.store.addLocalSpan(&captures),
        });
    }

    fn descriptorMaterializationForConstructedRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!DescriptorMaterialization {
        const identity_rep = self.parent.descriptorIdentityRep(rep_id);
        const rep = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
        if (rep.descriptor) |desc| {
            if (self.descriptorLocalForRequirementAndRepOrNull(desc, identity_rep)) |local| {
                if (self.descriptorBindingIsBoundForRep(identity_rep)) {
                    return .{ .desc = .{ .local = local } };
                }
            }
            if (self.descriptorBindingIsBoundForRep(identity_rep)) {
                return try self.descriptorMaterializationForKnownRep(identity_rep);
            }
        }
        return try self.descriptorMaterializationForKnownRep(identity_rep);
    }

    fn storageDescriptorForRepIfNeeded(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!ResultDescriptorSource {
        const desc_rep = self.parent.tagPayloadStorageDescRepIfNeeded(rep_id) orelse return .{};
        const materialization = try self.descriptorMaterializationForSourceRep(desc_rep);
        if (materialization.captures.len == 0) {
            return .{ .desc = materialization.desc };
        }

        const local = try self.addFrameLocal(.opaque_ptr);
        return .{
            .desc = .{ .local = local },
            .materialize = .{
                .local = local,
                .materialize = materialization.desc,
                .captures = materialization.captures,
            },
        };
    }

    fn descriptorRefForPayloadStorageTarget(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!ResultDescriptorSource {
        if (self.parent.result.store.getLocal(target).boxy_desc) |desc| {
            return .{ .desc = desc };
        }
        return try self.storageDescriptorForRepIfNeeded(rep_id);
    }

    fn assignWorkerValueToTagPayloadStorage(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        if (target_layout == source_layout) return try self.assignLocal(target, source, next);

        const source_layout_value = self.parent.result.layouts.getLayout(source_layout);
        const target_layout_value = self.parent.result.layouts.getLayout(target_layout);
        const source_is_box = source_layout_value.tag == .box or source_layout_value.tag == .box_of_zst or source_layout_value.tag == .erased_box;
        const target_is_box = target_layout_value.tag == .box or target_layout_value.tag == .box_of_zst or target_layout_value.tag == .erased_box;

        if (source_is_box and !target_is_box) {
            const source_desc = try self.descriptorRefForSourceLocalRep(source, rep_id);
            const target_desc_info = try self.descriptorRefForPayloadStorageTarget(target, rep_id);
            const target_desc = target_desc_info.desc orelse
                boxyLowerInvariant("boxy tag payload storage unbox had no target descriptor");
            self.parent.result.store.setLocalBoxyDesc(target, target_desc);
            const unbox = try self.parent.result.store.addCFStmt(.{ .assign_boxy_unbox = .{
                .target = target,
                .source = source,
                .source_desc = source_desc,
                .target_desc = target_desc,
                .target_layout = target_layout,
                .source_mode = .borrow,
                .next = next,
            } });
            return try self.prependOptionalDescriptorMaterialization(target_desc_info.materialize, unbox);
        }

        if (!source_is_box and target_is_box) {
            const source_desc = try self.descriptorRefForSourceStorageLocalRep(source, rep_id);
            const target_desc_info = try self.descriptorRefForPayloadStorageTarget(target, rep_id);
            const target_desc = target_desc_info.desc orelse
                boxyLowerInvariant("boxy tag payload storage box had no target descriptor");
            self.parent.result.store.setLocalBoxyDesc(target, target_desc);
            const box = try self.parent.result.store.addCFStmt(.{ .assign_boxy_box = .{
                .target = target,
                .payload = source,
                .payload_layout = source_layout,
                .source_desc = if (std.meta.eql(source_desc, target_desc)) null else source_desc,
                .payload_desc = target_desc,
                .payload_mode = .borrow,
                .next = next,
            } });
            return try self.prependOptionalDescriptorMaterialization(target_desc_info.materialize, box);
        }

        boxyLowerInvariant("boxy tag payload storage conversion saw incompatible non-box layouts");
    }

    fn directCallHiddenDescriptorUsesCallShape(
        self: *ProcBodyBuilder,
        arg: Plan.DirectCallHiddenDescriptorArg,
    ) bool {
        const identity_worker_rep = self.descriptorStorageRep(arg.worker_rep);
        const worker_rep = self.parent.plan.representations.items[@intFromEnum(identity_worker_rep)];
        return worker_rep.kind == .dynamic and worker_rep.children.len == 0 and worker_rep.tag_variants.len == 0;
    }

    fn bindDirectCallHiddenDescriptorLocals(
        self: *ProcBodyBuilder,
        hidden_args: []const Plan.DirectCallHiddenDescriptorArg,
        hidden_locals: []const DescriptorArgLocal,
        bind_worker_reps: bool,
    ) Allocator.Error!void {
        if (hidden_args.len != hidden_locals.len) {
            boxyLowerInvariant("boxy direct call hidden descriptor local count disagreed with hidden descriptor plan");
        }

        try self.ensureDescriptorLocals();
        var seen = collections.DenseMap(Plan.DescriptorRequirementId, LIR.LocalId).init(self.parent.allocator);
        defer seen.deinit();

        for (hidden_args, hidden_locals) |arg, hidden| {
            const entry = try seen.getOrPut(arg.worker_desc);
            if (entry.found_existing) {
                if (entry.value_ptr.* != hidden.local) {
                    boxyLowerInvariant("boxy direct call mapped one worker descriptor to two hidden locals");
                }
            } else {
                entry.value_ptr.* = hidden.local;
            }

            const local_rep = self.directCallHiddenDescriptorLocalRep(arg, hidden);
            try self.bindDescriptorRequirementLocalForRep(arg.worker_desc, local_rep, hidden.local, false);
            if (self.repOwnsDescriptor(local_rep, arg.worker_desc)) {
                try self.bindDescriptorIdentityLocalForRep(local_rep, hidden.local, false);
            }
            if (self.directCallHiddenDescriptorUsesCallShape(arg) and self.descriptorStorageRep(arg.worker_rep) != self.descriptorStorageRep(local_rep)) {
                if (!bind_worker_reps and try self.repQuery().repSubtreeContainsRep(local_rep, arg.worker_rep)) continue;
                try self.bindDescriptorRequirementLocalForRep(arg.worker_desc, arg.worker_rep, hidden.local, false);
                if (self.repOwnsDescriptor(arg.worker_rep, arg.worker_desc)) {
                    try self.bindDescriptorIdentityLocalForRep(arg.worker_rep, hidden.local, false);
                }
            }
        }
    }

    fn directCallHiddenDescriptorLocalRep(
        self: *ProcBodyBuilder,
        arg: Plan.DirectCallHiddenDescriptorArg,
        hidden: DescriptorArgLocal,
    ) Plan.TypeRepId {
        if (hidden.from_source_value or self.directCallHiddenDescriptorUsesCallShape(arg)) return arg.rep;
        return arg.worker_rep;
    }

    fn lowerDirectCallHiddenDictionaryArgs(
        self: *ProcBodyBuilder,
        hidden_args: []const Plan.DirectCallHiddenDictionaryArg,
    ) Allocator.Error![]DictionaryArgLocal {
        const lowered = try self.parent.allocator.alloc(DictionaryArgLocal, hidden_args.len);
        errdefer self.parent.allocator.free(lowered);

        for (hidden_args, lowered) |arg, *local| {
            const dict_ref: LIR.BoxyDictRef = switch (arg.source) {
                .bound_dictionaries => |dictionaries| blk: {
                    if (dictionaries.len == 0) {
                        boxyLowerInvariant("boxy direct call bound dictionary source was empty");
                    }
                    const first: Plan.DictionaryRequirementId = @enumFromInt(dictionaries.start);
                    if (!self.dictionaryBindingIsBound(first)) {
                        boxyLowerInvariant("boxy direct call dictionary source was not bound in the enclosing worker");
                    }
                    const dict_local = self.dictionaryLocalForRequirementOrNull(first) orelse
                        boxyLowerInvariant("boxy direct call bound dictionary source had no local");
                    break :blk .{ .local = dict_local };
                },
                .static_rep => |source_rep| try self.parent.staticDictRefForRepWithEvidence(
                    source_rep,
                    arg.worker_dictionaries,
                    arg.method_evidence,
                ),
            };
            local.* = switch (dict_ref) {
                .local => |dict_local| blk: {
                    if (self.parent.result.store.getLocal(dict_local).layout_idx != .opaque_ptr) {
                        boxyLowerInvariant("boxy hidden dictionary local was not opaque_ptr");
                    }
                    break :blk .{ .local = dict_local };
                },
                .static => blk: {
                    const materialized = (try self.reserveDictionarySlotForSpan(arg.worker_dictionaries)) orelse try self.addFrameLocal(.opaque_ptr);
                    break :blk .{
                        .local = materialized,
                        .materialize = dict_ref,
                    };
                },
            };
        }

        return lowered;
    }

    fn descriptorRefForKnownRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!LIR.BoxyDescRef {
        const identity_rep = self.parent.descriptorIdentityRep(rep_id);
        const rep = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
        if (rep.descriptor) |desc| {
            if (self.descriptorBindingIsBoundForRep(identity_rep)) {
                if (self.descriptorLocalForRequirementAndRepOrNull(desc, identity_rep)) |local| return .{ .local = local };
                if (try self.descriptorTemplateNeedsCapturesForKnownRep(identity_rep)) {
                    boxyLowerInvariant("boxy runtime-bound descriptor requirement had no matching local");
                }
            }
        }
        return try self.parent.staticDescRefForRep(identity_rep);
    }

    fn descriptorRefForSourceLocalRep(
        self: *ProcBodyBuilder,
        source: LIR.LocalId,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!LIR.BoxyDescRef {
        // A descriptor attached to the source local describes the actual
        // value and takes precedence over anything rep-derived—including
        // for representations that carry no descriptor requirement of their
        // own (fully known at this site).
        if (self.localEnvironmentDescriptorForRep(source, rep_id)) |local| return .{ .local = local };
        if (self.parent.result.store.getLocal(source).boxy_desc) |source_desc| return source_desc;
        const identity_rep = self.parent.descriptorIdentityRep(rep_id);
        return try self.descriptorRefForKnownRep(identity_rep);
    }

    fn staticDescriptorPayloadLayout(
        self: *const ProcBodyBuilder,
        desc: LIR.BoxyDescRef,
    ) ?layout.Idx {
        return switch (desc) {
            .static => |desc_id| blk: {
                const index = @intFromEnum(desc_id);
                if (index >= self.parent.result.boxy_type_descs.items.len) {
                    boxyLowerInvariant("static boxy descriptor id exceeded descriptor table");
                }
                break :blk self.parent.result.boxy_type_descs.items[index].payload_layout;
            },
            .local,
            .runtime,
            .dict_method_arg,
            .dict_method_hidden,
            => null,
        };
    }

    fn descriptorRefForSourceStorageLocalRep(
        self: *ProcBodyBuilder,
        source: LIR.LocalId,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!LIR.BoxyDescRef {
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        if (self.parent.result.store.getLocal(source).boxy_desc) |existing| {
            if (self.staticDescriptorPayloadLayout(existing)) |payload_layout| {
                if (payload_layout == source_layout) return existing;
            } else {
                return existing;
            }
        }
        if (self.localEnvironmentDescriptorForRep(source, rep_id)) |local| return .{ .local = local };

        const source_desc_rep = self.parent.tagPayloadStorageDescRepForLayout(rep_id, source_layout, true) orelse
            boxyLowerInvariant("boxy tag payload storage source descriptor did not match source layout");
        const source_desc = try self.descriptorRefForKnownRep(source_desc_rep);
        self.parent.result.store.setLocalBoxyDesc(source, source_desc);
        return source_desc;
    }

    fn descriptorMaterializationForSourceStorageLocalRep(
        self: *ProcBodyBuilder,
        source: LIR.LocalId,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!DescriptorMaterialization {
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        if (self.parent.result.store.getLocal(source).boxy_desc) |existing| {
            if (self.staticDescriptorPayloadLayout(existing)) |payload_layout| {
                if (payload_layout == source_layout) return .{ .desc = existing };
            } else {
                return .{ .desc = existing };
            }
        }
        if (self.localEnvironmentDescriptorForRep(source, rep_id)) |local| return .{ .desc = .{ .local = local } };

        const known = try self.descriptorMaterializationForKnownRep(rep_id);
        if (self.staticDescriptorPayloadLayout(known.desc)) |payload_layout| {
            if (payload_layout == source_layout) return known;
        }

        const source_desc_rep = self.parent.tagPayloadStorageDescRepForLayout(rep_id, source_layout, true) orelse
            boxyLowerInvariant("boxy source descriptor materialization did not match source storage layout");
        return try self.descriptorMaterializationForKnownRep(source_desc_rep);
    }

    fn descriptorRefForLocalOrKnownRep(
        self: *ProcBodyBuilder,
        source: LIR.LocalId,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!LIR.BoxyDescRef {
        const identity_rep = self.parent.descriptorIdentityRep(rep_id);
        return self.parent.result.store.getLocal(source).boxy_desc orelse
            try self.descriptorRefForKnownRep(identity_rep);
    }

    /// Whether a constructed field local could carry a runtime descriptor. A
    /// field storage layout that is itself an aggregate (struct, box, list, tag
    /// union) can receive a descriptor when its value crosses a representation
    /// boundary, so an aggregate built from such fields needs a descriptor to
    /// release them.
    fn fieldLocalMayCarryDescriptor(self: *const ProcBodyBuilder, field_local: LIR.LocalId) bool {
        return self.parent.layoutNeedsNestedBoxyDesc(self.parent.result.store.getLocal(field_local).layout_idx);
    }

    fn aggregateFieldsMayCarryDescriptor(
        self: *const ProcBodyBuilder,
        fields: []const AggregateDescriptorField,
    ) bool {
        for (fields) |field| {
            if (self.fieldLocalMayCarryDescriptor(field.local)) return true;
        }
        return false;
    }

    fn constructedAggregateDescriptorForFields(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        fields: []const AggregateDescriptorField,
    ) Allocator.Error!ConstructedAggregateDescriptor {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const rep = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
        if (rep.descriptor == null) {
            // A struct field can carry a runtime descriptor even when the
            // struct's own representation is concrete: a value converted across
            // a representation boundary threads its descriptor onto the field
            // locals, and ARC treats any descriptor-bearing local as
            // refcounted. Reconstructing such a struct concretely would leave
            // the aggregate with no descriptor, so ARC would drop it through
            // its concrete layout plan—which is a noop for the box-free
            // layout—and lose the release. Offer the representation's static
            // descriptor as a candidate the aggregate construction records; ARC
            // adopts it only when a field actually carries a descriptor, so
            // aggregates whose fields stay concrete keep the concrete plan.
            if (!self.aggregateFieldsMayCarryDescriptor(fields) and
                self.parent.result.store.getLocal(target).boxy_desc == null)
            {
                return .{};
            }
            return try self.constructedConcreteAggregateDescriptorForFields(target, identity_rep, fields);
        }

        const snapshot = try self.snapshotDescriptorBindings();
        defer snapshot.deinit(self.parent.allocator);
        defer self.restoreDescriptorBindings(snapshot);

        var field_initializers = std.ArrayList(DescriptorArgLocal).empty;
        errdefer field_initializers.deinit(self.parent.allocator);
        var overrides = std.ArrayList(DescriptorTemplateOverride).empty;
        defer overrides.deinit(self.parent.allocator);

        for (fields) |field| {
            const field_layout = self.parent.result.store.getLocal(field.local).layout_idx;
            const target_desc_rep = self.parent.tagPayloadStorageDescRepIfNeeded(field.target_rep) orelse continue;
            // The source identity describes the specialized bytes in the field;
            // the target identity names the generic descriptor requirement those
            // bytes satisfy. Only the source descriptor must match the committed
            // field layout.
            const source_desc_rep = self.parent.tagPayloadStorageDescRepForLayout(field.source_rep, field_layout, true) orelse
                boxyLowerInvariant("constructed aggregate source field had no storage descriptor representation");
            const desc_local = try self.prepareConstructedFieldDescriptorLocal(field.local, source_desc_rep, &field_initializers);
            try self.bindDescriptorIdentityLocalForRep(target_desc_rep, desc_local, false);
            const identity_desc_rep = self.parent.descriptorIdentityRep(target_desc_rep);
            var found = false;
            for (overrides.items) |override| {
                if (override.rep != identity_desc_rep) continue;
                found = true;
                break;
            }
            if (!found) {
                try overrides.append(self.parent.allocator, .{ .rep = identity_desc_rep, .local = desc_local });
            }
        }

        const materialization = try self.descriptorMaterializationForKnownRepWithOverrides(identity_rep, overrides.items);
        const initializers = try field_initializers.toOwnedSlice(self.parent.allocator);
        errdefer self.parent.allocator.free(initializers);

        const target_desc_info = try self.descriptorForConstructedTargetMaterialization(target, materialization);
        return .{
            .desc = target_desc_info.desc,
            .field_initializers = initializers,
            .materialize = target_desc_info.materialize,
        };
    }

    fn constructedTagDescriptorForPayloadFields(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        fields: []const AggregateDescriptorField,
    ) Allocator.Error!ConstructedAggregateDescriptor {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const rep = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
        if (rep.descriptor == null and !rep.contains_dynamic and
            self.parent.result.store.getLocal(target).boxy_desc == null and
            !self.aggregateFieldsMayCarryDescriptor(fields))
        {
            return .{};
        }

        const snapshot = try self.snapshotDescriptorBindings();
        defer snapshot.deinit(self.parent.allocator);
        defer self.restoreDescriptorBindings(snapshot);

        var field_initializers = std.ArrayList(DescriptorArgLocal).empty;
        errdefer field_initializers.deinit(self.parent.allocator);
        var overrides = std.ArrayList(DescriptorTemplateOverride).empty;
        defer overrides.deinit(self.parent.allocator);

        for (fields) |field| {
            const field_layout = self.parent.result.store.getLocal(field.local).layout_idx;
            const target_desc_rep = self.parent.tagPayloadStorageDescRepIfNeeded(field.target_rep) orelse continue;
            const source_desc_rep = self.parent.tagPayloadStorageDescRepForLayout(field.source_rep, field_layout, true) orelse
                boxyLowerInvariant("constructed tag source payload had no storage descriptor representation");
            const desc_local = try self.prepareConstructedFieldDescriptorLocal(field.local, source_desc_rep, &field_initializers);
            try self.bindDescriptorIdentityLocalForRep(target_desc_rep, desc_local, false);
            const identity_desc_rep = self.parent.descriptorIdentityRep(target_desc_rep);
            var found = false;
            for (overrides.items) |override| {
                if (override.rep != identity_desc_rep) continue;
                found = true;
                break;
            }
            if (!found) {
                try overrides.append(self.parent.allocator, .{ .rep = identity_desc_rep, .local = desc_local });
            }
        }

        const materialization = try self.descriptorMaterializationForKnownRepWithOverrides(identity_rep, overrides.items);
        const initializers = try field_initializers.toOwnedSlice(self.parent.allocator);
        errdefer self.parent.allocator.free(initializers);
        const target_desc_info = try self.descriptorForConstructedTargetMaterialization(target, materialization);
        return .{
            .desc = target_desc_info.desc,
            .field_initializers = initializers,
            .materialize = target_desc_info.materialize,
        };
    }

    fn constructedConcreteAggregateDescriptorForFields(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        fields: []const AggregateDescriptorField,
    ) Allocator.Error!ConstructedAggregateDescriptor {
        var refs = std.ArrayList(LIR.BoxyDescRef).empty;
        defer refs.deinit(self.parent.allocator);
        var captures = std.ArrayList(LIR.LocalId).empty;
        defer captures.deinit(self.parent.allocator);
        var field_initializers = std.ArrayList(DescriptorArgLocal).empty;
        errdefer field_initializers.deinit(self.parent.allocator);

        for (fields) |field| {
            const field_layout = self.parent.result.store.getLocal(field.local).layout_idx;
            const force_field = self.parent.layoutIsBoxStorage(field_layout);
            if (!force_field and !self.parent.layoutNeedsNestedBoxyDesc(field_layout)) continue;
            const desc_rep = self.parent.tagPayloadStorageDescRepForLayout(field.source_rep, field_layout, force_field) orelse continue;
            const desc_local = try self.prepareConstructedFieldDescriptorLocal(field.local, desc_rep, &field_initializers);
            try refs.append(self.parent.allocator, .{ .local = desc_local });
            try appendUniqueLocal(self.parent.allocator, &captures, desc_local);
        }

        if (refs.items.len == 0) {
            const initializers = try field_initializers.toOwnedSlice(self.parent.allocator);
            errdefer self.parent.allocator.free(initializers);
            const target_desc_info = try self.descriptorForConstructedTargetMaterialization(
                target,
                try self.descriptorMaterializationForKnownRep(rep_id),
            );
            return .{
                .desc = target_desc_info.desc,
                .field_initializers = initializers,
                .materialize = target_desc_info.materialize,
            };
        }

        const nested_start: u32 = @intCast(self.parent.result.boxy_desc_refs.items.len);
        try self.parent.result.boxy_desc_refs.appendSlice(self.parent.allocator, refs.items);

        const desc_id: LIR.BoxyTypeDescId = @enumFromInt(@as(u32, @intCast(self.parent.result.boxy_type_descs.items.len)));
        const payload_layout = self.parent.descriptorPayloadLayoutForRep(rep_id);
        const layout_value = self.parent.result.layouts.getLayout(payload_layout);
        const rep = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        try self.parent.result.boxy_type_descs.append(self.parent.allocator, .{
            .payload_layout = payload_layout,
            .contains_refcounted = self.parent.result.layouts.layoutContainsRefcounted(layout_value) or rep.contains_dynamic,
            .nested_descs = .{ .start = nested_start, .len = @intCast(refs.items.len) },
            .field_names = try self.parent.staticFieldNamesForRep(rep_id),
            .inspect_opaque = self.parent.repInspectsOpaque(rep_id),
            .debug_checked_type = rep.source_type.ty,
        });
        const capture_span = if (captures.items.len == 0)
            LIR.LocalSpan.empty()
        else
            try self.parent.result.store.addLocalSpan(captures.items);
        const initializers = try field_initializers.toOwnedSlice(self.parent.allocator);
        errdefer self.parent.allocator.free(initializers);
        const target_desc_info = try self.descriptorForConstructedTargetMaterialization(target, .{
            .desc = .{ .static = desc_id },
            .captures = capture_span,
        });
        return .{
            .desc = target_desc_info.desc,
            .field_initializers = initializers,
            .materialize = target_desc_info.materialize,
        };
    }

    fn prepareConstructedFieldDescriptorLocal(
        self: *ProcBodyBuilder,
        value: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        initializers: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!LIR.LocalId {
        if (self.parent.result.store.getLocal(value).boxy_desc) |desc| {
            if (desc.localOrNull()) |local| return local;

            const desc_local = try self.addFrameLocal(.opaque_ptr);
            try initializers.append(self.parent.allocator, .{
                .local = desc_local,
                .materialize = desc,
            });
            return desc_local;
        }

        const initial = try self.descriptorMaterializationForKnownRep(rep_id);
        const desc_local = try self.addFrameLocal(.opaque_ptr);
        try self.recordDescriptorLocalTemplate(desc_local, initial);
        if (self.parent.layoutNeedsNestedBoxyDesc(self.parent.result.store.getLocal(value).layout_idx)) {
            self.parent.result.store.setLocalBoxyDesc(value, .{ .local = desc_local });
        }
        try initializers.append(self.parent.allocator, .{
            .local = desc_local,
            .materialize = initial.desc,
            .captures = initial.captures,
        });
        return desc_local;
    }

    fn descriptorMaterializationForKnownRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!DescriptorMaterialization {
        return try self.descriptorMaterializationForKnownRepExcludingLocal(rep_id, null);
    }

    fn descriptorMaterializationForKnownRepExcludingLocal(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        excluded_local: ?LIR.LocalId,
    ) Allocator.Error!DescriptorMaterialization {
        const identity_rep = self.parent.descriptorIdentityRep(rep_id);
        const rep = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
        if (rep.descriptor) |desc| {
            if (self.descriptorBindingIsBoundForRep(identity_rep)) {
                if (self.descriptorLocalForRequirementAndRepOrNull(desc, identity_rep)) |local| {
                    if (local != excluded_local) {
                        return .{ .desc = .{ .local = local } };
                    }
                }
            }
        }
        if (!try self.descriptorTemplateNeedsCapturesForKnownRep(identity_rep)) {
            return .{
                .desc = try self.parent.staticDescRefForRep(identity_rep),
                .captures = LIR.LocalSpan.empty(),
            };
        }

        var captures = std.ArrayList(LIR.LocalId).empty;
        defer captures.deinit(self.parent.allocator);

        var context = try self.initDescriptorTemplateContext(false);
        defer context.deinit(self.parent.allocator);
        context.excluded_local = excluded_local;

        const desc: LIR.BoxyDescRef = .{ .static = try self.descriptorTemplateTypeDescForRep(identity_rep, &captures, &context) };
        const span = if (captures.items.len == 0)
            LIR.LocalSpan{ .start = 0, .len = 0 }
        else
            try self.parent.result.store.addLocalSpan(captures.items);
        return .{
            .desc = desc,
            .captures = span,
        };
    }

    fn descriptorMaterializationForExactRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!DescriptorMaterialization {
        var captures = std.ArrayList(LIR.LocalId).empty;
        defer captures.deinit(self.parent.allocator);

        var context = try self.initDescriptorTemplateContext(true);
        defer context.deinit(self.parent.allocator);

        const desc: LIR.BoxyDescRef = .{ .static = try self.descriptorTemplateTypeDescForRep(rep_id, &captures, &context) };
        const span = if (captures.items.len == 0)
            LIR.LocalSpan.empty()
        else
            try self.parent.result.store.addLocalSpan(captures.items);
        return .{ .desc = desc, .captures = span };
    }

    fn descriptorMaterializationForKnownRepWithOverrides(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        overrides: []const DescriptorTemplateOverride,
    ) Allocator.Error!DescriptorMaterialization {
        if (overrides.len == 0) return try self.descriptorMaterializationForKnownRep(rep_id);

        const identity_rep = self.parent.descriptorIdentityRep(rep_id);
        var captures = std.ArrayList(LIR.LocalId).empty;
        defer captures.deinit(self.parent.allocator);
        var context = try self.initDescriptorTemplateContext(false);
        defer context.deinit(self.parent.allocator);

        for (overrides) |override| {
            const override_rep = self.parent.descriptorIdentityRep(override.rep);
            context.forced_refs[@intFromEnum(override_rep)] = override.local;
        }

        const desc: LIR.BoxyDescRef = .{ .static = try self.descriptorTemplateTypeDescForRep(identity_rep, &captures, &context) };
        const span = if (captures.items.len == 0)
            LIR.LocalSpan.empty()
        else
            try self.parent.result.store.addLocalSpan(captures.items);
        return .{ .desc = desc, .captures = span };
    }

    fn descriptorTemplateNeedsCapturesForKnownRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!bool {
        const visited = try self.parent.allocator.alloc(bool, self.parent.plan.representations.items.len);
        defer self.parent.allocator.free(visited);
        @memset(visited, false);

        return self.descriptorTemplateBodyNeedsCaptures(rep_id, visited);
    }

    fn descriptorTemplateRefNeedsCaptures(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        parent_desc: ?Plan.DescriptorRequirementId,
        visited: []bool,
    ) bool {
        const identity_rep = self.parent.descriptorIdentityRep(rep_id);
        const rep = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
        if (rep.descriptor) |desc| {
            if (parent_desc == null or desc != parent_desc.?) {
                if (self.descriptorBindingIsBoundForRep(identity_rep) and
                    self.descriptorLocalForRequirementAndRepOrNull(desc, identity_rep) != null) return true;
            }
        }
        return self.descriptorTemplateBodyNeedsCaptures(identity_rep, visited);
    }

    fn descriptorTemplateBodyNeedsCaptures(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        visited: []bool,
    ) bool {
        const identity_rep = self.parent.descriptorIdentityRep(rep_id);
        const rep_index = @intFromEnum(identity_rep);
        if (visited[rep_index]) return false;
        visited[rep_index] = true;

        const rep = self.parent.plan.representations.items[rep_index];
        const current_desc = rep.descriptor;
        const rep_layout = self.parent.layout_plan.rep_layouts[rep_index];
        const payload_layout = rep_layout.descriptor_payload_layout orelse rep_layout.worker.layoutIdx();
        if (self.parent.descriptorBackingShapeRep(identity_rep)) |backing_rep| {
            return self.descriptorTemplateBodyNeedsCaptures(backing_rep, visited);
        }

        if (rep.declared_fields.len != 0) {
            for (self.parent.plan.declaredFieldSlice(rep.declared_fields)) |field| {
                const field_layout = self.parent.recordPayloadFieldLayout(payload_layout, field.index);
                const force_field = self.parent.layoutIsBoxStorage(field_layout);
                const desc_rep = self.parent.tagPayloadStorageDescRepForLayout(field.rep, field_layout, force_field) orelse continue;
                if (self.descriptorTemplateRefNeedsCaptures(desc_rep, current_desc, visited)) return true;
            }
        } else {
            var record_field_index: usize = 0;
            for (self.parent.plan.childSlice(rep.children)) |child| {
                if (child.role == .tag_ext) continue;
                const field_layout = switch (child.role) {
                    .record_field => blk: {
                        const field_layout = self.parent.recordPayloadFieldLayout(payload_layout, record_field_index);
                        record_field_index += 1;
                        break :blk field_layout;
                    },
                    .tuple_elem => |index| self.parent.recordPayloadFieldLayout(payload_layout, index),
                    .box_payload => self.parent.descriptorPayloadLayoutForRep(child.rep),
                    .list_elem => self.parent.listElementLayout(payload_layout),
                    .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_ext, .function_arg, .function_ret, .tag_payload, .tag_ext => continue,
                };
                const force_desc = child.role == .box_payload or self.parent.layoutIsBoxStorage(field_layout);
                const desc_rep = self.parent.tagPayloadStorageDescRepForLayout(child.rep, field_layout, force_desc) orelse continue;
                if (self.descriptorTemplateRefNeedsCaptures(desc_rep, current_desc, visited)) return true;
            }
        }

        const layout_value = self.parent.result.layouts.getLayout(payload_layout);
        const tag_layout = switch (layout_value.tag) {
            .tag_union => layout_value,
            .box => self.parent.result.layouts.getLayout(layout_value.getIdx()),
            .scalar, .box_of_zst, .erased_box, .list, .list_of_zst, .struct_, .closure, .erased_callable, .zst, .ptr => return false,
        };
        if (tag_layout.tag != .tag_union) return false;

        const tag_rep_id = self.parent.tagVariantRepForDesc(identity_rep);
        const tag_rep = self.parent.plan.representations.items[@intFromEnum(tag_rep_id)];
        if (tag_rep.kind == .bool_tag_union) return false;
        const tag_info = self.parent.result.layouts.getTagUnionInfo(tag_layout);

        for (self.parent.plan.tagVariantSlice(tag_rep.tag_variants), 0..) |variant, variant_index| {
            const variant_payload_layout = tag_info.variants.get(variant_index).payload_layout;
            const payloads = self.parent.plan.childSlice(variant.payloads);
            for (payloads, 0..) |child, payload_index| {
                const field_layout = self.parent.tagVariantPayloadFieldLayout(variant_payload_layout, payload_index, payloads.len);
                const desc_rep = self.parent.tagPayloadStorageDescRepForLayout(child.rep, field_layout, true) orelse continue;
                if (self.descriptorTemplateRefNeedsCaptures(desc_rep, current_desc, visited)) return true;
            }
        }

        var found_ext: ?Plan.TypeRepId = null;
        for (self.parent.plan.childSlice(tag_rep.children)) |child| {
            if (child.role != .tag_ext) continue;
            if (found_ext != null) boxyLowerInvariant("boxy descriptor capture probe saw duplicate tag extension children");
            found_ext = child.rep;
        }
        const ext_rep_id = found_ext orelse return false;
        if (ext_rep_id == tag_rep_id) return false;

        const ext_rep = self.parent.plan.representations.items[@intFromEnum(ext_rep_id)];
        if (ext_rep.kind == .empty_tag_union) return false;
        return self.descriptorTemplateRefNeedsCaptures(ext_rep_id, current_desc, visited);
    }

    fn descriptorMaterializationForSourceRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!DescriptorMaterialization {
        const identity_rep = self.parent.descriptorIdentityRep(rep_id);
        const rep = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
        if (rep.descriptor != null) {
            if (!self.descriptorBindingIsBoundForRep(identity_rep)) {
                return try self.descriptorMaterializationForKnownRep(identity_rep);
            }
        }
        return .{
            .desc = try self.descriptorRefForKnownRep(identity_rep),
            .captures = LIR.LocalSpan.empty(),
        };
    }

    fn prependDescriptorRebindForRepFromRep(
        self: *ProcBodyBuilder,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const reservation = try self.reserveDescriptorLocalForRepWithFresh(target_rep) orelse return next;
        const target_desc_local = reservation.local;
        if (self.localIsReadOnlyDescriptorInput(target_desc_local)) return next;
        const target_rep_info = self.parent.plan.representations.items[@intFromEnum(target_rep)];
        if (target_rep_info.descriptor != null) {
            if (self.descriptorBindingIsBoundForRep(target_rep)) return next;
        }
        const materialization = try self.descriptorMaterializationForSourceRep(source_rep);
        return try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
            .target = target_desc_local,
            .desc = materialization.desc,
            .captures = materialization.captures,
            .next = next,
        } });
    }

    fn initDescriptorTemplateContext(self: *ProcBodyBuilder, exact_storage: bool) Allocator.Error!DescriptorTemplateContext {
        const forced_refs = try self.parent.allocator.alloc(?LIR.LocalId, self.parent.plan.representations.items.len);
        errdefer self.parent.allocator.free(forced_refs);
        const exact_reps = try self.parent.allocator.alloc(?Plan.TypeRepId, self.parent.plan.representations.items.len);
        @memset(forced_refs, null);
        @memset(exact_reps, null);
        return .{
            .ids = std.AutoHashMap(DescriptorTemplateDescKey, LIR.BoxyTypeDescId).init(self.parent.allocator),
            .env_ids = std.AutoHashMap(DescriptorTemplateEnvKey, DescriptorTemplateEnvId).init(self.parent.allocator),
            .bindings = std.ArrayList(DescriptorTemplateBinding).empty,
            .forced_refs = forced_refs,
            .exact_reps = exact_reps,
            .exact_storage = exact_storage,
        };
    }

    fn descriptorTemplateExactRep(
        _: *const ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        context: *const DescriptorTemplateContext,
    ) Plan.TypeRepId {
        if (!context.exact_storage) return rep_id;

        var current = rep_id;
        var remaining = context.exact_reps.len;
        while (context.exact_reps[@intFromEnum(current)]) |next| {
            if (remaining == 0) {
                boxyLowerInvariant("boxy exact descriptor substitutions contained a cycle");
            }
            current = next;
            remaining -= 1;
        }
        return current;
    }

    /// Bind this representation's nominal backing formals to the arguments it
    /// supplies, for the descriptors nested inside it.
    ///
    /// A backing shape is written once against its declaration's formals and
    /// reached once per instantiation, so one template can descend through the
    /// same nominal at two argument sets and each descent binds the formals its
    /// own way. The bindings therefore last exactly as long as the descent that
    /// made them, and the returned scope is what undoes them.
    fn pushDescriptorTemplateExactReps(
        self: *const ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        context: *DescriptorTemplateContext,
    ) Allocator.Error!DescriptorTemplateScope {
        const scope = DescriptorTemplateScope{
            .bindings_start = context.bindings.items.len,
            .env = context.env,
        };
        if (!context.exact_storage) return scope;

        const rep = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        for (self.parent.plan.nominalBackingArgSubstitutionSlice(rep.nominal_backing_arg_substitutions)) |substitution| {
            if (substitution.formal_rep == substitution.actual_rep) continue;
            const slot = &context.exact_reps[@intFromEnum(substitution.formal_rep)];
            if (slot.*) |existing| {
                if (existing == substitution.actual_rep) continue;
            }
            try context.bindings.append(self.parent.allocator, .{
                .formal = substitution.formal_rep,
                .outer = slot.*,
            });
            slot.* = substitution.actual_rep;

            const key = DescriptorTemplateEnvKey{
                .parent = context.env,
                .formal = substitution.formal_rep,
                .actual = substitution.actual_rep,
            };
            const entry = try context.env_ids.getOrPut(key);
            if (!entry.found_existing) {
                entry.value_ptr.* = @enumFromInt(@as(u32, @intCast(context.env_ids.count())));
            }
            context.env = entry.value_ptr.*;
        }
        return scope;
    }

    /// Restore the bindings and environment a descent replaced.
    fn popDescriptorTemplateExactReps(
        context: *DescriptorTemplateContext,
        scope: DescriptorTemplateScope,
    ) void {
        var index = context.bindings.items.len;
        while (index > scope.bindings_start) {
            index -= 1;
            const binding = context.bindings.items[index];
            context.exact_reps[@intFromEnum(binding.formal)] = binding.outer;
        }
        context.bindings.shrinkRetainingCapacity(scope.bindings_start);
        context.env = scope.env;
    }

    fn descriptorTemplateRefForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        parent_desc: ?Plan.DescriptorRequirementId,
        captures: *std.ArrayList(LIR.LocalId),
        context: *DescriptorTemplateContext,
    ) Allocator.Error!LIR.BoxyDescRef {
        const exact_rep = self.descriptorTemplateExactRep(rep_id, context);
        if (exact_rep != rep_id) {
            return try self.descriptorTemplateRefForRep(exact_rep, parent_desc, captures, context);
        }
        const identity_rep = self.parent.descriptorIdentityRep(rep_id);
        const exact_payload_layout = self.parent.descriptorTemplatePayloadLayoutForRep(rep_id);
        const identity_payload_layout = self.parent.descriptorTemplatePayloadLayoutForRep(identity_rep);
        const shares_identity_storage = exact_payload_layout == identity_payload_layout;
        const may_reuse_whole_descriptor = !context.exact_storage or self.repIsBareDynamic(rep_id);
        if (shares_identity_storage and may_reuse_whole_descriptor) {
            if (context.forced_refs[@intFromEnum(identity_rep)]) |local| {
                if (context.excluded_local == local) {
                    return .{ .static = try self.descriptorTemplateTypeDescForRep(rep_id, captures, context) };
                }
                try appendUniqueLocal(self.parent.allocator, captures, local);
                return .{ .local = local };
            }
        }
        const rep = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
        if (shares_identity_storage and may_reuse_whole_descriptor) if (rep.descriptor) |desc| {
            if (parent_desc == null or desc != parent_desc.?) {
                if (self.descriptorLocalForRequirementAndRepOrNull(desc, identity_rep)) |local| {
                    if (self.descriptorBindingIsBoundForRep(identity_rep) and context.excluded_local != local) {
                        try appendUniqueLocal(self.parent.allocator, captures, local);
                        return .{ .local = local };
                    }
                }
            }
        };
        return .{ .static = try self.descriptorTemplateTypeDescForRep(rep_id, captures, context) };
    }

    fn descriptorTemplateTypeDescForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        captures: *std.ArrayList(LIR.LocalId),
        context: *DescriptorTemplateContext,
    ) Allocator.Error!LIR.BoxyTypeDescId {
        const rep_index = @intFromEnum(rep_id);
        const scope = try self.pushDescriptorTemplateExactReps(rep_id, context);
        defer popDescriptorTemplateExactReps(context, scope);
        const desc_key = DescriptorTemplateDescKey{ .rep = rep_id, .env = context.env };
        if (context.ids.get(desc_key)) |existing| return existing;

        const desc_id: LIR.BoxyTypeDescId = @enumFromInt(@as(u32, @intCast(self.parent.result.boxy_type_descs.items.len)));
        try context.ids.put(desc_key, desc_id);
        try self.parent.result.boxy_type_descs.append(self.parent.allocator, .{
            .payload_layout = .zst,
            .contains_refcounted = false,
        });

        const payload_layout = self.parent.descriptorTemplatePayloadLayoutForRep(rep_id);
        const layout_value = self.parent.result.layouts.getLayout(payload_layout);
        const rep = self.parent.plan.representations.items[rep_index];
        const current_desc = rep.descriptor;

        const nested_descs = try self.templateNestedDescRefsForRep(rep_id, current_desc, captures, context);
        const tag_variants = try self.templateTagVariantsForRep(rep_id, payload_layout, current_desc, captures, context);
        const tag_ext_desc = try self.templateTagExtDescForRep(rep_id, current_desc, captures, context);

        // Inspect adapter emission can append more descriptors, so finish the
        // value before taking the reserved ArrayList element's address.
        const completed_desc = LirProgram.BoxyTypeDesc{
            .payload_layout = payload_layout,
            .contains_refcounted = self.parent.result.layouts.layoutContainsRefcounted(layout_value) or rep.contains_dynamic,
            .nested_descs = nested_descs,
            .tag_variants = tag_variants,
            .tag_ext_desc = tag_ext_desc,
            .field_names = try self.parent.staticFieldNamesForRep(rep_id),
            .inspect_opaque = self.parent.repInspectsOpaque(rep_id),
            .inspect_method = try self.parent.staticInspectMethodForRep(rep_id),
            .presence_slot_present_discriminant = rep.presence_slot_present_discriminant,
            .debug_checked_type = rep.source_type.ty,
        };
        self.parent.result.boxy_type_descs.items[@intFromEnum(desc_id)] = completed_desc;
        return desc_id;
    }

    fn templateNestedDescRefsForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        current_desc: ?Plan.DescriptorRequirementId,
        captures: *std.ArrayList(LIR.LocalId),
        context: *DescriptorTemplateContext,
    ) Allocator.Error!LIR.BoxySpan {
        if (self.parent.descriptorBackingShapeRep(rep_id)) |backing_rep| {
            return try self.templateNestedDescRefsForRep(backing_rep, current_desc, captures, context);
        }

        const rep = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        if (try self.parent.staticGeneratedEvidenceNestedDescRefs(rep.kind)) |nested_descs| {
            return nested_descs;
        }
        const payload_layout = self.parent.descriptorTemplatePayloadLayoutForRep(rep_id);

        var refs = std.ArrayList(LIR.BoxyDescRef).empty;
        defer refs.deinit(self.parent.allocator);
        if (rep.declared_fields.len != 0) {
            const ordered = try self.parent.declaredFieldsInLayoutOrder(
                self.parent.plan.declaredFieldSlice(rep.declared_fields),
            );
            defer self.parent.allocator.free(ordered);
            for (ordered) |field| {
                const field_layout = self.parent.recordPayloadFieldLayout(payload_layout, field.index);
                const force_field = self.parent.layoutIsBoxStorage(field_layout);
                if (!force_field and !self.parent.layoutNeedsNestedBoxyDesc(field_layout)) continue;
                const desc_rep = self.parent.tagPayloadStorageDescRepForLayout(field.rep, field_layout, force_field) orelse continue;
                try refs.append(self.parent.allocator, try self.descriptorTemplateRefForRep(desc_rep, current_desc, captures, context));
            }
        } else {
            if (rep.children.len == 0) return .{};
            var record_field_index: usize = 0;
            for (self.parent.plan.childSlice(rep.children)) |child| {
                if (child.role == .tag_ext) continue;
                const field_layout = switch (child.role) {
                    .record_field => blk: {
                        const field_layout = self.parent.recordPayloadFieldLayout(payload_layout, record_field_index);
                        record_field_index += 1;
                        break :blk field_layout;
                    },
                    .tuple_elem => |index| self.parent.recordPayloadFieldLayout(payload_layout, index),
                    .box_payload => self.parent.descriptorTemplatePayloadLayoutForRep(child.rep),
                    .list_elem => self.parent.listElementLayout(payload_layout),
                    .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_ext, .function_arg, .function_ret, .tag_payload, .tag_ext => continue,
                };
                const force_desc = child.role == .box_payload or self.parent.layoutIsBoxStorage(field_layout);
                if (!force_desc and !self.parent.layoutNeedsNestedBoxyDesc(field_layout)) continue;
                const desc_rep = if (child.role == .box_payload)
                    self.parent.tagPayloadStorageDescRep(child.rep)
                else
                    self.parent.tagPayloadStorageDescRepForLayout(child.rep, field_layout, force_desc) orelse continue;
                const desc_ref = try self.descriptorTemplateRefForRep(desc_rep, current_desc, captures, context);
                try refs.append(self.parent.allocator, desc_ref);
            }
        }
        if (refs.items.len == 0) return .{};

        const start: u32 = @intCast(self.parent.result.boxy_desc_refs.items.len);
        try self.parent.result.boxy_desc_refs.appendSlice(self.parent.allocator, refs.items);
        return .{ .start = start, .len = @intCast(refs.items.len) };
    }

    fn templateTagVariantsForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        payload_layout: layout.Idx,
        current_desc: ?Plan.DescriptorRequirementId,
        captures: *std.ArrayList(LIR.LocalId),
        context: *DescriptorTemplateContext,
    ) Allocator.Error!LIR.BoxySpan {
        const layout_value = self.parent.result.layouts.getLayout(payload_layout);
        if (layout_value.tag == .zst) {
            return try self.templateZstTagVariantsForTagRep(
                self.parent.tagVariantRepForDesc(rep_id),
                current_desc,
                captures,
                context,
            );
        }
        const tag_layout = switch (layout_value.tag) {
            .tag_union => layout_value,
            .box => self.parent.result.layouts.getLayout(layout_value.getIdx()),
            .scalar, .box_of_zst, .erased_box, .list, .list_of_zst, .struct_, .closure, .erased_callable, .zst, .ptr => return .{},
        };
        if (tag_layout.tag != .tag_union) return .{};

        const tag_rep_id = self.parent.tagVariantRepForDesc(rep_id);
        const rep = self.parent.plan.representations.items[@intFromEnum(tag_rep_id)];
        if (rep.kind == .bool_tag_union) {
            return try self.parent.staticTagVariantsForRep(rep_id, payload_layout);
        }

        const variants = self.parent.plan.tagVariantSlice(rep.tag_variants);
        if (variants.len == 0) return .{};

        const tag_info = self.parent.result.layouts.getTagUnionInfo(tag_layout);
        const has_ext = (try self.templateTagExtDescForTagRep(tag_rep_id, current_desc, captures, context)) != null;
        const expected_layout_variants = variants.len + @intFromBool(has_ext);
        if (tag_info.variants.len != expected_layout_variants) {
            boxyLowerInvariant("boxy descriptor template variant count disagreed with committed layout");
        }

        var entries = std.ArrayList(LirProgram.BoxyTagVariant).empty;
        defer entries.deinit(self.parent.allocator);

        for (variants, 0..) |variant, index| {
            const variant_payload_layout = tag_info.variants.get(index).payload_layout;
            try entries.append(self.parent.allocator, .{
                .name = try self.parent.result.store.insertString(self.tagVariantNameText(variant)),
                .discriminant = @intCast(index),
                .payload_count = @intCast(self.parent.plan.childSlice(variant.payloads).len),
                .payload_layout = variant_payload_layout,
                .payload_descs = try self.templatePayloadDescRefsForTagVariant(
                    variant,
                    variant_payload_layout,
                    current_desc,
                    captures,
                    context,
                ),
            });
        }

        const start: u32 = @intCast(self.parent.result.boxy_tag_variants.items.len);
        try self.parent.result.boxy_tag_variants.appendSlice(self.parent.allocator, entries.items);
        return .{ .start = start, .len = @intCast(entries.items.len) };
    }

    fn templateZstTagVariantsForTagRep(
        self: *ProcBodyBuilder,
        tag_rep_id: Plan.TypeRepId,
        current_desc: ?Plan.DescriptorRequirementId,
        captures: *std.ArrayList(LIR.LocalId),
        context: *DescriptorTemplateContext,
    ) Allocator.Error!LIR.BoxySpan {
        const rep = self.parent.plan.representations.items[@intFromEnum(tag_rep_id)];
        const variants = self.parent.plan.tagVariantSlice(rep.tag_variants);
        if (variants.len == 0) return .{};
        if (variants.len != 1) {
            boxyLowerInvariant("zero-sized boxy descriptor template had multiple tag variants");
        }

        const variant = variants[0];
        const payload_descs = try self.templatePayloadDescRefsForTagVariant(
            variant,
            .zst,
            current_desc,
            captures,
            context,
        );
        const name = try self.parent.result.store.insertString(self.tagVariantNameText(variant));
        const start: u32 = @intCast(self.parent.result.boxy_tag_variants.items.len);
        try self.parent.result.boxy_tag_variants.append(self.parent.allocator, .{
            .name = name,
            .discriminant = 0,
            .payload_count = @intCast(self.parent.plan.childSlice(variant.payloads).len),
            .payload_layout = .zst,
            .payload_descs = payload_descs,
        });
        return .{ .start = start, .len = 1 };
    }

    fn templateTagExtDescForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        current_desc: ?Plan.DescriptorRequirementId,
        captures: *std.ArrayList(LIR.LocalId),
        context: *DescriptorTemplateContext,
    ) Allocator.Error!?LIR.BoxyDescRef {
        const tag_rep_id = self.parent.tagVariantRepForDesc(rep_id);
        return try self.templateTagExtDescForTagRep(tag_rep_id, current_desc, captures, context);
    }

    fn templateTagExtDescForTagRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        current_desc: ?Plan.DescriptorRequirementId,
        captures: *std.ArrayList(LIR.LocalId),
        context: *DescriptorTemplateContext,
    ) Allocator.Error!?LIR.BoxyDescRef {
        const rep = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        if (rep.kind == .bool_tag_union) return null;
        if (rep.tag_variants.len == 0 and rep.kind != .tag_union and rep.kind != .dynamic) return null;

        var found: ?Plan.TypeRepId = null;
        for (self.parent.plan.childSlice(rep.children)) |child| {
            if (child.role != .tag_ext) continue;
            if (found != null) boxyLowerInvariant("boxy descriptor template tag representation had duplicate row extension children");
            found = child.rep;
        }
        const ext_rep_id = found orelse return null;
        if (ext_rep_id == rep_id) return null;

        const ext_rep = self.parent.plan.representations.items[@intFromEnum(ext_rep_id)];
        if (ext_rep.kind == .empty_tag_union) return null;
        return try self.descriptorTemplateRefForRep(ext_rep_id, current_desc, captures, context);
    }

    fn templatePayloadDescRefsForTagVariant(
        self: *ProcBodyBuilder,
        variant: Plan.TagVariant,
        variant_payload_layout: layout.Idx,
        current_desc: ?Plan.DescriptorRequirementId,
        captures: *std.ArrayList(LIR.LocalId),
        context: *DescriptorTemplateContext,
    ) Allocator.Error!LIR.BoxySpan {
        const payloads = self.parent.plan.childSlice(variant.payloads);
        if (payloads.len == 0) return .{};

        var descs = std.ArrayList(LirProgram.BoxyTagPayloadDesc).empty;
        defer descs.deinit(self.parent.allocator);
        for (payloads, 0..) |child, index| {
            const field_layout = self.parent.tagVariantPayloadFieldLayout(variant_payload_layout, index, payloads.len);
            // Match the static descriptor path: a concrete tag payload may flow
            // into a worker whose view of that payload is erased, so the
            // descriptor template must be able to capture the runtime payload
            // descriptor even when the payload's own representation would not
            // otherwise require one.
            const desc_rep = self.parent.tagPayloadStorageDescRepForLayout(child.rep, field_layout, true) orelse continue;
            const desc_ref = try self.descriptorTemplateRefForRep(desc_rep, current_desc, captures, context);
            try descs.append(self.parent.allocator, .{
                .payload_index = @intCast(index),
                .desc = desc_ref,
            });
        }
        if (descs.items.len == 0) return .{};

        const start: u32 = @intCast(self.parent.result.boxy_tag_payload_descs.items.len);
        try self.parent.result.boxy_tag_payload_descs.appendSlice(self.parent.allocator, descs.items);
        return .{ .start = start, .len = @intCast(descs.items.len) };
    }

    fn descriptorRefForRepIfNeeded(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!?LIR.BoxyDescRef {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const exact_rep = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        if (exact_rep.descriptor) |desc| {
            if (self.descriptorLocalForRequirementAndRepOrNull(desc, rep_id)) |local| {
                return .{ .local = local };
            }
            if (identity_rep != rep_id) {
                return try self.descriptorRefForKnownRep(identity_rep);
            }
            if (self.descriptorBindingIsBoundForRep(rep_id)) {
                if (try self.descriptorTemplateNeedsCapturesForKnownRep(identity_rep)) {
                    boxyLowerInvariant("bound exact boxy descriptor requirement had no matching local");
                }
            }
            return try self.parent.staticDescRefForRep(rep_id);
        }

        const rep = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
        if (rep.descriptor == null) return null;
        return try self.descriptorRefForKnownRep(identity_rep);
    }

    /// The descriptor a representation-boundary conversion records for its
    /// concrete tag-union target local. A boundary target already carries the
    /// descriptor it was allocated with, and the release plan keys one
    /// descriptor per local, so the conversion reuses that descriptor. When the
    /// exact representation reserving the target local and the identity
    /// representation the boundary was dispatched on reserve distinct
    /// descriptor requirement locals, deriving afresh from the representation
    /// would record a second descriptor for the same local. Reusing the local's
    /// own descriptor keeps a single descriptor per local. A target with no
    /// recorded descriptor yet takes the representation-derived one, which is
    /// then recorded on the local.
    fn boundaryTargetDesc(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
    ) Allocator.Error!?LIR.BoxyDescRef {
        if (self.parent.result.store.getLocal(target).boxy_desc) |existing| return existing;
        const derived = try self.descriptorRefForRepIfNeeded(target_rep) orelse return null;
        self.parent.result.store.setLocalBoxyDesc(target, derived);
        return derived;
    }

    fn dictionaryRefForKnownRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        worker_dictionaries: Plan.Span,
    ) Allocator.Error!LIR.BoxyDictRef {
        const identity_rep = self.dictionaryIdentityRep(rep_id);
        const rep = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
        if (rep.dictionaries.len != 0) {
            const first: Plan.DictionaryRequirementId = @enumFromInt(rep.dictionaries.start);
            if (self.dictionaryBindingIsBound(first)) {
                if (self.dictionaryLocalForRequirementOrNull(first)) |local| return .{ .local = local };
                boxyLowerInvariant("boxy runtime-bound dictionary requirement had no local");
            }
        }
        if (rep.kind == .dynamic) {
            // A dynamic representation has no owner to build a static
            // dictionary from; the requirement must be satisfied by the
            // enclosing worker's own dictionary binding (a recursive or
            // sibling generic call passing its dictionaries along).
            if (worker_dictionaries.len != 0) {
                const callee_first: Plan.DictionaryRequirementId = @enumFromInt(worker_dictionaries.start);
                if (self.dictionaryBindingIsBound(callee_first)) {
                    if (self.dictionaryLocalForRequirementOrNull(callee_first)) |local| return .{ .local = local };
                }
            }
            boxyLowerInvariant("boxy dynamic representation dictionary requirement was not bound in the enclosing worker");
        }
        return try self.parent.staticDictRefForRep(identity_rep, worker_dictionaries);
    }

    fn dictionaryRefForPlannedSource(
        self: *ProcBodyBuilder,
        arg: Plan.DirectCallHiddenDictionaryArg,
    ) Allocator.Error!LIR.BoxyDictRef {
        return switch (arg.source) {
            .bound_dictionaries => |dictionaries| blk: {
                if (dictionaries.len == 0) {
                    boxyLowerInvariant("boxy callable use bound dictionary source was empty");
                }
                const first: Plan.DictionaryRequirementId = @enumFromInt(dictionaries.start);
                if (!self.dictionaryBindingIsBound(first)) {
                    boxyLowerInvariant("boxy callable use dictionary source was not bound in the enclosing worker");
                }
                const local = self.dictionaryLocalForRequirementOrNull(first) orelse
                    boxyLowerInvariant("boxy callable use bound dictionary source had no local");
                break :blk .{ .local = local };
            },
            .static_rep => |source_rep| try self.parent.staticDictRefForRepWithEvidence(
                source_rep,
                arg.worker_dictionaries,
                arg.method_evidence,
            ),
        };
    }

    fn prependHiddenDescriptorArgMaterialization(
        self: *ProcBodyBuilder,
        hidden_args: []const DescriptorArgLocal,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.prependDescriptorArgMaterializations(hidden_args, next);
    }

    fn prependDescriptorArgMaterializations(
        self: *ProcBodyBuilder,
        hidden_args: []const DescriptorArgLocal,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const visit = try self.parent.allocator.alloc(DescriptorMaterializationVisit, hidden_args.len);
        defer self.parent.allocator.free(visit);
        @memset(visit, .pending);

        var order = std.ArrayList(usize).empty;
        defer order.deinit(self.parent.allocator);
        for (hidden_args, 0..) |_, index| {
            try self.appendHiddenDescriptorMaterializationOrder(hidden_args, index, visit, &order);
        }

        var continuation = next;
        var index = order.items.len;
        while (index > 0) {
            index -= 1;
            const hidden = hidden_args[order.items[index]];
            const desc = hidden.materialize orelse
                boxyLowerInvariant("boxy hidden descriptor materialization order included a descriptor with no materialization");
            continuation = try self.prependDescriptorArgMaterialization(hidden, desc, continuation);
        }
        return continuation;
    }

    fn prependDescriptorArgMaterialization(
        self: *ProcBodyBuilder,
        hidden: DescriptorArgLocal,
        desc: LIR.BoxyDescRef,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.localIsReadOnlyDescriptorInput(hidden.local)) {
            boxyLowerInvariant("boxy descriptor arg materialization targeted read-only descriptor input");
        }
        const read_path = self.parent.descriptorReadPathSlice(hidden.read_path);
        if (read_path.len == 0) {
            return try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                .target = hidden.local,
                .desc = desc,
                .nested_index = hidden.nested_index,
                .tag_ext = hidden.tag_ext,
                .tag_residual_for = hidden.tag_residual_for,
                .captures = hidden.captures,
                .next = next,
            } });
        }
        if (hidden.nested_index != null or hidden.tag_ext or hidden.tag_residual_for != null) {
            boxyLowerInvariant("boxy descriptor materialization combined a read_path path with a legacy read_path");
        }

        const intermediate_count = read_path.len - 1;
        const intermediates = try self.parent.allocator.alloc(LIR.LocalId, intermediate_count);
        defer self.parent.allocator.free(intermediates);
        for (intermediates) |*local| local.* = try self.addFrameLocal(.opaque_ptr);

        var continuation = next;
        var read_index = read_path.len;
        while (read_index > 0) {
            read_index -= 1;
            const target = if (read_index == read_path.len - 1)
                hidden.local
            else
                intermediates[read_index];
            const source_desc = if (read_index == 0)
                desc
            else
                LIR.BoxyDescRef{ .local = intermediates[read_index - 1] };
            const step = read_path[read_index];
            continuation = try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                .target = target,
                .desc = source_desc,
                .nested_index = switch (step) {
                    .nested => |nested_index| nested_index,
                    .tag_payload, .tag_ext => null,
                },
                .tag_payload = switch (step) {
                    .tag_payload => |payload| .{
                        .tag_name = payload.tag_name,
                        .payload_index = payload.payload_index,
                    },
                    .nested, .tag_ext => null,
                },
                .tag_ext = switch (step) {
                    .tag_ext => true,
                    .nested, .tag_payload => false,
                },
                .captures = if (read_index == 0) hidden.captures else LIR.LocalSpan.empty(),
                .next = continuation,
            } });
        }
        return continuation;
    }

    fn prependOptionalDescriptorMaterialization(
        self: *ProcBodyBuilder,
        maybe_hidden: ?DescriptorArgLocal,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const hidden = maybe_hidden orelse return next;
        const desc = hidden.materialize orelse
            boxyLowerInvariant("optional descriptor materialization had no descriptor");
        return try self.prependDescriptorArgMaterialization(hidden, desc, next);
    }

    fn prependWorkerReturnDescriptorInitializers(
        self: *ProcBodyBuilder,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.prependDescriptorArgMaterializations(
            self.worker_return_descriptor_initializers.items,
            next,
        );
    }

    fn appendHiddenDescriptorMaterializationOrder(
        self: *ProcBodyBuilder,
        hidden_args: []const DescriptorArgLocal,
        index: usize,
        visit: []DescriptorMaterializationVisit,
        order: *std.ArrayList(usize),
    ) Allocator.Error!void {
        switch (visit[index]) {
            .done => return,
            .visiting => boxyLowerInvariant("boxy hidden descriptor materializations contained a dependency cycle"),
            .pending => {},
        }

        visit[index] = .visiting;
        const hidden = hidden_args[index];
        if (hidden.materialize) |materialize| {
            if (materialize.localOrNull()) |desc_local| {
                if (desc_local != hidden.local) {
                    if (self.hiddenDescriptorMaterializationIndexForLocal(hidden_args, desc_local)) |dependency| {
                        try self.appendHiddenDescriptorMaterializationOrder(hidden_args, dependency, visit, order);
                    }
                }
            }
            if (hidden.tag_residual_for) |target_desc| {
                if (target_desc.localOrNull()) |desc_local| {
                    if (desc_local != hidden.local) {
                        if (self.hiddenDescriptorMaterializationIndexForLocal(hidden_args, desc_local)) |dependency| {
                            try self.appendHiddenDescriptorMaterializationOrder(hidden_args, dependency, visit, order);
                        }
                    }
                }
            }
            const captures = self.parent.result.store.getLocalSpan(hidden.captures);
            for (0..GuardedList.borrowLen(captures)) |capture_index| {
                const capture = GuardedList.at(captures, capture_index);
                if (self.hiddenDescriptorMaterializationIndexForLocal(hidden_args, capture)) |dependency| {
                    try self.appendHiddenDescriptorMaterializationOrder(hidden_args, dependency, visit, order);
                }
            }
            try order.append(self.parent.allocator, index);
        }
        visit[index] = .done;
    }

    fn hiddenDescriptorMaterializationIndexForLocal(
        _: *ProcBodyBuilder,
        hidden_args: []const DescriptorArgLocal,
        local: LIR.LocalId,
    ) ?usize {
        for (hidden_args, 0..) |hidden, index| {
            if (hidden.local == local and hidden.materialize != null) return index;
        }
        return null;
    }

    fn prependHiddenDictionaryArgMaterialization(
        self: *ProcBodyBuilder,
        hidden_args: []const DictionaryArgLocal,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var continuation = next;
        var index = hidden_args.len;
        while (index > 0) {
            index -= 1;
            const hidden = hidden_args[index];
            if (hidden.materialize) |dict| {
                continuation = try self.parent.result.store.addCFStmt(.{ .assign_boxy_dict_ref = .{
                    .target = hidden.local,
                    .dict = dict,
                    .next = continuation,
                } });
            }
        }
        return continuation;
    }

    fn prependLoweredExprs(
        self: *ProcBodyBuilder,
        args: []const checked.CheckedExprId,
        lowered: []const LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (args.len != lowered.len) {
            boxyLowerInvariant("boxy lowered expression locals disagreed with source expression count");
        }
        var continuation = next;
        var index = args.len;
        while (index > 0) {
            index -= 1;
            continuation = try self.lowerExprInto(lowered[index], args[index], continuation);
        }
        return continuation;
    }

    fn prependLoweredCallOperandsExpected(
        self: *ProcBodyBuilder,
        operands: []const Plan.CallOperand,
        operand_types: []const Plan.CheckedTypeIdentity,
        arg_types: []const Plan.CheckedTypeIdentity,
        storage_arg_reps: []const Plan.TypeRepId,
        lowered: []const LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (operands.len != lowered.len or operands.len != operand_types.len or operands.len != arg_types.len or operands.len != storage_arg_reps.len) {
            boxyLowerInvariant("boxy expected lowered expression locals disagreed with source expression count");
        }
        var continuation = next;
        var index = operands.len;
        while (index > 0) {
            index -= 1;
            const operand_rep = self.repForTypeRef(operand_types[index]);
            continuation = switch (operands[index]) {
                .checked_expr => |arg| if (storage_arg_reps[index] == operand_rep)
                    try self.lowerExprExpectedTypeRefInto(lowered[index], arg_types[index], arg, continuation)
                else
                    try self.lowerExprStorageRepInto(lowered[index], storage_arg_reps[index], arg, continuation),
                .generated_quote => |literal| try self.assignStringLiteral(lowered[index], literal, continuation),
                .generated_numeral => |literal| try self.lowerGeneratedNumeralInto(
                    lowered[index],
                    storage_arg_reps[index],
                    literal,
                    continuation,
                ),
                .generated_interpolation_iter => |expr| try self.parent.lowerGeneratedInterpolationIterInto(
                    self,
                    lowered[index],
                    storage_arg_reps[index],
                    expr,
                    continuation,
                ),
            };
        }
        return continuation;
    }

    fn boolSwitchNoContinuation(
        self: *ProcBodyBuilder,
        cond: LIR.LocalId,
        true_body: LIR.CFStmtId,
        false_body: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const branches = [_]LIR.CFSwitchBranch{.{ .value = 1, .body = true_body }};
        return try self.parent.result.store.addCFStmt(.{ .switch_stmt = .{
            .cond = cond,
            .branches = try self.parent.result.store.addCFSwitchBranches(&branches),
            .default_branch = false_body,
            .continuation = null,
        } });
    }

    fn lowerDbgExprInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        child: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const after_dbg = try self.assignZst(target, next);
        const message = try self.addFrameLocal(.str);
        const debug_stmt = try self.parent.result.store.addCFStmt(.{ .debug = .{
            .message = message,
            .next = after_dbg,
        } });
        return try self.lowerInspectExprInto(message, child, debug_stmt);
    }

    fn lowerExpectExprInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        child: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const after = try self.assignZst(target, next);
        return try self.lowerExpectStmt(child, after);
    }

    fn lowerExpectStmt(
        self: *ProcBodyBuilder,
        child: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const child_expr = self.module.checked_bodies.expr(child);
        const cond = try self.addFrameLocalForType(child_expr.ty);
        const expect_stmt = try self.parent.result.store.addCFStmt(.{ .expect = .{
            .condition = cond,
            .next = next,
        } });
        return try self.lowerExprInto(cond, child, expect_stmt);
    }

    fn lowerExpectErrInto(
        self: *ProcBodyBuilder,
        child: checked.CheckedExprId,
        snippet: checked.CheckedStringLiteralId,
    ) Allocator.Error!LIR.CFStmtId {
        const child_expr = self.module.checked_bodies.expr(child);
        const child_local = try self.addFrameLocalForType(child_expr.ty);
        const rendered = try self.addFrameLocal(.str);
        const prefix = try self.addFrameLocal(.str);
        const with_value = try self.addFrameLocal(.str);
        const suffix = try self.addFrameLocal(.str);
        const message = try self.addFrameLocal(.str);

        const snippet_index = @intFromEnum(snippet);
        if (snippet_index >= self.module.checked_bodies.stringLiteralCount()) {
            boxyLowerInvariant("checked expect_err snippet referenced a missing string literal");
        }
        const snippet_text = self.module.checked_bodies.stringLiteral(@enumFromInt(snippet_index));
        const prefix_text = try std.fmt.allocPrint(
            self.parent.allocator,
            "The `?` operator in `{s}` evaluated an `Err` inside an `expect`. The value was: Err(",
            .{snippet_text},
        );
        defer self.parent.allocator.free(prefix_text);

        var continuation = try self.parent.result.store.addCFStmt(.{ .expect_err = .{
            .message = message,
            .region = self.parent.result.store.current_region,
        } });
        continuation = try self.assignStrConcat(message, with_value, suffix, continuation);
        continuation = try self.assignStringBytesLiteral(suffix, ")", continuation);
        continuation = try self.assignStrConcat(with_value, prefix, rendered, continuation);
        continuation = try self.lowerInspectLocalInto(rendered, child_local, child_expr.ty, continuation);
        continuation = try self.assignStringBytesLiteral(prefix, prefix_text, continuation);
        return try self.lowerExprInto(child_local, child, continuation);
    }

    fn lowerInspectExprInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        expr_id: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const expr = self.module.checked_bodies.expr(expr_id);
        const checked_rep = self.repForType(expr.ty);
        const storage_rep = self.exprStorageRep(expr, checked_rep);
        const value = try self.addFrameLocalForRep(storage_rep);
        const inspect = try self.lowerInspectRepLocalInto(target, value, storage_rep, next);
        return if (storage_rep == checked_rep)
            try self.lowerExprInto(value, expr_id, inspect)
        else
            try self.lowerExprStorageRepInto(value, storage_rep, expr_id, inspect);
    }

    fn lowerInspectLocalInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        checked_ty: checked.CheckedTypeId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.parent.result.store.getLocal(target).layout_idx != .str) {
            boxyLowerInvariant("boxy inspect target did not have Str layout");
        }
        return try self.lowerInspectRepLocalInto(target, source, self.repForType(checked_ty), next);
    }

    fn lowerInspectRepLocalInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const rep = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        return switch (rep.kind) {
            .in_progress => boxyLowerInvariant("in-progress boxy representation reached inspect lowering"),
            .dynamic => try self.lowerDescriptorInspectLocalsInto(target, source, rep_id, next),
            .erased_callable => try self.assignStringBytesLiteral(target, "<function>", next),
            .generated_field,
            .generated_field_names,
            .generated_tag_union_spec,
            => try self.assignStringBytesLiteral(target, "<opaque>", next),
            .list => try self.lowerListInspectLocalsInto(target, source, rep_id, next),
            .box => try self.lowerBoxInspectLocalsInto(target, source, rep_id, next),
            .primitive => |primitive| try self.lowerPrimitiveInspectLocalsInto(target, source, primitive, next),
            .bool_tag_union => try self.lowerBoolInspectLocalsInto(target, source, next),
            .empty_record => try self.assignStringBytesLiteral(target, "{}", next),
            .empty_tag_union => try self.parent.result.store.addCFStmt(.{ .crash = .{
                .msg = .{ .literal = try self.parent.result.store.insertString("uninhabited value reached Str.inspect") },
            } }),
            .alias => try self.lowerInspectRepLocalInto(target, source, self.repQuery().requiredSingleChild(rep_id, .alias_backing).rep, next),
            .nominal => |kind| switch (kind) {
                .transparent => if (try self.lowerToInspectMethodInto(target, source, rep_id, next)) |method_call|
                    method_call
                else if (rep.declared_fields.len != 0)
                    try self.lowerNominalBackingInspectLocalsInto(target, source, rep_id, next)
                else
                    try self.lowerInspectRepLocalInto(target, source, self.repQuery().requiredSingleChild(rep_id, .nominal_backing).rep, next),
                .opaque_nominal => if (try self.lowerToInspectMethodInto(target, source, rep_id, next)) |method_call|
                    method_call
                else
                    try self.assignStringBytesLiteral(target, "<opaque>", next),
                .builtin_other => try self.lowerInspectRepLocalInto(target, source, self.repQuery().requiredSingleChild(rep_id, .nominal_backing).rep, next),
            },
            .record,
            .record_unbound,
            => try self.lowerRecordInspectLocalsInto(target, source, rep, next),
            .tuple => try self.lowerTupleInspectLocalsInto(target, source, rep, next),
            .tag_union => if (rep.presence_slot_present_discriminant != null)
                try self.lowerPresenceSlotInspectLocalsInto(target, source, rep, next)
            else if (self.tagUnionRepHasExtension(rep))
                try self.lowerDescriptorInspectLocalsInto(target, source, rep_id, next)
            else
                try self.lowerTagUnionInspectLocalsInto(target, source, rep, next),
        };
    }

    fn lowerToInspectMethodInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!?LIR.CFStmtId {
        const worker_id = self.parent.methodWorkerForRepByName(rep_id, "to_inspect") orelse return null;
        const worker = self.parent.plan.workers.items[@intFromEnum(worker_id)];
        if (worker.hidden_descs.len != 0 or worker.hidden_dicts.len != 0) {
            boxyLowerInvariant("boxy to_inspect method worker carried hidden parameters");
        }

        const function = checkedFunctionPayload(procedureModuleById(self.parent.modules, worker.checked_type.module), worker.checked_type.ty);
        if (function.args.len != 1) {
            boxyLowerInvariant("boxy to_inspect method worker had unexpected arity");
        }
        const arg_types = [_]Plan.CheckedTypeIdentity{.{ .module = worker.checked_type.module, .ty = function.args[0] }};
        const source_args = [_]LIR.LocalId{source};
        const call = try self.lowerWorkerCallLocalsInto(
            target,
            .{ .module = worker.checked_type.module, .ty = function.ret },
            &arg_types,
            &arg_types,
            &source_args,
            null,
            null,
            null,
            worker_id,
            &.{},
            &.{},
            next,
        );
        return call;
    }

    fn lowerDescriptorInspectLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const source_desc = try self.descriptorRefForSourceLocalRep(source, rep_id);
        return try self.parent.result.store.addCFStmt(.{ .assign_boxy_inspect = .{
            .target = target,
            .source = source,
            .source_desc = source_desc,
            .source_mode = .borrow,
            .next = next,
        } });
    }

    fn tagUnionRepHasExtension(self: *const ProcBodyBuilder, rep: Plan.TypeRepresentation) bool {
        for (self.parent.plan.childSlice(rep.children)) |child| {
            if (child.role == .tag_ext) return true;
        }
        return false;
    }

    fn lowerNominalBackingInspectLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const backing_rep = self.repQuery().requiredSingleChild(rep_id, .nominal_backing).rep;
        const backing = try self.addFrameLocalForRep(backing_rep);
        const inspect = try self.lowerInspectRepLocalInto(target, backing, backing_rep, next);
        return try self.assignRepresentationBoundary(backing, source, backing_rep, rep_id, inspect);
    }

    fn lowerPrimitiveInspectLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        primitive: checked.CheckedPrimitive,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (primitive == .bool) {
            return try self.lowerBoolInspectLocalsInto(target, source, next);
        }
        const op = Common.primitiveInspectLowLevelOp(primitive);
        return try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
            .target = target,
            .op = op,
            .rc_effect = op.rcEffect(),
            .args = try self.parent.result.store.addLocalSpan(&[_]LIR.LocalId{source}),
            .next = next,
        } });
    }

    fn lowerBoolInspectLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const false_body = try self.assignStringBytesLiteral(target, "False", next);
        const true_body = try self.assignStringBytesLiteral(target, "True", next);
        const discriminant = try self.addFrameLocal(.u16);
        const branches = [_]LIR.CFSwitchBranch{.{ .value = 1, .body = true_body }};
        const switch_stmt = try self.parent.result.store.addCFStmt(.{ .switch_stmt = .{
            .cond = discriminant,
            .branches = try self.parent.result.store.addCFSwitchBranches(&branches),
            .default_branch = false_body,
            .continuation = null,
        } });
        return try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = discriminant,
            .op = .{ .discriminant = .{ .source = source } },
            .next = switch_stmt,
        } });
    }

    fn lowerRecordInspectLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        rep: Plan.TypeRepresentation,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const children = self.parent.plan.childSlice(rep.children);
        const field_count = recordEqualityFieldCount(children);
        if (field_count == 0) return try self.assignStringBytesLiteral(target, "{}", next);

        var parts = std.ArrayList(InspectPart).empty;
        defer parts.deinit(self.parent.allocator);
        try parts.append(self.parent.allocator, .{ .literal = "{ " });

        var field_index: u16 = 0;
        for (children) |child| {
            switch (child.role) {
                .record_field => |label| {
                    if (field_index != 0) try parts.append(self.parent.allocator, .{ .literal = ", " });
                    try parts.append(self.parent.allocator, .{ .literal = self.module.canonical_names.recordFieldLabelText(label) });
                    try parts.append(self.parent.allocator, .{ .literal = ": " });
                    try parts.append(self.parent.allocator, .{ .field = .{
                        .source = source,
                        .field_index = field_index,
                        .rep = child.rep,
                    } });
                    field_index += 1;
                },
                .record_ext => self.requireEmptyRecordExtension(child.rep),
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("record inspect representation had a non-record child role"),
            }
        }
        try parts.append(self.parent.allocator, .{ .literal = " }" });
        return try self.lowerInspectPartsInto(target, parts.items, next);
    }

    fn lowerTupleInspectLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        rep: Plan.TypeRepresentation,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const children = self.parent.plan.childSlice(rep.children);
        if (children.len == 0) return try self.assignStringBytesLiteral(target, "()", next);

        var parts = std.ArrayList(InspectPart).empty;
        defer parts.deinit(self.parent.allocator);
        try parts.append(self.parent.allocator, .{ .literal = "(" });
        for (children, 0..) |child, ordinal| {
            switch (child.role) {
                .tuple_elem => |index| {
                    if (ordinal != 0) try parts.append(self.parent.allocator, .{ .literal = ", " });
                    if (index > std.math.maxInt(u16)) {
                        boxyLowerInvariant("tuple inspect element index exceeded LIR field index range");
                    }
                    try parts.append(self.parent.allocator, .{ .field = .{
                        .source = source,
                        .field_index = @intCast(index),
                        .rep = child.rep,
                    } });
                },
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("tuple inspect representation had a non-tuple child role"),
            }
        }
        try parts.append(self.parent.allocator, .{ .literal = ")" });
        return try self.lowerInspectPartsInto(target, parts.items, next);
    }

    fn lowerTagUnionInspectLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        rep: Plan.TypeRepresentation,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const variants = self.parent.plan.tagVariantSlice(rep.tag_variants);
        if (variants.len == 0) {
            return try self.parent.result.store.addCFStmt(.{ .crash = .{
                .msg = .{ .literal = try self.parent.result.store.insertString("uninhabited value reached Str.inspect") },
            } });
        }
        if (variants.len == 1 and self.isZstLocal(source)) {
            return try self.lowerTagInspectVariant(target, source, variants[0], 0, next);
        }

        const discriminant = try self.addFrameLocal(.u16);
        const branches = try self.parent.allocator.alloc(LIR.CFSwitchBranch, variants.len);
        defer self.parent.allocator.free(branches);
        for (variants, branches, 0..) |variant, *branch, index| {
            if (index > std.math.maxInt(u16)) {
                boxyLowerInvariant("tag inspect variant index exceeded LIR variant range");
            }
            branch.* = .{
                .value = @intCast(index),
                .body = try self.lowerTagInspectVariant(target, source, variant, @intCast(index), next),
            };
        }

        const bad_discriminant = try self.parent.result.store.addCFStmt(.runtime_error);
        const switch_stmt = try self.parent.result.store.addCFStmt(.{ .switch_stmt = .{
            .cond = discriminant,
            .branches = try self.parent.result.store.addCFSwitchBranches(branches),
            .default_branch = bad_discriminant,
            .continuation = null,
        } });
        return try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = discriminant,
            .op = .{ .discriminant = .{ .source = source } },
            .next = switch_stmt,
        } });
    }

    fn lowerPresenceSlotInspectLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        rep: Plan.TypeRepresentation,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const present_discriminant = rep.presence_slot_present_discriminant orelse
            boxyLowerInvariant("presence-slot inspect lacked its Present discriminant");
        const variants = self.parent.plan.tagVariantSlice(rep.tag_variants);
        const present_index: usize = present_discriminant;
        if (variants.len != 2 or present_index >= variants.len) {
            boxyLowerInvariant("presence-slot inspect did not have exactly two variants");
        }
        const present_payloads = self.parent.plan.childSlice(variants[present_index].payloads);
        if (present_payloads.len != 1) {
            boxyLowerInvariant("presence-slot inspect Present arm did not have one payload");
        }
        const payload_child = present_payloads[0];
        switch (payload_child.role) {
            .tag_payload => |payload| if (payload.tag != variants[present_index].name or payload.index != 0) {
                boxyLowerInvariant("presence-slot inspect payload did not match its Present variant");
            },
            .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .tuple_elem, .function_arg, .function_ret, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("presence-slot inspect Present arm had a non-payload child"),
        }

        const missing_discriminant: u16 = if (present_discriminant == 0) 1 else 0;
        if (variants[missing_discriminant].payloads.len != 0) {
            boxyLowerInvariant("presence-slot inspect Missing arm carried a payload");
        }

        const present_body = try self.lowerInspectPartInto(target, .{ .tag_payload = .{
            .source = source,
            .variant_index = present_discriminant,
            .payload_index = null,
            .rep = payload_child.rep,
        } }, next);
        const missing_body = try self.assignStringBytesLiteral(target, "<missing>", next);
        const branches = [_]LIR.CFSwitchBranch{
            .{ .value = missing_discriminant, .body = missing_body },
            .{ .value = present_discriminant, .body = present_body },
        };
        const discriminant = try self.addFrameLocal(.u16);
        const switch_stmt = try self.parent.result.store.addCFStmt(.{ .switch_stmt = .{
            .cond = discriminant,
            .branches = try self.parent.result.store.addCFSwitchBranches(&branches),
            .default_branch = try self.parent.result.store.addCFStmt(.runtime_error),
            .continuation = null,
        } });
        return try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = discriminant,
            .op = .{ .discriminant = .{ .source = source } },
            .next = switch_stmt,
        } });
    }

    fn lowerBoxInspectLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const payload_rep = self.repQuery().requiredSingleChild(rep_id, .box_payload).rep;
        const payload = try self.addFrameLocalForRep(payload_rep);
        const prefix = try self.addFrameLocal(.str);
        const rendered = try self.addFrameLocal(.str);
        const with_value = try self.addFrameLocal(.str);
        const suffix = try self.addFrameLocal(.str);

        var continuation = try self.assignStrConcat(target, with_value, suffix, next);
        continuation = try self.assignStringBytesLiteral(suffix, ")", continuation);
        continuation = try self.assignStrConcat(with_value, prefix, rendered, continuation);
        continuation = try self.lowerInspectRepLocalInto(rendered, payload, payload_rep, continuation);
        continuation = try self.assignBoxBoundary(
            payload,
            source,
            payload_rep,
            .box_unbox,
            continuation,
        );
        return try self.assignStringBytesLiteral(prefix, "Box(", continuation);
    }

    fn lowerListInspectLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const elem_rep = self.repQuery().requiredSingleChild(rep_id, .list_elem).rep;
        const len = try self.addFrameLocal(.u64);
        const index = try self.addFrameLocal(.u64);
        const out = try self.addFrameLocal(.str);
        const zero_index = try self.addFrameLocal(.u64);
        const initial_out = try self.addFrameLocal(.str);
        const join_id = self.freshJoinPointId();

        const body = try self.lowerListInspectLoopBody(target, source, elem_rep, len, index, out, join_id, next);
        var initial_jump = try self.parent.result.store.addCFStmt(.{ .jump = .{ .target = join_id } });
        initial_jump = try self.setLocalInitializeJoinParam(out, initial_out, initial_jump);
        initial_jump = try self.setLocalInitializeJoinParam(index, zero_index, initial_jump);
        initial_jump = try self.assignStringBytesLiteral(initial_out, "[", initial_jump);
        initial_jump = try self.assignIntLiteral(zero_index, 0, initial_jump);
        initial_jump = try self.assignUnaryLowLevel(len, .list_len, source, initial_jump);

        return try self.parent.result.store.addCFStmt(.{ .join = .{
            .id = join_id,
            .params = try self.joinParamSpan(&[_]LIR.LocalId{ index, out }),
            .body = body,
            .remainder = initial_jump,
        } });
    }

    fn lowerListInspectLoopBody(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        elem_rep: Plan.TypeRepId,
        len: LIR.LocalId,
        index: LIR.LocalId,
        out: LIR.LocalId,
        join_id: LIR.JoinPointId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const done = try self.addFrameLocal(.bool);
        const finish = try self.lowerListInspectFinish(target, out, next);
        const step = try self.lowerListInspectStep(source, elem_rep, index, out, join_id);
        const switch_stmt = try self.boolSwitchNoContinuation(done, finish, step);
        return try self.assignBinaryLowLevel(done, .num_is_eq, index, len, switch_stmt);
    }

    fn lowerListInspectFinish(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        out: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const close = try self.addFrameLocal(.str);
        const concat = try self.assignStrConcat(target, out, close, next);
        return try self.assignStringBytesLiteral(close, "]", concat);
    }

    fn lowerListInspectStep(
        self: *ProcBodyBuilder,
        source: LIR.LocalId,
        elem_rep: Plan.TypeRepId,
        index: LIR.LocalId,
        out: LIR.LocalId,
        join_id: LIR.JoinPointId,
    ) Allocator.Error!LIR.CFStmtId {
        const sep = try self.addFrameLocal(.str);
        const zero = try self.addFrameLocal(.u64);
        const is_first = try self.addFrameLocal(.bool);
        const elem = try self.addFrameLocalForRep(elem_rep);
        const elem_str = try self.addFrameLocal(.str);
        const with_sep = try self.addFrameLocal(.str);
        const next_out = try self.addFrameLocal(.str);
        const one = try self.addFrameLocal(.u64);
        const next_index = try self.addFrameLocal(.u64);

        var continuation = try self.parent.result.store.addCFStmt(.{ .jump = .{ .target = join_id } });
        continuation = try self.setLocalInitializeJoinParam(out, next_out, continuation);
        continuation = try self.setLocalInitializeJoinParam(index, next_index, continuation);
        continuation = try self.assignBinaryLowLevel(next_index, .num_int_add_crash_on_overflow, index, one, continuation);
        continuation = try self.assignIntLiteral(one, 1, continuation);
        continuation = try self.assignStrConcat(next_out, with_sep, elem_str, continuation);
        continuation = try self.lowerInspectRepLocalInto(elem_str, elem, elem_rep, continuation);
        if (!self.isZstLocal(elem)) {
            continuation = try self.assignBinaryLowLevel(elem, .list_get_unsafe, source, index, continuation);
        }
        continuation = try self.assignStrConcat(with_sep, out, sep, continuation);

        const empty_sep = try self.assignStringBytesLiteral(sep, "", continuation);
        const comma_sep = try self.assignStringBytesLiteral(sep, ", ", continuation);
        const sep_switch = try self.boolSwitchNoContinuation(is_first, empty_sep, comma_sep);
        const compare_first = try self.assignBinaryLowLevel(is_first, .num_is_eq, index, zero, sep_switch);
        return try self.assignIntLiteral(zero, 0, compare_first);
    }

    fn lowerTagInspectVariant(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        variant: Plan.TagVariant,
        variant_index: u16,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const payloads = self.parent.plan.childSlice(variant.payloads);
        if (payloads.len == 0) {
            return try self.assignStringBytesLiteral(target, self.tagVariantNameText(variant), next);
        }

        var parts = std.ArrayList(InspectPart).empty;
        defer parts.deinit(self.parent.allocator);
        try parts.append(self.parent.allocator, .{ .literal = self.tagVariantNameText(variant) });
        try parts.append(self.parent.allocator, .{ .literal = "(" });
        for (payloads, 0..) |child, index| {
            switch (child.role) {
                .tag_payload => |payload| {
                    if (payload.tag != variant.name or payload.index != index) {
                        boxyLowerInvariant("tag inspect payload span did not match its payload child roles");
                    }
                },
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .tuple_elem, .function_arg, .function_ret, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("tag inspect variant payload span included a non-payload child"),
            }
            if (index != 0) try parts.append(self.parent.allocator, .{ .literal = ", " });
            if (index > std.math.maxInt(u16)) {
                boxyLowerInvariant("tag inspect payload index exceeded LIR payload index range");
            }
            try parts.append(self.parent.allocator, .{ .tag_payload = .{
                .source = source,
                .variant_index = variant_index,
                .payload_index = if (payloads.len == 1) null else @as(u16, @intCast(index)),
                .rep = child.rep,
            } });
        }
        try parts.append(self.parent.allocator, .{ .literal = ")" });
        return try self.lowerInspectPartsInto(target, parts.items, next);
    }

    fn lowerInspectPartsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        parts: []const InspectPart,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (parts.len == 0) return try self.assignStringBytesLiteral(target, "", next);

        const part_locals = try self.parent.allocator.alloc(LIR.LocalId, parts.len);
        defer self.parent.allocator.free(part_locals);
        for (part_locals) |*local| {
            local.* = try self.addFrameLocal(.str);
        }

        var continuation = try self.concatStringLocalsInto(target, part_locals, next);
        var index = parts.len;
        while (index > 0) {
            index -= 1;
            continuation = try self.lowerInspectPartInto(part_locals[index], parts[index], continuation);
        }
        return continuation;
    }

    fn lowerInspectPartInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        part: InspectPart,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return switch (part) {
            .literal => |text| try self.assignStringBytesLiteral(target, text, next),
            .field => |field| blk: {
                const value = try self.addFrameLocalForRep(field.rep);
                var continuation = try self.lowerInspectRepLocalInto(target, value, field.rep, next);
                if (!self.isZstLocal(value)) {
                    continuation = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
                        .target = value,
                        .op = .{ .field = .{
                            .source = field.source,
                            .field_idx = field.field_index,
                        } },
                        .next = continuation,
                    } });
                }
                break :blk continuation;
            },
            .tag_payload => |payload| blk: {
                const value = try self.addFrameLocalForRep(payload.rep);
                var continuation = try self.lowerInspectRepLocalInto(target, value, payload.rep, next);
                if (!self.isZstLocal(value)) {
                    continuation = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
                        .target = value,
                        .op = if (payload.payload_index) |index| .{ .tag_payload = .{
                            .source = payload.source,
                            .payload_idx = index,
                            .variant_index = payload.variant_index,
                            .tag_discriminant = payload.variant_index,
                        } } else .{ .tag_payload_struct = .{
                            .source = payload.source,
                            .variant_index = payload.variant_index,
                            .tag_discriminant = payload.variant_index,
                        } },
                        .next = continuation,
                    } });
                }
                break :blk continuation;
            },
        };
    }

    fn concatStringLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        parts: []const LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        switch (parts.len) {
            0 => return try self.assignStringBytesLiteral(target, "", next),
            1 => return try self.assignLocal(target, parts[0], next),
            else => {},
        }

        const concat_results = try self.parent.allocator.alloc(LIR.LocalId, parts.len - 1);
        defer self.parent.allocator.free(concat_results);
        for (concat_results[0 .. concat_results.len - 1]) |*local| {
            local.* = try self.addFrameLocal(.str);
        }
        concat_results[concat_results.len - 1] = target;

        var continuation = next;
        var concat_index = concat_results.len;
        while (concat_index > 0) {
            concat_index -= 1;
            const lhs = if (concat_index == 0) parts[0] else concat_results[concat_index - 1];
            const rhs = parts[concat_index + 1];
            continuation = try self.assignStrConcat(concat_results[concat_index], lhs, rhs, continuation);
        }
        return continuation;
    }

    fn assignStrConcat(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        lhs: LIR.LocalId,
        rhs: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
            .target = target,
            .op = .str_concat,
            .rc_effect = LIR.LowLevel.str_concat.rcEffect(),
            .args = try self.parent.result.store.addLocalSpan(&[_]LIR.LocalId{ lhs, rhs }),
            .next = next,
        } });
    }

    fn lowerReturn(
        self: *ProcBodyBuilder,
        expr_id: checked.CheckedExprId,
        lambda_id: checked.CheckedExprId,
    ) Allocator.Error!LIR.CFStmtId {
        const current = self.current_lambda orelse
            boxyLowerInvariant("checked return reached boxy lowering outside a lambda worker");
        if (current != lambda_id) {
            boxyLowerInvariant("checked return target lambda differed from current boxy worker lambda");
        }

        const expr = self.module.checked_bodies.expr(expr_id);
        const expr_rep = self.repForType(expr.ty);
        const expr_layout = self.workerRuntimeLayoutForRep(expr_rep).layoutIdx();
        const worker = self.parent.plan.workers.items[@intFromEnum(self.worker_layout.worker)];
        const worker_function = self.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("boxy explicit return reached a non-function worker");
        const ret_rep = worker_function.ret;
        const ret_layout = self.workerReturnLayout();

        const expr_local = try self.addFrameBoundaryTargetLocalForRep(expr_rep);
        const ret_local = try self.addWorkerReturnLocal(true);
        if (self.parent.result.store.getLocal(expr_local).layout_idx != expr_layout or
            self.parent.result.store.getLocal(ret_local).layout_idx != ret_layout)
        {
            boxyLowerInvariant("boxy explicit return boundary layout disagreed with its planned representations");
        }
        const ret_stmt = try self.parent.result.store.addCFStmt(.{ .ret = .{ .value = ret_local } });
        const assign_ret = try self.assignRepresentationBoundary(ret_local, expr_local, ret_rep, expr_rep, ret_stmt);
        return try self.lowerExprInto(expr_local, expr_id, assign_ret);
    }

    fn lowerBoolBinopInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        op: can.CIR.Expr.Binop.Op,
        lhs: checked.CheckedExprId,
        rhs: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const true_body, const false_body = switch (op) {
            .@"and" => .{
                try self.lowerExprInto(target, rhs, next),
                try self.assignBoolLiteral(target, false, next),
            },
            .@"or" => .{
                try self.assignBoolLiteral(target, true, next),
                try self.lowerExprInto(target, rhs, next),
            },
            .add, .sub, .mul, .div, .rem, .lt, .gt, .le, .ge, .eq, .ne, .div_trunc, .range_exclusive, .range_inclusive => boxyLowerInvariant("non-short-circuit checked binop reached boxy binop lowering before dispatch lowering"),
        };

        const lhs_expr = self.module.checked_bodies.expr(lhs);
        const cond = try self.addFrameLocalForType(lhs_expr.ty);
        const switch_stmt = try self.boolSwitchNoContinuation(cond, true_body, false_body);
        return try self.lowerExprInto(cond, lhs, switch_stmt);
    }

    fn lowerStructuralEqInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        lhs_id: checked.CheckedExprId,
        rhs_id: checked.CheckedExprId,
        planned_operand_rep: ?Plan.TypeRepId,
        negated: bool,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const lhs_expr = self.module.checked_bodies.expr(lhs_id);
        const rhs_expr = self.module.checked_bodies.expr(rhs_id);

        const rep_id = planned_operand_rep orelse self.repForType(lhs_expr.ty);
        const operand_layout = self.workerRuntimeLayoutForRep(rep_id).layoutIdx();
        if (planned_operand_rep == null and self.workerRuntimeLayoutForType(rhs_expr.ty).layoutIdx() != operand_layout) {
            boxyLowerInvariant("checked structural equality operand layouts disagreed");
        }

        const lhs = try self.addStructuralEqOperandLocalForRep(rep_id);
        const rhs = try self.addFrameLocal(operand_layout);
        if (self.parent.result.store.getLocal(lhs).boxy_desc) |desc| {
            self.parent.result.store.setLocalBoxyDesc(rhs, desc);
        }
        if (self.parent.result.store.getLocal(lhs).layout_idx != operand_layout or
            self.parent.result.store.getLocal(rhs).layout_idx != operand_layout)
        {
            boxyLowerInvariant("boxy structural equality operand local layout disagreed with checked type");
        }

        var continuation = try self.lowerEqRepLocalsInto(target, lhs, rhs, rep_id, negated, next);
        if (self.parent.result.store.getLocal(lhs).boxy_desc) |desc| {
            if (desc.localOrNull()) |shared_desc| {
                const snapshot = try self.snapshotDescriptorBindings();
                defer snapshot.deinit(self.parent.allocator);
                try self.markDescriptorLocalBound(shared_desc);
                continuation = try self.lowerStructuralEqRhsIntoSharedRep(rhs, rep_id, rhs_id, continuation);
                self.restoreDescriptorBindings(snapshot);
            } else {
                continuation = try self.lowerExprIntoRep(rhs, rep_id, rhs_id, continuation);
            }
        } else {
            continuation = try self.lowerExprIntoRep(rhs, rep_id, rhs_id, continuation);
        }
        return try self.lowerExprIntoRep(lhs, rep_id, lhs_id, continuation);
    }

    fn lowerStructuralEqRhsIntoSharedRep(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        expr_id: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const expr = self.module.checked_bodies.expr(expr_id);
        const source_rep = self.repForType(expr.ty);
        const source = try self.addFrameBoundaryTargetLocalForRep(source_rep);
        const assign = try self.assignPlannedCallBoundary(target, source, target_rep, source_rep, next);
        return try self.lowerExprInto(source, expr_id, assign);
    }

    fn lowerEqRepLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        lhs: LIR.LocalId,
        rhs: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        negated: bool,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.structural_eq_active_reps.items.len == 0 and try self.runtimeRepGraphIsRecursive(rep_id)) {
            return try self.lowerBoxyEqRepLocalsInto(target, lhs, rhs, rep_id, negated, next);
        }
        for (self.structural_eq_active_reps.items) |active_rep| {
            if (active_rep == rep_id) {
                return try self.lowerBoxyEqRepLocalsInto(target, lhs, rhs, rep_id, negated, next);
            }
        }
        try self.structural_eq_active_reps.append(self.parent.allocator, rep_id);
        defer self.structural_eq_active_reps.items.len -= 1;

        const rep = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        return switch (rep.kind) {
            .in_progress => boxyLowerInvariant("in-progress boxy representation reached structural equality lowering"),
            .dynamic => try self.lowerBoxyEqRepLocalsInto(target, lhs, rhs, rep_id, negated, next),
            .erased_callable => boxyLowerInvariant("erased callable structural equality reached boxy lowering"),
            .generated_field,
            .generated_field_names,
            .generated_tag_union_spec,
            => boxyLowerInvariant("compiler-owned encoding evidence reached structural equality lowering"),
            .list,
            .box,
            => try self.lowerBoxyEqRepLocalsInto(target, lhs, rhs, rep_id, negated, next),
            .primitive => |primitive| try self.lowerPrimitiveEqLocalsInto(target, lhs, rhs, primitive, negated, next),
            .bool_tag_union => try self.lowerBoolEqLocalsInto(target, lhs, rhs, negated, next),
            .empty_record,
            .empty_tag_union,
            => try self.assignBoolLiteral(target, !negated, next),
            .alias => try self.lowerEqRepLocalsInto(target, lhs, rhs, self.repQuery().requiredSingleChild(rep_id, .alias_backing).rep, negated, next),
            .nominal => |kind| switch (kind) {
                .transparent => if (rep.declared_fields.len != 0)
                    try self.lowerNominalBackingEqLocalsInto(target, lhs, rhs, rep_id, negated, next)
                else
                    try self.lowerEqRepLocalsInto(target, lhs, rhs, self.repQuery().requiredSingleChild(rep_id, .nominal_backing).rep, negated, next),
                .opaque_nominal => try self.lowerBoxyEqRepLocalsInto(target, lhs, rhs, rep_id, negated, next),
                .builtin_other => try self.lowerEqRepLocalsInto(target, lhs, rhs, self.repQuery().requiredSingleChild(rep_id, .nominal_backing).rep, negated, next),
            },
            .record,
            .record_unbound,
            => try self.lowerRecordEqLocalsInto(target, lhs, rhs, rep, negated, next),
            .tuple => try self.lowerTupleEqLocalsInto(target, lhs, rhs, rep, negated, next),
            .tag_union => try self.lowerTagUnionEqLocalsInto(target, lhs, rhs, rep_id, negated, next),
        };
    }

    const RuntimeRepVisit = enum { unseen, active, done };

    fn runtimeRepGraphIsRecursive(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!bool {
        const visits = try self.parent.allocator.alloc(RuntimeRepVisit, self.parent.plan.representations.items.len);
        defer self.parent.allocator.free(visits);
        @memset(visits, .unseen);
        return self.runtimeRepGraphIsRecursiveInner(rep_id, visits);
    }

    fn runtimeRepGraphIsRecursiveInner(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        visits: []RuntimeRepVisit,
    ) bool {
        const index = @intFromEnum(rep_id);
        switch (visits[index]) {
            .active => return true,
            .done => return false,
            .unseen => visits[index] = .active,
        }

        const rep = self.parent.plan.representations.items[index];
        for (self.parent.plan.childSlice(rep.children)) |child| {
            if (!Plan.childCarriesRuntimeDescriptor(child.role)) continue;
            if (self.runtimeRepGraphIsRecursiveInner(child.rep, visits)) return true;
        }
        for (self.parent.plan.declaredFieldSlice(rep.declared_fields)) |field| {
            if (self.runtimeRepGraphIsRecursiveInner(field.rep, visits)) return true;
        }
        for (self.parent.plan.tagVariantSlice(rep.tag_variants)) |variant| {
            for (self.parent.plan.childSlice(variant.payloads)) |payload| {
                if (self.runtimeRepGraphIsRecursiveInner(payload.rep, visits)) return true;
            }
        }

        visits[index] = .done;
        return false;
    }

    fn lowerBoxyEqRepLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        lhs: LIR.LocalId,
        rhs: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        negated: bool,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var continuation = next;
        var eq_target = target;
        if (negated) {
            const raw = try self.addFrameLocal(.bool);
            continuation = try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
                .target = target,
                .op = .bool_not,
                .rc_effect = LIR.LowLevel.bool_not.rcEffect(),
                .args = try self.parent.result.store.addLocalSpan(&[_]LIR.LocalId{raw}),
                .next = next,
            } });
            eq_target = raw;
        }

        const source_desc = try self.descriptorRefForLocalOrKnownRep(lhs, rep_id);
        return try self.parent.result.store.addCFStmt(.{ .assign_boxy_eq = .{
            .target = eq_target,
            .lhs = lhs,
            .rhs = rhs,
            .source_desc = source_desc,
            .source_mode = .borrow,
            .next = continuation,
        } });
    }

    fn lowerNominalBackingEqLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        lhs: LIR.LocalId,
        rhs: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        negated: bool,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const backing_rep = self.repQuery().requiredSingleChild(rep_id, .nominal_backing).rep;
        const backing_layout = self.workerRuntimeLayoutForRep(backing_rep).layoutIdx();
        const lhs_backing = try self.addFrameLocal(backing_layout);
        const rhs_backing = try self.addFrameLocal(backing_layout);
        var continuation = try self.lowerEqRepLocalsInto(target, lhs_backing, rhs_backing, backing_rep, negated, next);
        continuation = try self.assignRepresentationBoundary(rhs_backing, rhs, backing_rep, rep_id, continuation);
        return try self.assignRepresentationBoundary(lhs_backing, lhs, backing_rep, rep_id, continuation);
    }

    fn lowerPrimitiveEqLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        lhs: LIR.LocalId,
        rhs: LIR.LocalId,
        primitive: checked.CheckedPrimitive,
        negated: bool,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (primitive == .bool) {
            return try self.lowerBoolEqLocalsInto(target, lhs, rhs, negated, next);
        }

        switch (primitive) {
            .u8x16,
            .i8x16,
            .u16x8,
            .i16x8,
            .u32x4,
            .i32x4,
            .u64x2,
            .i64x2,
            => {
                const lhs_bits = try self.addFrameLocal(.u128);
                const rhs_bits = try self.addFrameLocal(.u128);
                const compare = try self.lowerPrimitiveEqLocalsInto(target, lhs_bits, rhs_bits, .u128, negated, next);
                const lower_rhs = try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
                    .target = rhs_bits,
                    .op = .simd_to_u128_bits,
                    .rc_effect = LIR.LowLevel.simd_to_u128_bits.rcEffect(),
                    .args = try self.parent.result.store.addLocalSpan(&[_]LIR.LocalId{rhs}),
                    .next = compare,
                } });
                return try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
                    .target = lhs_bits,
                    .op = .simd_to_u128_bits,
                    .rc_effect = LIR.LowLevel.simd_to_u128_bits.rcEffect(),
                    .args = try self.parent.result.store.addLocalSpan(&[_]LIR.LocalId{lhs}),
                    .next = lower_rhs,
                } });
            },
            .bool, .str, .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .f32, .f64, .dec => {},
        }

        const eq_op: LIR.LowLevel = switch (primitive) {
            .str => .str_is_eq,
            .u8,
            .i8,
            .u16,
            .i16,
            .u32,
            .i32,
            .u64,
            .i64,
            .u128,
            .i128,
            .f32,
            .f64,
            .dec,
            => .num_is_eq,
            .u8x16,
            .i8x16,
            .u16x8,
            .i16x8,
            .u32x4,
            .i32x4,
            .u64x2,
            .i64x2,
            => unreachable,
            .bool => unreachable,
        };
        const args = [_]LIR.LocalId{ lhs, rhs };
        if (!negated) {
            return try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
                .target = target,
                .op = eq_op,
                .rc_effect = eq_op.rcEffect(),
                .args = try self.parent.result.store.addLocalSpan(&args),
                .next = next,
            } });
        }

        const raw = try self.addFrameLocal(.bool);
        const not_stmt = try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
            .target = target,
            .op = .bool_not,
            .rc_effect = LIR.LowLevel.bool_not.rcEffect(),
            .args = try self.parent.result.store.addLocalSpan(&[_]LIR.LocalId{raw}),
            .next = next,
        } });
        return try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
            .target = raw,
            .op = eq_op,
            .rc_effect = eq_op.rcEffect(),
            .args = try self.parent.result.store.addLocalSpan(&args),
            .next = not_stmt,
        } });
    }

    fn lowerBoolEqLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        lhs: LIR.LocalId,
        rhs: LIR.LocalId,
        negated: bool,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const lhs_disc = try self.addFrameLocal(.u16);
        const rhs_disc = try self.addFrameLocal(.u16);
        const compare = try self.lowerPrimitiveEqLocalsInto(target, lhs_disc, rhs_disc, .u16, negated, next);
        const read_rhs = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = rhs_disc,
            .op = .{ .discriminant = .{ .source = rhs } },
            .next = compare,
        } });
        return try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = lhs_disc,
            .op = .{ .discriminant = .{ .source = lhs } },
            .next = read_rhs,
        } });
    }

    fn lowerRecordEqLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        lhs: LIR.LocalId,
        rhs: LIR.LocalId,
        rep: Plan.TypeRepresentation,
        negated: bool,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var current = try self.assignBoolLiteral(target, !negated, next);
        const failed = try self.assignBoolLiteral(target, negated, next);
        const children = self.parent.plan.childSlice(rep.children);
        var field_index = recordEqualityFieldCount(children);
        var i = children.len;
        while (i > 0) {
            i -= 1;
            const child = children[i];
            switch (child.role) {
                .record_field => {
                    field_index -= 1;
                    current = try self.lowerFieldEqStep(lhs, rhs, child.rep, field_index, current, failed);
                },
                .record_ext => self.requireEmptyRecordExtension(child.rep),
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("record equality representation had a non-record child role"),
            }
        }
        return current;
    }

    fn lowerTupleEqLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        lhs: LIR.LocalId,
        rhs: LIR.LocalId,
        rep: Plan.TypeRepresentation,
        negated: bool,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var current = try self.assignBoolLiteral(target, !negated, next);
        const failed = try self.assignBoolLiteral(target, negated, next);
        const children = self.parent.plan.childSlice(rep.children);
        var i = children.len;
        while (i > 0) {
            i -= 1;
            const child = children[i];
            switch (child.role) {
                .tuple_elem => |index| {
                    if (index > std.math.maxInt(u16)) {
                        boxyLowerInvariant("tuple equality element index exceeded LIR field index range");
                    }
                    current = try self.lowerFieldEqStep(lhs, rhs, child.rep, @intCast(index), current, failed);
                },
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("tuple equality representation had a non-tuple child role"),
            }
        }
        return current;
    }

    fn lowerFieldEqStep(
        self: *ProcBodyBuilder,
        lhs: LIR.LocalId,
        rhs: LIR.LocalId,
        field_rep: Plan.TypeRepId,
        field_index: u16,
        on_equal: LIR.CFStmtId,
        on_not_equal: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const field_layout = self.workerRuntimeLayoutForRep(field_rep).layoutIdx();
        const lhs_field = try self.addFrameLocal(field_layout);
        const rhs_field = try self.addFrameLocal(field_layout);
        const eq = try self.addFrameLocal(.bool);
        var current = try self.boolSwitchNoContinuation(eq, on_equal, on_not_equal);
        current = try self.lowerEqRepLocalsInto(eq, lhs_field, rhs_field, field_rep, false, current);
        if (!self.isZstLocal(rhs_field)) {
            current = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
                .target = rhs_field,
                .op = .{ .field = .{
                    .source = rhs,
                    .field_idx = field_index,
                } },
                .next = current,
            } });
        }
        if (!self.isZstLocal(lhs_field)) {
            current = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
                .target = lhs_field,
                .op = .{ .field = .{
                    .source = lhs,
                    .field_idx = field_index,
                } },
                .next = current,
            } });
        }
        return current;
    }

    fn lowerTagUnionEqLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        lhs: LIR.LocalId,
        rhs: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        negated: bool,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.isZstLocal(lhs) and self.isZstLocal(rhs)) {
            return try self.assignBoolLiteral(target, !negated, next);
        }

        const success = try self.assignBoolLiteral(target, !negated, next);
        const failed = try self.assignBoolLiteral(target, negated, next);

        const lhs_disc = try self.addFrameLocal(.u16);
        const rhs_disc = try self.addFrameLocal(.u16);
        const same_disc = try self.addFrameLocal(.bool);

        const rep = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        const variants = self.parent.plan.tagVariantSlice(rep.tag_variants);
        const branches = try self.parent.allocator.alloc(LIR.CFSwitchBranch, variants.len);
        defer self.parent.allocator.free(branches);
        for (variants, branches, 0..) |variant, *branch, index| {
            if (index > std.math.maxInt(u16)) {
                boxyLowerInvariant("tag-union equality variant index exceeded LIR variant range");
            }
            branch.* = .{
                .value = @intCast(index),
                .body = try self.lowerTagPayloadEqVariant(lhs, rhs, rep_id, variant, @intCast(index), success, failed),
            };
        }

        const payload_switch = try self.parent.result.store.addCFStmt(.{ .switch_stmt = .{
            .cond = lhs_disc,
            .branches = try self.parent.result.store.addCFSwitchBranches(branches),
            .default_branch = failed,
            .continuation = null,
        } });
        const disc_switch = try self.boolSwitchNoContinuation(same_disc, payload_switch, failed);
        const compare_disc = try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
            .target = same_disc,
            .op = .num_is_eq,
            .rc_effect = LIR.LowLevel.num_is_eq.rcEffect(),
            .args = try self.parent.result.store.addLocalSpan(&[_]LIR.LocalId{ lhs_disc, rhs_disc }),
            .next = disc_switch,
        } });
        const read_rhs = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = rhs_disc,
            .op = .{ .discriminant = .{ .source = rhs } },
            .next = compare_disc,
        } });
        return try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = lhs_disc,
            .op = .{ .discriminant = .{ .source = lhs } },
            .next = read_rhs,
        } });
    }

    fn lowerTagPayloadEqVariant(
        self: *ProcBodyBuilder,
        lhs: LIR.LocalId,
        rhs: LIR.LocalId,
        tag_rep_id: Plan.TypeRepId,
        variant: Plan.TagVariant,
        variant_index: u16,
        on_equal: LIR.CFStmtId,
        on_not_equal: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var current = on_equal;
        const payloads = self.parent.plan.childSlice(variant.payloads);
        const tag_rep = self.parent.plan.representations.items[@intFromEnum(tag_rep_id)];
        const source_has_payload_desc = tag_rep.descriptor != null or
            self.parent.result.store.getLocal(lhs).boxy_desc != null or
            self.parent.result.store.getLocal(rhs).boxy_desc != null;
        var i = payloads.len;
        while (i > 0) {
            i -= 1;
            const child = payloads[i];
            switch (child.role) {
                .tag_payload => |payload| {
                    if (payload.tag != variant.name or payload.index != @as(u32, @intCast(i))) {
                        boxyLowerInvariant("tag equality payload span did not match its payload child roles");
                    }
                },
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .tuple_elem, .function_arg, .function_ret, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("tag equality variant payload span included a non-payload child"),
            }
            const lhs_payload = try self.addExtractedTagPayloadLocal(child.rep, source_has_payload_desc);
            const rhs_payload = try self.addExtractedTagPayloadLocal(child.rep, source_has_payload_desc);
            const eq = try self.addFrameLocal(.bool);
            current = try self.boolSwitchNoContinuation(eq, current, on_not_equal);
            current = try self.lowerEqRepLocalsInto(eq, lhs_payload.local, rhs_payload.local, child.rep, false, current);

            if (i > std.math.maxInt(u16)) {
                boxyLowerInvariant("tag equality payload index exceeded LIR payload index range");
            }
            current = try self.assignConcreteTagPayloadRead(
                rhs_payload.local,
                child.rep,
                rhs_payload.desc_local,
                rhs,
                tag_rep_id,
                variant.name,
                variant_index,
                @intCast(i),
                payloads.len,
                current,
            );
            current = try self.assignConcreteTagPayloadRead(
                lhs_payload.local,
                child.rep,
                lhs_payload.desc_local,
                lhs,
                tag_rep_id,
                variant.name,
                variant_index,
                @intCast(i),
                payloads.len,
                current,
            );
        }
        return current;
    }

    fn lowerStructuralHashInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        value_id: checked.CheckedExprId,
        hasher_id: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const value_expr = self.module.checked_bodies.expr(value_id);
        const hasher_expr = self.module.checked_bodies.expr(hasher_id);
        const value = try self.addFrameLocalForType(value_expr.ty);
        const hasher = try self.addFrameLocalForType(hasher_expr.ty);
        if (self.parent.result.store.getLocal(target).layout_idx != self.parent.result.store.getLocal(hasher).layout_idx) {
            boxyLowerInvariant("checked structural hash target layout differed from input hasher layout");
        }
        var continuation = try self.lowerHashRepLocalsInto(target, value, hasher, self.repForType(value_expr.ty), next);
        continuation = try self.lowerExprInto(hasher, hasher_id, continuation);
        return try self.lowerExprInto(value, value_id, continuation);
    }

    fn lowerHashRepLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        value: LIR.LocalId,
        hasher: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const rep = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        return switch (rep.kind) {
            .in_progress => boxyLowerInvariant("in-progress boxy representation reached structural hash lowering"),
            .dynamic => boxyLowerInvariant("dynamic structural hash reached boxy lowering before descriptor hash support"),
            .erased_callable => boxyLowerInvariant("erased callable structural hash reached boxy lowering"),
            .generated_field,
            .generated_field_names,
            .generated_tag_union_spec,
            => boxyLowerInvariant("compiler-owned encoding evidence reached structural hash lowering"),
            .list,
            .box,
            => boxyLowerInvariant("owned structural hash reached boxy lowering before dictionary hash support"),
            .primitive => |primitive| try self.lowerPrimitiveHashLocalsInto(target, value, hasher, primitive, next),
            .bool_tag_union => try self.lowerPrimitiveHashLocalsInto(target, value, hasher, .bool, next),
            .empty_record,
            .empty_tag_union,
            => try self.assignLocal(target, hasher, next),
            .alias => try self.lowerHashRepLocalsInto(target, value, hasher, self.repQuery().requiredSingleChild(rep_id, .alias_backing).rep, next),
            .nominal => |kind| switch (kind) {
                .transparent => if (rep.declared_fields.len != 0)
                    try self.lowerNominalBackingHashLocalsInto(target, value, hasher, rep_id, next)
                else
                    try self.lowerHashRepLocalsInto(target, value, hasher, self.repQuery().requiredSingleChild(rep_id, .nominal_backing).rep, next),
                .opaque_nominal => boxyLowerInvariant("opaque nominal structural hash reached boxy lowering before descriptor hash support"),
                .builtin_other => try self.lowerHashRepLocalsInto(target, value, hasher, self.repQuery().requiredSingleChild(rep_id, .nominal_backing).rep, next),
            },
            .record,
            .record_unbound,
            => try self.lowerRecordHashLocalsInto(target, value, hasher, rep, next),
            .tuple => try self.lowerTupleHashLocalsInto(target, value, hasher, rep, next),
            .tag_union => try self.lowerTagUnionHashLocalsInto(target, value, hasher, rep, next),
        };
    }

    fn lowerNominalBackingHashLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        value: LIR.LocalId,
        hasher: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const backing_rep = self.repQuery().requiredSingleChild(rep_id, .nominal_backing).rep;
        const backing = try self.addFrameLocalForRep(backing_rep);
        const hash = try self.lowerHashRepLocalsInto(target, backing, hasher, backing_rep, next);
        return try self.assignRepresentationBoundary(backing, value, backing_rep, rep_id, hash);
    }

    fn lowerPrimitiveHashLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        value: LIR.LocalId,
        hasher: LIR.LocalId,
        primitive: checked.CheckedPrimitive,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const op = Common.hasherWriteOp(primitive);
        return try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
            .target = target,
            .op = op,
            .rc_effect = op.rcEffect(),
            .args = try self.parent.result.store.addLocalSpan(&[_]LIR.LocalId{ hasher, value }),
            .next = next,
        } });
    }

    const HashComponent = struct {
        rep: Plan.TypeRepId,
        field_index: u16,
    };

    fn lowerRecordHashLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        value: LIR.LocalId,
        hasher: LIR.LocalId,
        rep: Plan.TypeRepresentation,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const children = self.parent.plan.childSlice(rep.children);
        const components = try self.parent.allocator.alloc(HashComponent, recordEqualityFieldCount(children));
        defer self.parent.allocator.free(components);
        var field_index: u16 = 0;
        for (children) |child| {
            switch (child.role) {
                .record_field => {
                    components[field_index] = .{
                        .rep = child.rep,
                        .field_index = field_index,
                    };
                    field_index += 1;
                },
                .record_ext => self.requireEmptyRecordExtension(child.rep),
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("record hash representation had a non-record child role"),
            }
        }
        return try self.lowerFieldHashComponentsInto(target, value, hasher, components, next);
    }

    fn lowerTupleHashLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        value: LIR.LocalId,
        hasher: LIR.LocalId,
        rep: Plan.TypeRepresentation,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const children = self.parent.plan.childSlice(rep.children);
        const components = try self.parent.allocator.alloc(HashComponent, children.len);
        defer self.parent.allocator.free(components);
        for (children, components) |child, *component| {
            switch (child.role) {
                .tuple_elem => |index| {
                    if (index > std.math.maxInt(u16)) {
                        boxyLowerInvariant("tuple hash element index exceeded LIR field index range");
                    }
                    component.* = .{
                        .rep = child.rep,
                        .field_index = @intCast(index),
                    };
                },
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("tuple hash representation had a non-tuple child role"),
            }
        }
        return try self.lowerFieldHashComponentsInto(target, value, hasher, components, next);
    }

    fn lowerFieldHashComponentsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        value: LIR.LocalId,
        hasher: LIR.LocalId,
        components: []const HashComponent,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (components.len == 0) return try self.assignLocal(target, hasher, next);

        const hasher_layout = self.parent.result.store.getLocal(hasher).layout_idx;
        if (self.parent.result.store.getLocal(target).layout_idx != hasher_layout) {
            boxyLowerInvariant("structural hash target layout differed from input hasher layout");
        }

        const intermediate_count = components.len - 1;
        const intermediate_hashers = try self.parent.allocator.alloc(LIR.LocalId, intermediate_count);
        defer self.parent.allocator.free(intermediate_hashers);
        for (intermediate_hashers) |*local| {
            local.* = try self.addFrameLocal(hasher_layout);
        }

        var current = next;
        var i = components.len;
        while (i > 0) {
            i -= 1;
            const input_hasher = if (i == 0) hasher else intermediate_hashers[i - 1];
            const output_hasher = if (i == components.len - 1) target else intermediate_hashers[i];
            const component = components[i];
            const field = try self.addFrameLocalForRep(component.rep);
            current = try self.lowerHashRepLocalsInto(output_hasher, field, input_hasher, component.rep, current);
            if (!self.isZstLocal(field)) {
                current = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
                    .target = field,
                    .op = .{ .field = .{
                        .source = value,
                        .field_idx = component.field_index,
                    } },
                    .next = current,
                } });
            }
        }
        return current;
    }

    fn lowerTagUnionHashLocalsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        value: LIR.LocalId,
        hasher: LIR.LocalId,
        rep: Plan.TypeRepresentation,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const variants = self.parent.plan.tagVariantSlice(rep.tag_variants);
        if (variants.len == 1 and self.isZstLocal(value)) {
            return try self.lowerTagPayloadHashVariant(target, value, hasher, variants[0], 0, next);
        }

        const discriminant = try self.addFrameLocal(.u16);
        const branches = try self.parent.allocator.alloc(LIR.CFSwitchBranch, variants.len);
        defer self.parent.allocator.free(branches);
        for (variants, branches, 0..) |variant, *branch, index| {
            if (index > std.math.maxInt(u16)) {
                boxyLowerInvariant("tag-union hash variant index exceeded LIR variant range");
            }
            branch.* = .{
                .value = @intCast(index),
                .body = try self.lowerTagPayloadHashVariant(target, value, hasher, variant, @intCast(index), next),
            };
        }
        const bad_discriminant = try self.parent.result.store.addCFStmt(.runtime_error);
        const switch_stmt = try self.parent.result.store.addCFStmt(.{ .switch_stmt = .{
            .cond = discriminant,
            .branches = try self.parent.result.store.addCFSwitchBranches(branches),
            .default_branch = bad_discriminant,
            .continuation = null,
        } });
        return try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = discriminant,
            .op = .{ .discriminant = .{ .source = value } },
            .next = switch_stmt,
        } });
    }

    fn lowerTagPayloadHashVariant(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        value: LIR.LocalId,
        hasher: LIR.LocalId,
        variant: Plan.TagVariant,
        variant_index: u16,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const payloads = self.parent.plan.childSlice(variant.payloads);
        const hasher_layout = self.parent.result.store.getLocal(hasher).layout_idx;
        const after_discriminant = if (payloads.len == 0) target else try self.addFrameLocal(hasher_layout);

        const components = try self.parent.allocator.alloc(Plan.RepChild, payloads.len);
        defer self.parent.allocator.free(components);
        for (payloads, components, 0..) |child, *component, index| {
            switch (child.role) {
                .tag_payload => |payload| {
                    if (payload.tag != variant.name or payload.index != index) {
                        boxyLowerInvariant("tag hash payload span did not match its payload child roles");
                    }
                },
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .tuple_elem, .function_arg, .function_ret, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("tag hash variant payload span included a non-payload child"),
            }
            component.* = child;
        }

        var current = if (payloads.len == 0)
            next
        else
            try self.lowerTagPayloadHashComponentsInto(target, value, after_discriminant, components, variant_index, next);

        const discriminant_value = try self.addFrameLocal(.u64);
        current = try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
            .target = after_discriminant,
            .op = .hasher_write_u64,
            .rc_effect = LIR.LowLevel.hasher_write_u64.rcEffect(),
            .args = try self.parent.result.store.addLocalSpan(&[_]LIR.LocalId{ hasher, discriminant_value }),
            .next = current,
        } });
        return try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
            .target = discriminant_value,
            .value = .{ .i128_literal = .{
                .value = variant_index,
                .layout_idx = .u64,
            } },
            .next = current,
        } });
    }

    fn lowerTagPayloadHashComponentsInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        value: LIR.LocalId,
        hasher: LIR.LocalId,
        payloads: []const Plan.RepChild,
        variant_index: u16,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const hasher_layout = self.parent.result.store.getLocal(hasher).layout_idx;
        const intermediate_count = payloads.len - 1;
        const intermediate_hashers = try self.parent.allocator.alloc(LIR.LocalId, intermediate_count);
        defer self.parent.allocator.free(intermediate_hashers);
        for (intermediate_hashers) |*local| {
            local.* = try self.addFrameLocal(hasher_layout);
        }

        var current = next;
        var i = payloads.len;
        while (i > 0) {
            i -= 1;
            const input_hasher = if (i == 0) hasher else intermediate_hashers[i - 1];
            const output_hasher = if (i == payloads.len - 1) target else intermediate_hashers[i];
            const payload = payloads[i];
            const payload_local = try self.addFrameLocalForRep(payload.rep);
            current = try self.lowerHashRepLocalsInto(output_hasher, payload_local, input_hasher, payload.rep, current);
            if (!self.isZstLocal(payload_local)) {
                if (i > std.math.maxInt(u16)) {
                    boxyLowerInvariant("tag hash payload index exceeded LIR payload index range");
                }
                const payload_idx: ?u16 = if (payloads.len == 1) null else @as(u16, @intCast(i));
                current = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
                    .target = payload_local,
                    .op = if (payload_idx) |index| .{ .tag_payload = .{
                        .source = value,
                        .payload_idx = index,
                        .variant_index = variant_index,
                        .tag_discriminant = variant_index,
                    } } else .{ .tag_payload_struct = .{
                        .source = value,
                        .variant_index = variant_index,
                        .tag_discriminant = variant_index,
                    } },
                    .next = current,
                } });
            }
        }
        return current;
    }

    fn lowerUnaryLowLevelInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        result_ty: checked.CheckedTypeId,
        op: LIR.LowLevel,
        child: checked.CheckedExprId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const args = [_]checked.CheckedExprId{child};
        return try self.lowerLowLevelInto(target, result_ty, op, &args, next);
    }

    fn joinJump(self: *ProcBodyBuilder, join_id: LIR.JoinPointId) Allocator.Error!LIR.CFStmtId {
        return try self.parent.result.store.addCFStmt(.{ .jump = .{ .target = join_id } });
    }

    fn freshJoinPointId(self: *ProcBodyBuilder) LIR.JoinPointId {
        const id: LIR.JoinPointId = @enumFromInt(self.next_join_point);
        self.next_join_point += 1;
        return id;
    }

    const DynamicLiteralTarget = struct {
        payload_layout: layout.Idx,
        payload_desc: LIR.BoxyDescRef,
    };

    /// The runtime descriptor reference of a dynamic-storage literal target
    /// whose payload layout is not statically known, or null when the target
    /// is concrete or statically described.
    fn dynamicLiteralRuntimeDesc(self: *ProcBodyBuilder, target: LIR.LocalId) ?LIR.BoxyDescRef {
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        if (!self.layoutIsBoxyDynamicStorage(target_layout)) return null;
        const payload_desc = self.parent.result.store.getLocal(target).boxy_desc orelse return null;
        return switch (payload_desc) {
            .static => null,
            .local, .runtime, .dict_method_arg, .dict_method_hidden => payload_desc,
        };
    }

    fn dynamicLiteralTarget(self: *ProcBodyBuilder, target: LIR.LocalId) ?DynamicLiteralTarget {
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        if (!self.layoutIsBoxyDynamicStorage(target_layout)) return null;

        const payload_desc = self.parent.result.store.getLocal(target).boxy_desc orelse
            boxyLowerInvariant("boxy dynamic literal target had no payload descriptor");
        const payload_layout = switch (payload_desc) {
            .static => |desc_id| self.parent.result.boxy_type_descs.items[@intFromEnum(desc_id)].payload_layout,
            .local, .runtime, .dict_method_arg, .dict_method_hidden => boxyLowerInvariant("boxy dynamic literal target used a runtime descriptor without a concrete literal payload layout"),
        };
        if (payload_layout == target_layout) {
            boxyLowerInvariant("boxy dynamic literal target descriptor resolved to dynamic storage");
        }
        return .{
            .payload_layout = payload_layout,
            .payload_desc = payload_desc,
        };
    }

    /// Like `dynamicLiteralTarget`, but for literals whose payload layout the
    /// literal kind already fixes statically (str, f32, f64). A runtime-only
    /// descriptor conveys the target's representation at runtime and cannot
    /// supply the payload layout, so the known layout is used to box against it.
    fn dynamicLiteralTargetForLayout(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        known_payload_layout: layout.Idx,
    ) ?DynamicLiteralTarget {
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        if (!self.layoutIsBoxyDynamicStorage(target_layout)) return null;

        const payload_desc = self.parent.result.store.getLocal(target).boxy_desc orelse
            boxyLowerInvariant("boxy dynamic literal target had no payload descriptor");
        const payload_layout = switch (payload_desc) {
            .static => |desc_id| self.parent.result.boxy_type_descs.items[@intFromEnum(desc_id)].payload_layout,
            .local, .runtime, .dict_method_arg, .dict_method_hidden => known_payload_layout,
        };
        if (payload_layout == target_layout) {
            boxyLowerInvariant("boxy dynamic literal target descriptor resolved to dynamic storage");
        }
        return .{
            .payload_layout = payload_layout,
            .payload_desc = payload_desc,
        };
    }

    fn assignBoxedLiteralPayload(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        payload: LIR.LocalId,
        info: DynamicLiteralTarget,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.parent.result.store.addCFStmt(.{ .assign_boxy_box = .{
            .target = target,
            .payload = payload,
            .payload_layout = info.payload_layout,
            .payload_desc = info.payload_desc,
            .payload_mode = .move,
            .next = next,
        } });
    }

    fn assignCheckedNumeralLiteral(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        checked_ty: checked.CheckedTypeId,
        literal: can.ModuleEnv.NumeralLiteral,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const default_layout = builtinNumeralLayoutForType(self.module, checked_ty);
        if (self.dynamicLiteralRuntimeDesc(target)) |desc_ref| {
            const exact = self.module.module_env.exactNumeral(literal);
            const value: LIR.LiteralValue = switch (default_layout) {
                .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128 => .{ .boxy_dynamic_num_literal = .{
                    .value = exactIntBitsForLayout(exact, default_layout) orelse return try self.invalidNumeralLiteral(),
                    .desc = desc_ref,
                    .default_layout = default_layout,
                } },
                .f32, .f64, .dec => .{ .boxy_dynamic_frac_literal = .{
                    .dec_bits = (try exact_numeral.decBits(self.parent.allocator, exact)) orelse return try self.invalidNumeralLiteral(),
                    .desc = desc_ref,
                    .default_layout = default_layout,
                } },
                .bool, .str, .opaque_ptr, .zst, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2, _ => boxyLowerInvariant("builtin numeral resolved to a non-numeric layout"),
            };
            const assigned = try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
                .target = target,
                .value = value,
                .next = next,
            } });
            return try self.prependLiteralTargetDescriptorMaterialization(target, assigned);
        }
        if (self.dynamicLiteralTarget(target)) |info| {
            const payload = try self.addFrameLocal(info.payload_layout);
            const box = try self.assignBoxedLiteralPayload(target, payload, info, next);
            return try self.assignExactNumeralPayload(payload, info.payload_layout, literal, box);
        }
        return try self.assignExactNumeralPayload(
            target,
            self.parent.result.store.getLocal(target).layout_idx,
            literal,
            next,
        );
    }

    fn assignExactNumeralPayload(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        payload_layout: layout.Idx,
        literal: can.ModuleEnv.NumeralLiteral,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const exact = self.module.module_env.exactNumeral(literal);
        return switch (payload_layout) {
            .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128 => blk: {
                const value = exactIntBitsForLayout(exact, payload_layout) orelse
                    break :blk try self.invalidNumeralLiteral();
                break :blk try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
                    .target = target,
                    .value = .{ .i128_literal = .{ .value = value, .layout_idx = payload_layout } },
                    .next = next,
                } });
            },
            .f32 => try self.assignF32Literal(target, try exact_numeral.floatBits(f32, self.parent.allocator, exact), next),
            .f64 => try self.assignF64Literal(target, try exact_numeral.floatBits(f64, self.parent.allocator, exact), next),
            .dec => blk: {
                const bits = (try exact_numeral.decBits(self.parent.allocator, exact)) orelse
                    break :blk try self.invalidNumeralLiteral();
                break :blk try self.assignDecLiteral(target, .{ .num = bits }, next);
            },
            .bool, .str, .opaque_ptr, .zst, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2, _ => boxyLowerInvariant("checked numeral reached a non-numeric Boxy payload layout"),
        };
    }

    fn invalidNumeralLiteral(self: *ProcBodyBuilder) Allocator.Error!LIR.CFStmtId {
        return try self.parent.result.store.addCFStmt(.{ .crash = .{
            .msg = .{ .literal = try self.parent.result.store.insertString("invalid numeric literal") },
        } });
    }

    fn appendLiteralPayloadDesc(
        self: *ProcBodyBuilder,
        payload_layout: layout.Idx,
        checked_ty: checked.CheckedTypeId,
    ) Allocator.Error!LIR.BoxyDescRef {
        const desc_id: LIR.BoxyTypeDescId = @enumFromInt(@as(u32, @intCast(self.parent.result.boxy_type_descs.items.len)));
        const layout_value = self.parent.result.layouts.getLayout(payload_layout);
        try self.parent.result.boxy_type_descs.append(self.parent.allocator, .{
            .payload_layout = payload_layout,
            .contains_refcounted = self.parent.result.layouts.layoutContainsRefcounted(layout_value),
            .debug_checked_type = checked_ty,
        });
        return .{ .static = desc_id };
    }

    fn builtinNumeralLayoutForType(module: ProcedureModuleView, checked_ty: checked.CheckedTypeId) layout.Idx {
        const builtin = checkedBuiltinNominalForType(module, checked_ty) orelse
            boxyLowerInvariant("builtin numeral had no checked builtin nominal type");
        return switch (builtin) {
            .u8 => .u8,
            .i8 => .i8,
            .u16 => .u16,
            .i16 => .i16,
            .u32 => .u32,
            .i32 => .i32,
            .u64 => .u64,
            .i64 => .i64,
            .u128 => .u128,
            .i128 => .i128,
            .f32 => .f32,
            .f64 => .f64,
            .dec => .dec,
            .bool, .try_, .str, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2, .list, .box, .dict, .set, .iter, .parse_tag_union_spec, .fields, .field, .crypto_sha256_digest, .crypto_sha256_hasher, .crypto_blake3_digest, .crypto_blake3_hasher => boxyLowerInvariant("numeral had a non-numeric checked builtin nominal type"),
        };
    }

    fn exactIntBitsForLayout(exact: exact_numeral.Exact, payload_layout: layout.Idx) ?i128 {
        const target: exact_numeral.Target = switch (payload_layout) {
            .u8 => .u8,
            .i8 => .i8,
            .u16 => .u16,
            .i16 => .i16,
            .u32 => .u32,
            .i32 => .i32,
            .u64 => .u64,
            .i64 => .i64,
            .u128 => .u128,
            .i128 => .i128,
            .bool, .str, .f32, .f64, .dec, .opaque_ptr, .zst, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2, _ => boxyLowerInvariant("integer numeral requested bits for a non-integer layout"),
        };
        const bits = exact_numeral.intBits(exact, target) orelse return null;
        return switch (bits) {
            .i128 => |value| value,
            .u128 => |value| @bitCast(value),
        };
    }

    const GeneratedNumeralField = enum {
        is_negative,
        digits_before_pt,
        digits_after_pt,
        digits_after_pt_count,
    };

    fn lowerGeneratedNumeralInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        literal: can.ModuleEnv.NumeralLiteral,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (!literal.isMaterialized()) {
            boxyLowerInvariant("generated Numeral call operand was not materialized");
        }
        const literal_variant = self.generatedParserTagVariant(target_rep, "Literal");
        const payloads = self.parent.plan.childSlice(literal_variant.variant.payloads);
        if (payloads.len != 1) {
            boxyLowerInvariant("Numeral Literal tag did not have one record payload");
        }
        const record_rep = payloads[0].rep;
        const record = try self.addFrameBoundaryTargetLocalForRep(record_rep);
        const assign_tag = try self.assignGeneratedParserTag(
            target,
            target_rep,
            literal_variant,
            record,
            record_rep,
            next,
        );
        return try self.lowerGeneratedNumeralRecordInto(record, record_rep, literal, assign_tag);
    }

    fn lowerGeneratedNumeralRecordInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        literal: can.ModuleEnv.NumeralLiteral,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const record_rep = self.recordRepForBoundary(target_rep) orelse
            boxyLowerInvariant("Numeral Literal payload was not a record representation");
        const rep = self.parent.plan.representations.items[@intFromEnum(record_rep)];
        const view = procedureModuleById(self.parent.modules, rep.source_type.module);
        const payload_layout = switch (self.workerRuntimeLayoutForRep(target_rep)) {
            .concrete => self.parent.result.store.getLocal(target).layout_idx,
            .dynamic_box => self.parent.layout_plan.rep_layouts[@intFromEnum(record_rep)].descriptor_payload_layout orelse
                boxyLowerInvariant("dynamic Numeral record had no payload layout"),
        };
        const payload = switch (self.workerRuntimeLayoutForRep(target_rep)) {
            .concrete => target,
            .dynamic_box => try self.addFrameLocal(payload_layout),
        };
        const payload_layout_value = self.parent.result.layouts.getLayout(payload_layout);
        if (payload_layout_value.tag != .struct_) {
            boxyLowerInvariant("Numeral Literal record did not have a struct payload layout");
        }

        var fields: [4]LIR.LocalId = undefined;
        var field_reps: [4]Plan.TypeRepId = undefined;
        var field_kinds: [4]GeneratedNumeralField = undefined;
        var count: usize = 0;
        for (self.parent.plan.childSlice(rep.children)) |child| {
            const label = switch (child.role) {
                .record_field => |label| label,
                .record_ext => {
                    self.requireEmptyRecordExtension(child.rep);
                    continue;
                },
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("Numeral record representation had a non-record child"),
            };
            if (count >= fields.len) boxyLowerInvariant("Numeral record had too many fields");
            const field_text = view.canonical_names.recordFieldLabelText(label);
            field_kinds[count] = if (std.mem.eql(u8, field_text, "is_negative"))
                .is_negative
            else if (std.mem.eql(u8, field_text, "digits_before_pt"))
                .digits_before_pt
            else if (std.mem.eql(u8, field_text, "digits_after_pt"))
                .digits_after_pt
            else if (std.mem.eql(u8, field_text, "digits_after_pt_count"))
                .digits_after_pt_count
            else
                boxyLowerInvariant("Numeral record contained an unexpected field");
            field_reps[count] = child.rep;
            fields[count] = try self.addFrameLocal(self.parent.recordPayloadFieldLayout(payload_layout, @intCast(count)));
            count += 1;
        }
        if (count != fields.len) boxyLowerInvariant("Numeral record did not have four fields");

        var descriptor_fields: [4]AggregateDescriptorField = undefined;
        for (fields, field_reps, &descriptor_fields) |field, field_rep, *descriptor_field| {
            descriptor_field.* = .{
                .local = field,
                .target_rep = field_rep,
                .source_rep = field_rep,
            };
        }
        const aggregate_desc = try self.constructedAggregateDescriptorForFields(target, target_rep, &descriptor_fields);
        defer aggregate_desc.deinit(self.parent.allocator);
        var continuation = switch (self.workerRuntimeLayoutForRep(target_rep)) {
            .concrete => next,
            .dynamic_box => blk: {
                const payload_desc = aggregate_desc.desc orelse
                    boxyLowerInvariant("dynamic Numeral record had no descriptor");
                break :blk try self.parent.result.store.addCFStmt(.{ .assign_boxy_box = .{
                    .target = target,
                    .payload = payload,
                    .payload_layout = payload_layout,
                    .payload_desc = payload_desc,
                    .payload_mode = .move,
                    .next = next,
                } });
            },
        };
        continuation = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = payload,
            .fields = try self.parent.result.store.addLocalSpan(&fields),
            .contents_desc = aggregate_desc.contents_desc,
            .next = continuation,
        } });

        const before = self.module.module_env.numeralDigitsBefore(literal);
        const after = self.module.module_env.numeralDigitsAfter(literal);
        var index = fields.len;
        while (index > 0) {
            index -= 1;
            continuation = switch (field_kinds[index]) {
                .is_negative => try self.assignBoolLiteral(fields[index], literal.isNegative(), continuation),
                .digits_before_pt => try self.lowerGeneratedNumeralU8ListInto(fields[index], field_reps[index], before, continuation),
                .digits_after_pt => try self.lowerGeneratedNumeralU8ListInto(fields[index], field_reps[index], after, continuation),
                .digits_after_pt_count => try self.assignIntLiteral(fields[index], @intCast(literal.after_decimal_digit_count), continuation),
            };
        }
        continuation = try self.prependOptionalDescriptorMaterialization(aggregate_desc.materialize, continuation);
        return try self.prependDescriptorArgMaterializations(aggregate_desc.field_initializers, continuation);
    }

    fn lowerGeneratedNumeralU8ListInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        values: []const u8,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const list_rep = self.listRepForBoundary(target_rep) orelse
            boxyLowerInvariant("Numeral digit field was not a list representation");
        const elem_rep = self.repQuery().requiredSingleChild(list_rep, .list_elem).rep;
        if (self.workerRuntimeLayoutForRep(elem_rep).layoutIdx() != .u8 or self.localListElemLayout(target) != .u8) {
            boxyLowerInvariant("Numeral digit field was not a List(U8)");
        }
        const elems = try self.parent.allocator.alloc(LIR.LocalId, values.len);
        defer self.parent.allocator.free(elems);
        for (elems) |*elem| elem.* = try self.addFrameLocal(.u8);

        const desc_info = try self.stableDescriptorForConstructedValue(target, target_rep);
        if (desc_info.desc) |desc| self.parent.result.store.setLocalBoxyDesc(target, desc);
        var continuation = try self.assignList(target, elems, next);
        continuation = try self.prependOptionalDescriptorMaterialization(desc_info.materialize, continuation);
        var index = elems.len;
        while (index > 0) {
            index -= 1;
            continuation = try self.assignIntLiteral(elems[index], values[index], continuation);
        }
        return continuation;
    }

    /// Lower a builtin from_numeral conversion when no compile-time root was
    /// recorded for the expression.
    fn lowerNumFromNumeralInto(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        maybe_plan: ?static_dispatch.StaticDispatchPlanId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const plan = self.staticDispatchPlan(maybe_plan);
        const operands = plan.argsSlice(self.module.static_dispatch_plans);
        if (operands.len != 1) {
            boxyLowerInvariant("from_numeral plan did not carry exactly one operand");
        }
        const literal = switch (operands[0]) {
            .generated_numeral => |lit| lit,
            .checked_expr, .generated_interpolation_iter, .generated_quote => boxyLowerInvariant("from_numeral plan operand was not a generated numeral"),
        };
        if (self.dynamicLiteralRuntimeDesc(target)) |desc_ref| {
            const exact = self.module.module_env.exactNumeral(literal);
            const value: LIR.LiteralValue = if (exact.is_fractional) .{ .boxy_dynamic_frac_literal = .{
                .dec_bits = (try exact_numeral.decBits(self.parent.allocator, exact)) orelse
                    return try self.invalidNumeralLiteral(),
                .desc = desc_ref,
                .default_layout = .dec,
            } } else .{ .boxy_dynamic_num_literal = .{
                .value = exactIntBitsForLayout(exact, if (exact.is_negative) .i128 else .u128) orelse
                    return try self.invalidNumeralLiteral(),
                .desc = desc_ref,
                .default_layout = .dec,
            } };
            const assigned = try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
                .target = target,
                .value = value,
                .next = next,
            } });
            return try self.prependLiteralTargetDescriptorMaterialization(target, assigned);
        }
        if (self.dynamicLiteralTarget(target)) |info| {
            const payload = try self.addFrameLocal(info.payload_layout);
            const box = try self.assignBoxedLiteralPayload(target, payload, info, next);
            return try self.assignExactNumeralPayload(payload, info.payload_layout, literal, box);
        }
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        return try self.assignExactNumeralPayload(target, target_layout, literal, next);
    }

    fn prependLiteralTargetDescriptorMaterialization(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const target_desc = self.parent.result.store.getLocal(target).boxy_desc orelse return next;
        const local = target_desc.localOrNull() orelse return next;
        if (self.localIsReadOnlyDescriptorInput(local)) return next;
        if (std.mem.findScalar(LIR.LocalId, self.runtime_initialized_descriptor_locals.items, local) != null) return next;

        const template = self.descriptorTemplateForLocal(local) orelse {
            if (self.localIsDescriptorSlot(local)) return next;
            boxyLowerInvariant("dynamic literal target descriptor had no explicit producer template");
        };
        if (template.desc.localOrNull() == local) {
            boxyLowerInvariant("dynamic literal target descriptor producer referenced its own target");
        }
        return try self.prependDescriptorArgMaterialization(.{
            .local = local,
            .materialize = template.desc,
            .captures = template.captures,
        }, template.desc, next);
    }

    fn assignIntLiteral(self: *ProcBodyBuilder, target: LIR.LocalId, value: i128, next: LIR.CFStmtId) Allocator.Error!LIR.CFStmtId {
        if (self.dynamicLiteralRuntimeDesc(target)) |desc_ref| {
            // The target's numeric representation is only known through the
            // runtime descriptor; the literal encodes itself against it.
            const literal = try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
                .target = target,
                .value = .{ .boxy_dynamic_num_literal = .{
                    .value = value,
                    .desc = desc_ref,
                    .default_layout = .dec,
                } },
                .next = next,
            } });
            return try self.prependLiteralTargetDescriptorMaterialization(target, literal);
        }
        if (self.dynamicLiteralTarget(target)) |info| {
            const payload = try self.addFrameLocal(info.payload_layout);
            const box = try self.assignBoxedLiteralPayload(target, payload, info, next);
            return try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
                .target = payload,
                .value = .{ .i128_literal = .{
                    .value = value,
                    .layout_idx = info.payload_layout,
                } },
                .next = box,
            } });
        }
        return try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
            .target = target,
            .value = .{ .i128_literal = .{
                .value = value,
                .layout_idx = self.parent.result.store.getLocal(target).layout_idx,
            } },
            .next = next,
        } });
    }

    fn assignF32Literal(self: *ProcBodyBuilder, target: LIR.LocalId, value: f32, next: LIR.CFStmtId) Allocator.Error!LIR.CFStmtId {
        if (self.dynamicLiteralTargetForLayout(target, .f32)) |info| {
            if (info.payload_layout != .f32) {
                boxyLowerInvariant("boxy dynamic f32 literal descriptor did not resolve to f32 payload layout");
            }
            const payload = try self.addFrameLocal(.f32);
            const box = try self.assignBoxedLiteralPayload(target, payload, info, next);
            const literal = try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
                .target = payload,
                .value = .{ .f32_literal = value },
                .next = box,
            } });
            return try self.prependLiteralTargetDescriptorMaterialization(target, literal);
        }
        return try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
            .target = target,
            .value = .{ .f32_literal = value },
            .next = next,
        } });
    }

    fn assignF64Literal(self: *ProcBodyBuilder, target: LIR.LocalId, value: f64, next: LIR.CFStmtId) Allocator.Error!LIR.CFStmtId {
        if (self.dynamicLiteralTargetForLayout(target, .f64)) |info| {
            if (info.payload_layout != .f64) {
                boxyLowerInvariant("boxy dynamic f64 literal descriptor did not resolve to f64 payload layout");
            }
            const payload = try self.addFrameLocal(.f64);
            const box = try self.assignBoxedLiteralPayload(target, payload, info, next);
            const literal = try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
                .target = payload,
                .value = .{ .f64_literal = value },
                .next = box,
            } });
            return try self.prependLiteralTargetDescriptorMaterialization(target, literal);
        }
        return try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
            .target = target,
            .value = .{ .f64_literal = value },
            .next = next,
        } });
    }

    fn assignConstScalar(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        scalar: checked.ConstScalar,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return switch (scalar) {
            .i8 => |value| try self.assignIntLiteral(target, value, next),
            .i16 => |value| try self.assignIntLiteral(target, value, next),
            .i32 => |value| try self.assignIntLiteral(target, value, next),
            .i64 => |value| try self.assignIntLiteral(target, value, next),
            .i128 => |value| try self.assignIntLiteral(target, value, next),
            .u8 => |value| try self.assignIntLiteral(target, value, next),
            .u16 => |value| try self.assignIntLiteral(target, value, next),
            .u32 => |value| try self.assignIntLiteral(target, value, next),
            .u64 => |value| try self.assignIntLiteral(target, value, next),
            .u128 => |value| try self.assignIntLiteral(target, @bitCast(value), next),
            .f32_bits => |bits| try self.assignF32Literal(target, @bitCast(bits), next),
            .f64_bits => |bits| try self.assignF64Literal(target, @bitCast(bits), next),
            .dec_bits => |bits| try self.assignDecLiteral(target, .{ .num = bits }, next),
        };
    }

    fn assignStringLiteral(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        literal_id: checked.CheckedStringLiteralId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const text = self.module.checked_bodies.stringLiteral(literal_id);
        return try self.assignStringBytesLiteral(target, text, next);
    }

    fn lirStrLiteral(
        self: *ProcBodyBuilder,
        literal_id: checked.CheckedStringLiteralId,
    ) Allocator.Error!LIR.StrLiteral {
        const text = self.module.checked_bodies.stringLiteral(literal_id);
        return try self.parent.result.store.insertStringView(text, 0, @intCast(text.len));
    }

    fn assignStringBytesLiteral(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        text: []const u8,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.assignStringBytesView(target, text, 0, @intCast(text.len), next);
    }

    fn assignStringBytesView(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        backing: []const u8,
        offset: u32,
        len: u32,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.dynamicLiteralTargetForLayout(target, .str)) |info| {
            if (info.payload_layout != .str) {
                boxyLowerInvariant("boxy dynamic string literal descriptor did not resolve to string payload layout");
            }
            const payload = try self.addFrameLocal(.str);
            const box = try self.assignBoxedLiteralPayload(target, payload, info, next);
            return try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
                .target = payload,
                .value = .{ .str_literal = try self.parent.result.store.insertStringView(backing, offset, len) },
                .next = box,
            } });
        }
        return try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
            .target = target,
            .value = .{ .str_literal = try self.parent.result.store.insertStringView(backing, offset, len) },
            .next = next,
        } });
    }

    fn assignBoolLiteral(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        value: bool,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const variant: u16 = if (value) 1 else 0;
        return try self.parent.result.store.addCFStmt(.{ .assign_tag = .{
            .target = target,
            .variant_index = variant,
            .discriminant = variant,
            .payload = null,
            .next = next,
        } });
    }

    fn assignZst(self: *ProcBodyBuilder, target: LIR.LocalId, next: LIR.CFStmtId) Allocator.Error!LIR.CFStmtId {
        return try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = target,
            .fields = LIR.LocalSpan.empty(),
            .next = next,
        } });
    }

    fn assignList(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        elems: []const LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.parent.result.store.addCFStmt(.{ .assign_list = .{
            .target = target,
            .elems = try self.parent.result.store.addLocalSpan(elems),
            .next = next,
        } });
    }

    fn assignLocal(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (try self.assignToFixedDescriptorBoundary(target, source, next)) |adapted| return adapted;
        const assign = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = target,
            .op = .{ .local = source },
            .next = next,
        } });
        var transferred = try self.prependSetLocalDescriptorTransfer(target, source, .replace_existing, assign);
        transferred = try self.prependLocalDescriptorEnvironmentTransfer(target, source, .replace_existing, transferred);
        try self.recordTransferredLocalDescriptorEnvironment(target, source);
        return transferred;
    }

    fn assignLocalFromRep(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var continuation = try self.assignLocal(target, source, next);
        if (self.parent.result.store.getLocal(source).boxy_desc != null) return continuation;

        const target_desc = self.parent.result.store.getLocal(target).boxy_desc orelse return continuation;
        const target_desc_local = target_desc.localOrNull() orelse return continuation;
        if (self.localIsReadOnlyDescriptorInput(target_desc_local)) return continuation;

        const materialization = try self.descriptorMaterializationForSourceStorageLocalRep(source, source_rep);
        continuation = try self.prependDescriptorArgMaterialization(.{
            .local = target_desc_local,
            .materialize = materialization.desc,
            .captures = materialization.captures,
        }, materialization.desc, continuation);
        return continuation;
    }

    fn assignToFixedDescriptorBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!?LIR.CFStmtId {
        const target_desc = self.parent.result.store.getLocal(target).boxy_desc orelse return null;
        const source_desc = self.parent.result.store.getLocal(source).boxy_desc orelse return null;
        if (std.meta.eql(target_desc, source_desc)) return null;

        const target_is_fixed = if (target_desc.localOrNull()) |local|
            self.localIsReadOnlyDescriptorInput(local)
        else
            true;
        if (!target_is_fixed) return null;

        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        const adapter = try self.internMoveAdapter(.materialize, source_layout, target_layout);
        return try self.parent.result.store.addCFStmt(.{ .assign_boxy_adapt = .{
            .target = target,
            .source = source,
            .adapter = adapter,
            .source_desc = source_desc,
            .target_desc = target_desc,
            .source_mode = .move,
            .next = next,
        } });
    }

    fn assignNominalBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        if (target_layout == source_layout) {
            return if (target == source) next else try self.assignLocal(target, source, next);
        }

        if (self.isZstLocal(target)) {
            if (!self.isZstLocal(source)) {
                boxyLowerInvariant("nominal boundary tried to store non-zero-sized source into zero-sized target");
            }
            return try self.assignZst(target, next);
        }

        // A concrete non-box value crossing into dynamic box storage must be
        // boxed, not reinterpreted; the descriptor records the payload layout.
        const target_layout_value = self.parent.result.layouts.getLayout(target_layout);
        const source_layout_value = self.parent.result.layouts.getLayout(source_layout);
        const target_is_box = target_layout_value.tag == .box or target_layout_value.tag == .box_of_zst or target_layout_value.tag == .erased_box;
        const source_is_box = source_layout_value.tag == .box or source_layout_value.tag == .box_of_zst or source_layout_value.tag == .erased_box;
        const source_is_list = source_layout_value.tag == .list or source_layout_value.tag == .list_of_zst;
        if (target_is_box and !source_is_box and !source_is_list) {
            const desc_id: LIR.BoxyTypeDescId = @enumFromInt(@as(u32, @intCast(self.parent.result.boxy_type_descs.items.len)));
            try self.parent.result.boxy_type_descs.append(self.parent.allocator, .{
                .payload_layout = source_layout,
                .contains_refcounted = self.parent.result.layouts.layoutContainsRefcounted(source_layout_value),
            });
            const payload_desc = LIR.BoxyDescRef{ .static = desc_id };
            self.parent.result.store.setLocalBoxyDesc(target, payload_desc);
            return try self.parent.result.store.addCFStmt(.{ .assign_boxy_box = .{
                .target = target,
                .payload = source,
                .payload_layout = source_layout,
                .payload_desc = payload_desc,
                .payload_mode = .move,
                .next = next,
            } });
        }

        return try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = target,
            .op = .{ .nominal = .{ .backing_ref = source } },
            .next = next,
        } });
    }

    fn assignErasedCallableBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_function: FunctionChildren,
        source_function: FunctionChildren,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (!try self.callableBoundaryNeedsAdapter(target_function, source_function)) {
            return if (target == source) next else try self.assignLocal(target, source, next);
        }

        const adapter = try self.emitCallableAdapterProc(source_function, target_function);
        const descriptor_captures = try self.collectCallableAdapterDescriptorCaptures(source_function, target_function);
        defer self.parent.allocator.free(descriptor_captures);

        const capture_local = try self.addFrameLocal(adapter.capture_layout);
        const capture_fields = try self.parent.allocator.alloc(LIR.LocalId, 1 + descriptor_captures.len);
        defer self.parent.allocator.free(capture_fields);
        const capture_needs_materialization = try self.parent.allocator.alloc(bool, descriptor_captures.len);
        defer self.parent.allocator.free(capture_needs_materialization);
        capture_fields[0] = source;

        var descriptor_materializations = std.ArrayList(DescriptorArgLocal).empty;
        defer descriptor_materializations.deinit(self.parent.allocator);
        var result_desc_initializers = std.ArrayList(DescriptorArgLocal).empty;
        defer result_desc_initializers.deinit(self.parent.allocator);

        const descriptor_snapshot = try self.snapshotDescriptorBindings();
        defer descriptor_snapshot.deinit(self.parent.allocator);
        defer self.restoreDescriptorBindings(descriptor_snapshot);
        try self.bindLocalDescriptorEnvironment(source);

        for (descriptor_captures, 0..) |capture, index| {
            const desc_index = @intFromEnum(capture.desc);
            if (desc_index >= self.descriptor_locals.len) {
                boxyLowerInvariant("boxy callable adapter capture descriptor exceeded descriptor table");
            }
            const materializes_capture_rep =
                capture.materialize_read_path.len != 0 or
                self.descriptorStorageRep(capture.materialize_rep) == self.descriptorStorageRep(capture.rep);
            const force_materialize_self_tag_descriptor =
                materializes_capture_rep and
                capture.materialize_read_path.len == 0 and
                self.tagVariantRepForBoundary(capture.rep) != null;
            if (!force_materialize_self_tag_descriptor) {
                if (self.localEnvironmentDescriptorForRequirementAndRep(
                    source,
                    capture.desc,
                    capture.rep,
                )) |local| {
                    capture_fields[1 + index] = local;
                    capture_needs_materialization[index] = false;
                    continue;
                }
                if (capture.materialize_read_path.len == 0 and
                    self.descriptorStorageRep(capture.materialize_rep) == self.descriptorStorageRep(capture.rep))
                {
                    if (self.descriptorLocalForRequirementAndRepOrNull(capture.desc, capture.rep)) |local| {
                        if (self.descriptorLocalAvailableFromSource(source, local)) {
                            capture_fields[1 + index] = local;
                            capture_needs_materialization[index] = false;
                            continue;
                        }
                    }
                }
                if (capture.materialize_read_path.len == 0) {
                    if (self.localEnvironmentDescriptorForRequirementAndRep(
                        source,
                        capture.desc,
                        capture.materialize_rep,
                    )) |local| {
                        capture_fields[1 + index] = local;
                        capture_needs_materialization[index] = false;
                        continue;
                    }
                }
                if (self.descriptorLocalForRequirementAndRepOrNull(capture.desc, capture.materialize_rep)) |local| {
                    if (self.descriptorLocalAvailableFromSource(source, local)) {
                        capture_fields[1 + index] = local;
                        capture_needs_materialization[index] = false;
                        continue;
                    }
                }
                // The capture requirement belongs to the adapted function,
                // while materialize_rep belongs to the source function and can
                // therefore have a different requirement id. Reuse the source
                // rep's explicit descriptor binding when it exists; rebuilding
                // its descriptor can lose the exact runtime box allocation
                // identity already established at the call site.
                if (capture.materialize_read_path.len == 0) {
                    if (self.descriptorLocalForRepOrNull(capture.materialize_rep)) |local| {
                        if (self.descriptorLocalAvailableFromSource(source, local)) {
                            capture_fields[1 + index] = local;
                            capture_needs_materialization[index] = false;
                            continue;
                        }
                    }
                }
            }

            const local = try self.addFrameLocal(.opaque_ptr);
            try self.setDescriptorRequirementLocalForRep(capture.desc, capture.materialize_rep, local);
            try self.setDescriptorRequirementLocalForRep(capture.desc, capture.rep, local);
            capture_fields[1 + index] = local;
            capture_needs_materialization[index] = true;
        }

        for (descriptor_captures, capture_fields[1..], capture_needs_materialization) |capture, local, needs_materialization| {
            if (!needs_materialization) continue;
            const materialization: DescriptorMaterialization = if (self.static_descriptor_materialization_scope) |scope|
                .{ .desc = try self.parent.staticDescRefForWorkerRepWithSourceMap(
                    capture.materialize_rep,
                    scope.sources.get(capture.desc),
                    scope.sources,
                    scope.context,
                ) }
            else if (capture.materialize_read_path.len != 0) blk: {
                const root_rep = self.descriptorStorageRep(capture.materialize_rep);
                const root_desc = self.parent.plan.representations.items[@intFromEnum(root_rep)].descriptor orelse
                    boxyLowerInvariant("boxy callable adapter descriptor read path had no root descriptor requirement");
                const root_local = self.descriptorLocalForRequirementAndRepOrNull(root_desc, root_rep) orelse
                    boxyLowerInvariant("boxy callable adapter descriptor read path had no bound root descriptor");
                break :blk .{ .desc = .{ .local = root_local } };
            } else try self.descriptorMaterializationForSourceRep(capture.materialize_rep);
            if (materialization.captures.len == 0) {
                if (materialization.desc.localOrNull()) |materialized_local| {
                    if (materialized_local == local) {
                        continue;
                    }
                }
            }

            try descriptor_materializations.append(self.parent.allocator, .{
                .local = local,
                .materialize = materialization.desc,
                .read_path = capture.materialize_read_path,
                .captures = materialization.captures,
            });
        }

        var target_capture_index = descriptor_captures.len;
        while (target_capture_index > 0) {
            target_capture_index -= 1;
            try self.bindDescriptorCaptureTargetLocal(
                descriptor_captures[target_capture_index],
                capture_fields[1 + target_capture_index],
                &result_desc_initializers,
            );
        }

        const result_desc = try self.exactCallResultDescriptorRef(target_function.ret);
        try self.appendResultDescriptorInitializers(&result_desc_initializers, result_desc);

        var callable_bindings = std.ArrayList(LocalDescriptorEnvironmentBinding).empty;
        defer callable_bindings.deinit(self.parent.allocator);
        for (descriptor_captures, capture_fields[1..]) |capture, local| {
            try self.appendLocalDescriptorEnvironmentBinding(&callable_bindings, capture.desc, capture.rep, local);
            try self.appendLocalDescriptorEnvironmentBinding(&callable_bindings, capture.desc, capture.materialize_rep, local);
        }
        try self.recordLocalDescriptorEnvironment(target, target_function.rep, callable_bindings.items);

        const assign_callable = try self.parent.result.store.addCFStmt(.{ .assign_packed_erased_fn = .{
            .target = target,
            .proc = adapter.proc,
            .capture = capture_local,
            .capture_layout = adapter.capture_layout,
            .on_drop = self.erasedCallableOnDrop(adapter.capture_layout),
            .result_desc = result_desc.desc,
            .next = next,
        } });

        var continuation = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = capture_local,
            .fields = try self.parent.result.store.addLocalSpan(capture_fields),
            .next = assign_callable,
        } });
        continuation = try self.prependDescriptorArgMaterializations(result_desc_initializers.items, continuation);

        return try self.prependHiddenDescriptorArgMaterialization(descriptor_materializations.items, continuation);
    }

    fn callableBoundaryNeedsAdapter(
        self: *ProcBodyBuilder,
        target_function: FunctionChildren,
        source_function: FunctionChildren,
    ) Allocator.Error!bool {
        if (target_function.arg_count != source_function.arg_count) {
            boxyLowerInvariant("boxy erased callable boundary saw mismatched function arity");
        }

        const target_args = self.functionArgChildren(target_function);
        const source_args = self.functionArgChildren(source_function);
        for (target_args, source_args) |target_arg, source_arg| {
            if (!self.callableArgumentBoundaryIsDirect(target_arg.rep, source_arg.rep)) return true;
        }

        return !self.representationBoundaryIsDirect(target_function.ret, source_function.ret);
    }

    fn repsUseSameDynamicBoxStorage(
        self: *ProcBodyBuilder,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
    ) bool {
        const target_runtime = self.workerRuntimeLayoutForRep(self.descriptorStorageRep(target_rep));
        const source_runtime = self.workerRuntimeLayoutForRep(self.descriptorStorageRep(source_rep));
        return switch (target_runtime) {
            .dynamic_box => |target_dynamic| switch (source_runtime) {
                .dynamic_box => |source_dynamic| target_dynamic.storage_layout == source_dynamic.storage_layout,
                .concrete => false,
            },
            .concrete => false,
        };
    }

    fn repsUseSameBoxStorage(
        self: *ProcBodyBuilder,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
    ) bool {
        const target_layout = self.workerRuntimeLayoutForRep(target_rep).layoutIdx();
        const source_layout = self.workerRuntimeLayoutForRep(source_rep).layoutIdx();
        const target_is_box = switch (self.parent.result.layouts.getLayout(target_layout).tag) {
            .box, .box_of_zst, .erased_box => true,
            .scalar, .list, .list_of_zst, .struct_, .closure, .erased_callable, .zst, .tag_union, .ptr => false,
        };
        return target_is_box and switch (self.parent.result.layouts.getLayout(source_layout).tag) {
            .box, .box_of_zst, .erased_box => true,
            .scalar, .list, .list_of_zst, .struct_, .closure, .erased_callable, .zst, .tag_union, .ptr => false,
        };
    }

    fn representationBoundaryIsDirect(
        self: *ProcBodyBuilder,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
    ) bool {
        if (self.workerRuntimeLayoutForRep(target_rep).layoutIdx() != self.workerRuntimeLayoutForRep(source_rep).layoutIdx()) {
            return false;
        }
        if (self.repIsFullyConcrete(target_rep) and self.repIsFullyConcrete(source_rep)) return true;
        return target_rep == source_rep and
            self.descriptorStorageRep(target_rep) == self.descriptorStorageRep(source_rep);
    }

    fn callableArgumentBoundaryIsDirect(
        self: *ProcBodyBuilder,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
    ) bool {
        if (!self.representationBoundaryIsDirect(target_rep, source_rep)) return false;
        if (target_rep == source_rep) return true;
        return self.repIsFullyConcrete(target_rep) and self.repIsFullyConcrete(source_rep);
    }

    fn emitCallableAdapterProc(
        self: *ProcBodyBuilder,
        source_function: FunctionChildren,
        target_function: FunctionChildren,
    ) Allocator.Error!CallableAdapterCacheEntry {
        if (source_function.arg_count != target_function.arg_count) {
            boxyLowerInvariant("boxy callable adapter requested for mismatched function arity");
        }

        for (self.parent.callable_adapter_cache.items) |entry| {
            if (entry.source_rep == source_function.rep and entry.target_rep == target_function.rep) return entry;
        }

        const descriptor_captures = try self.collectCallableAdapterDescriptorCaptures(source_function, target_function);
        defer self.parent.allocator.free(descriptor_captures);

        const source_closure_layout = self.workerRuntimeLayoutForRep(source_function.rep).layoutIdx();
        const capture_layout = try self.callableAdapterCaptureLayout(source_closure_layout, descriptor_captures.len);
        var adapter_proc = ProcBodyBuilder.initSyntheticAdapter(self.parent, self.module, self.worker_layout);
        defer adapter_proc.deinit();

        const source_closure = try adapter_proc.addFrameLocal(source_closure_layout);
        const target_args = self.functionArgChildren(target_function);
        const source_args = self.functionArgChildren(source_function);
        const target_arg_locals = try self.parent.allocator.alloc(LIR.LocalId, target_function.arg_count);
        defer self.parent.allocator.free(target_arg_locals);
        for (target_args, target_arg_locals) |arg, *local| {
            local.* = try adapter_proc.addArgLocalForRep(arg.rep);
        }
        const capture_arg = try adapter_proc.addArgLocal(.opaque_ptr);
        const descriptor_locals = try self.parent.allocator.alloc(LIR.LocalId, descriptor_captures.len);
        defer self.parent.allocator.free(descriptor_locals);
        var capture_descriptor_initializers = std.ArrayList(DescriptorArgLocal).empty;
        defer capture_descriptor_initializers.deinit(self.parent.allocator);
        for (descriptor_captures, descriptor_locals) |capture, *local| {
            local.* = try adapter_proc.addFrameLocal(.opaque_ptr);
            try adapter_proc.bindDescriptorCaptureSourceLocal(capture, local.*);
        }
        var capture_index = descriptor_captures.len;
        while (capture_index > 0) {
            capture_index -= 1;
            try adapter_proc.bindDescriptorCaptureTargetLocal(
                descriptor_captures[capture_index],
                descriptor_locals[capture_index],
                &capture_descriptor_initializers,
            );
        }
        const erased_arg_desc_params = try adapter_proc.bindErasedArgumentDescriptorParams(target_function);
        const erased_reuse_arg = try adapter_proc.addArgLocal(try self.parent.result.layouts.insertErasedCallable());

        const ret_layout = adapter_proc.workerRuntimeLayoutForRep(target_function.ret).layoutIdx();
        const ret_local = try adapter_proc.addFrameLocalForRepWithFreshDescriptor(target_function.ret);
        const args_span = try self.parent.result.store.addLocalSpan(adapter_proc.arg_locals.items);
        const proc_id = try self.parent.result.store.addProcSpec(.{
            .name = lirSymbol(self.parent.symbols.fresh()),
            .args = args_span,
            .body = null,
            .ret_layout = ret_layout,
            .abi = .erased_callable,
            .erased_reuse_arg = erased_reuse_arg,
            .erased_call_args = try adapter_proc.erasedCallArgsPlan(target_arg_locals),
            .boxy_runtime_entry = true,
            .stack_probe = self.parent.stackProbeForProc(args_span, LIR.LocalSpan.empty(), ret_layout),
        });
        const cache_len = self.parent.callable_adapter_cache.items.len;
        errdefer self.parent.callable_adapter_cache.shrinkRetainingCapacity(cache_len);
        const cache_entry = CallableAdapterCacheEntry{
            .source_rep = source_function.rep,
            .target_rep = target_function.rep,
            .proc = proc_id,
            .capture_layout = capture_layout,
        };
        try self.parent.callable_adapter_cache.append(self.parent.allocator, cache_entry);

        const ret_stmt = try self.parent.result.store.addCFStmt(.{ .ret = .{ .value = ret_local } });
        var continuation = ret_stmt;

        const raw_ret = try adapter_proc.addFrameLocalForRepWithFreshDescriptor(source_function.ret);
        continuation = try adapter_proc.assignPlannedCallBoundary(
            ret_local,
            raw_ret,
            target_function.ret,
            source_function.ret,
            continuation,
        );
        const call_target = raw_ret;

        const out_desc = adapter_proc.callResultOutputDescriptorLocal(call_target);
        if (out_desc) |local| {
            try adapter_proc.markDescriptorLocalBound(local);
        }

        const call_args = try self.parent.allocator.alloc(LIR.LocalId, source_function.arg_count);
        defer self.parent.allocator.free(call_args);
        for (source_args, target_args, target_arg_locals, call_args) |source_arg, target_arg, target_arg_local, *call_arg| {
            call_arg.* = if (adapter_proc.callableArgumentBoundaryIsDirect(source_arg.rep, target_arg.rep))
                target_arg_local
            else
                try adapter_proc.addFrameBoundaryTargetLocalForRep(source_arg.rep);
        }

        const call_placeholder = try self.parent.result.store.addCFStmt(.runtime_error);
        var call_with_args = call_placeholder;
        var arg_index = source_function.arg_count;
        while (arg_index > 0) {
            arg_index -= 1;
            if (call_args[arg_index] == target_arg_locals[arg_index]) continue;
            call_with_args = try adapter_proc.assignPlannedCallBoundaryCopyingSource(
                call_args[arg_index],
                target_arg_locals[arg_index],
                source_args[arg_index].rep,
                target_args[arg_index].rep,
                call_with_args,
            );
        }

        var arg_desc_initializers = std.ArrayList(DescriptorArgLocal).empty;
        defer arg_desc_initializers.deinit(self.parent.allocator);
        const arg_descs = try adapter_proc.erasedCallArgumentDescriptorRefs(
            source_args,
            call_args,
            &arg_desc_initializers,
        );
        const expected_result_desc = try adapter_proc.exactCallResultDescriptorRef(source_function.ret);
        try adapter_proc.appendResultDescriptorInitializers(&arg_desc_initializers, expected_result_desc);
        const call_stmt = try self.parent.result.store.addCFStmt(.{
            .assign_call_erased = .{
                .target = call_target,
                .closure = source_closure,
                .args = try self.parent.result.store.addLocalSpan(call_args),
                .arg_layouts = try adapter_proc.appendErasedArgumentLayouts(call_args),
                .arg_plan = try adapter_proc.erasedCallArgsPlan(call_args),
                .arg_descs = arg_descs.locals,
                .arg_desc_keys = arg_descs.keys,
                // `result_desc` governs materialization into the source
                // signature's result layout. `out_desc` separately
                // preserves the exact descriptor returned by the callable.
                .result_desc = expected_result_desc.desc,
                .out_desc = out_desc,
                .reuse_closure = false,
                .reuse_source = null,
                .next = continuation,
            },
        });
        const call_entry = try adapter_proc.prependDescriptorArgMaterializations(arg_desc_initializers.items, call_stmt);
        self.parent.result.store.getCFStmtPtr(call_placeholder).* = self.parent.result.store.getCFStmt(call_entry);
        continuation = call_with_args;

        continuation = try adapter_proc.prependWorkerArgumentDescriptorInitializers(continuation);
        continuation = try adapter_proc.prependCallableAdapterCaptureBindings(
            capture_arg,
            capture_layout,
            source_closure,
            descriptor_locals,
            try adapter_proc.prependDescriptorArgMaterializations(
                capture_descriptor_initializers.items,
                try adapter_proc.prependStaticDescriptorMaterializationsForSlots(continuation),
            ),
        );

        const proc_spec = self.parent.result.store.getProcSpecPtr(proc_id);
        proc_spec.body = continuation;
        proc_spec.erased_arg_desc_offsets = try adapter_proc.callableAdapterArgumentDescriptorCaptureOffsets(
            target_function,
            descriptor_captures,
            capture_layout,
        );
        proc_spec.erased_arg_layouts = try adapter_proc.appendErasedArgumentLayouts(target_arg_locals);
        proc_spec.erased_arg_desc_params = erased_arg_desc_params;
        proc_spec.erased_capture_arg = capture_arg;
        const return_desc = try self.parent.returnDescriptorInfoForBody(
            continuation,
            args_span,
            self.parent.result.store.getLocal(ret_local).boxy_desc,
            &adapter_proc.frame_locals,
        );
        const frame_span = try self.parent.result.store.addLocalSpan(adapter_proc.frame_locals.items);
        proc_spec.frame_locals = frame_span;
        proc_spec.ret_desc = return_desc.external;
        proc_spec.runtime_ret_desc = return_desc.runtime_local;
        proc_spec.stack_probe = self.parent.stackProbeForProc(args_span, frame_span, ret_layout);
        return cache_entry;
    }

    fn callableAdapterArgumentDescriptorCaptureOffsets(
        self: *ProcBodyBuilder,
        function: FunctionChildren,
        descriptor_captures: []const CallableAdapterDescriptorCapture,
        capture_layout_idx: layout.Idx,
    ) Allocator.Error!LIR.BoxySpan {
        const capture_layout = self.parent.result.layouts.getLayout(capture_layout_idx);
        if (capture_layout.tag != .struct_) {
            boxyLowerInvariant("boxy callable adapter argument descriptors required struct capture storage");
        }
        var seen_reps = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen_reps.deinit();
        var seen_descs = collections.DenseMap(Plan.DescriptorRequirementId, void).init(self.parent.allocator);
        defer seen_descs.deinit();
        const start = self.parent.result.boxy_erased_arg_desc_offsets.items.len;
        for (self.functionArgChildren(function), 0..) |arg, arg_index| {
            var params = std.ArrayList(Plan.HiddenDescriptorParam).empty;
            defer params.deinit(self.parent.allocator);
            try self.collectHiddenDescriptorParamsForRep(arg.rep, &params, &seen_reps, &seen_descs);
            for (params.items, 0..) |param, descriptor_index| {
                if (arg_index > std.math.maxInt(u16)) {
                    boxyLowerInvariant("boxy callable adapter argument descriptor key exceeded its index range");
                }
                if (descriptor_index > std.math.maxInt(u16)) {
                    boxyLowerInvariant("boxy callable adapter argument descriptor index exceeded its key range");
                }
                const source = self.erasedArgumentDescriptorParamSource(params.items, descriptor_index);
                if (source.nested_index != std.math.maxInt(u16)) continue;
                var capture_index: ?u16 = null;
                for (descriptor_captures, 0..) |capture, index| {
                    if (capture.desc != param.desc) continue;
                    if (self.descriptorStorageRep(capture.rep) != self.descriptorStorageRep(param.rep) and
                        self.descriptorStorageRep(capture.materialize_rep) != self.descriptorStorageRep(param.rep))
                    {
                        continue;
                    }
                    if (capture_index != null) {
                        boxyLowerInvariant("boxy callable adapter argument descriptor matched multiple capture fields");
                    }
                    capture_index = @intCast(index + 1);
                }
                const index = capture_index orelse
                    boxyLowerInvariant("boxy callable adapter argument descriptor had no exact capture field");
                try self.parent.result.boxy_erased_arg_desc_offsets.append(
                    self.parent.allocator,
                    .{
                        .key = .{
                            .arg_index = @intCast(arg_index),
                            .descriptor_index = @intCast(descriptor_index),
                        },
                        .offset = self.parent.result.layouts.getStructFieldOffsetByOriginalIndex(capture_layout.getStruct().idx, index),
                    },
                );
            }
        }
        return .{
            .start = @intCast(start),
            .len = @intCast(self.parent.result.boxy_erased_arg_desc_offsets.items.len - start),
        };
    }

    fn collectCallableAdapterDescriptorCaptures(
        self: *ProcBodyBuilder,
        source_function: FunctionChildren,
        target_function: FunctionChildren,
    ) Allocator.Error![]CallableAdapterDescriptorCapture {
        var captures = std.ArrayList(CallableAdapterDescriptorCapture).empty;
        defer captures.deinit(self.parent.allocator);
        var seen_descs = collections.DenseMap(Plan.DescriptorRequirementId, usize).init(self.parent.allocator);
        defer seen_descs.deinit();

        // Target argument descriptor slots are overwritten by each invocation,
        // but the closure still needs valid initial descriptor values. Derive
        // those values from the corresponding source arguments. Nested
        // requirements unique to the source signature are immutable identities
        // of the wrapped callable and must be captured separately: an incoming
        // concrete root descriptor may legitimately omit them.
        try self.collectCallableAdapterDescriptorCapturesForFunction(
            target_function,
            source_function,
            true,
            false,
            &captures,
            &seen_descs,
        );
        try self.collectCallableAdapterSourceArgumentDescriptorCaptures(
            source_function,
            target_function,
            &captures,
            &seen_descs,
        );
        try self.appendMissingCallableAdapterResultDescriptorCaptures(
            source_function,
            target_function,
            &captures,
            &seen_descs,
        );
        try self.appendMissingCallableAdapterResultDescriptorCaptures(
            target_function,
            source_function,
            &captures,
            &seen_descs,
        );
        return try captures.toOwnedSlice(self.parent.allocator);
    }

    fn appendMissingCallableAdapterResultDescriptorCaptures(
        self: *ProcBodyBuilder,
        function: FunctionChildren,
        materialize_from: FunctionChildren,
        pending: *std.ArrayList(CallableAdapterDescriptorCapture),
        seen_descs: *collections.DenseMap(Plan.DescriptorRequirementId, usize),
    ) Allocator.Error!void {
        var candidates = std.ArrayList(CallableAdapterDescriptorCapture).empty;
        defer candidates.deinit(self.parent.allocator);
        var candidate_seen = collections.DenseMap(Plan.DescriptorRequirementId, usize).init(self.parent.allocator);
        defer candidate_seen.deinit();
        try self.collectCallableAdapterDescriptorCapturesForFunction(
            function,
            materialize_from,
            false,
            true,
            &candidates,
            &candidate_seen,
        );

        for (candidates.items) |capture| {
            if (seen_descs.contains(capture.desc)) continue;
            try seen_descs.put(capture.desc, pending.items.len);
            try pending.append(self.parent.allocator, capture);
        }
    }

    fn collectCallableAdapterSourceArgumentDescriptorCaptures(
        self: *ProcBodyBuilder,
        source_function: FunctionChildren,
        target_function: FunctionChildren,
        pending: *std.ArrayList(CallableAdapterDescriptorCapture),
        seen_descs: *collections.DenseMap(Plan.DescriptorRequirementId, usize),
    ) Allocator.Error!void {
        if (source_function.arg_count != target_function.arg_count) {
            boxyLowerInvariant("boxy callable adapter source descriptor capture saw mismatched arity");
        }

        var source_seen_reps = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer source_seen_reps.deinit();
        var source_seen_descs = collections.DenseMap(Plan.DescriptorRequirementId, void).init(self.parent.allocator);
        defer source_seen_descs.deinit();
        for (self.functionArgChildren(source_function)) |arg| {
            var params = std.ArrayList(Plan.HiddenDescriptorParam).empty;
            defer params.deinit(self.parent.allocator);
            try self.collectHiddenDescriptorParamsForRep(arg.rep, &params, &source_seen_reps, &source_seen_descs);
            for (params.items) |param| {
                const is_root = self.repOwnsShapeDescriptor(param.rep, param.desc) and
                    self.descriptorShapeIdentityRep(arg.rep) == self.descriptorShapeIdentityRep(param.rep);
                if (is_root or seen_descs.contains(param.desc)) continue;

                const index = pending.items.len;
                try seen_descs.put(param.desc, index);
                try pending.append(self.parent.allocator, .{
                    .desc = param.desc,
                    .rep = param.rep,
                    .materialize_rep = param.rep,
                    .source_type = param.source_type,
                });
            }
        }
    }

    fn collectCallableWorkerDescriptorCaptures(
        self: *ProcBodyBuilder,
        worker_function: FunctionChildren,
        call_function: FunctionChildren,
    ) Allocator.Error![]CallableAdapterDescriptorCapture {
        return try self.collectCallableDescriptorCaptures(worker_function, call_function);
    }

    fn collectCallableDescriptorCaptures(
        self: *ProcBodyBuilder,
        source_function: FunctionChildren,
        target_function: FunctionChildren,
    ) Allocator.Error![]CallableAdapterDescriptorCapture {
        var captures = std.ArrayList(CallableAdapterDescriptorCapture).empty;
        defer captures.deinit(self.parent.allocator);
        var seen_descs = collections.DenseMap(Plan.DescriptorRequirementId, usize).init(self.parent.allocator);
        defer seen_descs.deinit();

        try self.collectCallableAdapterDescriptorCapturesForFunction(source_function, target_function, true, true, &captures, &seen_descs);
        try self.collectCallableAdapterDescriptorCapturesForFunction(target_function, source_function, true, true, &captures, &seen_descs);

        return try captures.toOwnedSlice(self.parent.allocator);
    }

    fn collectCallableAdapterDescriptorCapturesForFunction(
        self: *ProcBodyBuilder,
        function: FunctionChildren,
        materialize_from: FunctionChildren,
        include_args: bool,
        include_return: bool,
        pending: *std.ArrayList(CallableAdapterDescriptorCapture),
        seen_descs: *collections.DenseMap(Plan.DescriptorRequirementId, usize),
    ) Allocator.Error!void {
        if (function.arg_count != materialize_from.arg_count) {
            boxyLowerInvariant("boxy callable adapter descriptor capture saw mismatched function arity");
        }

        var params = std.ArrayList(Plan.HiddenDescriptorParam).empty;
        defer params.deinit(self.parent.allocator);
        var seen_reps = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen_reps.deinit();
        var seen_requirements = collections.DenseMap(Plan.DescriptorRequirementId, void).init(self.parent.allocator);
        defer seen_requirements.deinit();
        if (include_args) {
            for (self.functionArgChildren(function)) |arg| {
                try self.collectHiddenDescriptorParamsForRep(arg.rep, &params, &seen_reps, &seen_requirements);
            }
        }
        if (include_return) {
            try self.collectHiddenDescriptorParamsForRep(function.ret, &params, &seen_reps, &seen_requirements);
        }
        if (params.items.len == 0) return;

        var mapped = collections.DenseMap(Plan.DescriptorRequirementId, CallableAdapterDescriptorCaptureSource).init(self.parent.allocator);
        defer mapped.deinit();
        var seen_rep_pairs = std.AutoHashMap(u64, void).init(self.parent.allocator);
        defer seen_rep_pairs.deinit();
        var substitutions = collections.DenseMap(Plan.TypeRepId, Plan.TypeRepId).init(self.parent.allocator);
        defer substitutions.deinit();

        if (include_args) {
            const function_args = self.functionArgChildren(function);
            const materialize_args = self.functionArgChildren(materialize_from);
            for (function_args, materialize_args) |function_arg, materialize_arg| {
                if (!try self.collectCallableAdapterDescriptorCaptureSources(function_arg.rep, materialize_arg.rep, params.items, &mapped, &seen_rep_pairs, &substitutions, false)) {
                    boxyLowerInvariant("boxy callable adapter descriptor mapping saw mismatched argument reps");
                }
            }
        }
        if (include_return) {
            if (!try self.collectCallableAdapterDescriptorCaptureSources(function.ret, materialize_from.ret, params.items, &mapped, &seen_rep_pairs, &substitutions, true)) {
                boxyLowerInvariant("boxy callable adapter descriptor mapping saw mismatched return reps");
            }
        }

        for (params.items) |param| {
            const materialize_source = mapped.get(param.desc) orelse blk: {
                const identity_param_rep = self.repQuery().descriptorArgumentIdentityRep(param.rep);
                if (identity_param_rep != param.rep) {
                    const identity_rep = self.parent.plan.representations.items[@intFromEnum(identity_param_rep)];
                    if (identity_rep.descriptor) |identity_desc| {
                        if (mapped.get(identity_desc)) |source| break :blk source;
                    }
                }
                boxyLowerInvariant("boxy callable adapter descriptor mapping did not cover a descriptor capture");
            };
            const materialize_rep = materialize_source.rep;
            if (seen_descs.get(param.desc)) |existing_index| {
                const existing = pending.items[existing_index];
                if (self.descriptorStorageRep(existing.materialize_rep) != self.descriptorStorageRep(materialize_rep) or
                    !self.descriptorReadPathSpansEql(existing.materialize_read_path, materialize_source.read_path))
                {
                    const existing_materializes_self =
                        existing.materialize_read_path.len == 0 and
                        self.descriptorStorageRep(existing.materialize_rep) == self.descriptorStorageRep(existing.rep);
                    const new_materializes_self =
                        materialize_source.read_path.len == 0 and
                        self.descriptorStorageRep(materialize_rep) == self.descriptorStorageRep(param.rep);
                    if (existing_materializes_self) continue;
                    if (new_materializes_self) {
                        pending.items[existing_index].materialize_rep = materialize_rep;
                        pending.items[existing_index].materialize_read_path = materialize_source.read_path;
                        continue;
                    }
                    boxyLowerInvariant("boxy callable adapter mapped one descriptor capture to incompatible materialization reps");
                }
                continue;
            }

            const index = pending.items.len;
            try seen_descs.put(param.desc, index);
            try pending.append(self.parent.allocator, .{
                .desc = param.desc,
                .rep = param.rep,
                .materialize_rep = materialize_rep,
                .materialize_read_path = materialize_source.read_path,
                .source_type = param.source_type,
            });
        }
    }

    fn descriptorReadPathSpansEql(
        self: *const ProcBodyBuilder,
        a: Plan.Span,
        b: Plan.Span,
    ) bool {
        const a_steps = self.parent.descriptorReadPathSlice(a);
        const b_steps = self.parent.descriptorReadPathSlice(b);
        if (a_steps.len != b_steps.len) return false;
        for (a_steps, b_steps) |a_step, b_step| {
            if (!std.meta.eql(a_step, b_step)) return false;
        }
        return true;
    }

    fn collectCallableAdapterDescriptorCaptureSources(
        self: *ProcBodyBuilder,
        function_rep_id: Plan.TypeRepId,
        materialize_rep_id: Plan.TypeRepId,
        params: []const Plan.HiddenDescriptorParam,
        mapped: *collections.DenseMap(Plan.DescriptorRequirementId, CallableAdapterDescriptorCaptureSource),
        seen_rep_pairs: *std.AutoHashMap(u64, void),
        substitutions: *collections.DenseMap(Plan.TypeRepId, Plan.TypeRepId),
        allow_missing_tag_payloads: bool,
    ) Allocator.Error!bool {
        var effective_materialize_rep_id = substitutions.get(function_rep_id) orelse materialize_rep_id;
        try self.recordNominalBackingRepSubstitutions(
            function_rep_id,
            effective_materialize_rep_id,
            substitutions,
        );
        effective_materialize_rep_id = substitutions.get(function_rep_id) orelse effective_materialize_rep_id;

        const identity_function_rep = self.repQuery().descriptorArgumentIdentityRep(function_rep_id);
        const identity_materialize_rep = self.repQuery().descriptorArgumentIdentityRep(effective_materialize_rep_id);
        if (identity_function_rep != function_rep_id or identity_materialize_rep != effective_materialize_rep_id) {
            return try self.collectCallableAdapterDescriptorCaptureSources(
                identity_function_rep,
                identity_materialize_rep,
                params,
                mapped,
                seen_rep_pairs,
                substitutions,
                allow_missing_tag_payloads,
            );
        }

        const pair_key = (@as(u64, @intFromEnum(function_rep_id)) << 32) |
            @as(u64, @intFromEnum(materialize_rep_id));
        const entry = try seen_rep_pairs.getOrPut(pair_key);
        if (entry.found_existing) return true;

        const function_rep = self.parent.plan.representations.items[@intFromEnum(function_rep_id)];
        const materialize_rep = self.parent.plan.representations.items[@intFromEnum(materialize_rep_id)];

        if (function_rep.descriptor) |function_desc| {
            try self.requireCallableAdapterDescriptorParam(params, function_desc);
            const capture_materialize_rep = substitutions.get(function_rep_id) orelse
                try self.descriptorCaptureMaterializeRep(function_rep_id, effective_materialize_rep_id);
            try self.putCallableAdapterDescriptorCaptureSource(mapped, function_desc, .{
                .rep = capture_materialize_rep,
            });
        }

        if (function_rep.children.len == 0) return true;

        if (materialize_rep.kind == .empty_tag_union) {
            for (self.parent.plan.childSlice(function_rep.children)) |function_child| {
                if (!try self.repQuery().repSubtreeHasDescriptor(function_child.rep)) continue;
                if (!try self.collectCallableAdapterDescriptorCaptureSources(function_child.rep, effective_materialize_rep_id, params, mapped, seen_rep_pairs, substitutions, allow_missing_tag_payloads)) return false;
            }
            return true;
        }

        if (materialize_rep.kind == .dynamic and materialize_rep.descriptor != null and materialize_rep.children.len == 0) {
            var projected_seen = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
            defer projected_seen.deinit();
            var read_path = std.ArrayList(DescriptorReadStep).empty;
            defer read_path.deinit(self.parent.allocator);
            try self.collectCallableAdapterProjectedDescriptorCaptureSources(
                function_rep_id,
                materialize_rep_id,
                params,
                mapped,
                &projected_seen,
                &read_path,
            );
            return true;
        }

        const function_children = self.parent.plan.childSlice(function_rep.children);
        const materialize_children = self.parent.plan.childSlice(materialize_rep.children);
        for (function_children) |function_child| {
            if (!try self.repQuery().repSubtreeHasDescriptor(function_child.rep)) continue;
            if (self.namedQuery().findMatchingChildByRole(materialize_children, function_child)) |materialize_child| {
                if (!try self.collectCallableAdapterDescriptorCaptureSources(function_child.rep, materialize_child.rep, params, mapped, seen_rep_pairs, substitutions, allow_missing_tag_payloads)) return false;
                continue;
            }
            if (self.repQuery().structuralWrapperBackingRep(effective_materialize_rep_id)) |materialize_backing| {
                const backing_children = self.parent.plan.childSlice(self.parent.plan.representations.items[@intFromEnum(materialize_backing)].children);
                if (self.namedQuery().findMatchingChildByRole(backing_children, function_child)) |materialize_child| {
                    if (!try self.collectCallableAdapterDescriptorCaptureSources(function_child.rep, materialize_child.rep, params, mapped, seen_rep_pairs, substitutions, allow_missing_tag_payloads)) return false;
                    continue;
                }
            }
            if (try self.namedQuery().findMatchingTagPayloadInRowExtension(materialize_children, function_child)) |materialize_child| {
                if (!try self.collectCallableAdapterDescriptorCaptureSources(function_child.rep, materialize_child.rep, params, mapped, seen_rep_pairs, substitutions, allow_missing_tag_payloads)) return false;
                continue;
            }
            if (try self.repQuery().findMatchingChildBySourceType(materialize_children, function_child)) |materialize_child| {
                if (!try self.collectCallableAdapterDescriptorCaptureSources(function_child.rep, materialize_child.rep, params, mapped, seen_rep_pairs, substitutions, allow_missing_tag_payloads)) return false;
                continue;
            }
            if (try self.repQuery().workerChildCanMatchUnwrappedCallRep(function_rep_id, function_child)) {
                if (!try self.collectCallableAdapterDescriptorCaptureSources(function_child.rep, effective_materialize_rep_id, params, mapped, seen_rep_pairs, substitutions, allow_missing_tag_payloads)) return false;
                continue;
            }
            if (function_child.role == .tag_ext and materialize_children.len == 0 and materialize_rep.descriptor != null) {
                if (!try self.collectCallableAdapterDescriptorCaptureSources(function_child.rep, effective_materialize_rep_id, params, mapped, seen_rep_pairs, substitutions, allow_missing_tag_payloads)) return false;
                continue;
            }
            if (allow_missing_tag_payloads and function_child.role == .tag_payload and materialize_rep.kind == .tag_union) {
                var known_seen = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
                defer known_seen.deinit();
                try self.collectCallableAdapterKnownDescriptorCaptureSources(
                    function_child.rep,
                    params,
                    mapped,
                    &known_seen,
                    substitutions,
                );
                continue;
            }
            return false;
        }
        return true;
    }

    fn descriptorCaptureMaterializeRep(
        self: *ProcBodyBuilder,
        function_rep_id: Plan.TypeRepId,
        materialize_rep_id: Plan.TypeRepId,
    ) Allocator.Error!Plan.TypeRepId {
        const identity_materialize_rep = self.repQuery().descriptorArgumentIdentityRep(materialize_rep_id);
        if (try self.descriptorCaptureCanUseMaterializeRep(function_rep_id, identity_materialize_rep)) {
            return identity_materialize_rep;
        }
        const identity_function_rep = self.repQuery().descriptorArgumentIdentityRep(function_rep_id);
        return if (self.repIsFullyConcrete(identity_function_rep))
            identity_function_rep
        else
            identity_materialize_rep;
    }

    fn descriptorCaptureCanUseMaterializeRep(
        self: *ProcBodyBuilder,
        function_rep_id: Plan.TypeRepId,
        materialize_rep_id: Plan.TypeRepId,
    ) Allocator.Error!bool {
        const function_tag_rep = self.tagVariantRepForBoundary(function_rep_id) orelse return true;
        const materialize_tag_rep = self.tagVariantRepForBoundary(materialize_rep_id) orelse {
            const materialize_rep = self.parent.plan.representations.items[@intFromEnum(materialize_rep_id)];
            return materialize_rep.kind == .dynamic and materialize_rep.descriptor != null and materialize_rep.children.len == 0;
        };

        const function_variants = self.parent.plan.tagVariantSlice(self.parent.plan.representations.items[@intFromEnum(function_tag_rep)].tag_variants);
        const materialize_variants = self.parent.plan.tagVariantSlice(self.parent.plan.representations.items[@intFromEnum(materialize_tag_rep)].tag_variants);
        if (function_variants.len != materialize_variants.len) return false;

        for (function_variants, materialize_variants) |function_variant, materialize_variant| {
            if (!std.mem.eql(u8, self.tagVariantNameText(function_variant), self.tagVariantNameText(materialize_variant))) {
                return false;
            }
        }
        return true;
    }

    fn collectCallableAdapterKnownDescriptorCaptureSources(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        params: []const Plan.HiddenDescriptorParam,
        mapped: *collections.DenseMap(Plan.DescriptorRequirementId, CallableAdapterDescriptorCaptureSource),
        seen_reps: *collections.DenseMap(Plan.TypeRepId, void),
        substitutions: *collections.DenseMap(Plan.TypeRepId, Plan.TypeRepId),
    ) Allocator.Error!void {
        const identity_rep = self.repQuery().descriptorArgumentIdentityRep(rep_id);
        const entry = try seen_reps.getOrPut(identity_rep);
        if (entry.found_existing) return;

        const rep = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
        if (rep.descriptor) |desc| {
            try self.requireCallableAdapterDescriptorParam(params, desc);
            const substituted_rep = substitutions.get(identity_rep) orelse substitutions.get(rep_id);
            try self.putCallableAdapterDescriptorCaptureSource(mapped, desc, .{
                .rep = substituted_rep orelse
                    try self.descriptorCaptureMaterializeRep(identity_rep, identity_rep),
            });
        }

        for (self.parent.plan.childSlice(rep.children)) |child| {
            try self.collectCallableAdapterKnownDescriptorCaptureSources(
                child.rep,
                params,
                mapped,
                seen_reps,
                substitutions,
            );
        }
    }

    fn collectCallableAdapterProjectedDescriptorCaptureSources(
        self: *ProcBodyBuilder,
        current_rep_id: Plan.TypeRepId,
        root_materialize_rep: Plan.TypeRepId,
        params: []const Plan.HiddenDescriptorParam,
        mapped: *collections.DenseMap(Plan.DescriptorRequirementId, CallableAdapterDescriptorCaptureSource),
        seen_reps: *collections.DenseMap(Plan.TypeRepId, void),
        read_path: *std.ArrayList(DescriptorReadStep),
    ) Allocator.Error!void {
        const identity_current = self.descriptorStorageRep(current_rep_id);
        const entry = try seen_reps.getOrPut(identity_current);
        if (entry.found_existing) return;

        const current_rep = self.parent.plan.representations.items[@intFromEnum(identity_current)];
        if (current_rep.descriptor) |desc| {
            if (self.callableAdapterHasDescriptorParam(params, desc)) {
                try self.putCallableAdapterProjectedDescriptorCaptureSource(
                    mapped,
                    desc,
                    root_materialize_rep,
                    read_path.items,
                );
            }
        }

        if (self.tagVariantRepForBoundary(identity_current)) |tag_rep_id| {
            const tag_rep = self.parent.plan.representations.items[@intFromEnum(tag_rep_id)];
            const variants = self.parent.plan.tagVariantSlice(tag_rep.tag_variants);
            const descriptor_layout = self.parent.descriptorPayloadLayoutForRep(identity_current);
            const descriptor_layout_value = self.parent.result.layouts.getLayout(descriptor_layout);
            const tag_layout = switch (descriptor_layout_value.tag) {
                .tag_union => descriptor_layout_value,
                .box => self.parent.result.layouts.getLayout(descriptor_layout_value.getIdx()),
                .zst => null,
                .scalar, .box_of_zst, .erased_box, .list, .list_of_zst, .struct_, .closure, .erased_callable, .ptr => boxyLowerInvariant("boxy callable descriptor read_path tag had a non-tag payload layout"),
            };
            if (tag_layout) |layout_value| {
                if (layout_value.tag != .tag_union) {
                    boxyLowerInvariant("boxy callable descriptor read_path tag box had a non-tag payload");
                }
                const tag_info = self.parent.result.layouts.getTagUnionInfo(layout_value);
                if (tag_info.variants.len < variants.len) {
                    boxyLowerInvariant("boxy callable descriptor read_path tag layout had too few variants");
                }
                for (variants, 0..) |variant, variant_index| {
                    try self.collectCallableAdapterTagPayloadDescriptorCaptureSources(
                        variant,
                        tag_info.variants.get(variant_index).payload_layout,
                        root_materialize_rep,
                        params,
                        mapped,
                        seen_reps,
                        read_path,
                    );
                }
            } else {
                if (variants.len != 1) {
                    boxyLowerInvariant("boxy callable zero-sized tag read_path had multiple variants");
                }
                try self.collectCallableAdapterTagPayloadDescriptorCaptureSources(
                    variants[0],
                    .zst,
                    root_materialize_rep,
                    params,
                    mapped,
                    seen_reps,
                    read_path,
                );
            }

            var ext_rep: ?Plan.TypeRepId = null;
            for (self.parent.plan.childSlice(tag_rep.children)) |child| {
                if (child.role != .tag_ext) continue;
                if (ext_rep != null) {
                    boxyLowerInvariant("boxy callable descriptor read_path tag had duplicate row extensions");
                }
                ext_rep = child.rep;
            }
            if (ext_rep) |rep_id| {
                const ext = self.parent.plan.representations.items[@intFromEnum(rep_id)];
                if (rep_id != tag_rep_id and ext.kind != .empty_tag_union) {
                    try read_path.append(self.parent.allocator, .tag_ext);
                    try self.collectCallableAdapterProjectedDescriptorCaptureSources(
                        rep_id,
                        root_materialize_rep,
                        params,
                        mapped,
                        seen_reps,
                        read_path,
                    );
                    read_path.items.len -= 1;
                }
            }
            return;
        }

        const payload_layout = self.parent.descriptorPayloadLayoutForRep(identity_current);
        var nested_index: u32 = 0;

        if (current_rep.declared_fields.len != 0) {
            for (self.parent.plan.declaredFieldSlice(current_rep.declared_fields)) |field| {
                const field_layout = self.parent.recordPayloadFieldLayout(payload_layout, field.index);
                const force_field = self.parent.layoutIsBoxStorage(field_layout);
                const nested_rep = self.nestedDescriptorRepForStorage(field.rep, field_layout, force_field) orelse continue;
                try read_path.append(self.parent.allocator, .{ .nested = nested_index });
                try self.collectCallableAdapterProjectedDescriptorCaptureSources(
                    nested_rep,
                    root_materialize_rep,
                    params,
                    mapped,
                    seen_reps,
                    read_path,
                );
                read_path.items.len -= 1;
                nested_index += 1;
            }
            return;
        }

        var record_field_index: u32 = 0;
        for (self.parent.plan.childSlice(current_rep.children)) |child| {
            if (child.role == .tag_ext) continue;
            const field_layout = switch (child.role) {
                .record_field => blk: {
                    const field_layout = self.parent.recordPayloadFieldLayout(payload_layout, record_field_index);
                    record_field_index += 1;
                    break :blk field_layout;
                },
                .tuple_elem => |index| self.parent.recordPayloadFieldLayout(payload_layout, index),
                .box_payload => self.parent.descriptorPayloadLayoutForRep(child.rep),
                .list_elem => self.parent.listElementLayout(payload_layout),
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_ext, .function_arg, .function_ret, .tag_payload, .tag_ext => continue,
            };
            const force_desc = child.role == .box_payload or self.parent.layoutIsBoxStorage(field_layout);
            const nested_rep = self.nestedDescriptorRepForStorage(child.rep, field_layout, force_desc) orelse continue;
            try read_path.append(self.parent.allocator, .{ .nested = nested_index });
            try self.collectCallableAdapterProjectedDescriptorCaptureSources(
                nested_rep,
                root_materialize_rep,
                params,
                mapped,
                seen_reps,
                read_path,
            );
            read_path.items.len -= 1;
            nested_index += 1;
        }
    }

    fn collectCallableAdapterTagPayloadDescriptorCaptureSources(
        self: *ProcBodyBuilder,
        variant: Plan.TagVariant,
        variant_payload_layout: layout.Idx,
        root_materialize_rep: Plan.TypeRepId,
        params: []const Plan.HiddenDescriptorParam,
        mapped: *collections.DenseMap(Plan.DescriptorRequirementId, CallableAdapterDescriptorCaptureSource),
        seen_reps: *collections.DenseMap(Plan.TypeRepId, void),
        read_path: *std.ArrayList(DescriptorReadStep),
    ) Allocator.Error!void {
        const payloads = self.parent.plan.childSlice(variant.payloads);
        for (payloads, 0..) |payload, payload_index| {
            const field_layout = self.parent.tagVariantPayloadFieldLayout(
                variant_payload_layout,
                payload_index,
                payloads.len,
            );
            const payload_rep = self.parent.tagPayloadStorageDescRepForLayout(payload.rep, field_layout, true) orelse continue;
            try read_path.append(self.parent.allocator, .{ .tag_payload = .{
                .tag_name = try self.lirTagNameForVariant(variant),
                .payload_index = @intCast(payload_index),
            } });
            try self.collectCallableAdapterProjectedDescriptorCaptureSources(
                payload_rep,
                root_materialize_rep,
                params,
                mapped,
                seen_reps,
                read_path,
            );
            read_path.items.len -= 1;
        }
    }

    fn putCallableAdapterProjectedDescriptorCaptureSource(
        self: *ProcBodyBuilder,
        mapped: *collections.DenseMap(Plan.DescriptorRequirementId, CallableAdapterDescriptorCaptureSource),
        desc: Plan.DescriptorRequirementId,
        root_materialize_rep: Plan.TypeRepId,
        read_path: []const DescriptorReadStep,
    ) Allocator.Error!void {
        if (mapped.contains(desc)) return;
        try self.putCallableAdapterDescriptorCaptureSource(mapped, desc, .{
            .rep = root_materialize_rep,
            .read_path = try self.parent.addDescriptorReadPath(read_path),
        });
    }

    fn callableAdapterHasDescriptorParam(
        self: *ProcBodyBuilder,
        params: []const Plan.HiddenDescriptorParam,
        desc: Plan.DescriptorRequirementId,
    ) bool {
        return self.hiddenDescriptorParamForRequirement(params, desc) != null;
    }

    fn hiddenDescriptorParamForRequirement(
        self: *ProcBodyBuilder,
        params: []const Plan.HiddenDescriptorParam,
        desc: Plan.DescriptorRequirementId,
    ) ?Plan.HiddenDescriptorParam {
        const requirement = self.parent.plan.descriptors.items[@intFromEnum(desc)];
        const identity_rep = self.repQuery().descriptorArgumentIdentityRep(requirement.rep);
        var identity_match: ?Plan.HiddenDescriptorParam = null;
        for (params) |param| {
            if (param.desc == desc) return param;
            if (self.repQuery().descriptorArgumentIdentityRep(param.rep) != identity_rep) continue;
            if (identity_match != null) {
                boxyLowerInvariant("boxy hidden descriptor ABI contained duplicate parameters for one identity");
            }
            identity_match = param;
        }
        return identity_match;
    }

    fn requireCallableAdapterDescriptorParam(
        self: *ProcBodyBuilder,
        params: []const Plan.HiddenDescriptorParam,
        desc: Plan.DescriptorRequirementId,
    ) Allocator.Error!void {
        if (self.callableAdapterHasDescriptorParam(params, desc)) return;
        boxyLowerInvariant("boxy callable adapter descriptor mapping found descriptor outside function params");
    }

    fn putCallableAdapterDescriptorCaptureSource(
        _: *ProcBodyBuilder,
        mapped: *collections.DenseMap(Plan.DescriptorRequirementId, CallableAdapterDescriptorCaptureSource),
        desc: Plan.DescriptorRequirementId,
        source: CallableAdapterDescriptorCaptureSource,
    ) Allocator.Error!void {
        const put = try mapped.getOrPut(desc);
        if (put.found_existing) {
            // Every insertion is derived from a representation whose exact
            // descriptor requirement is `desc`. Repeated paths therefore
            // describe the same immutable runtime descriptor identity; retain
            // the first validated source as the capture read path.
            return;
        }
        put.value_ptr.* = source;
    }

    fn callableAdapterCaptureLayout(
        self: *ProcBodyBuilder,
        source_closure_layout: layout.Idx,
        descriptor_count: usize,
    ) Allocator.Error!layout.Idx {
        const fields = try self.parent.allocator.alloc(layout.StructField, 1 + descriptor_count);
        defer self.parent.allocator.free(fields);
        fields[0] = .{ .index = 0, .layout = source_closure_layout };
        for (fields[1..], 0..) |*field, index| {
            if (index + 1 > std.math.maxInt(u16)) {
                boxyLowerInvariant("boxy callable adapter capture field index exceeded layout range");
            }
            field.* = .{
                .index = @intCast(index + 1),
                .layout = .opaque_ptr,
            };
        }
        return try self.parent.result.layouts.putStructFields(fields);
    }

    fn prependCallableAdapterCaptureBindings(
        self: *ProcBodyBuilder,
        capture_arg: LIR.LocalId,
        capture_layout: layout.Idx,
        source_closure: LIR.LocalId,
        descriptor_locals: []const LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const capture_value = try self.addFrameLocal(capture_layout);
        var continuation = next;
        var index = descriptor_locals.len;
        while (index > 0) {
            index -= 1;
            continuation = try self.prependErasedCaptureSlotRead(descriptor_locals[index], capture_value, @intCast(index + 1), continuation);
        }
        continuation = try self.prependErasedCaptureSlotRead(source_closure, capture_value, 0, continuation);

        const args = [_]LIR.LocalId{capture_arg};
        return try self.parent.result.store.addCFStmt(.{ .assign_low_level = .{
            .target = capture_value,
            .op = .erased_capture_load,
            .rc_effect = LIR.LowLevel.erased_capture_load.rcEffect(),
            .args = try self.parent.result.store.addLocalSpan(&args),
            .next = continuation,
        } });
    }

    fn bindDescriptorCaptureSourceLocal(
        self: *ProcBodyBuilder,
        capture: CallableAdapterDescriptorCapture,
        local: LIR.LocalId,
    ) Allocator.Error!void {
        try self.ensureDescriptorLocals();
        try self.markReadOnlyDescriptorInput(local);
        const source_rep = self.callableAdapterCaptureSourceRep(capture);
        try self.bindDescriptorRequirementLocalForRep(capture.desc, source_rep, local, false);
        try self.bindDescriptorIdentityLocalForRep(source_rep, local, false);
    }

    fn bindDescriptorCaptureTargetLocal(
        self: *ProcBodyBuilder,
        capture: CallableAdapterDescriptorCapture,
        source_local: LIR.LocalId,
        initializers: *std.ArrayList(DescriptorArgLocal),
    ) Allocator.Error!void {
        const source_rep = self.callableAdapterCaptureSourceRep(capture);
        const target_local = if (self.representationBoundaryIsDirect(capture.rep, source_rep))
            source_local
        else adapted: {
            const adapted_info = try self.adapterDescriptorForCallBoundary(
                capture.rep,
                source_rep,
                .{ .desc = .{ .local = source_local } },
                initializers,
            );
            try self.appendResultDescriptorInitializers(initializers, adapted_info);
            const adapted_desc = adapted_info.desc orelse
                boxyLowerInvariant("boxy callable adapter capture produced no target descriptor");
            break :adapted adapted_desc.localOrNull() orelse materialize: {
                const local = try self.addFrameLocal(.opaque_ptr);
                try initializers.append(self.parent.allocator, .{
                    .local = local,
                    .materialize = adapted_desc,
                });
                break :materialize local;
            };
        };

        try self.bindDescriptorRequirementLocalForRep(capture.desc, capture.rep, target_local, true);
        try self.bindDescriptorIdentityLocalForRep(capture.rep, target_local, true);
    }

    fn callableAdapterCaptureSourceRep(
        _: *const ProcBodyBuilder,
        capture: CallableAdapterDescriptorCapture,
    ) Plan.TypeRepId {
        return if (capture.materialize_read_path.len == 0)
            capture.materialize_rep
        else
            capture.rep;
    }

    fn repOwnsDescriptor(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        desc: Plan.DescriptorRequirementId,
    ) bool {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const rep = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
        return if (rep.descriptor) |rep_desc| rep_desc == desc else false;
    }

    fn repOwnsShapeDescriptor(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        desc: Plan.DescriptorRequirementId,
    ) bool {
        const identity_rep = self.descriptorShapeIdentityRep(rep_id);
        const rep = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
        return if (rep.descriptor) |rep_desc| rep_desc == desc else false;
    }

    fn descriptorShapeIdentityRep(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Plan.TypeRepId {
        const rep = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        if (rep.descriptor != null) return rep_id;
        return self.parent.descriptorIdentityRep(rep_id);
    }

    fn appendLocalDescriptorEnvironmentBinding(
        self: *ProcBodyBuilder,
        bindings: *std.ArrayList(LocalDescriptorEnvironmentBinding),
        desc: Plan.DescriptorRequirementId,
        rep_id: Plan.TypeRepId,
        local: LIR.LocalId,
    ) Allocator.Error!void {
        const identity_rep = self.descriptorStorageRep(rep_id);
        for (bindings.items) |binding| {
            if (binding.desc != desc or self.descriptorStorageRep(binding.rep) != identity_rep) continue;
            // One checked type variable can occur in multiple values of an
            // aggregate. Its requirement and storage identity prove that the
            // runtime descriptor is shared, so retain the first binding.
            return;
        }
        try bindings.append(self.parent.allocator, .{
            .desc = desc,
            .rep = identity_rep,
            .local = local,
        });
    }

    fn appendDescriptorIdentityLocalEnvironmentBinding(
        self: *ProcBodyBuilder,
        bindings: *std.ArrayList(LocalDescriptorEnvironmentBinding),
        desc: Plan.DescriptorRequirementId,
        rep_id: Plan.TypeRepId,
        local: LIR.LocalId,
    ) Allocator.Error!void {
        if (!self.repOwnsDescriptor(rep_id, desc)) return;
        const identity_rep = self.descriptorStorageRep(rep_id);
        try self.appendLocalDescriptorEnvironmentBinding(bindings, desc, identity_rep, local);
    }

    fn recordLocalDescriptorEnvironment(
        self: *ProcBodyBuilder,
        local: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        bindings: []const LocalDescriptorEnvironmentBinding,
    ) Allocator.Error!void {
        if (bindings.len == 0) return;
        const owned = try self.parent.allocator.dupe(LocalDescriptorEnvironmentBinding, bindings);
        errdefer self.parent.allocator.free(owned);
        for (self.local_descriptor_environments.items) |*env| {
            if (env.local != local) continue;
            self.parent.allocator.free(env.bindings);
            env.* = .{
                .local = local,
                .rep = rep_id,
                .bindings = owned,
            };
            return;
        }
        try self.local_descriptor_environments.append(self.parent.allocator, .{
            .local = local,
            .rep = rep_id,
            .bindings = owned,
        });
    }

    fn recordAggregateLocalDescriptorEnvironment(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        fields: []const LIR.LocalId,
    ) Allocator.Error!void {
        var bindings = std.ArrayList(LocalDescriptorEnvironmentBinding).empty;
        defer bindings.deinit(self.parent.allocator);
        for (fields) |field| {
            const env = self.localDescriptorEnvironmentForLocal(field) orelse continue;
            for (env.bindings) |binding| {
                try self.appendLocalDescriptorEnvironmentBinding(&bindings, binding.desc, binding.rep, binding.local);
            }
        }
        try self.recordLocalDescriptorEnvironment(target, target_rep, bindings.items);
    }

    fn recordDirectCallResultDescriptorEnvironment(
        self: *ProcBodyBuilder,
        local: LIR.LocalId,
        result_rep: Plan.TypeRepId,
        hidden_args: []const Plan.DirectCallHiddenDescriptorArg,
        hidden_locals: []const DescriptorArgLocal,
    ) Allocator.Error!void {
        if (hidden_args.len != hidden_locals.len) {
            boxyLowerInvariant("boxy direct call result descriptor environment saw mismatched hidden args");
        }
        if (hidden_args.len == 0) return;

        var bindings = std.ArrayList(LocalDescriptorEnvironmentBinding).empty;
        defer bindings.deinit(self.parent.allocator);
        for (hidden_args, hidden_locals) |arg, hidden| {
            const local_rep = self.directCallHiddenDescriptorLocalRep(arg, hidden);
            try self.appendLocalDescriptorEnvironmentBinding(&bindings, arg.worker_desc, local_rep, hidden.local);
            try self.appendDescriptorIdentityLocalEnvironmentBinding(&bindings, arg.worker_desc, local_rep, hidden.local);
            if (self.directCallHiddenDescriptorUsesCallShape(arg) and
                self.descriptorStorageRep(arg.worker_rep) != self.descriptorStorageRep(local_rep))
            {
                try self.appendLocalDescriptorEnvironmentBinding(&bindings, arg.worker_desc, arg.worker_rep, hidden.local);
                try self.appendDescriptorIdentityLocalEnvironmentBinding(&bindings, arg.worker_desc, arg.worker_rep, hidden.local);
            }
        }
        try self.recordLocalDescriptorEnvironment(local, result_rep, bindings.items);
    }

    fn localDescriptorEnvironmentForLocal(
        self: *ProcBodyBuilder,
        local: LIR.LocalId,
    ) ?LocalDescriptorEnvironment {
        var index = self.local_descriptor_environments.items.len;
        while (index > 0) {
            index -= 1;
            const env = self.local_descriptor_environments.items[index];
            if (env.local == local) return env;
        }
        return null;
    }

    fn localEnvironmentDescriptorForRep(
        self: *ProcBodyBuilder,
        local: LIR.LocalId,
        rep_id: Plan.TypeRepId,
    ) ?LIR.LocalId {
        const env = self.localDescriptorEnvironmentForLocal(local) orelse return null;
        const identity_rep = self.descriptorStorageRep(rep_id);
        var found: ?LIR.LocalId = null;
        for (env.bindings) |binding| {
            if (self.descriptorStorageRep(binding.rep) != identity_rep) continue;
            if (found != null and found.? != binding.local) {
                boxyLowerInvariant("boxy local descriptor environment had multiple identities for one representation");
            }
            found = binding.local;
        }
        return found;
    }

    fn localEnvironmentDescriptorForRequirementAndRep(
        self: *ProcBodyBuilder,
        local: LIR.LocalId,
        desc: Plan.DescriptorRequirementId,
        rep_id: Plan.TypeRepId,
    ) ?LIR.LocalId {
        const env = self.localDescriptorEnvironmentForLocal(local) orelse return null;
        const identity_rep = self.descriptorStorageRep(rep_id);
        var found: ?LIR.LocalId = null;
        for (env.bindings) |binding| {
            if (binding.desc != desc or self.descriptorStorageRep(binding.rep) != identity_rep) continue;
            if (found != null and found.? != binding.local) {
                boxyLowerInvariant("boxy local descriptor environment had multiple bindings for one exact requirement");
            }
            found = binding.local;
        }
        return found;
    }

    fn bindLocalDescriptorEnvironment(self: *ProcBodyBuilder, local: LIR.LocalId) Allocator.Error!void {
        const env = self.localDescriptorEnvironmentForLocal(local) orelse return;
        try self.ensureDescriptorLocals();
        for (env.bindings) |binding| {
            try self.bindDescriptorRequirementLocalForRep(binding.desc, binding.rep, binding.local, false);
        }
    }

    fn descriptorLocalAvailableFromSource(
        self: *ProcBodyBuilder,
        source: LIR.LocalId,
        descriptor_local: LIR.LocalId,
    ) bool {
        if (self.localIsReadOnlyDescriptorInput(descriptor_local)) return true;
        if (self.parent.result.store.getLocal(source).boxy_desc) |desc| {
            if (desc.localOrNull() == descriptor_local) return true;
        }
        const env = self.localDescriptorEnvironmentForLocal(source) orelse return false;
        for (env.bindings) |binding| {
            if (binding.local == descriptor_local) return true;
        }
        return false;
    }

    fn propagateLocalDescriptorEnvironmentToField(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source: LIR.LocalId,
    ) Allocator.Error!void {
        const env = self.localDescriptorEnvironmentForLocal(source) orelse return;
        var bindings = std.ArrayList(LocalDescriptorEnvironmentBinding).empty;
        defer bindings.deinit(self.parent.allocator);
        for (env.bindings) |binding| {
            if (!try self.repSubtreeContainsDescriptor(target_rep, binding.desc)) continue;
            try self.appendLocalDescriptorEnvironmentBinding(&bindings, binding.desc, binding.rep, binding.local);
        }
        try self.recordLocalDescriptorEnvironment(target, target_rep, bindings.items);

        const identity_target = self.descriptorStorageRep(target_rep);
        const target_info = self.parent.plan.representations.items[@intFromEnum(identity_target)];
        const target_desc = target_info.descriptor orelse return;
        for (bindings.items) |binding| {
            if (binding.desc == target_desc and self.descriptorStorageRep(binding.rep) == identity_target) {
                self.parent.result.store.setLocalBoxyDesc(target, .{ .local = binding.local });
                return;
            }
        }
    }

    fn recordDescriptorEnvironmentFromDescriptorLocal(
        self: *ProcBodyBuilder,
        local: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        desc_local: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.recordDescriptorEnvironmentFromDescriptorRef(
            local,
            rep_id,
            .{ .local = desc_local },
            next,
        );
    }

    fn recordDescriptorEnvironmentFromDescriptorRef(
        self: *ProcBodyBuilder,
        local: LIR.LocalId,
        rep_id: Plan.TypeRepId,
        desc_ref: LIR.BoxyDescRef,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var bindings = std.ArrayList(LocalDescriptorEnvironmentBinding).empty;
        defer bindings.deinit(self.parent.allocator);
        var initializers = std.ArrayList(DescriptorArgLocal).empty;
        defer initializers.deinit(self.parent.allocator);
        var seen = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen.deinit();

        try self.collectDescriptorEnvironmentForRep(
            rep_id,
            desc_ref,
            &bindings,
            &initializers,
            &seen,
        );
        try self.recordLocalDescriptorEnvironment(local, rep_id, bindings.items);
        return try self.prependDescriptorArgMaterializations(initializers.items, next);
    }

    fn collectDescriptorEnvironmentForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        desc_ref: LIR.BoxyDescRef,
        bindings: *std.ArrayList(LocalDescriptorEnvironmentBinding),
        initializers: *std.ArrayList(DescriptorArgLocal),
        seen: *collections.DenseMap(Plan.TypeRepId, void),
    ) Allocator.Error!void {
        const identity_rep = self.descriptorStorageRep(rep_id);
        return try self.collectDescriptorEnvironmentForIdentityRep(identity_rep, desc_ref, bindings, initializers, seen);
    }

    fn collectShapeDescriptorEnvironmentForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        desc_ref: LIR.BoxyDescRef,
        bindings: *std.ArrayList(LocalDescriptorEnvironmentBinding),
        initializers: *std.ArrayList(DescriptorArgLocal),
        seen: *collections.DenseMap(Plan.TypeRepId, void),
    ) Allocator.Error!void {
        const identity_rep = self.descriptorShapeIdentityRep(rep_id);
        return try self.collectDescriptorEnvironmentForIdentityRep(identity_rep, desc_ref, bindings, initializers, seen);
    }

    fn collectDescriptorEnvironmentForIdentityRep(
        self: *ProcBodyBuilder,
        identity_rep: Plan.TypeRepId,
        desc_ref: LIR.BoxyDescRef,
        bindings: *std.ArrayList(LocalDescriptorEnvironmentBinding),
        initializers: *std.ArrayList(DescriptorArgLocal),
        seen: *collections.DenseMap(Plan.TypeRepId, void),
    ) Allocator.Error!void {
        const seen_entry = try seen.getOrPut(identity_rep);
        if (seen_entry.found_existing) return;

        if (desc_ref.localOrNull()) |local| {
            const rep = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
            if (rep.descriptor) |desc| {
                try self.appendLocalDescriptorEnvironmentBinding(bindings, desc, identity_rep, local);
            }
        }

        if (self.parent.descriptorBackingShapeRep(identity_rep)) |backing_rep| {
            return try self.collectDescriptorEnvironmentForIdentityRep(
                self.descriptorStorageRep(backing_rep),
                desc_ref,
                bindings,
                initializers,
                seen,
            );
        }

        const rep = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
        const payload_layout = self.parent.descriptorPayloadLayoutForRep(identity_rep);
        var nested_index: u32 = 0;

        if (rep.declared_fields.len != 0) {
            const ordered = try self.parent.declaredFieldsInLayoutOrder(
                self.parent.plan.declaredFieldSlice(rep.declared_fields),
            );
            defer self.parent.allocator.free(ordered);
            for (ordered) |field| {
                const field_layout = self.parent.recordPayloadFieldLayout(payload_layout, field.index);
                const force_field = self.parent.layoutIsBoxStorage(field_layout);
                const nested_rep = self.nestedDescriptorRepForStorage(field.rep, field_layout, force_field) orelse continue;
                try self.collectNestedDescriptorEnvironmentForRep(nested_rep, desc_ref, nested_index, bindings, initializers, seen);
                nested_index += 1;
            }
            return;
        }

        var record_field_index: u32 = 0;
        for (self.parent.plan.childSlice(rep.children)) |child| {
            if (child.role == .tag_ext) continue;
            const field_layout = switch (child.role) {
                .record_field => blk: {
                    const field_layout = self.parent.recordPayloadFieldLayout(payload_layout, record_field_index);
                    record_field_index += 1;
                    break :blk field_layout;
                },
                .tuple_elem => |index| self.parent.recordPayloadFieldLayout(payload_layout, index),
                .box_payload => self.parent.descriptorPayloadLayoutForRep(child.rep),
                .list_elem => self.parent.listElementLayout(payload_layout),
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_ext, .function_arg, .function_ret, .tag_payload, .tag_ext => continue,
            };
            const force_desc = child.role == .box_payload or self.parent.layoutIsBoxStorage(field_layout);
            const nested_rep = self.nestedDescriptorRepForStorage(child.rep, field_layout, force_desc) orelse continue;
            try self.collectNestedDescriptorEnvironmentForRep(nested_rep, desc_ref, nested_index, bindings, initializers, seen);
            nested_index += 1;
        }
    }

    fn collectNestedDescriptorEnvironmentForRep(
        self: *ProcBodyBuilder,
        nested_rep: Plan.TypeRepId,
        parent_desc: LIR.BoxyDescRef,
        nested_index: u32,
        bindings: *std.ArrayList(LocalDescriptorEnvironmentBinding),
        initializers: *std.ArrayList(DescriptorArgLocal),
        seen: *collections.DenseMap(Plan.TypeRepId, void),
    ) Allocator.Error!void {
        const nested_local = try self.addFrameLocal(.opaque_ptr);
        switch (parent_desc) {
            .static => {
                const materialization = try self.descriptorMaterializationForKnownRep(nested_rep);
                try initializers.append(self.parent.allocator, .{
                    .local = nested_local,
                    .materialize = materialization.desc,
                    .captures = materialization.captures,
                });
            },
            .local, .runtime, .dict_method_arg, .dict_method_hidden => try initializers.append(self.parent.allocator, .{
                .local = nested_local,
                .materialize = parent_desc,
                .nested_index = nested_index,
            }),
        }
        try self.collectDescriptorEnvironmentForRep(
            nested_rep,
            .{ .local = nested_local },
            bindings,
            initializers,
            seen,
        );
    }

    fn repSubtreeContainsDescriptor(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        desc: Plan.DescriptorRequirementId,
    ) Allocator.Error!bool {
        var seen = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
        defer seen.deinit();
        return try self.repSubtreeContainsDescriptorInner(rep_id, desc, &seen);
    }

    fn repSubtreeContainsDescriptorInner(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        desc: Plan.DescriptorRequirementId,
        seen: *collections.DenseMap(Plan.TypeRepId, void),
    ) Allocator.Error!bool {
        const entry = try seen.getOrPut(rep_id);
        if (entry.found_existing) return false;

        const rep = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        if (rep.descriptor == desc) return true;
        for (self.parent.plan.childSlice(rep.children)) |child| {
            if (try self.repSubtreeContainsDescriptorInner(child.rep, desc, seen)) return true;
        }
        for (self.parent.plan.tagVariantSlice(rep.tag_variants)) |variant| {
            for (self.parent.plan.childSlice(variant.payloads)) |payload| {
                if (try self.repSubtreeContainsDescriptorInner(payload.rep, desc, seen)) return true;
            }
        }
        return false;
    }

    fn setDescriptorRequirementLocalForRep(
        self: *ProcBodyBuilder,
        desc: Plan.DescriptorRequirementId,
        rep_id: Plan.TypeRepId,
        local: LIR.LocalId,
    ) Allocator.Error!void {
        try self.ensureDescriptorLocals();
        const desc_index = @intFromEnum(desc);
        if (desc_index >= self.descriptor_locals.len or desc_index >= self.descriptor_local_reps.len) {
            boxyLowerInvariant("boxy descriptor binding exceeded descriptor table");
        }
        const identity_rep = self.descriptorStorageRep(rep_id);
        if (self.descriptor_locals[desc_index] == null or
            self.descriptor_local_reps[desc_index] == null or
            self.descriptor_local_reps[desc_index].? == identity_rep)
        {
            const preserves_bound = self.descriptor_locals[desc_index] == local and
                self.descriptor_local_reps[desc_index] == identity_rep and
                self.descriptor_bound[desc_index];
            self.descriptor_locals[desc_index] = local;
            self.descriptor_local_reps[desc_index] = identity_rep;
            self.descriptor_bound[desc_index] = preserves_bound;
            return;
        }

        if (self.descriptorRepBindingIndex(desc, identity_rep)) |index| {
            const existing = self.descriptor_rep_bindings.items[index];
            self.descriptor_rep_bindings.items[index] = .{
                .desc = desc,
                .rep = identity_rep,
                .local = local,
                .bound = existing.local == local and existing.bound,
            };
            return;
        }
        try self.descriptor_rep_bindings.append(self.parent.allocator, .{
            .desc = desc,
            .rep = identity_rep,
            .local = local,
            .bound = false,
        });
    }

    fn markDescriptorRequirementBoundForRep(
        self: *ProcBodyBuilder,
        desc: Plan.DescriptorRequirementId,
        rep_id: Plan.TypeRepId,
    ) void {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const desc_index = @intFromEnum(desc);
        if (desc_index < self.descriptor_local_reps.len and self.descriptor_local_reps[desc_index] == identity_rep) {
            self.descriptor_bound[desc_index] = true;
            return;
        }
        if (self.descriptorRepBindingIndex(desc, identity_rep)) |index| {
            self.descriptor_rep_bindings.items[index].bound = true;
            return;
        }
        boxyLowerInvariant("boxy descriptor bound marker had no representation-local binding");
    }

    fn bindDescriptorRequirementLocalForRep(
        self: *ProcBodyBuilder,
        desc: Plan.DescriptorRequirementId,
        rep_id: Plan.TypeRepId,
        local: LIR.LocalId,
        bind_slot: bool,
    ) Allocator.Error!void {
        const desc_index = @intFromEnum(desc);
        if (desc_index >= self.descriptor_locals.len or desc_index >= self.descriptor_slot_reps.len) {
            boxyLowerInvariant("boxy descriptor binding exceeded descriptor table");
        }
        if (bind_slot) {
            self.descriptor_slots[desc_index] = local;
            self.descriptor_slot_reps[desc_index] = self.descriptorStorageRep(rep_id);
        }
        try self.setDescriptorRequirementLocalForRep(desc, rep_id, local);
        self.markDescriptorRequirementBoundForRep(desc, rep_id);
    }

    fn bindDescriptorIdentityLocalForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        local: LIR.LocalId,
        bind_slot: bool,
    ) Allocator.Error!void {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const rep = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
        const desc = rep.descriptor orelse return;
        try self.bindDescriptorRequirementLocalForRep(desc, identity_rep, local, bind_slot);
    }

    fn functionArgChildren(self: *ProcBodyBuilder, function: FunctionChildren) []const Plan.RepChild {
        const rep = self.parent.plan.representations.items[@intFromEnum(function.rep)];
        const children = self.parent.plan.childSlice(rep.children);
        return children[function.args_start..][0..function.arg_count];
    }

    /// A representation is fully concrete when its value carries no
    /// descriptor-driven storage: it needs neither a static descriptor nor any
    /// dynamically boxed field. Such a value's reference counting is entirely
    /// determined by its layout, so two fully-concrete values with byte-identical
    /// layouts are interchangeable without any conversion.
    fn repIsFullyConcrete(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) bool {
        const rep = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        return rep.descriptor == null and !rep.contains_dynamic;
    }

    fn repsHaveSameSourceType(
        self: *const ProcBodyBuilder,
        a: Plan.TypeRepId,
        b: Plan.TypeRepId,
    ) bool {
        const identity_a = self.descriptorStorageRep(a);
        const identity_b = self.descriptorStorageRep(b);
        const a_rep = self.parent.plan.representations.items[@intFromEnum(identity_a)];
        const b_rep = self.parent.plan.representations.items[@intFromEnum(identity_b)];
        return planTypeRefEql(a_rep.source_type, b_rep.source_type);
    }

    /// A bare dynamic representation carries no structural payload shape of
    /// its own. When a concrete value is boxed into it, the source descriptor is
    /// the only explicit description of the allocation that was actually made.
    fn repIsBareDynamic(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) bool {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const rep = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
        return rep.kind == .dynamic and
            rep.children.len == 0 and
            rep.declared_fields.len == 0 and
            rep.tag_variants.len == 0;
    }

    /// Whether a value laid out as `a` can be reinterpreted as a value laid out
    /// as `b` with no byte-level conversion: the two layouts have the same tag,
    /// size, and recursively-interchangeable children. Distinct recursive size
    /// cycles are interned under distinct indices, so a seen set pairs the two
    /// cycles and treats a re-encountered pair as already matched.
    fn boundaryLayoutsInterchangeable(
        self: *ProcBodyBuilder,
        a: layout.Idx,
        b: layout.Idx,
    ) Allocator.Error!bool {
        var seen = std.AutoHashMap(u64, void).init(self.parent.allocator);
        defer seen.deinit();
        return try self.boundaryLayoutsInterchangeableInner(a, b, &seen);
    }

    fn boundaryLayoutsInterchangeableInner(
        self: *ProcBodyBuilder,
        a: layout.Idx,
        b: layout.Idx,
        seen: *std.AutoHashMap(u64, void),
    ) Allocator.Error!bool {
        if (a == b) return true;

        const layouts = &self.parent.result.layouts;
        const a_layout = layouts.getLayout(a);
        const b_layout = layouts.getLayout(b);
        if (a_layout.tag != b_layout.tag) return false;
        if (layouts.layoutSize(a_layout) != layouts.layoutSize(b_layout)) return false;

        const key = (@as(u64, @intFromEnum(a)) << 32) | @as(u64, @intFromEnum(b));
        if ((try seen.getOrPut(key)).found_existing) return true;

        switch (a_layout.tag) {
            .scalar => return std.meta.eql(a_layout.getScalar(), b_layout.getScalar()),
            .zst => return true,
            .erased_box => return true,
            .box, .box_of_zst => {
                return try self.boundaryLayoutsInterchangeableInner(
                    layouts.getBoxInfo(a_layout).elem_layout_idx,
                    layouts.getBoxInfo(b_layout).elem_layout_idx,
                    seen,
                );
            },
            .list, .list_of_zst => {
                return try self.boundaryLayoutsInterchangeableInner(
                    layouts.getListInfo(a_layout).elem_layout_idx,
                    layouts.getListInfo(b_layout).elem_layout_idx,
                    seen,
                );
            },
            .struct_ => {
                const a_info = layouts.getStructInfo(a_layout);
                const b_info = layouts.getStructInfo(b_layout);
                if (a_info.fields.len != b_info.fields.len) return false;
                var i: u32 = 0;
                while (i < a_info.fields.len) : (i += 1) {
                    const a_field = a_info.fields.get(i);
                    const b_field = b_info.fields.get(i);
                    if (a_field.is_padding != b_field.is_padding) return false;
                    if (!try self.boundaryLayoutsInterchangeableInner(a_field.layout, b_field.layout, seen)) return false;
                }
                return true;
            },
            .tag_union => {
                const a_info = layouts.getTagUnionInfo(a_layout);
                const b_info = layouts.getTagUnionInfo(b_layout);
                if (a_info.variants.len != b_info.variants.len) return false;
                if (a_info.discriminant_offset != b_info.discriminant_offset) return false;
                var i: u32 = 0;
                while (i < a_info.variants.len) : (i += 1) {
                    if (!try self.boundaryLayoutsInterchangeableInner(
                        a_info.variants.get(i).payload_layout,
                        b_info.variants.get(i).payload_layout,
                        seen,
                    )) return false;
                }
                return true;
            },
            .closure, .erased_callable, .ptr => return false,
        }
    }

    fn assignRepresentationBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.assignRepresentationBoundaryWithSourceMode(
            target,
            source,
            target_rep,
            source_rep,
            .borrow,
            next,
        );
    }

    fn assignRepresentationBoundaryConsumingSource(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.assignRepresentationBoundaryWithSourceMode(
            target,
            source,
            target_rep,
            source_rep,
            .move,
            next,
        );
    }

    fn assignRepresentationBoundaryWithSourceMode(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        dynamic_box_source_mode: LIR.BoxyTransferMode,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        const identity_target_rep = self.descriptorStorageRep(target_rep);
        const identity_source_rep = self.descriptorStorageRep(source_rep);
        if (target_layout == source_layout and
            identity_target_rep == identity_source_rep and
            (target_rep == source_rep or
                (self.repIsFullyConcrete(target_rep) and self.repIsFullyConcrete(source_rep))))
        {
            return if (target == source) next else try self.assignLocalFromRep(target, source, source_rep, next);
        }

        // Alternative-pattern remapping can bind a generic payload local to a
        // concrete representative binder. Preserve the local's explicit
        // dynamic-box storage classification before descriptor identity
        // selection makes the two descriptor identity reps look concrete.
        if (self.parent.layoutIsBoxStorage(source_layout) and
            !self.parent.layoutIsBoxStorage(target_layout) and
            self.parent.result.store.getLocal(source).boxy_desc != null)
        {
            return try self.assignDynamicBoxStorageToConcrete(
                target,
                source,
                identity_target_rep,
                identity_source_rep,
                dynamic_box_source_mode,
                next,
            );
        }

        // Two representations of the same source-level recursive type can be
        // structurally identical but receive distinct rep ids and distinct, yet
        // byte-identical, layout indices because the layout store interns each
        // recursive size cycle separately. Converting one into the other
        // field-by-field would recurse forever through the shared cycle. When
        // layout interchangeability proves the byte layouts identical, and
        // either layout-only RC or source-type identity proves the descriptor
        // interpretation is identical, relabelling the local is the boundary.
        const layouts_interchangeable = target_layout != source_layout and
            try self.boundaryLayoutsInterchangeable(target_layout, source_layout);
        const relabel_is_safe =
            (self.repIsFullyConcrete(identity_target_rep) and self.repIsFullyConcrete(identity_source_rep)) or
            self.repsHaveSameSourceType(identity_target_rep, identity_source_rep);
        if (layouts_interchangeable and relabel_is_safe) {
            const source_desc = self.parent.result.store.getLocal(source).boxy_desc;
            const target_desc = self.parent.result.store.getLocal(target).boxy_desc;
            return try self.parent.result.store.addCFStmt(.{ .assign_boxy_adapt = .{
                .target = target,
                .source = source,
                .adapter = try self.internAdapter(
                    .relabel,
                    source_layout,
                    target_layout,
                    dynamic_box_source_mode == .move,
                ),
                .source_desc = source_desc,
                .target_desc = target_desc,
                .source_mode = dynamic_box_source_mode,
                .next = next,
            } });
        }

        if (target_layout == source_layout) {
            if (self.functionChildrenForRep(identity_target_rep)) |target_function| {
                if (self.functionChildrenForRep(identity_source_rep)) |source_function| {
                    return try self.assignErasedCallableBoundary(target, source, target_function, source_function, next);
                }
            }
        }

        return switch (self.workerRuntimeLayoutForRep(identity_target_rep)) {
            .dynamic_box => switch (self.workerRuntimeLayoutForRep(identity_source_rep)) {
                .dynamic_box => if (try self.assignDynamicTagUnionToDynamicBoundary(target, source, identity_target_rep, identity_source_rep, next)) |adapted|
                    adapted
                else if (target_layout == source_layout)
                    try self.assignDynamicBoxToDynamicBoundary(target, source, identity_target_rep, identity_source_rep, next)
                else
                    try self.assignDynamicBoxToDynamicBoundary(target, source, identity_target_rep, identity_source_rep, next),
                .concrete => if (try self.assignConcreteTagUnionToDynamicBoundary(target, source, identity_target_rep, identity_source_rep, next)) |adapted|
                    adapted
                else blk: {
                    const source_info = if (self.parent.result.store.getLocal(source).boxy_desc) |desc|
                        ResultDescriptorSource{ .desc = desc }
                    else blk_source: {
                        const materialization = try self.descriptorMaterializationForSourceRep(identity_source_rep);
                        if (materialization.captures.len == 0) {
                            break :blk_source ResultDescriptorSource{ .desc = materialization.desc };
                        }
                        const local = try self.addFrameLocal(.opaque_ptr);
                        break :blk_source ResultDescriptorSource{
                            .desc = .{ .local = local },
                            .materialize = .{
                                .local = local,
                                .materialize = materialization.desc,
                                .captures = materialization.captures,
                            },
                        };
                    };
                    const source_desc = source_info.desc orelse
                        boxyLowerInvariant("boxy concrete-to-dynamic source descriptor was not available");
                    const rep_payload_desc = if (self.descriptorBindingIsBoundForRep(identity_target_rep))
                        try self.descriptorRefForRepIfNeeded(identity_target_rep)
                    else
                        null;
                    const desc_for_payload = if (rep_payload_desc != null and !self.repIsBareDynamic(identity_target_rep))
                        rep_payload_desc.?
                    else
                        source_desc;
                    const existing_target_desc = self.parent.result.store.getLocal(target).boxy_desc;
                    const payload_desc = existing_target_desc orelse desc_for_payload;
                    if (existing_target_desc == null) {
                        self.parent.result.store.setLocalBoxyDesc(target, payload_desc);
                    }
                    const writable_target_desc = if (existing_target_desc) |desc| blk_desc: {
                        const local = desc.localOrNull() orelse break :blk_desc null;
                        if (self.localIsReadOnlyDescriptorInput(local)) break :blk_desc null;
                        break :blk_desc desc;
                    } else null;
                    const box = try self.parent.result.store.addCFStmt(.{ .assign_boxy_box = .{
                        .target = target,
                        .payload = source,
                        .payload_layout = source_layout,
                        .source_desc = if (std.meta.eql(source_desc, desc_for_payload)) null else source_desc,
                        .payload_desc = payload_desc,
                        .payload_mode = .move,
                        .next = next,
                    } });
                    var continuation = box;
                    if (writable_target_desc) |desc| {
                        if (!std.meta.eql(desc, desc_for_payload)) {
                            continuation = try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                                .target = desc.localOrNull() orelse
                                    boxyLowerInvariant("boxy target descriptor local disappeared"),
                                .desc = desc_for_payload,
                                .next = continuation,
                            } });
                        }
                    }
                    if (source_info.materialize) |materialize| {
                        continuation = try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                            .target = materialize.local,
                            .desc = materialize.materialize orelse
                                boxyLowerInvariant("boxy concrete-to-dynamic source descriptor materialization had no descriptor"),
                            .nested_index = materialize.nested_index,
                            .tag_ext = materialize.tag_ext,
                            .tag_residual_for = materialize.tag_residual_for,
                            .captures = materialize.captures,
                            .next = continuation,
                        } });
                    }
                    break :blk continuation;
                },
            },
            .concrete => switch (self.workerRuntimeLayoutForRep(identity_source_rep)) {
                .dynamic_box => if (try self.assignDynamicRecordToConcreteBoundary(target, source, identity_target_rep, identity_source_rep, next)) |adapted|
                    adapted
                else blk: {
                    const source_desc = try self.descriptorRefForSourceLocalRep(source, identity_source_rep);
                    const target_desc_info = try self.storageDescriptorForRepIfNeeded(identity_target_rep);
                    // A `.dynamic`-rep target reports no static storage descriptor,
                    // but when its unboxed storage layout carries an erased
                    // `erased_box` the value must still be reference-counted through
                    // a descriptor (a layout-driven concrete RC walk cannot align
                    // the box's allocation). The unboxed storage has the same shape
                    // as the box payload, so reuse the source box's descriptor.
                    var selected_target_desc = target_desc_info;
                    if (selected_target_desc.desc == null and self.repContainsDynamicStorage(identity_target_rep)) {
                        selected_target_desc.desc = source_desc;
                    }
                    const resolved_target_desc = self.resultDescriptorForCallTarget(target, selected_target_desc);
                    if (self.parent.result.store.getLocal(target).boxy_desc == null) {
                        if (resolved_target_desc.desc) |desc| {
                            self.parent.result.store.setLocalBoxyDesc(target, desc);
                        }
                    }
                    const adapt = try self.assignDynamicBoxMaterialization(
                        target,
                        source,
                        source_desc,
                        resolved_target_desc.desc,
                        dynamic_box_source_mode,
                        next,
                    );
                    break :blk try self.prependOptionalDescriptorMaterialization(resolved_target_desc.materialize, adapt);
                },
                .concrete => if (try self.assignListRepresentationBoundary(target, source, identity_target_rep, identity_source_rep, next)) |adapted|
                    adapted
                else if (try self.assignSingletonZstTagToConcreteBoundary(target, source, identity_target_rep, identity_source_rep, next)) |adapted|
                    adapted
                else if (try self.assignConcreteTagUnionToConcreteBoundary(target, source, identity_target_rep, identity_source_rep, next)) |adapted|
                    adapted
                else if (try self.assignConcreteTagUnionToScalarBoundary(target, source, identity_target_rep, identity_source_rep, next)) |adapted|
                    adapted
                else if (try self.assignConcreteRecordToConcreteBoundary(target, source, identity_target_rep, identity_source_rep, next)) |adapted|
                    adapted
                else
                    try self.assignDescriptorAwareNominalBoundary(
                        target,
                        source,
                        target_rep,
                        source_rep,
                        dynamic_box_source_mode,
                        next,
                    ),
            },
        };
    }

    fn assignDescriptorAwareNominalBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        source_mode: LIR.BoxyTransferMode,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const target_desc = self.parent.result.store.getLocal(target).boxy_desc;
        const source_desc = self.parent.result.store.getLocal(source).boxy_desc;
        if (target_desc) |desc| {
            if (desc.localOrNull()) |target_desc_local| {
                if (!self.localIsReadOnlyDescriptorInput(target_desc_local) and
                    (source_desc == null or !std.meta.eql(desc, source_desc.?)))
                {
                    return try self.assignPlannedCallBoundaryWithSourceMode(
                        target,
                        source,
                        target_rep,
                        source_rep,
                        source_mode,
                        next,
                    );
                }
            }
        }
        return try self.assignNominalBoundary(target, source, next);
    }

    fn assignDynamicBoxStorageToConcrete(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        source_mode: LIR.BoxyTransferMode,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const source_desc = try self.descriptorRefForSourceLocalRep(source, source_rep);
        const target_desc_info = try self.storageDescriptorForRepIfNeeded(target_rep);
        var selected_target_desc = target_desc_info;
        if (selected_target_desc.desc == null and self.repContainsDynamicStorage(target_rep)) {
            if (self.parent.result.store.getLocal(target).boxy_desc == null) {
                selected_target_desc.desc = source_desc;
            }
        }
        const resolved_target_desc = self.resultDescriptorForCallTarget(target, selected_target_desc);
        if (self.parent.result.store.getLocal(target).boxy_desc == null) {
            if (resolved_target_desc.desc) |desc| {
                self.parent.result.store.setLocalBoxyDesc(target, desc);
            }
        }
        const adapt = try self.assignDynamicBoxMaterialization(
            target,
            source,
            source_desc,
            resolved_target_desc.desc,
            source_mode,
            next,
        );
        return try self.prependOptionalDescriptorMaterialization(resolved_target_desc.materialize, adapt);
    }

    fn assignDynamicBoxMaterialization(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        source_desc: LIR.BoxyDescRef,
        target_desc: ?LIR.BoxyDescRef,
        source_mode: LIR.BoxyTransferMode,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        return try self.parent.result.store.addCFStmt(.{ .assign_boxy_adapt = .{
            .target = target,
            .source = source,
            .adapter = try self.internAdapter(
                .materialize,
                source_layout,
                target_layout,
                source_mode == .move,
            ),
            .source_desc = source_desc,
            .target_desc = target_desc,
            .source_mode = source_mode,
            .next = next,
        } });
    }

    fn assignDynamicBoxToDynamicBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const source_desc = try self.descriptorRefForSourceLocalRep(source, source_rep);
        if (self.parent.result.store.getLocal(target).boxy_desc) |target_desc| {
            if (target_desc.localOrNull()) |target_desc_local| {
                if (!self.localIsReadOnlyDescriptorInput(target_desc_local)) {
                    if (target == source) {
                        if (std.meta.eql(target_desc, source_desc)) return next;
                        return try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                            .target = target_desc_local,
                            .desc = source_desc,
                            .next = next,
                        } });
                    }
                    if (self.parent.result.store.getLocal(source).boxy_desc == null) {
                        self.parent.result.store.setLocalBoxyDesc(source, source_desc);
                    }
                    return try self.assignLocal(target, source, next);
                }
            }
            // The target's descriptor is a fixed boundary identity. Preserve
            // it and materialize the source through the planned adapter instead
            // of trying to attach the source's descriptor to the target local.
            return try self.assignLocal(target, source, next);
        }
        if (!self.descriptorBindingIsBoundForRep(target_rep)) {
            if (try self.reserveDescriptorLocalForRep(target_rep)) |reserved_target_desc| {
                var target_desc = reserved_target_desc;
                if (self.localIsReadOnlyDescriptorInput(target_desc)) {
                    target_desc = try self.addFrameLocal(.opaque_ptr);
                }
                self.parent.result.store.setLocalBoxyDesc(target, .{ .local = target_desc });
                const rebind = try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                    .target = target_desc,
                    .desc = source_desc,
                    .next = if (target == source) next else try self.assignLocal(target, source, next),
                } });
                return rebind;
            }
        }
        self.parent.result.store.setLocalBoxyDesc(target, source_desc);
        return if (target == source) next else try self.assignLocal(target, source, next);
    }

    fn assignDynamicRecordToConcreteBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!?LIR.CFStmtId {
        const source_record_rep = self.recordRepForBoundary(source_rep) orelse return null;
        const target_record_rep = self.recordRepForBoundary(target_rep) orelse return null;
        if (source_record_rep == target_record_rep) return null;

        const source_record = self.parent.plan.representations.items[@intFromEnum(source_record_rep)];
        const target_record = self.parent.plan.representations.items[@intFromEnum(target_record_rep)];
        if (source_record.kind != .dynamic) return null;
        switch (target_record.kind) {
            .record, .record_unbound => {},
            .dynamic => if (!self.repHasRecordFieldChildrenForBoundary(target_record)) return null,
            .in_progress, .primitive, .bool_tag_union, .erased_callable, .alias, .tuple, .nominal, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return null,
        }

        const source_payload_layout = self.parent.layout_plan.rep_layouts[@intFromEnum(source_record_rep)].descriptor_payload_layout orelse
            boxyLowerInvariant("dynamic record boundary source had no descriptor payload layout");
        const target_field_count = self.recordFieldCount(self.parent.plan.childSlice(target_record.children));
        if (target_field_count == 0) return null;

        const source_payload = try self.addFrameLocal(source_payload_layout);
        // The unboxed source payload lives past the field conversions and is then
        // dropped. When it carries an `erased_box` it must be
        // reference-counted through a descriptor, so tag it with the source box's
        // descriptor (which describes exactly this payload shape).
        const source_payload_desc: ?LIR.BoxyDescRef = if (self.repContainsDynamicStorage(source_record_rep))
            try self.descriptorRefForSourceLocalRep(source, source_rep)
        else
            null;
        if (source_payload_desc) |desc| {
            self.parent.result.store.setLocalBoxyDesc(source_payload, desc);
        }
        const target_fields = try self.parent.allocator.alloc(LIR.LocalId, target_field_count);
        defer self.parent.allocator.free(target_fields);
        const source_fields = try self.parent.allocator.alloc(LIR.LocalId, target_field_count);
        defer self.parent.allocator.free(source_fields);
        const target_field_reps = try self.parent.allocator.alloc(Plan.TypeRepId, target_field_count);
        defer self.parent.allocator.free(target_field_reps);
        const source_field_reps = try self.parent.allocator.alloc(Plan.TypeRepId, target_field_count);
        defer self.parent.allocator.free(source_field_reps);
        const source_field_indices = try self.parent.allocator.alloc(u16, target_field_count);
        defer self.parent.allocator.free(source_field_indices);

        const source_view = procedureModuleById(self.parent.modules, source_record.source_type.module);
        const target_view = procedureModuleById(self.parent.modules, target_record.source_type.module);
        var field_index: usize = 0;
        for (self.parent.plan.childSlice(target_record.children)) |target_child| {
            switch (target_child.role) {
                .record_field => |target_label| {
                    const source_field = self.findRecordFieldByLabel(source_record_rep, source_view, target_view, target_label) orelse
                        boxyLowerInvariant("dynamic record boundary source was missing target field");
                    target_fields[field_index] = if (self.representationBoundaryIsDirect(target_child.rep, source_field.rep))
                        try self.addFrameLocalForRep(target_child.rep)
                    else
                        try self.addFrameBoundaryTargetLocalForRep(target_child.rep);
                    source_fields[field_index] = try self.addFrameLocalForRep(source_field.rep);
                    target_field_reps[field_index] = target_child.rep;
                    source_field_reps[field_index] = source_field.rep;
                    source_field_indices[field_index] = source_field.index;
                    field_index += 1;
                },
                .record_ext => self.requireEmptyRecordExtension(target_child.rep),
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("dynamic record boundary target had non-record child role"),
            }
        }
        if (field_index != target_field_count) {
            boxyLowerInvariant("dynamic record boundary field count disagreed with target record children");
        }

        const descriptor_fields = try self.parent.allocator.alloc(AggregateDescriptorField, target_field_count);
        defer self.parent.allocator.free(descriptor_fields);
        for (target_fields, target_field_reps, source_field_reps, descriptor_fields) |field_local, target_field_rep, source_field_rep, *field| {
            field.* = .{
                .local = field_local,
                .target_rep = target_field_rep,
                .source_rep = source_field_rep,
            };
        }
        const aggregate_desc = try self.constructedAggregateDescriptorForFields(target, target_rep, descriptor_fields);
        defer aggregate_desc.deinit(self.parent.allocator);

        var continuation = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = target,
            .fields = try self.parent.result.store.addLocalSpan(target_fields),
            .contents_desc = aggregate_desc.contents_desc,
            .next = next,
        } });
        continuation = try self.prependOptionalDescriptorMaterialization(aggregate_desc.materialize, continuation);

        var index = target_field_count;
        while (index > 0) {
            index -= 1;
            try self.propagateLocalDescriptorEnvironmentToField(source_fields[index], source_field_reps[index], source_payload);
            continuation = try self.assignRepresentationBoundary(
                target_fields[index],
                source_fields[index],
                target_field_reps[index],
                source_field_reps[index],
                continuation,
            );
            const read_field = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
                .target = source_fields[index],
                .op = .{ .field = .{
                    .source = source_payload,
                    .field_idx = source_field_indices[index],
                } },
                .next = continuation,
            } });
            continuation = try self.prependRecordFieldDescriptorBind(
                source_fields[index],
                source_payload,
                source_record_rep,
                source_field_indices[index],
                read_field,
            );
        }

        try self.recordAggregateLocalDescriptorEnvironment(target, target_rep, target_fields);

        const unbox_source = try self.parent.result.store.addCFStmt(.{ .assign_boxy_unbox = .{
            .target = source_payload,
            .source = source,
            .source_desc = try self.descriptorRefForSourceLocalRep(source, source_rep),
            .target_desc = source_payload_desc,
            .target_layout = source_payload_layout,
            .source_mode = .borrow,
            .next = continuation,
        } });
        return try self.prependDescriptorArgMaterializations(aggregate_desc.field_initializers, unbox_source);
    }

    fn assignConcreteRecordToConcreteBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!?LIR.CFStmtId {
        if (target_rep == source_rep) return null;

        const source_record_rep = self.recordRepForBoundary(source_rep) orelse return null;
        const target_record_rep = self.recordRepForBoundary(target_rep) orelse return null;
        if (source_record_rep == target_record_rep) {
            // The same backing record rep can be laid out at two different byte
            // layouts: a transparent nominal that opts into declared field order
            // reserves unnamed padding its structural backing omits (z@0, pad@4,
            // a@8 vs the structural a@0, z@4). A flat nominal reinterpret would
            // land each field at the wrong host-visible offset, so when the byte
            // layouts differ the fields must be repositioned by their identity
            // index; when the layouts already match a plain reinterpret suffices.
            const target_layout = self.parent.result.store.getLocal(target).layout_idx;
            const source_layout = self.parent.result.store.getLocal(source).layout_idx;
            if (target_layout == source_layout) return null;
        }

        const source_record = self.parent.plan.representations.items[@intFromEnum(source_record_rep)];
        const target_record = self.parent.plan.representations.items[@intFromEnum(target_record_rep)];
        switch (source_record.kind) {
            .record, .record_unbound => {},
            .dynamic => if (!self.repHasRecordFieldChildrenForBoundary(source_record)) return null,
            .in_progress, .primitive, .bool_tag_union, .erased_callable, .alias, .tuple, .nominal, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return null,
        }
        switch (target_record.kind) {
            .record, .record_unbound => {},
            .dynamic => if (!self.repHasRecordFieldChildrenForBoundary(target_record)) return null,
            .in_progress, .primitive, .bool_tag_union, .erased_callable, .alias, .tuple, .nominal, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return null,
        }
        const boxed_source_layout = self.workerRuntimeLayoutForRep(source_record_rep).layoutIdx();
        const boxed_source_layout_value = self.parent.result.layouts.getLayout(boxed_source_layout);
        const source_backing_is_box = switch (boxed_source_layout_value.tag) {
            .box, .box_of_zst, .erased_box => true,
            .scalar, .list, .list_of_zst, .struct_, .closure, .erased_callable, .zst, .tag_union, .ptr => false,
        };
        // A plan-dynamic record whose backing is concrete at this site (fully
        // known instantiation) converts field-by-field like a concrete record;
        // only genuinely boxed backings take the box round-trip.
        if ((source_record.kind == .dynamic or target_record.kind == .dynamic) and source_backing_is_box) {
            const source_desc = try self.descriptorRefForSourceLocalRep(source, source_rep);
            try self.bindConstructedTargetDescriptor(target, target_rep);
            const target_desc = try self.constructedTargetDescForRep(target_rep);
            const target_layout = self.parent.result.store.getLocal(target).layout_idx;
            const source_layout = self.parent.result.store.getLocal(source).layout_idx;
            const boxed_source = try self.addFrameLocal(boxed_source_layout);
            self.parent.result.store.setLocalBoxyDesc(boxed_source, source_desc);
            var continuation = try self.parent.result.store.addCFStmt(.{ .assign_boxy_unbox = .{
                .target = target,
                .source = boxed_source,
                .source_desc = source_desc,
                .target_desc = target_desc,
                .target_layout = target_layout,
                .source_mode = .move,
                .next = next,
            } });
            continuation = try self.prependConstructedDescriptorRebindForRep(target_rep, continuation);
            return try self.parent.result.store.addCFStmt(.{ .assign_boxy_box = .{
                .target = boxed_source,
                .payload = source,
                .payload_layout = source_layout,
                .payload_desc = source_desc,
                .payload_mode = .borrow,
                .next = continuation,
            } });
        }

        const target_field_count = self.recordFieldCount(self.parent.plan.childSlice(target_record.children));
        if (target_field_count == 0) return null;

        const target_fields = try self.parent.allocator.alloc(LIR.LocalId, target_field_count);
        defer self.parent.allocator.free(target_fields);
        const source_fields = try self.parent.allocator.alloc(LIR.LocalId, target_field_count);
        defer self.parent.allocator.free(source_fields);
        const target_field_reps = try self.parent.allocator.alloc(Plan.TypeRepId, target_field_count);
        defer self.parent.allocator.free(target_field_reps);
        const source_field_reps = try self.parent.allocator.alloc(Plan.TypeRepId, target_field_count);
        defer self.parent.allocator.free(source_field_reps);
        const source_field_indices = try self.parent.allocator.alloc(u16, target_field_count);
        defer self.parent.allocator.free(source_field_indices);

        const source_view = procedureModuleById(self.parent.modules, source_record.source_type.module);
        const target_view = procedureModuleById(self.parent.modules, target_record.source_type.module);
        var field_index: usize = 0;
        for (self.parent.plan.childSlice(target_record.children)) |target_child| {
            switch (target_child.role) {
                .record_field => |target_label| {
                    const source_field = self.findRecordFieldByLabel(source_record_rep, source_view, target_view, target_label) orelse
                        boxyLowerInvariant("concrete record boundary source was missing target field");
                    target_fields[field_index] = if (self.representationBoundaryIsDirect(target_child.rep, source_field.rep))
                        try self.addFrameLocalForRep(target_child.rep)
                    else
                        try self.addFrameBoundaryTargetLocalForRep(target_child.rep);
                    source_fields[field_index] = try self.addFrameLocalForRep(source_field.rep);
                    target_field_reps[field_index] = target_child.rep;
                    source_field_reps[field_index] = source_field.rep;
                    source_field_indices[field_index] = source_field.index;
                    field_index += 1;
                },
                .record_ext => self.requireEmptyRecordExtension(target_child.rep),
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("concrete record boundary target had non-record child role"),
            }
        }
        if (field_index != target_field_count) {
            boxyLowerInvariant("concrete record boundary field count disagreed with target record children");
        }

        const descriptor_fields = try self.parent.allocator.alloc(AggregateDescriptorField, target_field_count);
        defer self.parent.allocator.free(descriptor_fields);
        for (target_fields, target_field_reps, source_field_reps, descriptor_fields) |field_local, target_field_rep, source_field_rep, *field| {
            field.* = .{
                .local = field_local,
                .target_rep = target_field_rep,
                .source_rep = source_field_rep,
            };
        }
        const aggregate_desc = try self.constructedAggregateDescriptorForFields(target, target_rep, descriptor_fields);
        defer aggregate_desc.deinit(self.parent.allocator);

        var continuation = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = target,
            .fields = try self.parent.result.store.addLocalSpan(target_fields),
            .contents_desc = aggregate_desc.contents_desc,
            .next = next,
        } });
        continuation = try self.prependOptionalDescriptorMaterialization(aggregate_desc.materialize, continuation);

        var index = target_field_count;
        while (index > 0) {
            index -= 1;
            try self.propagateLocalDescriptorEnvironmentToField(source_fields[index], source_field_reps[index], source);
            continuation = try self.assignRepresentationBoundary(
                target_fields[index],
                source_fields[index],
                target_field_reps[index],
                source_field_reps[index],
                continuation,
            );
            const read_field = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
                .target = source_fields[index],
                .op = .{ .field = .{
                    .source = source,
                    .field_idx = source_field_indices[index],
                } },
                .next = continuation,
            } });
            continuation = try self.prependRecordFieldDescriptorBind(
                source_fields[index],
                source,
                source_record_rep,
                source_field_indices[index],
                read_field,
            );
        }

        try self.recordAggregateLocalDescriptorEnvironment(target, target_rep, target_fields);

        return try self.prependDescriptorArgMaterializations(aggregate_desc.field_initializers, continuation);
    }

    fn assignListRepresentationBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!?LIR.CFStmtId {
        const target_list_rep = self.listRepForBoundary(target_rep) orelse return null;
        const source_list_rep = self.listRepForBoundary(source_rep) orelse return null;

        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        const target_layout_value = self.parent.result.layouts.getLayout(target_layout);
        const source_layout_value = self.parent.result.layouts.getLayout(source_layout);
        if (!layoutIsList(target_layout_value) or !layoutIsList(source_layout_value)) return null;

        const target_elem = self.repQuery().requiredSingleChild(target_list_rep, .list_elem);
        const source_elem = self.repQuery().requiredSingleChild(source_list_rep, .list_elem);
        var target_elem_desc_local = try self.reserveDescriptorLocalForRep(target_elem.rep);
        if (target_elem_desc_local == null and
            self.parent.layoutNeedsNestedBoxyDesc(self.parent.listElementLayout(target_layout)))
        {
            target_elem_desc_local = try self.addFrameLocal(.opaque_ptr);
        }
        if (target_elem_desc_local) |elem_desc_local| {
            if (self.parent.result.store.getLocal(target).boxy_desc) |target_desc| {
                if (target_desc.localOrNull() == elem_desc_local) {
                    target_elem_desc_local = try self.addFrameLocal(.opaque_ptr);
                }
            }
        }

        const len = try self.addFrameLocal(.u64);
        const capacity = try self.addFrameLocal(.u64);
        const index = try self.addFrameLocal(.u64);
        const zero = try self.addFrameLocal(.u64);
        const initial_list = try self.addFrameLocal(target_layout);
        const acc = try self.addFrameLocal(target_layout);
        const source_elem_desc_info = try self.descriptorForSourceListElement(source, source_list_rep, source_elem.rep);
        const target_desc_info = if (target_elem_desc_local) |elem_desc_local|
            try self.constructedListDescriptorForElementLocal(target, target_rep, elem_desc_local)
        else
            try self.stableDescriptorForConstructedValue(target, target_rep);
        if (target_desc_info.desc) |desc| {
            self.parent.result.store.setLocalBoxyDesc(target, desc);
            self.parent.result.store.setLocalBoxyDesc(initial_list, desc);
            self.parent.result.store.setLocalBoxyDesc(acc, desc);
        }
        const join_id = self.freshJoinPointId();

        const body = try self.assignListRepresentationBoundaryLoopBody(
            target,
            source,
            source_rep,
            target_elem.rep,
            source_elem.rep,
            target_elem_desc_local,
            len,
            index,
            acc,
            join_id,
            next,
        );

        var initial_jump = try self.parent.result.store.addCFStmt(.{ .jump = .{ .target = join_id } });
        initial_jump = try self.setLocalInitializeJoinParam(acc, initial_list, initial_jump);
        initial_jump = try self.setLocalInitializeJoinParam(index, zero, initial_jump);
        initial_jump = try self.assignU64Literal(zero, 0, initial_jump);
        initial_jump = try self.assignUnaryLowLevel(initial_list, .list_with_capacity, capacity, initial_jump);
        initial_jump = try self.assignUnaryLowLevel(capacity, .list_capacity, source, initial_jump);
        initial_jump = try self.assignUnaryLowLevel(len, .list_len, source, initial_jump);
        initial_jump = try self.prependOptionalDescriptorMaterialization(target_desc_info.materialize, initial_jump);
        if (target_elem_desc_local) |elem_desc_local| {
            const source_elem_desc = source_elem_desc_info.desc orelse
                boxyLowerInvariant("boxy list boundary initial element descriptor had no source descriptor");
            initial_jump = try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                .target = elem_desc_local,
                .desc = source_elem_desc,
                .next = initial_jump,
            } });
            initial_jump = try self.prependOptionalDescriptorMaterialization(source_elem_desc_info.materialize, initial_jump);
        }
        initial_jump = try self.prependConstructedDescriptorRebindForRep(source_rep, initial_jump);

        return try self.parent.result.store.addCFStmt(.{ .join = .{
            .id = join_id,
            .params = try self.joinParamSpan(&[_]LIR.LocalId{ index, acc }),
            .body = body,
            .remainder = initial_jump,
        } });
    }

    fn assignListRepresentationBoundaryLoopBody(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        source_rep: Plan.TypeRepId,
        target_elem_rep: Plan.TypeRepId,
        source_elem_rep: Plan.TypeRepId,
        target_elem_desc_local: ?LIR.LocalId,
        len: LIR.LocalId,
        index: LIR.LocalId,
        acc: LIR.LocalId,
        join_id: LIR.JoinPointId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const done = try self.addFrameLocal(.bool);
        const finish = try self.assignLocal(target, acc, next);
        const step = try self.assignListRepresentationBoundaryLoopStep(
            source,
            source_rep,
            target_elem_rep,
            source_elem_rep,
            target_elem_desc_local,
            index,
            acc,
            join_id,
        );
        const switch_stmt = try self.boolSwitchNoContinuation(done, finish, step);
        return try self.assignBinaryLowLevel(done, .num_is_eq, index, len, switch_stmt);
    }

    fn assignListRepresentationBoundaryLoopStep(
        self: *ProcBodyBuilder,
        source: LIR.LocalId,
        source_list_rep: Plan.TypeRepId,
        target_elem_rep: Plan.TypeRepId,
        source_elem_rep: Plan.TypeRepId,
        target_elem_desc_local: ?LIR.LocalId,
        index: LIR.LocalId,
        acc: LIR.LocalId,
        join_id: LIR.JoinPointId,
    ) Allocator.Error!LIR.CFStmtId {
        const source_list_layout = self.parent.result.store.getLocal(source).layout_idx;
        const target_list_layout = self.parent.result.store.getLocal(acc).layout_idx;
        const source_storage_layout = self.parent.listElementLayout(source_list_layout);
        const target_storage_layout = self.parent.listElementLayout(target_list_layout);
        const source_worker_layout = self.workerRuntimeLayoutForRep(source_elem_rep).layoutIdx();
        const requires_storage_adapter = source_storage_layout != source_worker_layout or
            source_storage_layout != target_storage_layout;
        const source_elem = try self.addFrameLocal(if (requires_storage_adapter)
            source_storage_layout
        else
            source_worker_layout);
        const target_elem = if (requires_storage_adapter)
            try self.addFrameLocal(target_storage_layout)
        else if (self.representationBoundaryIsDirect(target_elem_rep, source_elem_rep) or
            self.repsUseSameDynamicBoxStorage(target_elem_rep, source_elem_rep))
            source_elem
        else
            try self.addFrameBoundaryTargetLocalForRep(target_elem_rep);
        if (target_elem != source_elem) {
            if (target_elem_desc_local) |desc_local| {
                self.parent.result.store.setLocalBoxyDesc(target_elem, .{ .local = desc_local });
            }
        }
        const source_elem_desc_info = try self.descriptorForSourceListElement(source, source_list_rep, source_elem_rep);
        const source_elem_desc = source_elem_desc_info.desc orelse
            boxyLowerInvariant("boxy list boundary source element descriptor had no descriptor");
        self.parent.result.store.setLocalBoxyDesc(source_elem, source_elem_desc);
        const next_acc = try self.addFrameLocal(self.parent.result.store.getLocal(acc).layout_idx);
        if (self.parent.result.store.getLocal(acc).boxy_desc) |desc| {
            self.parent.result.store.setLocalBoxyDesc(next_acc, desc);
        }
        const one = try self.addFrameLocal(.u64);
        const next_index = try self.addFrameLocal(.u64);

        var continuation = try self.parent.result.store.addCFStmt(.{ .jump = .{ .target = join_id } });
        continuation = try self.setLocalInitializeJoinParam(acc, next_acc, continuation);
        continuation = try self.setLocalInitializeJoinParam(index, next_index, continuation);
        continuation = try self.assignListAppendMovingElement(next_acc, acc, target_elem, continuation);
        if (requires_storage_adapter) {
            const source_desc = source_elem_desc_info.desc orelse
                boxyLowerInvariant("contextual list element storage had no exact source descriptor");
            continuation = try self.parent.result.store.addCFStmt(.{ .assign_boxy_adapt = .{
                .target = target_elem,
                .source = source_elem,
                .adapter = try self.internMoveAdapter(
                    if (source_storage_layout == target_storage_layout) .relabel else .materialize,
                    source_storage_layout,
                    target_storage_layout,
                ),
                .source_desc = source_desc,
                .target_desc = source_desc,
                .source_mode = .move,
                .next = continuation,
            } });
        } else if (target_elem != source_elem) {
            continuation = try self.assignRepresentationBoundary(target_elem, source_elem, target_elem_rep, source_elem_rep, continuation);
        }
        continuation = try self.assignBinaryLowLevel(source_elem, .list_get_unsafe, source, index, continuation);
        continuation = try self.prependOptionalDescriptorMaterialization(source_elem_desc_info.materialize, continuation);
        continuation = try self.assignBinaryLowLevel(next_index, .num_int_add_crash_on_overflow, index, one, continuation);
        return try self.assignU64Literal(one, 1, continuation);
    }

    fn descriptorForSourceListElement(
        self: *ProcBodyBuilder,
        source: LIR.LocalId,
        source_list_rep: Plan.TypeRepId,
        source_elem_rep: Plan.TypeRepId,
    ) Allocator.Error!ResultDescriptorSource {
        const identity_list_rep = self.descriptorStorageRep(source_list_rep);
        const identity_elem_rep = self.descriptorStorageRep(source_elem_rep);
        if (try self.sourceNestedDescriptorLocalForHiddenArg(source, identity_list_rep, identity_elem_rep)) |nested| {
            return .{
                .desc = .{ .local = nested.local },
                .materialize = nested,
            };
        }

        const materialization = try self.descriptorMaterializationForSourceRep(identity_elem_rep);
        if (materialization.captures.len == 0) {
            return .{ .desc = materialization.desc };
        }

        const desc_local = try self.addFrameLocal(.opaque_ptr);
        return .{
            .desc = .{ .local = desc_local },
            .materialize = .{
                .local = desc_local,
                .materialize = materialization.desc,
                .captures = materialization.captures,
            },
        };
    }

    fn assignSingletonZstTagToConcreteBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!?LIR.CFStmtId {
        if (!self.isZstLocal(source)) return null;

        const target_tag_rep = self.tagVariantRepForBoundary(target_rep) orelse return null;
        const source_tag_rep = self.tagVariantRepForBoundary(source_rep) orelse return null;

        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        const target_layout_value = self.parent.result.layouts.getLayout(target_layout);
        if (target_layout_value.tag != .tag_union) return null;

        const source_rep_info = self.parent.plan.representations.items[@intFromEnum(source_tag_rep)];
        const source_variants = self.parent.plan.tagVariantSlice(source_rep_info.tag_variants);
        if (source_variants.len != 1) return null;
        const source_variant = source_variants[0];
        if (self.parent.plan.childSlice(source_variant.payloads).len != 0) return null;

        const target_rep_info = self.parent.plan.representations.items[@intFromEnum(target_tag_rep)];
        const target_variants = self.parent.plan.tagVariantSlice(target_rep_info.tag_variants);
        const source_name = self.tagVariantNameText(source_variant);

        for (target_variants, 0..) |target_variant, index| {
            if (!std.mem.eql(u8, source_name, self.tagVariantNameText(target_variant))) continue;
            if (index > std.math.maxInt(u16)) {
                boxyLowerInvariant("singleton tag widening target variant index exceeded LIR variant range");
            }
            if (self.parent.plan.childSlice(target_variant.payloads).len != 0) return null;
            if (self.isZstLocal(target)) return try self.assignZst(target, next);
            return try self.parent.result.store.addCFStmt(.{ .assign_tag = .{
                .target = target,
                .target_desc = try self.boundaryTargetDesc(target, target_rep),
                .variant_index = @intCast(index),
                .discriminant = @intCast(index),
                .payload = null,
                .next = next,
            } });
        }

        return null;
    }

    fn assignConcreteTagUnionToConcreteBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!?LIR.CFStmtId {
        const target_tag_rep = self.tagVariantRepForBoundary(target_rep) orelse return null;
        const source_tag_rep = self.tagVariantRepForBoundary(source_rep) orelse return null;

        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        const target_layout_value = self.parent.result.layouts.getLayout(target_layout);
        const source_layout_value = self.parent.result.layouts.getLayout(source_layout);
        if (target_layout_value.tag != .tag_union or source_layout_value.tag != .tag_union) return null;

        // Equal-layout tag unions can preserve the source value and its exact
        // descriptor when the planned representations prove that every source
        // payload uses storage accepted by the target. This is an explicit
        // descriptor transfer, not a representation-identity shortcut: the
        // target's reserved descriptor local is initialized by assignLocal.
        if (target_layout == source_layout and
            self.parent.result.store.getLocal(source).boxy_desc != null and
            try self.repsCanReuseSourceDescriptor(source_tag_rep, target_tag_rep))
        {
            return try self.assignLocal(target, source, next);
        }

        const target_variants = self.parent.plan.tagVariantSlice(self.parent.plan.representations.items[@intFromEnum(target_tag_rep)].tag_variants);
        const source_variants = self.parent.plan.tagVariantSlice(self.parent.plan.representations.items[@intFromEnum(source_tag_rep)].tag_variants);
        if (target_variants.len == 0 or source_variants.len == 0) return null;

        // Checked row coercions can widen or narrow a concrete tag union. Prove
        // that one row is a subset of the other before emitting either form;
        // partially overlapping rows would indicate invalid producer data.
        var source_has_excluded_variant = false;
        for (source_variants) |source_variant| {
            const source_name = self.tagVariantNameText(source_variant);
            for (target_variants) |target_variant| {
                if (std.mem.eql(u8, source_name, self.tagVariantNameText(target_variant))) break;
            } else {
                source_has_excluded_variant = true;
            }
        }
        var target_has_added_variant = false;
        for (target_variants) |target_variant| {
            const target_name = self.tagVariantNameText(target_variant);
            for (source_variants) |source_variant| {
                if (std.mem.eql(u8, target_name, self.tagVariantNameText(source_variant))) break;
            } else {
                target_has_added_variant = true;
            }
        }
        if (source_has_excluded_variant and target_has_added_variant) {
            boxyLowerInvariant("boxy concrete tag boundary rows overlapped without a subset relationship");
        }
        const unreachable_source_variant = try self.parent.result.store.addCFStmt(.runtime_error);
        const branches = try self.parent.allocator.alloc(LIR.CFSwitchBranch, source_variants.len);
        defer self.parent.allocator.free(branches);
        for (source_variants, branches, 0..) |source_variant, *branch, source_index| {
            if (source_index > std.math.maxInt(u16)) {
                boxyLowerInvariant("boxy concrete-to-concrete tag adapter variant index exceeded LIR variant range");
            }
            const target_match: ?struct { variant: Plan.TagVariant, index: u16 } = blk: {
                const source_name = self.tagVariantNameText(source_variant);
                for (target_variants, 0..) |target_candidate, candidate_index| {
                    if (!std.mem.eql(u8, source_name, self.tagVariantNameText(target_candidate))) continue;
                    if (candidate_index > std.math.maxInt(u16)) {
                        boxyLowerInvariant("boxy concrete-to-concrete tag adapter target variant index exceeded LIR variant range");
                    }
                    break :blk .{ .variant = target_candidate, .index = @intCast(candidate_index) };
                }
                break :blk null;
            };
            const target_variant_match = target_match orelse {
                branch.* = .{
                    .value = @intCast(source_index),
                    .body = unreachable_source_variant,
                };
                continue;
            };
            branch.* = .{
                .value = @intCast(source_index),
                .body = try self.assignConcreteTagVariantToConcrete(
                    target,
                    source,
                    target_rep,
                    source_tag_rep,
                    target_variant_match.variant,
                    source_variant,
                    target_variant_match.index,
                    @intCast(source_index),
                    next,
                ),
            };
        }

        const discriminant = try self.addFrameLocal(.u16);
        const switch_stmt = try self.parent.result.store.addCFStmt(.{ .switch_stmt = .{
            .cond = discriminant,
            .branches = try self.parent.result.store.addCFSwitchBranches(branches),
            .default_branch = unreachable_source_variant,
            .continuation = null,
        } });
        const read_discriminant = try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = discriminant,
            .op = .{ .discriminant = .{ .source = source } },
            .next = switch_stmt,
        } });
        return read_discriminant;
    }

    /// Adapt a concrete tag union into a target whose every payload is
    /// zero-sized, so its layout collapsed to a bare scalar discriminant.
    /// Concrete tag-union layouts on both sides order variants the same way
    /// (alphabetically, over the same checked tag set), so the discriminant
    /// carries over positionally; only its byte position and width change.
    fn assignConcreteTagUnionToScalarBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!?LIR.CFStmtId {
        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        const target_layout_value = self.parent.result.layouts.getLayout(target_layout);
        const source_layout_value = self.parent.result.layouts.getLayout(source_layout);
        if (source_layout_value.tag != .tag_union) return null;
        switch (target_layout_value.tag) {
            .scalar => {},
            .tag_union => {
                // Only a target whose variants all have zero-sized payloads is
                // a bare discriminant; other unions need payload conversion.
                const target_info = self.parent.result.layouts.getTagUnionInfo(target_layout_value);
                var variant_index: u32 = 0;
                while (variant_index < target_info.variants.len) : (variant_index += 1) {
                    const payload_layout = target_info.variants.get(variant_index).payload_layout;
                    if (!self.parent.result.layouts.isZeroSized(self.parent.result.layouts.getLayout(payload_layout))) return null;
                }
            },
            .box, .box_of_zst, .erased_box, .list, .list_of_zst, .struct_, .closure, .erased_callable, .zst, .ptr => return null,
        }

        const source_tag_count = self.checkedTagUnionCountForBoundary(source_rep) orelse return null;
        const target_tag_count = self.checkedTagUnionCountForBoundary(target_rep) orelse return null;
        if (source_tag_count != target_tag_count) return null;
        const source_layout_info = self.parent.result.layouts.getTagUnionInfo(source_layout_value);
        if (source_layout_info.variants.len != source_tag_count) return null;

        const branches = try self.parent.allocator.alloc(LIR.CFSwitchBranch, source_tag_count);
        defer self.parent.allocator.free(branches);
        for (branches, 0..) |*branch, index| {
            branch.* = .{
                .value = @intCast(index),
                .body = try self.parent.result.store.addCFStmt(.{ .assign_literal = .{
                    .target = target,
                    .value = .{ .i64_literal = .{
                        .value = @intCast(index),
                        .layout_idx = target_layout,
                    } },
                    .next = next,
                } }),
            };
        }

        const bad_discriminant = try self.parent.result.store.addCFStmt(.runtime_error);
        const discriminant = try self.addFrameLocal(.u16);
        const switch_stmt = try self.parent.result.store.addCFStmt(.{ .switch_stmt = .{
            .cond = discriminant,
            .branches = try self.parent.result.store.addCFSwitchBranches(branches),
            .default_branch = bad_discriminant,
            .continuation = null,
        } });
        return try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = discriminant,
            .op = .{ .discriminant = .{ .source = source } },
            .next = switch_stmt,
        } });
    }

    /// The number of tags in the checked tag-union type behind this
    /// representation, following alias and transparent-nominal wrappers, or
    /// null when the representation does not resolve to a closed checked tag
    /// union.
    fn checkedTagUnionCountForBoundary(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) ?usize {
        var current = rep_id;
        var depth: u16 = 0;
        while (true) {
            if (depth == 1024) boxyLowerInvariant("tag representation wrapper chain exceeded boxy lowerer limit");
            depth += 1;

            const rep = self.parent.plan.representations.items[@intFromEnum(current)];
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent, .builtin_other => current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep,
                    .opaque_nominal => return null,
                },
                .tag_union => {
                    const view = procedureModuleById(self.parent.modules, rep.source_type.module);
                    var ty = rep.source_type.ty;
                    var type_depth: u16 = 0;
                    while (true) {
                        if (type_depth == 1024) boxyLowerInvariant("checked type alias chain exceeded boxy lowerer limit");
                        type_depth += 1;
                        switch (view.checked_types.payload(ty)) {
                            .alias => |alias| ty = alias.backing,
                            .tag_union => |tag_union| return tag_union.tags.len,
                            .pending, .err, .flex, .rigid, .record, .record_unbound, .tuple, .nominal, .function, .empty_record, .empty_tag_union => return null,
                        }
                    }
                },
                .in_progress, .dynamic, .primitive, .bool_tag_union, .erased_callable, .record, .record_unbound, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .empty_tag_union => return null,
            }
        }
    }

    fn assignConcreteTagVariantToConcrete(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_tag_rep: Plan.TypeRepId,
        target_variant: Plan.TagVariant,
        source_variant: Plan.TagVariant,
        target_variant_index: u16,
        source_variant_index: u16,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const target_payloads = self.parent.plan.childSlice(target_variant.payloads);
        const source_payloads = self.parent.plan.childSlice(source_variant.payloads);
        if (target_payloads.len != source_payloads.len) {
            boxyLowerInvariant("boxy concrete tag adapter saw payload count mismatch between source and target variants");
        }

        if (target_payloads.len == 0) {
            const target_desc_info = try self.stableDescriptorForConstructedValue(target, target_rep);
            const assign_tag = try self.parent.result.store.addCFStmt(.{ .assign_tag = .{
                .target = target,
                .target_desc = target_desc_info.desc,
                .variant_index = target_variant_index,
                .discriminant = target_variant_index,
                .payload = null,
                .next = next,
            } });
            return try self.prependOptionalDescriptorMaterialization(target_desc_info.materialize, assign_tag);
        }

        const target_layout = self.parent.result.store.getLocal(target).layout_idx;
        const target_payload_layout = self.tagUnionPayloadLayout(target_layout, target_variant_index);
        if (self.parent.result.layouts.isZeroSized(self.parent.result.layouts.getLayout(target_payload_layout))) {
            const target_desc_info = try self.stableDescriptorForConstructedValue(target, target_rep);
            const assign_tag = try self.parent.result.store.addCFStmt(.{ .assign_tag = .{
                .target = target,
                .target_desc = target_desc_info.desc,
                .variant_index = target_variant_index,
                .discriminant = target_variant_index,
                .payload = null,
                .next = next,
            } });
            return try self.prependOptionalDescriptorMaterialization(target_desc_info.materialize, assign_tag);
        }

        const target_payload = try self.addFrameLocal(target_payload_layout);
        const source_has_payload_desc = self.parent.plan.representations.items[@intFromEnum(source_tag_rep)].descriptor != null or
            self.parent.result.store.getLocal(source).boxy_desc != null;

        if (target_payloads.len == 1) {
            const source_payload = try self.addExtractedTagPayloadLocal(source_payloads[0].rep, source_has_payload_desc);
            const descriptor_fields = [_]AggregateDescriptorField{.{
                .local = target_payload,
                .target_rep = target_payloads[0].rep,
                .source_rep = source_payloads[0].rep,
            }};
            const tag_desc = try self.constructedTagDescriptorForPayloadFields(target, target_rep, &descriptor_fields);
            defer tag_desc.deinit(self.parent.allocator);
            const assign_tag = try self.parent.result.store.addCFStmt(.{ .assign_tag = .{
                .target = target,
                .target_desc = tag_desc.desc,
                .variant_index = target_variant_index,
                .discriminant = target_variant_index,
                .payload = target_payload,
                .next = next,
            } });
            var continuation = try self.prependOptionalDescriptorMaterialization(tag_desc.materialize, assign_tag);
            continuation = try self.assignRepresentationBoundary(
                target_payload,
                source_payload.local,
                target_payloads[0].rep,
                source_payloads[0].rep,
                continuation,
            );
            continuation = try self.assignConcreteTagPayloadRead(
                source_payload.local,
                source_payloads[0].rep,
                source_payload.desc_local,
                source,
                source_tag_rep,
                source_variant.name,
                source_variant_index,
                0,
                source_payloads.len,
                continuation,
            );
            return try self.prependDescriptorArgMaterializations(tag_desc.field_initializers, continuation);
        }

        return try self.assignConcreteTagPayloadStructToConcrete(
            target,
            target_rep,
            target_payload,
            source,
            source_tag_rep,
            source_variant,
            target_variant_index,
            source_variant_index,
            target_payloads,
            source_payloads,
            next,
        );
    }

    fn assignConcreteTagPayloadStructToConcrete(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        target_payload: LIR.LocalId,
        source: LIR.LocalId,
        source_tag_rep: Plan.TypeRepId,
        source_variant: Plan.TagVariant,
        target_variant_index: u16,
        source_variant_index: u16,
        target_payloads: []const Plan.RepChild,
        source_payloads: []const Plan.RepChild,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (target_payloads.len != source_payloads.len) {
            boxyLowerInvariant("boxy concrete tag payload adapter saw mismatched struct field counts");
        }

        const target_fields = try self.parent.allocator.alloc(LIR.LocalId, target_payloads.len);
        defer self.parent.allocator.free(target_fields);
        const source_fields = try self.parent.allocator.alloc(ExtractedTagPayloadLocal, source_payloads.len);
        defer self.parent.allocator.free(source_fields);
        const source_has_payload_desc = self.parent.plan.representations.items[@intFromEnum(source_tag_rep)].descriptor != null or
            self.parent.result.store.getLocal(source).boxy_desc != null;

        const target_payload_layout = self.parent.result.store.getLocal(target_payload).layout_idx;
        for (target_fields, 0..) |*local, index| {
            local.* = try self.addFrameLocal(try self.aggregateFieldLayout(target_payload_layout, index));
        }
        for (source_payloads, source_fields) |child, *local| {
            local.* = try self.addExtractedTagPayloadLocal(child.rep, source_has_payload_desc);
        }

        const descriptor_fields = try self.parent.allocator.alloc(AggregateDescriptorField, target_payloads.len);
        defer self.parent.allocator.free(descriptor_fields);
        for (target_fields, target_payloads, source_payloads, descriptor_fields) |field_local, target_child, source_child, *field| {
            field.* = .{
                .local = field_local,
                .target_rep = target_child.rep,
                .source_rep = source_child.rep,
            };
        }
        const tag_desc = try self.constructedTagDescriptorForPayloadFields(target, target_rep, descriptor_fields);
        defer tag_desc.deinit(self.parent.allocator);
        const assign_tag = try self.parent.result.store.addCFStmt(.{ .assign_tag = .{
            .target = target,
            .target_desc = tag_desc.desc,
            .variant_index = target_variant_index,
            .discriminant = target_variant_index,
            .payload = target_payload,
            .next = next,
        } });
        var continuation = try self.prependOptionalDescriptorMaterialization(tag_desc.materialize, assign_tag);
        continuation = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = target_payload,
            .fields = try self.parent.result.store.addLocalSpan(target_fields),
            .next = continuation,
        } });

        var index = target_payloads.len;
        while (index > 0) {
            index -= 1;
            continuation = try self.assignRepresentationBoundary(
                target_fields[index],
                source_fields[index].local,
                target_payloads[index].rep,
                source_payloads[index].rep,
                continuation,
            );
            continuation = try self.assignConcreteTagPayloadRead(
                source_fields[index].local,
                source_payloads[index].rep,
                source_fields[index].desc_local,
                source,
                source_tag_rep,
                source_variant.name,
                source_variant_index,
                @intCast(index),
                source_payloads.len,
                continuation,
            );
        }

        return try self.prependDescriptorArgMaterializations(tag_desc.field_initializers, continuation);
    }

    fn assignConcreteTagUnionToDynamicBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!?LIR.CFStmtId {
        if (!self.repHasTagDomain(target_rep)) return null;
        const source_tag_rep = self.tagVariantRepForBoundary(source_rep) orelse return null;
        const source_layout = self.parent.result.store.getLocal(source).layout_idx;
        const source_layout_value = self.parent.result.layouts.getLayout(source_layout);
        if (source_layout_value.tag != .tag_union) return null;

        const variants = self.parent.plan.tagVariantSlice(self.parent.plan.representations.items[@intFromEnum(source_tag_rep)].tag_variants);
        if (variants.len == 0) return null;
        var all_variants_have_no_payload = true;
        for (variants) |variant| {
            const source_payloads = self.parent.plan.childSlice(variant.payloads);
            if (source_payloads.len != 0) all_variants_have_no_payload = false;
            var seen_payloads = collections.DenseMap(Plan.TypeRepId, void).init(self.parent.allocator);
            defer seen_payloads.deinit();
            const target_payloads = (try self.dynamicTagPayloadsForTextInner(target_rep, self.tagVariantNameText(variant), &seen_payloads)) orelse return null;
            if (source_payloads.len != target_payloads.len) return null;
        }
        // Reusing the concrete source descriptor relabels the source value's box
        // as the open target without rewriting it. When the open row's storage
        // is wider than the concrete tag, reading the relabelled box through the
        // open descriptor runs past the boxed allocation. For payloadless
        // variants the per-variant conversion below rebuilds the open tag
        // exactly, so decline the relabel there and let it run.
        const target_payload_layout = self.parent.descriptorPayloadLayoutForRep(target_rep);
        const source_storage_size = self.parent.result.layouts.layoutSize(self.parent.result.layouts.getLayout(source_layout));
        const target_storage_size = self.parent.result.layouts.layoutSize(self.parent.result.layouts.getLayout(target_payload_layout));
        const relabel_would_overread = all_variants_have_no_payload and source_storage_size < target_storage_size;
        if (!relabel_would_overread and
            self.tagDomainHasOpenExtension(target_rep) and
            try self.concreteTagUnionBoundaryCanReuseSourceDescriptor(target_rep, source_tag_rep, variants))
        {
            const source_desc = try self.descriptorRefForSourceStorageLocalRep(source, source_rep);
            const existing_target_desc = self.parent.result.store.getLocal(target).boxy_desc;
            const can_initialize_target_desc = if (existing_target_desc) |existing|
                std.meta.eql(existing, source_desc) or
                    if (existing.localOrNull()) |local| !self.localIsReadOnlyDescriptorInput(local) else false
            else
                true;
            if (can_initialize_target_desc) {
                const target_desc_info = self.resultDescriptorForCallTarget(target, .{ .desc = source_desc });
                const target_desc = target_desc_info.desc orelse
                    boxyLowerInvariant("boxy concrete tag relabel had no target descriptor");
                if (existing_target_desc == null) {
                    self.parent.result.store.setLocalBoxyDesc(target, target_desc);
                }
                const box = try self.parent.result.store.addCFStmt(.{ .assign_boxy_box = .{
                    .target = target,
                    .payload = source,
                    .payload_layout = source_layout,
                    .source_desc = source_desc,
                    .payload_desc = target_desc,
                    .payload_mode = .move,
                    .next = next,
                } });
                return try self.prependOptionalDescriptorMaterialization(target_desc_info.materialize, box);
            }
        }

        const branches = try self.parent.allocator.alloc(LIR.CFSwitchBranch, variants.len);
        defer self.parent.allocator.free(branches);
        for (variants, branches, 0..) |variant, *branch, index| {
            if (index > std.math.maxInt(u16)) {
                boxyLowerInvariant("boxy concrete-to-dynamic tag adapter variant index exceeded LIR variant range");
            }
            branch.* = .{
                .value = @intCast(index),
                .body = try self.assignConcreteTagVariantToDynamic(target, source, target_rep, source_tag_rep, variant, @intCast(index), next),
            };
        }

        const bad_discriminant = try self.parent.result.store.addCFStmt(.runtime_error);
        const discriminant = try self.addFrameLocal(.u16);
        const switch_stmt = try self.parent.result.store.addCFStmt(.{ .switch_stmt = .{
            .cond = discriminant,
            .branches = try self.parent.result.store.addCFSwitchBranches(branches),
            .default_branch = bad_discriminant,
            .continuation = null,
        } });
        return try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = discriminant,
            .op = .{ .discriminant = .{ .source = source } },
            .next = switch_stmt,
        } });
    }

    fn concreteTagUnionBoundaryCanReuseSourceDescriptor(
        self: *ProcBodyBuilder,
        target_rep: Plan.TypeRepId,
        source_tag_rep: Plan.TypeRepId,
        variants: []const Plan.TagVariant,
    ) Allocator.Error!bool {
        for (variants) |variant| {
            const source_payloads = self.parent.plan.childSlice(variant.payloads);
            const target_payloads = (try self.dynamicTagPayloadsForRepTagNameOrNull(target_rep, source_tag_rep, variant.name)) orelse {
                return false;
            };
            if (source_payloads.len != target_payloads.len) {
                return false;
            }
            for (source_payloads, target_payloads) |source_payload, target_payload| {
                const identity_source = self.descriptorStorageRep(source_payload.rep);
                const identity_target = self.descriptorStorageRep(target_payload.rep);
                // Relabelling reuses the source value's bytes and descriptor
                // under the target rep's identity, so it is only sound when the
                // source and target agree on how each payload field is stored.
                // A worker can return a tag whose payload fields are erased
                // (`erased_box`) while the dynamic target realizes them inline
                // (a fully-concrete instantiation, e.g. `Ok(val, input)` at a
                // call site where both are `Str`). Reusing the erased source
                // descriptor there would leave the boxed fields where the
                // target expects inline bytes, so require matching storage and
                // otherwise let the per-variant construct materialize the fields.
                if (self.repStoredAsDynamicBox(identity_source) != self.repStoredAsDynamicBox(identity_target)) return false;
                if (!try self.repsCanReuseSourceDescriptor(identity_source, identity_target)) return false;
            }
        }
        return true;
    }

    fn repStoredAsDynamicBox(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) bool {
        return switch (self.workerRuntimeLayoutForRep(rep_id)) {
            .dynamic_box => true,
            .concrete => false,
        };
    }

    fn repsCanReuseSourceDescriptor(
        self: *ProcBodyBuilder,
        source_rep: Plan.TypeRepId,
        target_rep: Plan.TypeRepId,
    ) Allocator.Error!bool {
        var seen = std.AutoHashMap(u64, void).init(self.parent.allocator);
        defer seen.deinit();
        return try self.repsCanReuseSourceDescriptorInner(source_rep, target_rep, &seen);
    }

    fn repsCanReuseSourceDescriptorInner(
        self: *ProcBodyBuilder,
        source_rep: Plan.TypeRepId,
        target_rep: Plan.TypeRepId,
        seen: *std.AutoHashMap(u64, void),
    ) Allocator.Error!bool {
        const identity_source = self.descriptorStorageRep(source_rep);
        const identity_target = self.descriptorStorageRep(target_rep);
        if (identity_source == identity_target) return true;

        const key = (@as(u64, @intFromEnum(identity_source)) << 32) | @as(u64, @intFromEnum(identity_target));
        const entry = try seen.getOrPut(key);
        if (entry.found_existing) return true;

        const source = self.parent.plan.representations.items[@intFromEnum(identity_source)];
        const target = self.parent.plan.representations.items[@intFromEnum(identity_target)];
        switch (source.kind) {
            .dynamic => return true,
            .primitive => |source_primitive| switch (target.kind) {
                .primitive => |target_primitive| return source_primitive == target_primitive,
                .in_progress, .dynamic, .bool_tag_union, .erased_callable, .alias, .record, .record_unbound, .tuple, .nominal, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return false,
            },
            .bool_tag_union => return target.kind == .bool_tag_union,
            .empty_record => return target.kind == .empty_record,
            .empty_tag_union => return target.kind == .empty_tag_union,
            .tag_union => switch (target.kind) {
                .tag_union => return try self.tagUnionRepsCanReuseSourceDescriptor(identity_source, identity_target, seen),
                .in_progress, .dynamic, .primitive, .bool_tag_union, .erased_callable, .alias, .record, .record_unbound, .tuple, .nominal, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .empty_tag_union => return false,
            },
            .list => switch (target.kind) {
                .list => {
                    const source_elem = self.repQuery().requiredSingleChild(identity_source, .list_elem).rep;
                    const target_elem = self.repQuery().requiredSingleChild(identity_target, .list_elem).rep;
                    return try self.repsCanReuseSourceDescriptorInner(source_elem, target_elem, seen);
                },
                .in_progress, .dynamic, .primitive, .bool_tag_union, .erased_callable, .alias, .record, .record_unbound, .tuple, .nominal, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return false,
            },
            .in_progress, .erased_callable, .alias, .record, .record_unbound, .tuple, .nominal, .box, .generated_field, .generated_field_names, .generated_tag_union_spec => return false,
        }
    }

    fn tagUnionRepsCanReuseSourceDescriptor(
        self: *ProcBodyBuilder,
        source_rep: Plan.TypeRepId,
        target_rep: Plan.TypeRepId,
        seen: *std.AutoHashMap(u64, void),
    ) Allocator.Error!bool {
        const source = self.parent.plan.representations.items[@intFromEnum(source_rep)];
        const target = self.parent.plan.representations.items[@intFromEnum(target_rep)];
        const target_variants = self.parent.plan.tagVariantSlice(target.tag_variants);
        for (self.parent.plan.tagVariantSlice(source.tag_variants)) |source_variant| {
            const source_name = self.tagVariantNameText(source_variant);
            const target_variant = blk: {
                for (target_variants) |candidate| {
                    if (std.mem.eql(u8, source_name, self.tagVariantNameText(candidate))) {
                        break :blk candidate;
                    }
                }
                return false;
            };

            const source_payloads = self.parent.plan.childSlice(source_variant.payloads);
            const target_payloads = self.parent.plan.childSlice(target_variant.payloads);
            if (source_payloads.len != target_payloads.len) return false;
            for (source_payloads, target_payloads) |source_payload, target_payload| {
                if (!try self.repsCanReuseSourceDescriptorInner(source_payload.rep, target_payload.rep, seen)) return false;
            }
        }

        return true;
    }

    fn tagDomainHasOpenExtension(
        self: *const ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) bool {
        const ext_rep_id = self.tagDomainExtensionRep(rep_id) orelse return false;
        return !self.repIsEmptyTagUnion(ext_rep_id);
    }

    fn tagDomainExtensionRep(
        self: *const ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) ?Plan.TypeRepId {
        const tag_rep_id = self.tagDomainRep(rep_id) orelse return null;
        const rep = self.parent.plan.representations.items[@intFromEnum(tag_rep_id)];
        for (self.parent.plan.childSlice(rep.children)) |child| {
            if (child.role != .tag_ext) continue;
            return child.rep;
        }
        return null;
    }

    fn repIsEmptyTagUnion(
        self: *const ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) bool {
        const identity = self.descriptorStorageRep(rep_id);
        const rep = self.parent.plan.representations.items[@intFromEnum(identity)];
        return rep.kind == .empty_tag_union;
    }

    fn tagDomainDescriptorCanFlowTo(
        self: *ProcBodyBuilder,
        source_rep: Plan.TypeRepId,
        target_rep: Plan.TypeRepId,
    ) Allocator.Error!bool {
        var seen = std.AutoHashMap(u64, void).init(self.parent.allocator);
        defer seen.deinit();
        return try self.tagDomainDescriptorCanFlowToInner(source_rep, target_rep, &seen);
    }

    fn tagDomainDescriptorCanFlowToInner(
        self: *ProcBodyBuilder,
        source_rep: Plan.TypeRepId,
        target_rep: Plan.TypeRepId,
        seen: *std.AutoHashMap(u64, void),
    ) Allocator.Error!bool {
        const identity_source = self.descriptorStorageRep(source_rep);
        const identity_target = self.descriptorStorageRep(target_rep);
        const key = (@as(u64, @intFromEnum(identity_source)) << 32) | @as(u64, @intFromEnum(identity_target));
        const entry = try seen.getOrPut(key);
        if (entry.found_existing) return true;

        const source_tag_rep = self.tagDomainRep(identity_source) orelse
            return self.targetAcceptsUnconstrainedDynamicTagDescriptor(identity_target);
        if (self.tagDomainRep(identity_target) == null) {
            return self.targetAcceptsUnconstrainedDynamicTagDescriptor(identity_target);
        }

        const source_rep_value = self.parent.plan.representations.items[@intFromEnum(source_tag_rep)];
        for (self.parent.plan.tagVariantSlice(source_rep_value.tag_variants)) |variant| {
            const source_payloads = self.parent.plan.childSlice(variant.payloads);
            if (try self.dynamicTagPayloadsForRepTagNameOrNull(identity_target, source_tag_rep, variant.name)) |target_payloads| {
                if (!try self.tagPayloadsCanReuseDescriptor(source_payloads, target_payloads, seen)) return false;
            } else if (!self.targetTagDomainHasUnconstrainedExtension(identity_target)) {
                return false;
            }
        }

        const source_ext = self.tagDomainExtensionRep(source_tag_rep) orelse return true;
        if (self.repIsEmptyTagUnion(source_ext)) return true;
        return try self.tagDomainDescriptorCanFlowToInner(source_ext, identity_target, seen);
    }

    fn tagPayloadsCanReuseDescriptor(
        self: *ProcBodyBuilder,
        source_payloads: []const Plan.RepChild,
        target_payloads: []const Plan.RepChild,
        seen: *std.AutoHashMap(u64, void),
    ) Allocator.Error!bool {
        if (source_payloads.len != target_payloads.len) return false;
        for (source_payloads, target_payloads) |source_payload, target_payload| {
            const identity_source = self.descriptorStorageRep(source_payload.rep);
            const identity_target = self.descriptorStorageRep(target_payload.rep);
            if (!try self.repsCanReuseSourceDescriptorInner(identity_source, identity_target, seen)) return false;
        }
        return true;
    }

    fn targetAcceptsUnconstrainedDynamicTagDescriptor(
        self: *const ProcBodyBuilder,
        target_rep: Plan.TypeRepId,
    ) bool {
        const identity_target = self.descriptorStorageRep(target_rep);
        const target = self.parent.plan.representations.items[@intFromEnum(identity_target)];
        if (target.kind == .dynamic and target.tag_variants.len == 0 and target.children.len == 0) return true;
        return self.targetTagDomainHasUnconstrainedExtension(identity_target);
    }

    fn targetTagDomainHasUnconstrainedExtension(
        self: *const ProcBodyBuilder,
        target_rep: Plan.TypeRepId,
    ) bool {
        const ext_rep = self.tagDomainExtensionRep(target_rep) orelse return false;
        return self.targetAcceptsUnconstrainedDynamicTagDescriptor(ext_rep);
    }

    fn assignDynamicTagUnionToDynamicBoundary(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!?LIR.CFStmtId {
        if (!self.repHasTagDomain(target_rep)) return null;
        const source_tag_rep = self.tagVariantRepForBoundary(source_rep) orelse return null;
        if (self.tagDomainHasOpenExtension(source_tag_rep) and
            try self.tagDomainDescriptorCanFlowTo(source_tag_rep, target_rep))
        {
            return null;
        }
        const variants = self.parent.plan.tagVariantSlice(self.parent.plan.representations.items[@intFromEnum(source_tag_rep)].tag_variants);
        if (variants.len == 0) return null;
        for (variants) |variant| {
            const source_payloads = self.parent.plan.childSlice(variant.payloads);
            const target_payloads = (try self.dynamicTagPayloadsForRepTagNameOrNull(target_rep, source_tag_rep, variant.name)) orelse return null;
            if (source_payloads.len != target_payloads.len) return null;
        }
        // A row-polymorphic source can carry its active variant in a runtime
        // extension descriptor, so enumerating only the source rep's local
        // variants is not exhaustive. The explicit adapter specializes the
        // target descriptor from the exact source descriptor and materializes
        // every local or extension variant through that descriptor pair.
        return try self.assignPlannedCallBoundary(target, source, target_rep, source_rep, next);
    }

    fn repHasTagDomain(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) bool {
        const tag_rep_id = self.tagDomainRep(rep_id) orelse return false;
        const rep = self.parent.plan.representations.items[@intFromEnum(tag_rep_id)];
        if (rep.tag_variants.len != 0) return true;
        for (self.parent.plan.childSlice(rep.children)) |child| {
            if (child.role != .tag_ext) continue;
            const ext_rep = self.parent.plan.representations.items[@intFromEnum(child.rep)];
            return ext_rep.kind != .empty_tag_union;
        }
        return false;
    }

    fn tagDomainHasLocalVariant(
        self: *const ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        tag_name: names.TagNameId,
    ) bool {
        const tag_rep_id = self.tagDomainRep(rep_id) orelse return false;
        const rep = self.parent.plan.representations.items[@intFromEnum(tag_rep_id)];
        const expected_name = self.module.canonical_names.tagLabelText(tag_name);
        for (self.parent.plan.tagVariantSlice(rep.tag_variants)) |variant| {
            if (std.mem.eql(u8, expected_name, self.tagVariantNameText(variant))) return true;
        }
        return false;
    }

    fn tagDomainRep(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) ?Plan.TypeRepId {
        var current = rep_id;
        var depth: u16 = 0;
        while (true) {
            if (depth == 1024) boxyLowerInvariant("tag domain wrapper chain exceeded boxy lowerer limit");
            depth += 1;

            const rep = self.parent.plan.representations.items[@intFromEnum(current)];
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent, .builtin_other => current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep,
                    .opaque_nominal => return null,
                },
                .tag_union, .dynamic => return current,
                .in_progress, .primitive, .bool_tag_union, .erased_callable, .record, .record_unbound, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .empty_tag_union => return null,
            }
        }
    }

    fn assignConcreteTagVariantToDynamic(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        source_tag_rep: Plan.TypeRepId,
        variant: Plan.TagVariant,
        variant_index: u16,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        try self.bindConstructedTargetDescriptor(target, target_rep);
        const target_desc = try self.constructedTargetDescForRep(target_rep);
        const tag_name = try self.lirTagNameForVariant(variant);
        const source_payloads = self.parent.plan.childSlice(variant.payloads);
        const target_payloads = try self.dynamicTagPayloadsForVariantName(target_rep, variant);
        if (source_payloads.len != target_payloads.len) {
            boxyLowerInvariant("boxy concrete-to-dynamic tag adapter saw payload count mismatch between source and target variants");
        }
        if (target_payloads.len == 0) {
            const assign_tag = try self.parent.result.store.addCFStmt(.{ .assign_boxy_tag = .{
                .target = target,
                .target_desc = target_desc,
                .tag_name = tag_name,
                .next = next,
            } });
            return try self.prependConstructedDescriptorRebindForRep(target_rep, assign_tag);
        }

        const payload = try self.dynamicTagPayloadLocalForChildren(target_payloads);
        const payload_desc = if (payload.desc_rep) |payload_rep| try self.descriptorRefForKnownRep(payload_rep) else null;
        const assign_tag = try self.parent.result.store.addCFStmt(.{ .assign_boxy_tag = .{
            .target = target,
            .target_desc = target_desc,
            .tag_name = tag_name,
            .payload = payload.local,
            .payload_layout = payload.layout_idx,
            .payload_desc = payload_desc,
            .payload_mode = .move,
            .next = next,
        } });
        var continuation = try self.prependConstructedDescriptorRebindForRep(target_rep, assign_tag);
        const source_has_payload_desc = self.parent.plan.representations.items[@intFromEnum(source_tag_rep)].descriptor != null or
            self.parent.result.store.getLocal(source).boxy_desc != null;

        if (target_payloads.len == 1) {
            const source_payload = try self.addExtractedTagPayloadLocal(source_payloads[0].rep, source_has_payload_desc);
            continuation = try self.assignRepresentationBoundary(payload.local, source_payload.local, target_payloads[0].rep, source_payloads[0].rep, continuation);
            return try self.assignConcreteTagPayloadRead(
                source_payload.local,
                source_payloads[0].rep,
                source_payload.desc_local,
                source,
                source_tag_rep,
                variant.name,
                variant_index,
                0,
                source_payloads.len,
                continuation,
            );
        }

        const source_fields = try self.parent.allocator.alloc(ExtractedTagPayloadLocal, source_payloads.len);
        defer self.parent.allocator.free(source_fields);
        const target_fields = try self.parent.allocator.alloc(LIR.LocalId, target_payloads.len);
        defer self.parent.allocator.free(target_fields);
        for (source_payloads, source_fields) |source_payload, *field| {
            field.* = try self.addExtractedTagPayloadLocal(source_payload.rep, source_has_payload_desc);
        }
        for (target_payloads, target_fields) |target_payload, *field| {
            field.* = try self.addFrameLocalForRep(target_payload.rep);
        }

        continuation = try self.parent.result.store.addCFStmt(.{ .assign_struct = .{
            .target = payload.local,
            .fields = try self.parent.result.store.addLocalSpan(target_fields),
            .next = continuation,
        } });
        var payload_index = source_payloads.len;
        while (payload_index > 0) {
            payload_index -= 1;
            continuation = try self.assignRepresentationBoundary(
                target_fields[payload_index],
                source_fields[payload_index].local,
                target_payloads[payload_index].rep,
                source_payloads[payload_index].rep,
                continuation,
            );
            continuation = try self.assignConcreteTagPayloadRead(
                source_fields[payload_index].local,
                source_payloads[payload_index].rep,
                source_fields[payload_index].desc_local,
                source,
                source_tag_rep,
                variant.name,
                variant_index,
                @intCast(payload_index),
                source_payloads.len,
                continuation,
            );
        }
        return continuation;
    }

    fn assignConcreteTagPayloadRead(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        target_rep: Plan.TypeRepId,
        target_desc: ?LIR.LocalId,
        source: LIR.LocalId,
        source_tag_rep: Plan.TypeRepId,
        tag_name: names.TagNameId,
        variant_index: u16,
        payload_index: u32,
        payload_count: usize,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const tag_rep = self.parent.plan.representations.items[@intFromEnum(source_tag_rep)];
        var after_read = next;
        if (target_desc) |desc_local| {
            after_read = try self.recordDescriptorEnvironmentFromDescriptorLocal(
                target,
                self.parent.tagPayloadStorageDescRep(target_rep),
                desc_local,
                after_read,
            );
        }
        if (tag_rep.descriptor != null or target_desc != null) {
            const writable_target_desc = if (target_desc) |desc_local|
                if (self.localIsReadOnlyDescriptorInput(desc_local)) null else desc_local
            else
                null;
            return try self.parent.result.store.addCFStmt(.{ .assign_boxy_tag_payload = .{
                .target = target,
                .target_desc = writable_target_desc,
                .source = source,
                .source_desc = try self.descriptorRefForLocalOrKnownRep(source, source_tag_rep),
                .tag_name = try self.lirTagNameForRep(source_tag_rep, tag_name),
                .payload_index = payload_index,
                .source_mode = .copy,
                .next = after_read,
            } });
        }

        if (self.isZstLocal(target)) return try self.assignZst(target, after_read);
        if (payload_count == 1) {
            return try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
                .target = target,
                .op = .{ .tag_payload_struct = .{
                    .source = source,
                    .variant_index = variant_index,
                    .tag_discriminant = variant_index,
                } },
                .next = after_read,
            } });
        }
        return try self.parent.result.store.addCFStmt(.{ .assign_ref = .{
            .target = target,
            .op = .{ .tag_payload = .{
                .source = source,
                .payload_idx = @intCast(payload_index),
                .variant_index = variant_index,
                .tag_discriminant = variant_index,
            } },
            .next = after_read,
        } });
    }

    fn setLocalReplace(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.isZstLocal(target)) return next;
        if (self.parent.result.store.getLocal(target).layout_idx != self.parent.result.store.getLocal(source).layout_idx) {
            boxyLowerInvariant("boxy reassignment required explicit box/adapt lowering before set_local");
        }
        const write_value = try self.parent.result.store.addCFStmt(.{ .set_local = .{
            .target = target,
            .value = source,
            .mode = .replace_existing,
            .next = next,
        } });
        var transferred = try self.prependSetLocalDescriptorTransfer(target, source, .replace_existing, write_value);
        transferred = try self.prependLocalDescriptorEnvironmentTransfer(target, source, .replace_existing, transferred);
        try self.recordTransferredLocalDescriptorEnvironment(target, source);
        return transferred;
    }

    fn setLocalInitializeJoinParam(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        if (self.parent.result.store.getLocal(target).layout_idx != self.parent.result.store.getLocal(source).layout_idx) {
            boxyLowerInvariant("boxy join parameter initialization required matching layouts");
        }
        const write_value = try self.parent.result.store.addCFStmt(.{ .set_local = .{
            .target = target,
            .value = source,
            .mode = .initialize_join_param,
            .next = next,
        } });
        var transferred = try self.prependSetLocalDescriptorTransfer(target, source, .initialize_join_param, write_value);
        transferred = try self.prependLocalDescriptorEnvironmentTransfer(target, source, .initialize_join_param, transferred);
        try self.recordTransferredLocalDescriptorEnvironment(target, source);
        return transferred;
    }

    fn setLocalInitializeJoinParamFromRep(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        source_rep: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var continuation = try self.setLocalInitializeJoinParam(target, source, next);
        if (self.parent.result.store.getLocal(source).boxy_desc != null) return continuation;
        const target_desc = self.parent.result.store.getLocal(target).boxy_desc orelse return continuation;
        const target_desc_local = target_desc.localOrNull() orelse return continuation;
        const materialization = try self.descriptorMaterializationForSourceStorageLocalRep(source, source_rep);
        continuation = try self.prependDescriptorArgMaterialization(.{
            .local = target_desc_local,
            .materialize = materialization.desc,
            .captures = materialization.captures,
        }, materialization.desc, continuation);
        return continuation;
    }

    fn prependLocalDescriptorEnvironmentTransfer(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        mode: LIR.SetLocalWriteMode,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const target_env = self.localDescriptorEnvironmentForLocal(target) orelse return next;
        const source_env = self.localDescriptorEnvironmentForLocal(source) orelse return next;
        var continuation = next;
        for (target_env.bindings) |target_binding| {
            var source_local: ?LIR.LocalId = null;
            for (source_env.bindings) |source_binding| {
                if (source_binding.desc != target_binding.desc or
                    self.descriptorStorageRep(source_binding.rep) != self.descriptorStorageRep(target_binding.rep))
                {
                    continue;
                }
                if (source_local != null and source_local.? != source_binding.local) {
                    boxyLowerInvariant("boxy local descriptor transfer had multiple source locals for one target binding");
                }
                source_local = source_binding.local;
            }
            const value = source_local orelse
                boxyLowerInvariant("boxy local descriptor transfer source was missing a target binding");
            if (value == target_binding.local) continue;
            if (self.localIsReadOnlyDescriptorInput(target_binding.local)) {
                boxyLowerInvariant("boxy local descriptor transfer targeted a read-only descriptor input");
            }
            continuation = try self.parent.result.store.addCFStmt(.{ .set_local = .{
                .target = target_binding.local,
                .value = value,
                .mode = mode,
                .next = continuation,
            } });
        }
        return continuation;
    }

    fn recordTransferredLocalDescriptorEnvironment(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
    ) Allocator.Error!void {
        const env = self.localDescriptorEnvironmentForLocal(source) orelse return;
        if (self.localDescriptorEnvironmentForLocal(target) != null) return;
        const source_desc_local = if (self.parent.result.store.getLocal(source).boxy_desc) |desc| desc.localOrNull() else null;
        const target_desc_local = if (self.parent.result.store.getLocal(target).boxy_desc) |desc| desc.localOrNull() else null;
        const has_direct_transfer = source_desc_local != null and target_desc_local != null and source_desc_local != target_desc_local;
        if (!has_direct_transfer and self.descriptor_transfer_aliases.items.len == 0) {
            try self.recordLocalDescriptorEnvironment(target, env.rep, env.bindings);
            return;
        }

        const transferred = try self.parent.allocator.alloc(LocalDescriptorEnvironmentBinding, env.bindings.len);
        defer self.parent.allocator.free(transferred);
        for (env.bindings, transferred) |binding, *mapped| {
            mapped.* = binding;
            if (has_direct_transfer and binding.local == source_desc_local.?) mapped.local = target_desc_local.?;
            mapped.local = self.transferredDescriptorAlias(mapped.local);
        }
        try self.recordLocalDescriptorEnvironment(target, env.rep, transferred);
    }

    fn prependSetLocalDescriptorTransfer(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        source: LIR.LocalId,
        mode: LIR.SetLocalWriteMode,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const maybe_source_desc = self.parent.result.store.getLocal(source).boxy_desc;
        const target_desc = self.parent.result.store.getLocal(target).boxy_desc orelse {
            const source_desc = maybe_source_desc orelse return next;
            self.parent.result.store.setLocalBoxyDesc(target, source_desc);
            return next;
        };
        const target_desc_local = target_desc.localOrNull() orelse return next;
        const source_desc = maybe_source_desc orelse return next;
        if (std.meta.eql(target_desc, source_desc)) return next;
        if (self.localIsReadOnlyDescriptorInput(target_desc_local)) return next;
        try self.markDescriptorLocalBound(target_desc_local);
        const source_desc_local = source_desc.localOrNull() orelse {
            const local = try self.addFrameLocal(.opaque_ptr);
            const transfer = try self.parent.result.store.addCFStmt(.{ .set_local = .{
                .target = target_desc_local,
                .value = local,
                .mode = mode,
                .next = next,
            } });
            return try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                .target = local,
                .desc = source_desc,
                .next = transfer,
            } });
        };
        try self.recordDescriptorTransferAlias(source_desc_local, target_desc_local);
        return try self.parent.result.store.addCFStmt(.{ .set_local = .{
            .target = target_desc_local,
            .value = source_desc_local,
            .mode = mode,
            .next = next,
        } });
    }

    fn recordDescriptorTransferAlias(
        self: *ProcBodyBuilder,
        source: LIR.LocalId,
        target: LIR.LocalId,
    ) Allocator.Error!void {
        if (source == target) return;
        for (self.descriptor_transfer_aliases.items) |*alias| {
            if (alias.source != source) continue;
            alias.target = target;
            return;
        }
        try self.descriptor_transfer_aliases.append(self.parent.allocator, .{ .source = source, .target = target });
    }

    fn transferredDescriptorAlias(self: *const ProcBodyBuilder, local: LIR.LocalId) LIR.LocalId {
        var current = local;
        var depth: usize = 0;
        while (depth < self.descriptor_transfer_aliases.items.len) : (depth += 1) {
            var changed = false;
            for (self.descriptor_transfer_aliases.items) |alias| {
                if (alias.source != current) continue;
                current = alias.target;
                changed = true;
                break;
            }
            if (!changed) break;
        }
        return current;
    }

    fn markDescriptorLocalBound(self: *ProcBodyBuilder, local: LIR.LocalId) Allocator.Error!void {
        if (std.mem.findScalar(LIR.LocalId, self.runtime_initialized_descriptor_locals.items, local) == null) {
            try self.runtime_initialized_descriptor_locals.append(self.parent.allocator, local);
        }
        for (self.descriptor_locals, 0..) |maybe_local, index| {
            if (maybe_local == local) self.descriptor_bound[index] = true;
        }
        for (self.descriptor_slots, 0..) |maybe_local, index| {
            if (maybe_local == local) self.descriptor_bound[index] = true;
        }
        for (self.descriptor_rep_bindings.items) |*binding| {
            if (binding.local == local) binding.bound = true;
        }
    }

    fn joinParamSpan(
        self: *ProcBodyBuilder,
        values: []const LIR.LocalId,
    ) Allocator.Error!LIR.LocalSpan {
        var params = std.ArrayList(LIR.LocalId).empty;
        defer params.deinit(self.parent.allocator);
        for (values) |value| {
            try params.append(self.parent.allocator, value);
            if (self.parent.result.store.getLocal(value).boxy_desc) |desc| {
                if (desc.localOrNull()) |desc_local| {
                    if (std.mem.findScalar(LIR.LocalId, params.items, desc_local) == null) {
                        try params.append(self.parent.allocator, desc_local);
                    }
                }
            }
            if (self.localDescriptorEnvironmentForLocal(value)) |env| {
                for (env.bindings) |binding| {
                    if (std.mem.findScalar(LIR.LocalId, params.items, binding.local) == null) {
                        try params.append(self.parent.allocator, binding.local);
                    }
                }
            }
        }
        return try self.parent.result.store.addLocalSpan(params.items);
    }

    fn addArgLocal(self: *ProcBodyBuilder, layout_idx: @import("layout").Idx) Allocator.Error!LIR.LocalId {
        const local = try self.parent.addLocal(layout_idx);
        try self.arg_locals.append(self.parent.allocator, local);
        try self.frame_locals.append(self.parent.allocator, local);
        return local;
    }

    fn addArgLocalForRep(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Allocator.Error!LIR.LocalId {
        const layout_idx = self.workerRuntimeLayoutForRep(rep_id).layoutIdx();
        const initial_desc = if (self.erased_argument_descriptors) null else try self.initialDescriptorRefForRep(rep_id);
        const local = try self.parent.addLocalWithBoxyDesc(layout_idx, initial_desc);
        try self.arg_locals.append(self.parent.allocator, local);
        try self.frame_locals.append(self.parent.allocator, local);
        return local;
    }

    fn addFrameLocal(self: *ProcBodyBuilder, layout_idx: @import("layout").Idx) Allocator.Error!LIR.LocalId {
        const local = try self.parent.addLocal(layout_idx);
        try self.frame_locals.append(self.parent.allocator, local);
        return local;
    }

    fn addFrameLocalForType(self: *ProcBodyBuilder, ty: checked.CheckedTypeId) Allocator.Error!LIR.LocalId {
        const rep_id = self.repForType(ty);
        return try self.addFrameLocalForRep(rep_id);
    }

    fn addFrameLocalForRep(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Allocator.Error!LIR.LocalId {
        const layout_idx = self.workerRuntimeLayoutForRep(rep_id).layoutIdx();
        const identity_rep = self.descriptorStorageRep(rep_id);
        const exact = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        const identity = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
        var desc: ?LIR.BoxyDescRef = null;
        if (exact.descriptor == null and
            (exact.contains_dynamic or identity.contains_dynamic) and
            !self.parent.layoutIsBoxStorage(layout_idx) and
            self.parent.layoutNeedsNestedBoxyDesc(layout_idx))
        {
            desc = .{ .local = try self.addFrameLocal(.opaque_ptr) };
        } else {
            desc = try self.frameDescriptorRefForRep(rep_id);
            if (desc == null and self.repContainsDynamicStorage(rep_id)) {
                desc = try self.parent.staticDescRefForRep(identity_rep);
            }
        }
        const local = try self.addFrameLocal(layout_idx);
        if (desc) |desc_ref| self.parent.result.store.setLocalBoxyDesc(local, desc_ref);
        return local;
    }

    fn addGeneratedParserOutputLocalForRep(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Allocator.Error!LIR.LocalId {
        const layout_idx = self.workerRuntimeLayoutForRep(rep_id).layoutIdx();
        if (!self.parent.layoutNeedsNestedBoxyDesc(layout_idx)) return try self.addFrameLocalForRep(rep_id);
        return try self.addFrameLocalForRepWithRequiredFreshDescriptor(rep_id);
    }

    fn ensureGeneratedParserOutputDescriptorForRep(
        self: *ProcBodyBuilder,
        local: LIR.LocalId,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!void {
        const layout_idx = self.parent.result.store.getLocal(local).layout_idx;
        if (!self.parent.layoutNeedsNestedBoxyDesc(layout_idx)) return;
        if (self.parent.result.store.getLocal(local).boxy_desc) |desc| {
            if (desc.localOrNull()) |desc_local| {
                if (!self.localIsReadOnlyDescriptorInput(desc_local)) return;
            }
        }

        const desc_local = try self.addFrameLocal(.opaque_ptr);
        self.parent.result.store.setLocalBoxyDesc(local, .{ .local = desc_local });
        try self.recordDescriptorLocalTemplate(
            desc_local,
            try self.descriptorMaterializationForExactRep(rep_id),
        );
    }

    fn addFrameLocalForRepWithFreshDescriptor(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Allocator.Error!LIR.LocalId {
        const layout_idx = self.workerRuntimeLayoutForRep(rep_id).layoutIdx();
        const local = try self.addFrameLocal(layout_idx);
        const identity_rep = self.descriptorStorageRep(rep_id);
        const identity = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
        if (identity.descriptor != null or
            (identity.contains_dynamic and self.parent.layoutNeedsNestedBoxyDesc(layout_idx)))
        {
            const desc_local = try self.addFrameLocal(.opaque_ptr);
            self.parent.result.store.setLocalBoxyDesc(local, .{ .local = desc_local });
        } else if (self.repContainsDynamicStorage(rep_id)) {
            self.parent.result.store.setLocalBoxyDesc(local, try self.parent.staticDescRefForRep(identity_rep));
        } else if (try self.descriptorRefForRepIfNeeded(rep_id)) |desc| {
            switch (desc) {
                .static => self.parent.result.store.setLocalBoxyDesc(local, desc),
                .local,
                .runtime,
                .dict_method_arg,
                .dict_method_hidden,
                => self.parent.result.store.setLocalBoxyDesc(local, .{ .local = try self.addFrameLocal(.opaque_ptr) }),
            }
        }
        if (self.parent.result.store.getLocal(local).boxy_desc) |desc| {
            if (desc.localOrNull()) |desc_local| {
                try self.recordDescriptorLocalTemplate(
                    desc_local,
                    try self.descriptorMaterializationForExactRep(rep_id),
                );
            }
        }
        return local;
    }

    fn addFrameLocalForRepWithRequiredFreshDescriptor(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Allocator.Error!LIR.LocalId {
        const local = try self.addFrameLocal(self.workerRuntimeLayoutForRep(rep_id).layoutIdx());
        const desc_local = try self.addFrameLocal(.opaque_ptr);
        self.parent.result.store.setLocalBoxyDesc(local, .{ .local = desc_local });
        try self.recordDescriptorLocalTemplate(
            desc_local,
            try self.descriptorMaterializationForExactRep(rep_id),
        );
        return local;
    }

    fn frameDescriptorRefForRep(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Allocator.Error!?LIR.BoxyDescRef {
        const rep = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        if (rep.descriptor != null) {
            const local = try self.reserveDescriptorLocalForRep(rep_id) orelse
                boxyLowerInvariant("boxy descriptor-bearing frame representation had no descriptor local");
            return .{ .local = local };
        }
        return try self.descriptorRefForRepIfNeeded(rep_id);
    }

    fn initialDescriptorRefForRep(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Allocator.Error!?LIR.BoxyDescRef {
        const identity_rep = self.descriptorStorageRep(rep_id);
        if (self.parent.plan.representations.items[@intFromEnum(identity_rep)].descriptor != null) return null;
        return try self.descriptorRefForRepIfNeeded(rep_id);
    }

    fn addStructuralEqOperandLocalForRep(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Allocator.Error!LIR.LocalId {
        return try self.addFrameLocalForRepWithFreshDescriptor(rep_id);
    }

    fn addFrameBoundaryTargetLocalForRep(self: *ProcBodyBuilder, rep_id: Plan.TypeRepId) Allocator.Error!LIR.LocalId {
        const runtime = self.workerRuntimeLayoutForRep(rep_id);
        const identity_rep = self.descriptorStorageRep(rep_id);
        const exact = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        const identity = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
        const desc: ?LIR.BoxyDescRef = if (self.parent.layoutIsBoxStorage(runtime.layoutIdx()) or
            exact.descriptor != null or identity.descriptor != null or
            ((exact.contains_dynamic or identity.contains_dynamic) and
                self.parent.layoutNeedsNestedBoxyDesc(runtime.layoutIdx())))
            .{ .local = try self.addFrameLocal(.opaque_ptr) }
        else if (self.repContainsDynamicStorage(rep_id))
            try self.parent.staticDescRefForRep(identity_rep)
        else
            null;
        const local = try self.addFrameLocal(runtime.layoutIdx());
        if (desc) |desc_ref| self.parent.result.store.setLocalBoxyDesc(local, desc_ref);
        if (desc) |desc_ref| {
            if (desc_ref.localOrNull()) |desc_local| {
                try self.recordDescriptorLocalTemplate(
                    desc_local,
                    try self.descriptorMaterializationForExactRep(rep_id),
                );
            }
        }
        return local;
    }

    fn addFrameLocalForRuntimeRep(
        self: *ProcBodyBuilder,
        runtime: Layouts.RuntimeLayout,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!LIR.LocalId {
        if (runtime.layoutIdx() == self.workerRuntimeLayoutForRep(rep_id).layoutIdx()) {
            return try self.addFrameLocalForRep(rep_id);
        }
        const desc = try self.frameDescriptorRefForRep(rep_id);
        const local = try self.addFrameLocal(runtime.layoutIdx());
        if (desc) |desc_ref| self.parent.result.store.setLocalBoxyDesc(local, desc_ref);
        return local;
    }

    fn addWorkerReturnLocal(self: *ProcBodyBuilder, fresh_descriptor: bool) Allocator.Error!LIR.LocalId {
        const worker = self.parent.plan.workers.items[@intFromEnum(self.worker_layout.worker)];
        const function = self.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("boxy worker return local requested for a non-function worker");
        // A bound return descriptor is an input template, not mutable storage
        // for the exact descriptor produced by this invocation. The body may
        // refine dynamic positions while constructing its result, so workers
        // that return a runtime descriptor always need an independent
        // descriptor local.
        const local = if (fresh_descriptor)
            try self.addFrameLocalForRepWithFreshDescriptor(function.ret)
        else
            try self.addFrameLocalForRep(function.ret);
        if (fresh_descriptor) {
            if (self.parent.result.store.getLocal(local).boxy_desc) |desc| {
                if (desc.localOrNull()) |desc_local| {
                    const materialization = try self.descriptorMaterializationForExactResultRep(function.ret);
                    if (materialization.desc.localOrNull() == desc_local) {
                        boxyLowerInvariant("boxy worker return descriptor initializer referenced its own target");
                    }
                    try self.worker_return_descriptor_initializers.append(self.parent.allocator, .{
                        .local = desc_local,
                        .materialize = materialization.desc,
                        .captures = materialization.captures,
                    });
                    try appendUniqueLocal(
                        self.parent.allocator,
                        &self.runtime_initialized_descriptor_locals,
                        desc_local,
                    );
                }
            }
        }
        if (self.parent.result.store.getLocal(local).layout_idx != self.workerReturnLayout()) {
            boxyLowerInvariant("boxy worker return representation layout disagreed with worker layout plan");
        }
        return local;
    }

    fn markLocalDescriptorForType(self: *ProcBodyBuilder, local: LIR.LocalId, ty: checked.CheckedTypeId) Allocator.Error!void {
        const rep_id = self.repForType(ty);
        try self.markLocalDescriptorForRep(local, rep_id);
    }

    fn markLocalDescriptorForRep(self: *ProcBodyBuilder, local: LIR.LocalId, rep_id: Plan.TypeRepId) Allocator.Error!void {
        if (self.parent.result.store.getLocal(local).boxy_desc != null) return;
        const desc_ref = try self.descriptorRefForRepIfNeeded(rep_id);
        if (desc_ref) |desc| {
            self.parent.result.store.setLocalBoxyDesc(local, desc);
        }
    }

    fn mutableDescriptorLocalForValue(self: *ProcBodyBuilder, value: LIR.LocalId) Allocator.Error!LIR.LocalId {
        if (self.parent.result.store.getLocal(value).boxy_desc) |desc| {
            return desc.localOrNull() orelse
                boxyLowerInvariant("boxy runtime descriptor initialization targeted a statically described value");
        }
        const local = try self.addFrameLocal(.opaque_ptr);
        self.parent.result.store.setLocalBoxyDesc(value, .{ .local = local });
        return local;
    }

    fn ensureTagPayloadTargetDescriptorLocal(
        self: *ProcBodyBuilder,
        target: LIR.LocalId,
        payload_rep: Plan.TypeRepId,
    ) Allocator.Error!?LIR.LocalId {
        if (!self.parent.repNeedsTagPayloadDesc(payload_rep)) return null;
        return try self.mutableDescriptorLocalForValue(target);
    }

    fn ensureBinderLocals(self: *ProcBodyBuilder) Allocator.Error!void {
        if (self.binder_locals.len != 0) return;
        self.binder_locals = try self.parent.allocator.alloc(?LIR.LocalId, self.module.checked_bodies.patternBinderCount());
        errdefer self.parent.allocator.free(self.binder_locals);
        self.binder_reps = try self.parent.allocator.alloc(?Plan.TypeRepId, self.module.checked_bodies.patternBinderCount());
        @memset(self.binder_locals, null);
        @memset(self.binder_reps, null);
    }

    fn ensureDescriptorLocals(self: *ProcBodyBuilder) Allocator.Error!void {
        if (self.descriptor_locals.len != 0) return;
        self.descriptor_locals = try self.parent.allocator.alloc(?LIR.LocalId, self.parent.plan.descriptors.items.len);
        errdefer self.parent.allocator.free(self.descriptor_locals);
        self.descriptor_local_reps = try self.parent.allocator.alloc(?Plan.TypeRepId, self.parent.plan.descriptors.items.len);
        errdefer self.parent.allocator.free(self.descriptor_local_reps);
        self.descriptor_bound = try self.parent.allocator.alloc(bool, self.parent.plan.descriptors.items.len);
        errdefer self.parent.allocator.free(self.descriptor_bound);
        self.descriptor_slots = try self.parent.allocator.alloc(?LIR.LocalId, self.parent.plan.descriptors.items.len);
        errdefer self.parent.allocator.free(self.descriptor_slots);
        self.descriptor_slot_reps = try self.parent.allocator.alloc(?Plan.TypeRepId, self.parent.plan.descriptors.items.len);
        @memset(self.descriptor_locals, null);
        @memset(self.descriptor_local_reps, null);
        @memset(self.descriptor_bound, false);
        @memset(self.descriptor_slots, null);
        @memset(self.descriptor_slot_reps, null);
    }

    fn ensureDictionaryLocals(self: *ProcBodyBuilder) Allocator.Error!void {
        if (self.dictionary_locals.len != 0) return;
        self.dictionary_locals = try self.parent.allocator.alloc(?LIR.LocalId, self.parent.plan.dictionaries.items.len);
        errdefer self.parent.allocator.free(self.dictionary_locals);
        self.dictionary_bound = try self.parent.allocator.alloc(bool, self.parent.plan.dictionaries.items.len);
        errdefer self.parent.allocator.free(self.dictionary_bound);
        self.dictionary_slots = try self.parent.allocator.alloc(?LIR.LocalId, self.parent.plan.dictionaries.items.len);
        @memset(self.dictionary_locals, null);
        @memset(self.dictionary_bound, false);
        @memset(self.dictionary_slots, null);
    }

    fn descriptorRepBindingIndex(
        self: *const ProcBodyBuilder,
        desc: Plan.DescriptorRequirementId,
        identity_rep: Plan.TypeRepId,
    ) ?usize {
        for (self.descriptor_rep_bindings.items, 0..) |binding, index| {
            if (binding.desc == desc and binding.rep == identity_rep) return index;
        }
        return null;
    }

    fn descriptorLocalForRequirementAndRepOrNull(
        self: *ProcBodyBuilder,
        desc: Plan.DescriptorRequirementId,
        rep_id: Plan.TypeRepId,
    ) ?LIR.LocalId {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const desc_index = @intFromEnum(desc);
        if (desc_index < self.descriptor_locals.len) {
            if (self.descriptor_locals[desc_index]) |local| {
                if (desc_index >= self.descriptor_local_reps.len) {
                    boxyLowerInvariant("boxy descriptor local representation table was missing an entry");
                }
                const local_rep = self.descriptor_local_reps[desc_index] orelse
                    boxyLowerInvariant("boxy descriptor local had no representation binding");
                if (local_rep == identity_rep) return local;
            }
        }

        if (self.descriptorRepBindingIndex(desc, identity_rep)) |index| {
            return self.descriptor_rep_bindings.items[index].local;
        }
        return null;
    }

    fn descriptorLocalForRepOrNull(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) ?LIR.LocalId {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const rep = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
        const desc = rep.descriptor orelse return null;
        return self.descriptorLocalForRequirementAndRepOrNull(desc, identity_rep);
    }

    fn descriptorBindingIsBoundForRep(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) bool {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const rep = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
        const desc = rep.descriptor orelse return true;
        const desc_index = @intFromEnum(desc);
        if (desc_index < self.descriptor_bound.len and self.descriptor_bound[desc_index]) {
            if (desc_index >= self.descriptor_local_reps.len) return false;
            if (self.descriptor_local_reps[desc_index] == identity_rep) return true;
        }
        for (self.descriptor_rep_bindings.items) |binding| {
            if (binding.desc == desc and binding.rep == identity_rep) return binding.bound;
        }
        return false;
    }

    fn dictionaryLocalForRequirementOrNull(
        self: *const ProcBodyBuilder,
        dict: Plan.DictionaryRequirementId,
    ) ?LIR.LocalId {
        const dict_index = @intFromEnum(dict);
        if (dict_index >= self.dictionary_locals.len) return null;
        return self.dictionary_locals[dict_index];
    }

    fn dictionaryBindingIsBound(self: *const ProcBodyBuilder, dict: Plan.DictionaryRequirementId) bool {
        const dict_index = @intFromEnum(dict);
        if (dict_index >= self.dictionary_bound.len) return false;
        return self.dictionary_bound[dict_index];
    }

    fn snapshotDescriptorBindings(self: *ProcBodyBuilder) Allocator.Error!DescriptorBindingsSnapshot {
        try self.ensureDescriptorLocals();
        const locals = try self.parent.allocator.dupe(?LIR.LocalId, self.descriptor_locals);
        errdefer self.parent.allocator.free(locals);
        const local_reps = try self.parent.allocator.dupe(?Plan.TypeRepId, self.descriptor_local_reps);
        errdefer self.parent.allocator.free(local_reps);
        const bound = try self.parent.allocator.dupe(bool, self.descriptor_bound);
        errdefer self.parent.allocator.free(bound);
        const slots = try self.parent.allocator.dupe(?LIR.LocalId, self.descriptor_slots);
        errdefer self.parent.allocator.free(slots);
        const slot_reps = try self.parent.allocator.dupe(?Plan.TypeRepId, self.descriptor_slot_reps);
        errdefer self.parent.allocator.free(slot_reps);
        const rep_bindings = try self.parent.allocator.dupe(DescriptorRepBinding, self.descriptor_rep_bindings.items);
        return .{
            .locals = locals,
            .local_reps = local_reps,
            .bound = bound,
            .slots = slots,
            .slot_reps = slot_reps,
            .rep_bindings = rep_bindings,
            .runtime_initialized_len = self.runtime_initialized_descriptor_locals.items.len,
        };
    }

    fn restoreDescriptorBindings(self: *ProcBodyBuilder, snapshot: DescriptorBindingsSnapshot) void {
        if (snapshot.locals.len != self.descriptor_locals.len or
            snapshot.local_reps.len != self.descriptor_local_reps.len or
            snapshot.bound.len != self.descriptor_bound.len or
            snapshot.slots.len != self.descriptor_slots.len or
            snapshot.slot_reps.len != self.descriptor_slot_reps.len)
        {
            boxyLowerInvariant("boxy descriptor binding snapshot length disagreed with active descriptor table");
        }
        @memcpy(self.descriptor_locals, snapshot.locals);
        @memcpy(self.descriptor_local_reps, snapshot.local_reps);
        @memcpy(self.descriptor_bound, snapshot.bound);
        @memcpy(self.descriptor_slots, snapshot.slots);
        @memcpy(self.descriptor_slot_reps, snapshot.slot_reps);
        self.descriptor_rep_bindings.items.len = snapshot.rep_bindings.len;
        @memcpy(self.descriptor_rep_bindings.items, snapshot.rep_bindings);
        self.runtime_initialized_descriptor_locals.items.len = snapshot.runtime_initialized_len;
    }

    fn reserveDescriptorLocalForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!?LIR.LocalId {
        const reservation = try self.reserveDescriptorLocalForRepWithFresh(rep_id);
        return if (reservation) |reserved| reserved.local else null;
    }

    fn reserveDescriptorLocalForRepWithFresh(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!?DescriptorLocalReservation {
        const rep = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        if (rep.descriptor) |desc| {
            try self.ensureDescriptorLocals();
            if (self.descriptorLocalForRequirementAndRepOrNull(desc, rep_id)) |local| {
                return .{ .local = local, .fresh = false };
            }
        }
        const reservation = try self.reserveDescriptorSlotForRepWithFresh(rep_id);
        if (reservation) |reserved| {
            const desc = rep.descriptor orelse unreachable;
            try self.setDescriptorRequirementLocalForRep(desc, rep_id, reserved.local);
        }
        return reservation;
    }

    fn reserveRuntimeDescriptorLocalForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!?LIR.LocalId {
        const reservation = try self.reserveDescriptorLocalForRepWithFresh(rep_id);
        if (reservation) |reserved| {
            const rep = self.parent.plan.representations.items[@intFromEnum(rep_id)];
            const desc = rep.descriptor orelse unreachable;
            if (!reserved.fresh and self.localIsReadOnlyDescriptorInput(reserved.local)) {
                const desc_index = @intFromEnum(desc);
                const identity_rep = self.descriptorStorageRep(rep_id);
                const local = try self.addFrameLocal(.opaque_ptr);
                self.descriptor_slots[desc_index] = local;
                self.descriptor_slot_reps[desc_index] = identity_rep;
                try self.setDescriptorRequirementLocalForRep(desc, identity_rep, local);
                self.markDescriptorRequirementBoundForRep(desc, identity_rep);
                return local;
            }
            self.markDescriptorRequirementBoundForRep(desc, rep_id);
            return reserved.local;
        }
        return null;
    }

    fn reserveDescriptorSlotForRepWithFresh(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
    ) Allocator.Error!?DescriptorLocalReservation {
        const rep = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        const desc = rep.descriptor orelse return null;
        try self.ensureDescriptorLocals();
        const desc_index = @intFromEnum(desc);
        if (desc_index >= self.descriptor_slots.len or desc_index >= self.descriptor_slot_reps.len) {
            boxyLowerInvariant("boxy descriptor requirement index exceeded descriptor local table");
        }
        const identity_rep = self.descriptorStorageRep(rep_id);
        if (self.descriptor_slots[desc_index]) |existing| {
            const slot_rep = self.descriptor_slot_reps[desc_index] orelse
                boxyLowerInvariant("boxy descriptor slot had no representation binding");
            if (slot_rep == identity_rep) return .{ .local = existing, .fresh = false };
        }
        const local = try self.addFrameLocal(.opaque_ptr);
        self.descriptor_slots[desc_index] = local;
        self.descriptor_slot_reps[desc_index] = identity_rep;
        return .{ .local = local, .fresh = true };
    }

    fn reserveDictionarySlotForSpan(
        self: *ProcBodyBuilder,
        span: Plan.Span,
    ) Allocator.Error!?LIR.LocalId {
        const reservation = try self.reserveDictionarySlotForSpanWithFresh(span);
        return if (reservation) |reserved| reserved.local else null;
    }

    fn reserveDictionarySlotForSpanWithFresh(
        self: *ProcBodyBuilder,
        span: Plan.Span,
    ) Allocator.Error!?DescriptorLocalReservation {
        if (span.len == 0) return null;
        try self.ensureDictionaryLocals();
        const dict_index: usize = @intCast(span.start);
        if (dict_index >= self.dictionary_slots.len) {
            boxyLowerInvariant("boxy dictionary requirement index exceeded dictionary local table");
        }
        if (self.dictionary_slots[dict_index]) |existing| return .{ .local = existing, .fresh = false };
        const local = try self.addFrameLocal(.opaque_ptr);
        var offset: u32 = 0;
        while (offset < span.len) : (offset += 1) {
            const index: usize = @intCast(span.start + offset);
            self.dictionary_slots[index] = local;
        }
        return .{ .local = local, .fresh = true };
    }

    fn reserveDescriptorLocalForType(
        self: *ProcBodyBuilder,
        ty: checked.CheckedTypeId,
    ) Allocator.Error!?LIR.LocalId {
        return try self.reserveDescriptorLocalForRep(self.repForType(ty));
    }

    fn reserveRuntimeDescriptorLocalForType(
        self: *ProcBodyBuilder,
        ty: checked.CheckedTypeId,
    ) Allocator.Error!?LIR.LocalId {
        return try self.reserveRuntimeDescriptorLocalForRep(self.repForType(ty));
    }

    fn bindRuntimeDescriptorLocalForValueType(
        self: *ProcBodyBuilder,
        value: LIR.LocalId,
        ty: checked.CheckedTypeId,
    ) Allocator.Error!?LIR.LocalId {
        if (self.parent.result.store.getLocal(value).boxy_desc) |value_desc| {
            if (value_desc.localOrNull()) |desc_local| {
                return desc_local;
            }
        }

        const layout_idx = self.parent.result.store.getLocal(value).layout_idx;
        const descriptor_sensitive_storage = self.parent.layoutIsBoxStorage(layout_idx);
        if (!descriptor_sensitive_storage) return null;

        const desc_local = try self.reserveRuntimeDescriptorLocalForType(ty) orelse
            try self.addFrameLocal(.opaque_ptr);
        self.parent.result.store.setLocalBoxyDesc(value, .{ .local = desc_local });
        return desc_local;
    }

    fn prependConstructedDescriptorRebindForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        const rep = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        const desc = rep.descriptor orelse return next;
        const local = self.descriptorLocalForRequirementAndRepOrNull(desc, rep_id) orelse return next;
        if (self.localIsReadOnlyDescriptorInput(local)) return next;
        if (std.mem.findScalar(LIR.LocalId, self.runtime_initialized_descriptor_locals.items, local) != null) return next;
        if (self.descriptorBindingIsBoundForRep(rep_id)) return next;
        const materialization = try self.descriptorMaterializationForKnownRep(rep_id);
        if (materialization.captures.len == 0) return next;
        return try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
            .target = local,
            .desc = materialization.desc,
            .captures = materialization.captures,
            .next = next,
        } });
    }

    fn prependStaticDescriptorMaterializationsForSlots(
        self: *ProcBodyBuilder,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        return try self.prependStaticDescriptorMaterializationsForScopedSlots(null, next);
    }

    fn prependStaticDescriptorMaterializationsForSlotsWithSources(
        self: *ProcBodyBuilder,
        sources: *const StaticDescriptorSourceMap,
        context: *StaticDescInstantiationContext,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var continuation = next;
        if (self.descriptor_slots.len == 0) return continuation;

        var index = self.descriptor_slots.len;
        while (index > 0) {
            index -= 1;
            const local = self.descriptor_slots[index] orelse continue;
            const slot_rep = self.descriptor_slot_reps[index] orelse
                boxyLowerInvariant("boxy descriptor slot materialization had no representation binding");
            if (std.mem.findScalar(LIR.LocalId, self.runtime_initialized_descriptor_locals.items, local) != null) continue;
            if (self.descriptorBindingIsBoundForRep(slot_rep)) continue;
            if (self.localIsReadOnlyDescriptorInput(local)) continue;
            continuation = try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                .target = local,
                .desc = try self.parent.staticDescRefForWorkerRepWithSourceMap(
                    slot_rep,
                    null,
                    sources,
                    context,
                ),
                .next = continuation,
            } });
        }
        return continuation;
    }

    fn prependStaticDescriptorMaterializationsForScopedSlots(
        self: *ProcBodyBuilder,
        outer: ?*const DescriptorBindingsSnapshot,
        next: LIR.CFStmtId,
    ) Allocator.Error!LIR.CFStmtId {
        var continuation = next;
        if (self.descriptor_slots.len == 0) return continuation;

        var index = self.descriptor_slots.len;
        while (index > 0) {
            index -= 1;
            const local = self.descriptor_slots[index] orelse continue;
            const slot_rep = self.descriptor_slot_reps[index] orelse
                boxyLowerInvariant("boxy descriptor slot materialization had no representation binding");
            if (outer) |snapshot| {
                if (snapshot.slots[index] == local and snapshot.slot_reps[index] == slot_rep) continue;
            }
            if (std.mem.findScalar(LIR.LocalId, self.runtime_initialized_descriptor_locals.items, local) != null) continue;
            if (self.descriptorBindingIsBoundForRep(slot_rep)) continue;
            if (self.localIsReadOnlyDescriptorInput(local)) continue;
            const materialization = try self.descriptorMaterializationForKnownRep(slot_rep);
            continuation = try self.parent.result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
                .target = local,
                .desc = materialization.desc,
                .captures = materialization.captures,
                .next = continuation,
            } });
        }
        return continuation;
    }

    fn markReadOnlyDescriptorInput(self: *ProcBodyBuilder, local: LIR.LocalId) Allocator.Error!void {
        try appendUniqueLocal(self.parent.allocator, &self.read_only_descriptor_inputs, local);
    }

    fn localIsReadOnlyDescriptorInput(self: *const ProcBodyBuilder, local: LIR.LocalId) bool {
        for (self.read_only_descriptor_inputs.items) |input| {
            if (input == local) return true;
        }
        return false;
    }

    fn localIsDescriptorSlot(self: *const ProcBodyBuilder, local: LIR.LocalId) bool {
        for (self.descriptor_slots) |maybe_local| {
            if (maybe_local == local) return true;
        }
        return false;
    }

    fn descriptorSourceRep(
        self: *const ProcBodyBuilder,
        source: ResultDescriptorSource,
        planned_rep: Plan.TypeRepId,
    ) Plan.TypeRepId {
        const desc = source.desc orelse return planned_rep;
        const local = desc.localOrNull() orelse return planned_rep;
        var source_rep: ?Plan.TypeRepId = null;
        for (self.descriptor_slots, self.descriptor_slot_reps) |maybe_slot, maybe_rep| {
            if (maybe_slot != local) continue;
            const rep = maybe_rep orelse
                boxyLowerInvariant("boxy descriptor slot had no representation binding");
            if (source_rep) |existing| {
                if (existing != rep) {
                    boxyLowerInvariant("boxy descriptor local had conflicting exact representation bindings");
                }
            } else {
                source_rep = rep;
            }
        }
        return source_rep orelse planned_rep;
    }

    fn reservePatternBindings(self: *ProcBodyBuilder, pattern_id: checked.CheckedPatternId) Allocator.Error!void {
        try self.ensureBinderLocals();
        const pattern = self.module.checked_bodies.pattern(pattern_id);
        switch (pattern.data) {
            .assign => |binder| {
                try self.reserveBinderLocal(binder, pattern.ty);
                _ = try self.reserveDescriptorLocalForType(pattern.ty);
            },
            .as => |as| {
                try self.reserveBinderLocal(as.binder, pattern.ty);
                _ = try self.reserveDescriptorLocalForType(pattern.ty);
                try self.reservePatternBindings(as.pattern);
            },
            .tuple => |items| for (items) |item| try self.reservePatternBindings(item),
            .record_destructure => |destructs| {
                for (destructs) |destruct| {
                    switch (destruct.kind) {
                        .required,
                        .sub_pattern,
                        .rest,
                        => |child| try self.reservePatternBindings(child),
                    }
                }
            },
            .nominal => |nominal| try self.reservePatternBindings(nominal.backing_pattern),
            .applied_tag => |tag| for (tag.args) |arg| try self.reservePatternBindings(arg),
            .list => |list| {
                for (list.patterns) |child| try self.reservePatternBindings(child);
                if (list.rest) |rest| {
                    if (rest.pattern) |rest_pattern| try self.reservePatternBindings(rest_pattern);
                }
            },
            .str_interpolation => |str| {
                for (str.steps) |step| {
                    if (step.capture) |capture| try self.reservePatternBindings(capture);
                }
            },
            .underscore,
            .numeral_literal,
            .str_literal,
            => {},
            .runtime_error,
            .pending,
            => boxyLowerInvariant("refutable or pending checked pattern reached boxy irrefutable binder reservation"),
        }
    }

    fn requireIrrefutableTagPattern(
        self: *ProcBodyBuilder,
        ty: checked.CheckedTypeId,
        name: names.TagNameId,
        args: []const checked.CheckedPatternId,
    ) Allocator.Error!void {
        var current = self.repForType(ty);
        while (true) {
            const rep = self.parent.plan.representations.items[@intFromEnum(current)];
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent => current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep,
                    .opaque_nominal, .builtin_other => boxyLowerInvariant("irrefutable tag pattern had an opaque nominal representation"),
                },
                .tag_union => {
                    const variants = self.parent.plan.tagVariantSlice(rep.tag_variants);
                    if (variants.len != 1) {
                        boxyLowerInvariant("refutable tag pattern reached boxy irrefutable binder lowering");
                    }
                    const variant = self.tagVariant(rep, name);
                    if (variant.index != 0) {
                        boxyLowerInvariant("single-variant tag pattern had a nonzero variant index");
                    }
                    return try self.validateTagPatternPayloads(variant.name, variant.payloads, args);
                },
                .in_progress, .dynamic, .primitive, .bool_tag_union, .erased_callable, .record, .record_unbound, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .empty_tag_union => boxyLowerInvariant("irrefutable tag pattern did not have a tag-union representation"),
            }
        }
    }

    fn reserveMatchPatternBindings(self: *ProcBodyBuilder, pattern_id: checked.CheckedPatternId) Allocator.Error!void {
        try self.ensureBinderLocals();
        const pattern = self.module.checked_bodies.pattern(pattern_id);
        switch (pattern.data) {
            .assign => |binder| {
                try self.reserveMatchBinderLocal(binder, pattern.ty);
            },
            .as => |as| {
                try self.reserveMatchBinderLocal(as.binder, pattern.ty);
                try self.reserveMatchPatternBindings(as.pattern);
            },
            .applied_tag => |tag| for (tag.args) |arg| try self.reserveMatchPatternBindings(arg),
            .tuple => |items| for (items) |item| try self.reserveMatchPatternBindings(item),
            .record_destructure => |destructs| {
                for (destructs) |destruct| {
                    switch (destruct.kind) {
                        .required,
                        .sub_pattern,
                        .rest,
                        => |child| try self.reserveMatchPatternBindings(child),
                    }
                }
            },
            .nominal => |nominal| try self.reserveMatchPatternBindings(nominal.backing_pattern),
            .list => |list| {
                for (list.patterns) |child| try self.reserveMatchPatternBindings(child);
                if (list.rest) |rest| {
                    if (rest.pattern) |rest_pattern| try self.reserveMatchPatternBindings(rest_pattern);
                }
            },
            .str_interpolation => |str| {
                for (str.steps) |step| {
                    if (step.capture) |capture| try self.reserveMatchPatternBindings(capture);
                }
            },
            .underscore,
            .numeral_literal,
            .str_literal,
            => {},
            .runtime_error,
            .pending,
            => boxyLowerInvariant("runtime-error or pending checked pattern reached boxy match binder reservation"),
        }
    }

    fn reserveMatchPatternBindingsFromRep(
        self: *ProcBodyBuilder,
        pattern_id: checked.CheckedPatternId,
        source_rep: Plan.TypeRepId,
    ) Allocator.Error!void {
        try self.ensureBinderLocals();
        const pattern = self.module.checked_bodies.pattern(pattern_id);
        const pattern_rep = self.repForType(pattern.ty);
        if (pattern_rep == source_rep or
            self.workerRuntimeLayoutForRep(pattern_rep).layoutIdx() == self.workerRuntimeLayoutForRep(source_rep).layoutIdx())
        {
            return try self.reserveMatchPatternBindings(pattern_id);
        }

        switch (pattern.data) {
            .assign => |binder| try self.reserveMatchBinderLocalForRep(binder, source_rep),
            .as => |as| {
                try self.reserveMatchBinderLocalForRep(as.binder, source_rep);
                try self.reserveMatchPatternBindingsFromRep(as.pattern, source_rep);
            },
            .applied_tag => |tag| {
                const tag_rep = self.tagVariantRepForBoundary(source_rep) orelse
                    boxyLowerInvariant("boxy tag pattern binder source had no tag representation");
                const rep = self.parent.plan.representations.items[@intFromEnum(tag_rep)];
                const payloads = switch (rep.kind) {
                    .dynamic => try self.dynamicTagPayloadsForName(tag_rep, tag.name),
                    .tag_union => self.parent.plan.childSlice(self.tagVariant(rep, tag.name).payloads),
                    .in_progress, .primitive, .bool_tag_union, .erased_callable, .alias, .record, .record_unbound, .tuple, .nominal, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .empty_tag_union => boxyLowerInvariant("boxy tag pattern binder source was not a tag representation"),
                };
                if (payloads.len != tag.args.len) {
                    boxyLowerInvariant("boxy tag pattern binder payload count disagreed with its source representation");
                }
                for (tag.args, payloads) |arg, payload| {
                    try self.reserveMatchPatternBindingsFromRep(arg, payload.rep);
                }
            },
            .underscore,
            .numeral_literal,
            .str_literal,
            => {},
            .pending, .nominal, .record_destructure, .list, .tuple, .str_interpolation, .runtime_error => try self.reserveMatchPatternBindings(pattern_id),
        }
    }

    fn reserveMatchPatternDescriptors(
        self: *ProcBodyBuilder,
        pattern_id: checked.CheckedPatternId,
        remaps: []const checked.CheckedAlternativeBinderRemap,
    ) Allocator.Error!void {
        const pattern = self.module.checked_bodies.pattern(pattern_id);
        switch (pattern.data) {
            .assign => |binder| {
                const representative = self.matchBinderRepresentative(binder, remaps);
                _ = try self.bindRuntimeDescriptorLocalForValueType(
                    self.localForBinder(representative),
                    self.binderType(representative),
                );
            },
            .as => |as| {
                const representative = self.matchBinderRepresentative(as.binder, remaps);
                _ = try self.bindRuntimeDescriptorLocalForValueType(
                    self.localForBinder(representative),
                    self.binderType(representative),
                );
                try self.reserveMatchPatternDescriptors(as.pattern, remaps);
            },
            .applied_tag => |tag| for (tag.args) |arg| try self.reserveMatchPatternDescriptors(arg, remaps),
            .tuple => |items| for (items) |item| try self.reserveMatchPatternDescriptors(item, remaps),
            .record_destructure => |destructs| {
                for (destructs) |destruct| {
                    switch (destruct.kind) {
                        .required,
                        .sub_pattern,
                        .rest,
                        => |child| try self.reserveMatchPatternDescriptors(child, remaps),
                    }
                }
            },
            .nominal => |nominal| try self.reserveMatchPatternDescriptors(nominal.backing_pattern, remaps),
            .list => |list| {
                for (list.patterns) |child| try self.reserveMatchPatternDescriptors(child, remaps);
                if (list.rest) |rest| {
                    if (rest.pattern) |rest_pattern| try self.reserveMatchPatternDescriptors(rest_pattern, remaps);
                }
            },
            .str_interpolation => |str| {
                for (str.steps) |step| {
                    if (step.capture) |capture| try self.reserveMatchPatternDescriptors(capture, remaps);
                }
            },
            .underscore,
            .numeral_literal,
            .str_literal,
            => {},
            .runtime_error,
            .pending,
            => boxyLowerInvariant("runtime-error or pending checked pattern reached boxy match descriptor reservation"),
        }
    }

    fn patternCanMiss(self: *ProcBodyBuilder, pattern_id: checked.CheckedPatternId) Allocator.Error!bool {
        const pattern = self.module.checked_bodies.pattern(pattern_id);
        return switch (pattern.data) {
            .assign,
            .underscore,
            => false,
            .as => |as| try self.patternCanMiss(as.pattern),
            .tuple => |items| blk: {
                for (items) |item| {
                    if (try self.patternCanMiss(item)) break :blk true;
                }
                break :blk false;
            },
            .record_destructure => |destructs| blk: {
                for (destructs) |destruct| {
                    const child = switch (destruct.kind) {
                        .required,
                        .sub_pattern,
                        .rest,
                        => |child| child,
                    };
                    if (try self.patternCanMiss(child)) break :blk true;
                }
                break :blk false;
            },
            .nominal => |nominal| try self.patternCanMiss(nominal.backing_pattern),
            .applied_tag => |tag| try self.appliedTagPatternCanMiss(pattern.ty, tag.name, tag.args),
            .list,
            .str_interpolation,
            .numeral_literal,
            .str_literal,
            => true,
            .runtime_error,
            .pending,
            => boxyLowerInvariant("runtime-error or pending checked pattern reached boxy match miss analysis"),
        };
    }

    fn patternIsIgnored(self: *ProcBodyBuilder, pattern_id: checked.CheckedPatternId) bool {
        return switch (self.module.checked_bodies.pattern(pattern_id).data) {
            .underscore => true,
            .pending, .assign, .as, .applied_tag, .nominal, .record_destructure, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .runtime_error => false,
        };
    }

    fn appliedTagPatternCanMiss(
        self: *ProcBodyBuilder,
        tag_ty: checked.CheckedTypeId,
        name: names.TagNameId,
        args: []const checked.CheckedPatternId,
    ) Allocator.Error!bool {
        var payload_can_miss = false;
        for (args) |arg| {
            if (try self.patternCanMiss(arg)) {
                payload_can_miss = true;
                break;
            }
        }

        const rep_id = self.repForType(tag_ty);
        return self.appliedTagPatternRepCanMiss(tag_ty, rep_id, name, args, payload_can_miss);
    }

    fn appliedTagPatternRepCanMiss(
        self: *ProcBodyBuilder,
        tag_ty: checked.CheckedTypeId,
        rep_id: Plan.TypeRepId,
        name: names.TagNameId,
        args: []const checked.CheckedPatternId,
        payload_can_miss: bool,
    ) Allocator.Error!bool {
        const rep = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        return switch (rep.kind) {
            .bool_tag_union => blk: {
                if (args.len != 0) {
                    boxyLowerInvariant("builtin Bool match pattern carried a payload during miss analysis");
                }
                _ = self.boolVariantIndex(name);
                break :blk true;
            },
            .tag_union => blk: {
                const variants = self.parent.plan.tagVariantSlice(rep.tag_variants);
                const variant = self.tagVariant(rep, name);
                const payloads = self.parent.plan.childSlice(variant.payloads);
                if (payloads.len != args.len) {
                    boxyLowerInvariant("tag match pattern payload count disagreed during miss analysis");
                }
                break :blk variants.len > 1 or payload_can_miss;
            },
            .dynamic => blk: {
                const payloads = try self.dynamicTagPayloadsForName(rep_id, name);
                if (payloads.len != args.len) {
                    boxyLowerInvariant("dynamic tag match pattern payload count disagreed during miss analysis");
                }
                break :blk true;
            },
            .alias => return try self.appliedTagPatternRepCanMiss(
                tag_ty,
                self.repQuery().requiredSingleChild(rep_id, .alias_backing).rep,
                name,
                args,
                payload_can_miss,
            ),
            .nominal => |kind| switch (kind) {
                .transparent, .builtin_other => {
                    const backing_ty = resolvedNominalBacking(self.module, tag_ty);
                    const backing_rep = self.repQuery().requiredSingleChild(rep_id, .nominal_backing).rep;
                    return try self.appliedTagPatternRepCanMiss(backing_ty, backing_rep, name, args, payload_can_miss);
                },
                .opaque_nominal => boxyLowerInvariant("opaque nominal tag match pattern reached boxy miss analysis"),
            },
            .empty_tag_union => boxyLowerInvariant("empty tag-union match pattern reached boxy miss analysis"),
            .in_progress, .primitive, .erased_callable, .record, .record_unbound, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record => boxyLowerInvariant("tag match pattern checked type did not have a boxy tag-union representation during miss analysis"),
        };
    }

    fn reserveReassignPatternBindings(self: *ProcBodyBuilder, pattern_id: checked.CheckedPatternId) Allocator.Error!void {
        try self.ensureBinderLocals();
        const pattern = self.module.checked_bodies.pattern(pattern_id);
        switch (pattern.data) {
            .assign => |binder| {
                try self.reserveBinderLocalIfFresh(binder, pattern.ty);
                _ = try self.reserveDescriptorLocalForType(pattern.ty);
            },
            .as => |as| {
                try self.reserveBinderLocalIfFresh(as.binder, pattern.ty);
                _ = try self.reserveDescriptorLocalForType(pattern.ty);
                try self.reserveReassignPatternBindings(as.pattern);
            },
            .tuple => |items| for (items) |item| try self.reserveReassignPatternBindings(item),
            .record_destructure => |destructs| {
                for (destructs) |destruct| {
                    switch (destruct.kind) {
                        .required,
                        .sub_pattern,
                        .rest,
                        => |child| try self.reserveReassignPatternBindings(child),
                    }
                }
            },
            .nominal => |nominal| try self.reserveReassignPatternBindings(nominal.backing_pattern),
            .list => |list| {
                if (list.patterns.len != 0) {
                    boxyLowerInvariant("refutable list pattern reached boxy reassign binder reservation");
                }
                if (list.rest) |rest| {
                    if (rest.pattern) |rest_pattern| try self.reserveReassignPatternBindings(rest_pattern);
                }
            },
            .underscore,
            .numeral_literal,
            .str_literal,
            .str_interpolation,
            => {},
            .applied_tag,
            .runtime_error,
            .pending,
            => boxyLowerInvariant("refutable or pending checked pattern reached boxy reassign binder reservation"),
        }
    }

    fn bindPatternToLocal(self: *ProcBodyBuilder, pattern_id: checked.CheckedPatternId, local: LIR.LocalId) void {
        const pattern = self.module.checked_bodies.pattern(pattern_id);
        switch (pattern.data) {
            .assign => |binder| self.bindLocal(binder, local),
            .pending, .as, .applied_tag, .nominal, .record_destructure, .list, .tuple, .numeral_literal, .str_literal, .str_interpolation, .underscore, .runtime_error => boxyLowerInvariant("boxy pattern required pattern lowering before it was emitted"),
        }
    }

    fn reserveBinderLocal(
        self: *ProcBodyBuilder,
        binder: checked.PatternBinderId,
        ty: checked.CheckedTypeId,
    ) Allocator.Error!void {
        const rep = self.repForType(ty);
        const local = if (self.parent.layoutIsBoxStorage(self.workerRuntimeLayoutForRep(rep).layoutIdx()))
            try self.addFrameLocalForRepWithFreshDescriptor(rep)
        else
            try self.addFrameLocalForRep(rep);
        self.bindLocal(binder, local);
    }

    fn reserveMatchBinderLocal(
        self: *ProcBodyBuilder,
        binder: checked.PatternBinderId,
        ty: checked.CheckedTypeId,
    ) Allocator.Error!void {
        return try self.reserveMatchBinderLocalForRep(binder, self.repForType(ty));
    }

    fn reserveMatchBinderLocalForRep(
        self: *ProcBodyBuilder,
        binder: checked.PatternBinderId,
        rep: Plan.TypeRepId,
    ) Allocator.Error!void {
        const local = try self.addFrameLocalForRepWithFreshDescriptor(rep);
        self.bindLocalForRep(binder, local, rep);
    }

    fn reserveBinderLocalIfFresh(
        self: *ProcBodyBuilder,
        binder: checked.PatternBinderId,
        ty: checked.CheckedTypeId,
    ) Allocator.Error!void {
        if (self.binderLocalOrNull(binder) != null) return;
        try self.reserveBinderLocal(binder, ty);
    }

    fn bindLocal(self: *ProcBodyBuilder, binder: checked.PatternBinderId, local: LIR.LocalId) void {
        const index = @intFromEnum(binder);
        if (index >= self.binder_locals.len) boxyLowerInvariant("boxy pattern referenced a missing pattern binder");
        if (self.binder_locals[index] != null) boxyLowerInvariant("boxy pattern bound the same pattern binder more than once");
        self.binder_locals[index] = local;
    }

    fn bindLocalForRep(
        self: *ProcBodyBuilder,
        binder: checked.PatternBinderId,
        local: LIR.LocalId,
        rep: Plan.TypeRepId,
    ) void {
        self.bindLocal(binder, local);
        const index = @intFromEnum(binder);
        if (index >= self.binder_reps.len) boxyLowerInvariant("boxy pattern referenced a missing binder representation");
        self.binder_reps[index] = rep;
    }

    fn binderLocalOrNull(self: *const ProcBodyBuilder, binder: checked.PatternBinderId) ?LIR.LocalId {
        const index = @intFromEnum(binder);
        if (index >= self.binder_locals.len) boxyLowerInvariant("boxy pattern referenced a missing pattern binder");
        return self.binder_locals[index];
    }

    fn binderStorageRep(self: *ProcBodyBuilder, binder: checked.PatternBinderId) Plan.TypeRepId {
        const index = @intFromEnum(binder);
        if (index >= self.binder_reps.len) boxyLowerInvariant("boxy binder representation lookup referenced a missing binder");
        return self.binder_reps[index] orelse self.repForType(self.binderType(binder));
    }

    fn binderIsReassigned(
        _: *const ProcBodyBuilder,
        reassigned_binders: []const checked.PatternBinderId,
        binder: checked.PatternBinderId,
    ) bool {
        for (reassigned_binders) |reassigned| {
            if (reassigned == binder) return true;
        }
        return false;
    }

    fn localForBinder(self: *ProcBodyBuilder, binder: checked.PatternBinderId) LIR.LocalId {
        const binder_index = @intFromEnum(binder);
        if (binder_index >= self.binder_locals.len) boxyLowerInvariant("boxy local lookup referenced a missing binder local");
        return self.binder_locals[binder_index] orelse
            boxyLowerInvariant("boxy local lookup referenced a binder before it was bound");
    }

    fn localForPattern(self: *ProcBodyBuilder, pattern: checked.CheckedPatternId) LIR.LocalId {
        const pattern_index = @intFromEnum(pattern);
        if (pattern_index >= self.module.checked_bodies.pattern_binder_by_pattern.len) {
            boxyLowerInvariant("boxy local lookup referenced a pattern without binder metadata");
        }
        const binder = self.module.checked_bodies.pattern_binder_by_pattern[pattern_index] orelse
            boxyLowerInvariant("boxy local lookup referenced a non-binding pattern");
        return self.localForBinder(binder);
    }

    fn resolvedValueRecord(self: *const ProcBodyBuilder, ref_id: checked.ResolvedValueRefId) checked.ResolvedValueRefRecord {
        return resolvedValueRecordInModule(self.module, ref_id);
    }

    fn resolvedValueRecordInModule(module: ProcedureModuleView, ref_id: checked.ResolvedValueRefId) checked.ResolvedValueRefRecord {
        const raw = @intFromEnum(ref_id);
        if (raw >= module.resolved_value_refs.records.len) {
            boxyLowerInvariant("checked lookup referenced a missing resolved value");
        }
        return module.resolved_value_refs.records[raw];
    }

    fn workerReturnLayout(self: *const ProcBodyBuilder) @import("layout").Idx {
        if (self.worker_layout.ret) |ret| return ret.layoutIdx();
        return self.worker_layout.value.layoutIdx();
    }

    fn repForType(self: *const ProcBodyBuilder, ty: checked.CheckedTypeId) Plan.TypeRepId {
        var contextual_rep: ?Plan.TypeRepId = null;
        for (self.lambda_arg_patterns, self.lambda_arg_worker_reps) |pattern_id, worker_rep| {
            if (self.module.checked_bodies.pattern(pattern_id).ty != ty) continue;
            if (contextual_rep) |existing| {
                if (existing != worker_rep) {
                    boxyLowerInvariant("one checked lambda parameter type mapped to conflicting worker representations");
                }
            } else {
                contextual_rep = worker_rep;
            }
        }
        if (contextual_rep) |rep| return rep;
        return self.repForModuleType(self.module, ty);
    }

    fn repForModuleType(self: *const ProcBodyBuilder, module: ProcedureModuleView, ty: checked.CheckedTypeId) Plan.TypeRepId {
        return self.parent.plan.repForSourceType(.{ .module = module.key, .ty = ty }) orelse {
            boxyLowerInvariant("checked body referenced a type missing from the boxy representation plan");
        };
    }

    fn repForTypeRef(self: *const ProcBodyBuilder, type_ref: Plan.CheckedTypeIdentity) Plan.TypeRepId {
        return self.parent.plan.repForSourceType(type_ref) orelse
            boxyLowerInvariant("checked body referenced a type ref missing from the boxy representation plan");
    }

    fn workerRuntimeLayoutForType(self: *const ProcBodyBuilder, ty: checked.CheckedTypeId) Layouts.RuntimeLayout {
        return self.parent.layout_plan.rep_layouts[@intFromEnum(self.repForType(ty))].worker;
    }

    fn workerRuntimeLayoutForTypeRef(self: *const ProcBodyBuilder, type_ref: Plan.CheckedTypeIdentity) Layouts.RuntimeLayout {
        return self.parent.layout_plan.rep_layouts[@intFromEnum(self.repForTypeRef(type_ref))].worker;
    }

    fn workerRuntimeLayoutForRep(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) Layouts.RuntimeLayout {
        return self.parent.layout_plan.rep_layouts[@intFromEnum(rep_id)].worker;
    }

    fn localUsesWorkerLayoutForRep(self: *const ProcBodyBuilder, local: LIR.LocalId, rep_id: Plan.TypeRepId) bool {
        return self.parent.result.store.getLocal(local).layout_idx == self.workerRuntimeLayoutForRep(rep_id).layoutIdx();
    }

    fn tagPayloadStorageLayoutForRep(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) layout.Idx {
        const desc_rep = self.parent.tagPayloadStorageDescRepIfNeeded(rep_id) orelse
            return self.workerRuntimeLayoutForRep(rep_id).layoutIdx();
        const rep_layout = self.parent.layout_plan.rep_layouts[@intFromEnum(desc_rep)];
        return rep_layout.descriptor_payload_layout orelse rep_layout.worker.layoutIdx();
    }

    fn aggregateFieldLayout(
        self: *const ProcBodyBuilder,
        aggregate_layout: layout.Idx,
        field_index: usize,
    ) Allocator.Error!layout.Idx {
        if (field_index > std.math.maxInt(u32)) {
            boxyLowerInvariant("aggregate field index exceeded LIR layout field range");
        }
        const aggregate = self.parent.result.layouts.getLayout(aggregate_layout);
        return switch (aggregate.tag) {
            .struct_ => self.parent.result.layouts.getStructFieldLayoutByOriginalIndex(
                aggregate.getStruct().idx,
                @intCast(field_index),
            ),
            .zst => .zst,
            .scalar, .box, .box_of_zst, .erased_box, .list, .list_of_zst, .closure, .erased_callable, .tag_union, .ptr => boxyLowerInvariant("aggregate field layout requested for non-struct layout"),
        };
    }

    fn hostRuntimeLayoutForRep(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) Layouts.RuntimeLayout {
        return self.parent.layout_plan.rep_layouts[@intFromEnum(rep_id)].host;
    }

    fn descriptorStorageRep(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) Plan.TypeRepId {
        var current = rep_id;
        var depth: u16 = 0;
        while (true) {
            if (depth == 1024) boxyLowerInvariant("descriptor representation wrapper chain exceeded boxy lowerer limit");
            depth += 1;

            const rep = self.parent.plan.representations.items[@intFromEnum(current)];
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent => {
                        if (rep.declared_fields.len != 0 or
                            rep.nominal_backing_arg_substitutions.len != 0) return current;
                        current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep;
                    },
                    .opaque_nominal, .builtin_other => return current,
                },
                .box => {
                    const child = self.repQuery().requiredSingleChild(current, .box_payload).rep;
                    if (self.workerRuntimeLayoutForRep(current).layoutIdx() != self.workerRuntimeLayoutForRep(child).layoutIdx()) return current;
                    current = child;
                },
                .in_progress, .dynamic, .primitive, .bool_tag_union, .erased_callable, .record, .record_unbound, .tuple, .list, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return current,
            }
        }
    }

    fn repContainsDynamicStorage(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) bool {
        const identity_rep = self.descriptorStorageRep(rep_id);
        const exact = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        const identity = self.parent.plan.representations.items[@intFromEnum(identity_rep)];
        return exact.contains_dynamic or identity.contains_dynamic;
    }

    fn dictionaryIdentityRep(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) Plan.TypeRepId {
        // A transparent nominal owns the method namespace its dictionary slots
        // dispatch through, so only aliases are unwrapped; the nominal identity
        // is preserved for method resolution.
        var current = rep_id;
        var depth: u16 = 0;
        while (true) {
            if (depth == 1024) boxyLowerInvariant("dictionary representation wrapper chain exceeded boxy lowerer limit");
            depth += 1;

            const rep = self.parent.plan.representations.items[@intFromEnum(current)];
            if (rep.kind != .alias) return current;
            current = self.repQuery().requiredSingleChild(current, .alias_backing).rep;
        }
    }

    fn tagVariantRepForBoundary(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) ?Plan.TypeRepId {
        var current = rep_id;
        var depth: u16 = 0;
        while (true) {
            if (depth == 1024) boxyLowerInvariant("tag representation wrapper chain exceeded boxy lowerer limit");
            depth += 1;

            const rep = self.parent.plan.representations.items[@intFromEnum(current)];
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent, .builtin_other => current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep,
                    .opaque_nominal => return null,
                },
                .tag_union, .dynamic => {
                    if (rep.tag_variants.len == 0) return null;
                    return current;
                },
                .in_progress, .primitive, .bool_tag_union, .erased_callable, .record, .record_unbound, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .empty_tag_union => return null,
            }
        }
    }

    fn listRepForBoundary(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) ?Plan.TypeRepId {
        var current = rep_id;
        var depth: u16 = 0;
        while (true) {
            if (depth == 1024) boxyLowerInvariant("list representation wrapper chain exceeded boxy lowerer limit");
            depth += 1;

            const rep = self.parent.plan.representations.items[@intFromEnum(current)];
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent, .builtin_other => current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep,
                    .opaque_nominal => return null,
                },
                .list => return current,
                .in_progress, .dynamic, .primitive, .bool_tag_union, .erased_callable, .record, .record_unbound, .tuple, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return null,
            }
        }
    }

    fn tupleRepForBoundary(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) ?Plan.TypeRepId {
        var current = rep_id;
        var depth: u16 = 0;
        while (true) {
            if (depth == 1024) boxyLowerInvariant("tuple representation wrapper chain exceeded boxy lowerer limit");
            depth += 1;

            const rep = self.parent.plan.representations.items[@intFromEnum(current)];
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent, .builtin_other => current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep,
                    .opaque_nominal => return null,
                },
                .tuple => return current,
                .dynamic => {
                    var has_element = false;
                    for (self.parent.plan.childSlice(rep.children)) |child| {
                        switch (child.role) {
                            .tuple_elem => has_element = true,
                            .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => return null,
                        }
                    }
                    return if (has_element) current else null;
                },
                .in_progress, .primitive, .bool_tag_union, .erased_callable, .record, .record_unbound, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return null,
            }
        }
    }

    fn declaredAggregateRepForBoundary(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) ?Plan.TypeRepId {
        var current = rep_id;
        var depth: u16 = 0;
        while (true) {
            if (depth == 1024) boxyLowerInvariant("declared aggregate wrapper chain exceeded boxy lowerer limit");
            depth += 1;

            const rep = self.parent.plan.representations.items[@intFromEnum(current)];
            if (rep.declared_fields.len != 0) return current;
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent, .builtin_other => current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep,
                    .opaque_nominal => return null,
                },
                .in_progress, .dynamic, .primitive, .bool_tag_union, .erased_callable, .record, .record_unbound, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return null,
            }
        }
    }

    fn functionReturnRepForType(self: *const ProcBodyBuilder, ty: checked.CheckedTypeId) Plan.TypeRepId {
        return self.functionReturnRepForRep(self.repForType(ty));
    }

    const FunctionChildren = struct {
        rep: Plan.TypeRepId,
        args_start: u32,
        arg_count: u32,
        ret: Plan.TypeRepId,
    };

    fn functionChildrenForRep(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) ?FunctionChildren {
        var current = rep_id;
        var depth: u16 = 0;
        while (true) {
            if (depth == 1024) boxyLowerInvariant("function representation alias chain exceeded boxy lowerer limit");
            depth += 1;

            const rep = self.parent.plan.representations.items[@intFromEnum(current)];
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent => current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep,
                    .opaque_nominal, .builtin_other => return null,
                },
                .erased_callable => {
                    const children = self.parent.plan.childSlice(rep.children);
                    var args_start: ?u32 = null;
                    var arg_count: u32 = 0;
                    var ret: ?Plan.TypeRepId = null;
                    for (children, 0..) |child, i| {
                        switch (child.role) {
                            .function_arg => {
                                if (args_start == null) args_start = @intCast(i);
                                arg_count += 1;
                            },
                            .function_ret => ret = child.rep,
                            .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .tuple_elem, .tag_payload, .tag_ext, .list_elem, .box_payload => {},
                        }
                    }
                    return .{
                        .rep = current,
                        .args_start = args_start orelse 0,
                        .arg_count = arg_count,
                        .ret = ret orelse boxyLowerInvariant("function representation had no return child"),
                    };
                },
                .in_progress, .dynamic, .primitive, .bool_tag_union, .record, .record_unbound, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return null,
            }
        }
    }

    fn erasedCaptureDescriptorSourcesForFunctionUse(
        self: *ProcBodyBuilder,
        worker_id: Plan.WorkerPlanId,
        call_function: FunctionChildren,
        captures: []const Plan.ErasedCapture,
        planned_hidden_args: []const Plan.DirectCallHiddenDescriptorArg,
    ) Allocator.Error![]ErasedCaptureDescriptorSource {
        const result = try self.parent.allocator.alloc(ErasedCaptureDescriptorSource, captures.len);
        errdefer self.parent.allocator.free(result);
        for (captures, result) |capture, *source| {
            source.* = .{ .rep = capture.rep };
        }

        const worker = self.parent.plan.workers.items[@intFromEnum(worker_id)];
        const params = self.parent.plan.hiddenDescriptorParamSlice(worker.hidden_descs);
        if (params.len == 0) return result;
        if (planned_hidden_args.len != 0 and planned_hidden_args.len != params.len) {
            boxyLowerInvariant("boxy callable descriptor capture plan disagreed with worker hidden parameters");
        }

        const worker_function = self.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("boxy erased callable with hidden descriptors was not a function worker");
        if (worker_function.arg_count != call_function.arg_count) {
            boxyLowerInvariant("boxy erased callable descriptor mapping saw mismatched function arity");
        }

        if (try self.callableBoundaryNeedsAdapter(call_function, worker_function)) {
            const adapter_captures = try self.collectCallableWorkerDescriptorCaptures(worker_function, call_function);
            defer self.parent.allocator.free(adapter_captures);

            for (captures, result) |capture, *source| {
                if (capture.kind != .hidden_desc or capture.body_descriptor) continue;
                const desc = capture.desc orelse
                    boxyLowerInvariant("boxy hidden descriptor erased capture had no descriptor requirement");
                var found: ?CallableAdapterDescriptorCapture = null;
                for (adapter_captures) |adapter_capture| {
                    if (adapter_capture.desc != desc) continue;
                    if (found != null) {
                        boxyLowerInvariant("boxy erased callable descriptor source plan contained duplicate requirements");
                    }
                    found = adapter_capture;
                }
                const adapter_capture = found orelse
                    boxyLowerInvariant("boxy erased callable adapter did not plan a hidden descriptor source");
                source.* = .{
                    .rep = adapter_capture.materialize_rep,
                    .read_path = adapter_capture.materialize_read_path,
                };
            }
            self.applyPlannedBodyDescriptorCaptureSources(captures, result, planned_hidden_args);
            return result;
        }

        var mapped = collections.DenseMap(Plan.DescriptorRequirementId, Plan.TypeRepId).init(self.parent.allocator);
        defer mapped.deinit();
        var seen = std.AutoHashMap(u64, void).init(self.parent.allocator);
        defer seen.deinit();
        var substitutions = collections.DenseMap(Plan.TypeRepId, Plan.TypeRepId).init(self.parent.allocator);
        defer substitutions.deinit();

        const worker_children = self.parent.plan.childSlice(self.parent.plan.representations.items[@intFromEnum(worker_function.rep)].children);
        const call_children = self.parent.plan.childSlice(self.parent.plan.representations.items[@intFromEnum(call_function.rep)].children);
        const worker_args = worker_children[worker_function.args_start..][0..worker_function.arg_count];
        const call_args = call_children[call_function.args_start..][0..call_function.arg_count];
        for (worker_args, call_args) |worker_child, call_child| {
            if (!try self.collectErasedCaptureDescriptorReps(worker_child.rep, call_child.rep, params, &mapped, &seen, &substitutions)) {
                boxyLowerInvariant("boxy erased callable descriptor mapping saw mismatched child roles");
            }
        }
        if (!try self.collectErasedCaptureDescriptorReps(worker_function.ret, call_function.ret, params, &mapped, &seen, &substitutions)) {
            boxyLowerInvariant("boxy erased callable descriptor mapping saw mismatched child roles");
        }

        for (captures, result) |capture, *source| {
            if (capture.kind != .hidden_desc or capture.body_descriptor) continue;
            const desc = capture.desc orelse
                boxyLowerInvariant("boxy hidden descriptor erased capture had no descriptor requirement");
            source.rep = mapped.get(desc) orelse
                boxyLowerInvariant("boxy erased callable descriptor mapping did not cover a signature descriptor capture");
        }
        self.applyPlannedBodyDescriptorCaptureSources(captures, result, planned_hidden_args);
        return result;
    }

    fn applyPlannedBodyDescriptorCaptureSources(
        _: *ProcBodyBuilder,
        captures: []const Plan.ErasedCapture,
        sources: []ErasedCaptureDescriptorSource,
        planned_hidden_args: []const Plan.DirectCallHiddenDescriptorArg,
    ) void {
        for (captures, sources) |capture, *source| {
            if (capture.kind != .hidden_desc or !capture.body_descriptor) continue;
            const desc = capture.desc orelse
                boxyLowerInvariant("boxy body descriptor capture had no descriptor requirement");
            var found: ?Plan.TypeRepId = null;
            for (planned_hidden_args) |arg| {
                if (arg.worker_desc != desc) continue;
                if (found != null and found.? != arg.rep) {
                    boxyLowerInvariant("boxy callable use planned conflicting body descriptor sources");
                }
                found = arg.rep;
            }
            source.rep = found orelse
                boxyLowerInvariant("boxy callable use did not plan a body descriptor capture source");
            source.read_path = .{};
        }
    }

    fn collectErasedCaptureDescriptorReps(
        self: *ProcBodyBuilder,
        worker_rep_id: Plan.TypeRepId,
        call_rep_id: Plan.TypeRepId,
        params: []const Plan.HiddenDescriptorParam,
        mapped: *collections.DenseMap(Plan.DescriptorRequirementId, Plan.TypeRepId),
        seen_rep_pairs: *std.AutoHashMap(u64, void),
        substitutions: *collections.DenseMap(Plan.TypeRepId, Plan.TypeRepId),
    ) Allocator.Error!bool {
        const effective_call_rep_id = substitutions.get(worker_rep_id) orelse call_rep_id;
        const pair_key = (@as(u64, @intFromEnum(worker_rep_id)) << 32) |
            @as(u64, @intFromEnum(effective_call_rep_id));
        const entry = try seen_rep_pairs.getOrPut(pair_key);
        if (entry.found_existing) return true;

        const worker_rep = self.parent.plan.representations.items[@intFromEnum(worker_rep_id)];
        const call_rep = self.parent.plan.representations.items[@intFromEnum(effective_call_rep_id)];
        try self.recordNominalBackingRepSubstitutions(
            worker_rep_id,
            effective_call_rep_id,
            substitutions,
        );

        if (worker_rep.descriptor) |worker_desc| {
            const param = self.hiddenDescriptorParamForRequirement(params, worker_desc) orelse {
                boxyLowerInvariant("boxy erased callable descriptor mapping found descriptor outside worker params");
            };
            const mapped_rep = substitutions.get(worker_rep_id) orelse
                try self.descriptorCaptureMaterializeRep(worker_rep_id, effective_call_rep_id);
            const put = try mapped.getOrPut(param.desc);
            if (put.found_existing and put.value_ptr.* != mapped_rep) {
                boxyLowerInvariant("boxy erased callable descriptor mapping assigned one worker descriptor to two reps");
            }
            put.value_ptr.* = mapped_rep;
        }

        if (worker_rep.children.len == 0) return true;

        if (call_rep.kind == .empty_tag_union) {
            for (self.parent.plan.childSlice(worker_rep.children)) |worker_child| {
                if (!try self.repQuery().repSubtreeHasDescriptor(worker_child.rep)) continue;
                if (!try self.collectErasedCaptureDescriptorReps(worker_child.rep, effective_call_rep_id, params, mapped, seen_rep_pairs, substitutions)) return false;
            }
            return true;
        }

        const worker_children = self.parent.plan.childSlice(worker_rep.children);
        const call_children = self.parent.plan.childSlice(call_rep.children);
        for (worker_children) |worker_child| {
            if (!try self.repQuery().repSubtreeHasDescriptor(worker_child.rep)) continue;
            if (self.namedQuery().findMatchingChildByRole(call_children, worker_child)) |call_child| {
                if (!try self.collectErasedCaptureDescriptorReps(worker_child.rep, call_child.rep, params, mapped, seen_rep_pairs, substitutions)) return false;
                continue;
            }
            if (self.repQuery().structuralWrapperBackingRep(effective_call_rep_id)) |call_backing| {
                const backing_children = self.parent.plan.childSlice(self.parent.plan.representations.items[@intFromEnum(call_backing)].children);
                if (self.namedQuery().findMatchingChildByRole(backing_children, worker_child)) |call_child| {
                    if (!try self.collectErasedCaptureDescriptorReps(worker_child.rep, call_child.rep, params, mapped, seen_rep_pairs, substitutions)) return false;
                    continue;
                }
            }
            if (try self.namedQuery().findMatchingTagPayloadInRowExtension(call_children, worker_child)) |call_child| {
                if (!try self.collectErasedCaptureDescriptorReps(worker_child.rep, call_child.rep, params, mapped, seen_rep_pairs, substitutions)) return false;
                continue;
            }
            if (try self.repQuery().findMatchingChildBySourceType(call_children, worker_child)) |call_child| {
                if (!try self.collectErasedCaptureDescriptorReps(worker_child.rep, call_child.rep, params, mapped, seen_rep_pairs, substitutions)) return false;
                continue;
            }
            if (try self.repQuery().workerChildCanMatchUnwrappedCallRep(worker_rep_id, worker_child)) {
                if (!try self.collectErasedCaptureDescriptorReps(worker_child.rep, effective_call_rep_id, params, mapped, seen_rep_pairs, substitutions)) return false;
                continue;
            }
            if (worker_child.role == .tag_ext and call_children.len == 0 and call_rep.descriptor != null) {
                if (!try self.collectErasedCaptureDescriptorReps(worker_child.rep, effective_call_rep_id, params, mapped, seen_rep_pairs, substitutions)) return false;
                continue;
            }
            return false;
        }
        return true;
    }

    fn recordNominalBackingRepSubstitutions(
        self: *ProcBodyBuilder,
        worker_rep_id: Plan.TypeRepId,
        call_rep_id: Plan.TypeRepId,
        substitutions: *collections.DenseMap(Plan.TypeRepId, Plan.TypeRepId),
    ) Allocator.Error!void {
        const worker_rep = self.parent.plan.representations.items[@intFromEnum(worker_rep_id)];
        if (worker_rep.kind != .nominal) return;
        const call_rep = self.parent.plan.representations.items[@intFromEnum(call_rep_id)];
        if (call_rep.kind != .nominal) return;

        const call_substitutions = self.parent.plan.nominalBackingArgSubstitutionSlice(
            call_rep.nominal_backing_arg_substitutions,
        );
        for (self.parent.plan.nominalBackingArgSubstitutionSlice(worker_rep.nominal_backing_arg_substitutions)) |backing_substitution| {
            var exact_call_arg_rep: ?Plan.TypeRepId = null;
            for (call_substitutions) |call_substitution| {
                if (call_substitution.arg_index != backing_substitution.arg_index) continue;
                if (exact_call_arg_rep != null) {
                    boxyLowerInvariant("boxy nominal backing substitution found duplicate call arguments");
                }
                exact_call_arg_rep = call_substitution.actual_rep;
            }
            const exact_rep = exact_call_arg_rep orelse
                boxyLowerInvariant("boxy nominal backing substitution was missing a call argument");
            if (backing_substitution.formal_rep == exact_rep) continue;
            const put = try substitutions.getOrPut(backing_substitution.formal_rep);
            if (put.found_existing and put.value_ptr.* != exact_rep) {
                boxyLowerInvariant("boxy nominal backing substitution assigned one backing formal to two call arguments");
            }
            put.value_ptr.* = exact_rep;
        }
    }

    fn erasedCaptureDictionaryRepsForFunctionUse(
        self: *ProcBodyBuilder,
        worker_id: Plan.WorkerPlanId,
        value_function: FunctionChildren,
        captures: []const Plan.ErasedCapture,
    ) Allocator.Error![]Plan.TypeRepId {
        const result = try self.parent.allocator.alloc(Plan.TypeRepId, captures.len);
        errdefer self.parent.allocator.free(result);
        for (captures, result) |capture, *rep| {
            rep.* = capture.rep;
        }

        const worker = self.parent.plan.workers.items[@intFromEnum(worker_id)];
        const params = self.parent.plan.hiddenDictionaryParamSlice(worker.hidden_dicts);
        if (params.len == 0) return result;

        const worker_function = self.functionChildrenForRep(worker.rep) orelse
            boxyLowerInvariant("boxy erased callable with hidden dictionaries was not a function worker");
        if (worker_function.arg_count != value_function.arg_count) {
            boxyLowerInvariant("boxy erased callable dictionary mapping saw mismatched function arity");
        }

        var mapped = collections.DenseMap(Plan.TypeRepId, Plan.TypeRepId).init(self.parent.allocator);
        defer mapped.deinit();
        var seen = std.AutoHashMap(u64, void).init(self.parent.allocator);
        defer seen.deinit();
        var substitutions = collections.DenseMap(Plan.TypeRepId, Plan.TypeRepId).init(self.parent.allocator);
        defer substitutions.deinit();

        const worker_children = self.parent.plan.childSlice(self.parent.plan.representations.items[@intFromEnum(worker_function.rep)].children);
        const value_children = self.parent.plan.childSlice(self.parent.plan.representations.items[@intFromEnum(value_function.rep)].children);
        const worker_args = worker_children[worker_function.args_start..][0..worker_function.arg_count];
        const value_args = value_children[value_function.args_start..][0..value_function.arg_count];
        for (worker_args, value_args) |worker_child, value_child| {
            try self.collectErasedCaptureDictionaryReps(worker_child.rep, value_child.rep, &mapped, &seen, &substitutions);
        }
        try self.collectErasedCaptureDictionaryReps(worker_function.ret, value_function.ret, &mapped, &seen, &substitutions);

        for (captures, result) |capture, *rep| {
            if (capture.kind != .hidden_dict) continue;
            if (capture.body_dictionary) continue;
            rep.* = mapped.get(capture.rep) orelse
                boxyLowerInvariant("boxy erased callable dictionary mapping did not cover a hidden dictionary capture");
        }
        return result;
    }

    fn collectErasedCaptureDictionaryReps(
        self: *ProcBodyBuilder,
        worker_rep_id: Plan.TypeRepId,
        value_rep_id: Plan.TypeRepId,
        mapped: *collections.DenseMap(Plan.TypeRepId, Plan.TypeRepId),
        seen_rep_pairs: *std.AutoHashMap(u64, void),
        substitutions: *collections.DenseMap(Plan.TypeRepId, Plan.TypeRepId),
    ) Allocator.Error!void {
        const effective_value_rep_id = substitutions.get(worker_rep_id) orelse value_rep_id;
        const pair_key = (@as(u64, @intFromEnum(worker_rep_id)) << 32) |
            @as(u64, @intFromEnum(effective_value_rep_id));
        const entry = try seen_rep_pairs.getOrPut(pair_key);
        if (entry.found_existing) return;

        const worker_rep = self.parent.plan.representations.items[@intFromEnum(worker_rep_id)];
        const value_rep = self.parent.plan.representations.items[@intFromEnum(effective_value_rep_id)];
        try self.recordNominalBackingRepSubstitutions(worker_rep_id, effective_value_rep_id, substitutions);

        if (worker_rep.dictionaries.len != 0) {
            const mapped_rep = self.repQuery().dictionaryArgumentIdentityRep(effective_value_rep_id);
            const put = try mapped.getOrPut(worker_rep_id);
            if (put.found_existing and put.value_ptr.* != mapped_rep) {
                boxyLowerInvariant("boxy erased callable dictionary mapping assigned one worker rep to two reps");
            }
            put.value_ptr.* = mapped_rep;
        }

        if (worker_rep.children.len == 0) return;

        if (value_rep.kind == .empty_tag_union) {
            for (self.parent.plan.childSlice(worker_rep.children)) |worker_child| {
                if (!try self.repQuery().repSubtreeHasDictionary(worker_child.rep)) continue;
                try self.collectErasedCaptureDictionaryReps(worker_child.rep, effective_value_rep_id, mapped, seen_rep_pairs, substitutions);
            }
            return;
        }

        const worker_children = self.parent.plan.childSlice(worker_rep.children);
        const value_children = self.parent.plan.childSlice(value_rep.children);
        for (worker_children) |worker_child| {
            if (!try self.repQuery().repSubtreeHasDictionary(worker_child.rep)) continue;
            if (self.namedQuery().findMatchingChildByRole(value_children, worker_child)) |value_child| {
                try self.collectErasedCaptureDictionaryReps(worker_child.rep, value_child.rep, mapped, seen_rep_pairs, substitutions);
                continue;
            }
            if (self.repQuery().structuralWrapperBackingRep(effective_value_rep_id)) |value_backing| {
                const backing_children = self.parent.plan.childSlice(self.parent.plan.representations.items[@intFromEnum(value_backing)].children);
                if (self.namedQuery().findMatchingChildByRole(backing_children, worker_child)) |value_child| {
                    try self.collectErasedCaptureDictionaryReps(worker_child.rep, value_child.rep, mapped, seen_rep_pairs, substitutions);
                    continue;
                }
            }
            if (try self.namedQuery().findMatchingTagPayloadInRowExtension(value_children, worker_child)) |value_child| {
                try self.collectErasedCaptureDictionaryReps(worker_child.rep, value_child.rep, mapped, seen_rep_pairs, substitutions);
                continue;
            }
            if (try self.repQuery().findMatchingDictionaryChildBySourceType(value_children, worker_child)) |value_child| {
                try self.collectErasedCaptureDictionaryReps(worker_child.rep, value_child.rep, mapped, seen_rep_pairs, substitutions);
                continue;
            }
            if (try self.repQuery().workerChildCanMatchUnwrappedCallRepForDictionaries(worker_rep_id, worker_child)) {
                try self.collectErasedCaptureDictionaryReps(worker_child.rep, effective_value_rep_id, mapped, seen_rep_pairs, substitutions);
                continue;
            }
            if (worker_child.role == .tag_ext and value_children.len == 0 and value_rep.dictionaries.len != 0) {
                try self.collectErasedCaptureDictionaryReps(worker_child.rep, effective_value_rep_id, mapped, seen_rep_pairs, substitutions);
                continue;
            }
            boxyLowerInvariant("boxy erased callable dictionary mapping saw mismatched child roles");
        }
    }

    fn functionReturnRepForRep(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) Plan.TypeRepId {
        var current = rep_id;
        var depth: u16 = 0;
        while (true) {
            if (depth == 1024) boxyLowerInvariant("function representation alias chain exceeded boxy lowerer limit");
            depth += 1;

            const rep = self.parent.plan.representations.items[@intFromEnum(current)];
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent => current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep,
                    .opaque_nominal, .builtin_other => boxyLowerInvariant("opaque or unsupported nominal reached function return layout lowering"),
                },
                .erased_callable => {
                    for (self.parent.plan.childSlice(rep.children)) |child| {
                        switch (child.role) {
                            .function_ret => return child.rep,
                            .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .tuple_elem, .function_arg, .tag_payload, .tag_ext, .list_elem, .box_payload => {},
                        }
                    }
                    boxyLowerInvariant("function representation had no return child");
                },
                .in_progress, .dynamic, .primitive, .bool_tag_union, .record, .record_unbound, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => boxyLowerInvariant("list_map_can_reuse transform argument is not a function"),
            }
        }
    }

    fn requireEmptyRecordExtension(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) void {
        const rep = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        if (rep.kind != .empty_record) {
            boxyLowerInvariant("open record representation reached boxy body lowering without an explicit closed row");
        }
    }

    fn recordExprFieldIndex(
        self: *const ProcBodyBuilder,
        fields: []const checked.CheckedRecordExprField,
        label_view: ProcedureModuleView,
        label: @TypeOf(@as(checked.CheckedRecordExprField, undefined).label),
    ) ?usize {
        var found: ?usize = null;
        for (fields, 0..) |field, index| {
            if (!Plan.recordFieldNameMatches(viewNames(self.module), field.label, viewNames(label_view), label)) continue;
            if (found != null) {
                boxyLowerInvariant("record expression contained the same field label more than once");
            }
            found = index;
        }
        return found;
    }

    fn recordEqualityFieldCount(children: []const Plan.RepChild) u16 {
        var count: usize = 0;
        for (children) |child| {
            switch (child.role) {
                .record_field => count += 1,
                .record_ext => {},
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("record equality representation had a non-record child role"),
            }
        }
        if (count > std.math.maxInt(u16)) {
            boxyLowerInvariant("record equality field count exceeded LIR field index range");
        }
        return @intCast(count);
    }

    const RecordFieldAccessInfo = struct {
        record_rep: Plan.TypeRepId,
        field_idx: u16,
        field_rep: Plan.TypeRepId,
        field_kind: checked.CheckedFieldKind.Tag,
    };

    const MatchedRecordField = struct {
        index: u16,
        rep: Plan.TypeRepId,
    };

    fn recordRepForBoundary(self: *const ProcBodyBuilder, rep_id: Plan.TypeRepId) ?Plan.TypeRepId {
        var current = rep_id;
        var depth: u16 = 0;
        while (true) {
            if (depth == 1024) boxyLowerInvariant("record boundary representation wrapper chain exceeded boxy lowerer limit");
            depth += 1;

            const rep = self.parent.plan.representations.items[@intFromEnum(current)];
            switch (rep.kind) {
                .record,
                .record_unbound,
                => return current,
                .dynamic => return if (self.repHasRecordFieldChildrenForBoundary(rep)) current else null,
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent,
                    .builtin_other,
                    => current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep,
                    .opaque_nominal => return null,
                },
                .in_progress, .primitive, .bool_tag_union, .erased_callable, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => return null,
            }
        }
    }

    fn recordFieldCount(self: *const ProcBodyBuilder, children: []const Plan.RepChild) usize {
        var count: usize = 0;
        for (children) |child| {
            switch (child.role) {
                .record_field => count += 1,
                .record_ext => self.requireEmptyRecordExtension(child.rep),
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("record boundary representation had a non-record child role"),
            }
        }
        return count;
    }

    fn findRecordFieldByLabel(
        self: *const ProcBodyBuilder,
        record_rep_id: Plan.TypeRepId,
        source_view: ProcedureModuleView,
        target_view: ProcedureModuleView,
        target_label: @TypeOf(@as(checked.CheckedRecordExprField, undefined).label),
    ) ?MatchedRecordField {
        const rep = self.parent.plan.representations.items[@intFromEnum(record_rep_id)];
        var index: u16 = 0;
        for (self.parent.plan.childSlice(rep.children)) |child| {
            switch (child.role) {
                .record_field => |source_label| {
                    if (Plan.recordFieldNameMatches(viewNames(source_view), source_label, viewNames(target_view), target_label)) {
                        return .{
                            .index = index,
                            .rep = child.rep,
                        };
                    }
                    index += 1;
                },
                .record_ext => self.requireEmptyRecordExtension(child.rep),
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("record boundary source had a non-record child role"),
            }
        }
        return null;
    }

    fn repHasRecordFieldChildrenForBoundary(
        self: *const ProcBodyBuilder,
        rep: Plan.TypeRepresentation,
    ) bool {
        var has_field = false;
        for (self.parent.plan.childSlice(rep.children)) |child| {
            switch (child.role) {
                .record_field => has_field = true,
                .record_ext => {
                    const ext = self.parent.plan.representations.items[@intFromEnum(child.rep)];
                    if (ext.kind != .empty_record) return false;
                },
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => return false,
            }
        }
        return has_field;
    }

    fn recordFieldAccessInfo(
        self: *const ProcBodyBuilder,
        record_rep_id: Plan.TypeRepId,
        access_view: ProcedureModuleView,
        field_name: @TypeOf(@as(checked.CheckedRecordExprField, undefined).label),
    ) RecordFieldAccessInfo {
        const rep = self.parent.plan.representations.items[@intFromEnum(record_rep_id)];
        switch (rep.kind) {
            .record,
            .record_unbound,
            => {},
            .dynamic => {
                if (!self.repHasRecordFieldChildren(rep)) {
                    boxyLowerInvariant("record field access receiver did not have known boxy record fields");
                }
            },
            .alias => return self.recordFieldAccessInfo(self.repQuery().requiredSingleChild(record_rep_id, .alias_backing).rep, access_view, field_name),
            .nominal => |kind| switch (kind) {
                .transparent,
                .builtin_other,
                => return self.recordFieldAccessInfo(self.repQuery().requiredSingleChild(record_rep_id, .nominal_backing).rep, access_view, field_name),
                .opaque_nominal => boxyLowerInvariant("opaque nominal record field access reached boxy lowering"),
            },
            .in_progress, .primitive, .bool_tag_union, .erased_callable, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => {
                boxyLowerInvariant("record field access receiver did not have a boxy record representation");
            },
        }

        var index: u16 = 0;
        const source_view = procedureModuleById(self.parent.modules, rep.source_type.module);
        for (self.parent.plan.childSlice(rep.children)) |child| {
            switch (child.role) {
                .record_field => |label| {
                    if (Plan.recordFieldNameMatches(viewNames(source_view), label, viewNames(access_view), field_name)) {
                        return .{
                            .record_rep = record_rep_id,
                            .field_idx = index,
                            .field_rep = child.rep,
                            .field_kind = child.record_field_kind.tag,
                        };
                    }
                    index += 1;
                },
                .record_ext => self.requireEmptyRecordExtension(child.rep),
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("record field access representation had a non-record child role"),
            }
        }
        boxyLowerInvariant("record field access referenced a field outside its checked type representation");
    }

    fn recordFieldNestedDescriptorIndex(
        self: *const ProcBodyBuilder,
        record_rep_id: Plan.TypeRepId,
        field_idx: u16,
    ) ?u32 {
        const rep = self.parent.plan.representations.items[@intFromEnum(record_rep_id)];
        const payload_layout = self.parent.descriptorPayloadLayoutForRep(record_rep_id);
        var desc_index: u32 = 0;
        if (rep.declared_fields.len != 0) {
            var matched_has_desc: ?bool = null;
            for (self.parent.plan.declaredFieldSlice(rep.declared_fields)) |field| {
                const field_layout = self.parent.recordPayloadFieldLayout(payload_layout, field.index);
                const force_field = self.parent.layoutIsBoxStorage(field_layout);
                const has_desc = self.parent.layoutNeedsNestedBoxyDesc(field_layout) and
                    self.parent.tagPayloadStorageDescRepForLayout(field.rep, field_layout, force_field) != null;
                if (field.index == field_idx) matched_has_desc = has_desc;
                if (has_desc and field.index < field_idx) desc_index += 1;
            }
            return if (matched_has_desc) |has_desc| if (has_desc) desc_index else null else boxyLowerInvariant("record field descriptor lookup referenced a field outside declared field order");
        }

        var index: u16 = 0;
        for (self.parent.plan.childSlice(rep.children)) |child| {
            switch (child.role) {
                .record_field => {
                    const field_layout = self.parent.recordPayloadFieldLayout(payload_layout, index);
                    const force_field = self.parent.layoutIsBoxStorage(field_layout);
                    const has_desc = self.parent.layoutNeedsNestedBoxyDesc(field_layout) and
                        self.parent.tagPayloadStorageDescRepForLayout(child.rep, field_layout, force_field) != null;
                    if (index == field_idx) return if (has_desc) desc_index else null;
                    if (has_desc) desc_index += 1;
                    index += 1;
                },
                .record_ext => self.requireEmptyRecordExtension(child.rep),
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("record field descriptor lookup representation had a non-record child role"),
            }
        }
        boxyLowerInvariant("record field descriptor lookup referenced a field outside its representation");
    }

    fn tupleElemNestedDescriptorIndex(
        self: *const ProcBodyBuilder,
        tuple_rep_id: Plan.TypeRepId,
        elem_index: u32,
    ) ?u32 {
        const rep = self.parent.plan.representations.items[@intFromEnum(tuple_rep_id)];
        const payload_layout = self.parent.descriptorPayloadLayoutForRep(tuple_rep_id);
        var desc_index: u32 = 0;
        for (self.parent.plan.childSlice(rep.children)) |child| {
            const index = switch (child.role) {
                .tuple_elem => |index| index,
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("tuple descriptor lookup representation had a non-tuple child role"),
            };
            const field_layout = self.parent.recordPayloadFieldLayout(payload_layout, index);
            const force_field = self.parent.layoutIsBoxStorage(field_layout);
            const has_desc = self.parent.layoutNeedsNestedBoxyDesc(field_layout) and
                self.parent.tagPayloadStorageDescRepForLayout(child.rep, field_layout, force_field) != null;
            if (index == elem_index) return if (has_desc) desc_index else null;
            if (has_desc) desc_index += 1;
        }
        boxyLowerInvariant("tuple descriptor lookup referenced an element outside its representation");
    }

    fn repHasRecordFieldChildren(
        self: *const ProcBodyBuilder,
        rep: Plan.TypeRepresentation,
    ) bool {
        for (self.parent.plan.childSlice(rep.children)) |child| {
            switch (child.role) {
                .record_field => return true,
                .record_ext => {},
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .tuple_elem, .function_arg, .function_ret, .tag_payload, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("record field access representation had a non-record child role"),
            }
        }
        return false;
    }

    const TagVariantLookup = struct {
        index: u16,
        name: names.TagNameId,
        name_module: checked.ModuleId,
        payloads: Plan.Span,
    };

    fn tagVariantForTypeRef(
        self: *const ProcBodyBuilder,
        type_ref: Plan.CheckedTypeIdentity,
        name: names.TagNameId,
    ) TagVariantLookup {
        const requested_module = procedureModuleById(self.parent.modules, type_ref.module);
        var current = self.repForTypeRef(type_ref);
        var depth: u16 = 0;
        while (true) {
            if (depth == 1024) boxyLowerInvariant("tag-union representation wrapper chain exceeded boxy lowerer limit");
            depth += 1;

            const rep = self.parent.plan.representations.items[@intFromEnum(current)];
            switch (rep.kind) {
                .alias => current = self.repQuery().requiredSingleChild(current, .alias_backing).rep,
                .nominal => |kind| switch (kind) {
                    .transparent => current = self.repQuery().requiredSingleChild(current, .nominal_backing).rep,
                    .opaque_nominal, .builtin_other => boxyLowerInvariant("opaque or builtin nominal reached iterator tag-variant lookup"),
                },
                .tag_union,
                .dynamic,
                => return self.tagVariantForModule(rep, requested_module, name),
                .in_progress, .primitive, .bool_tag_union, .erased_callable, .record, .record_unbound, .tuple, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .empty_tag_union => boxyLowerInvariant("iterator step type did not have a boxy tag-union representation"),
            }
        }
    }

    fn tagVariant(
        self: *const ProcBodyBuilder,
        rep: Plan.TypeRepresentation,
        name: names.TagNameId,
    ) TagVariantLookup {
        return self.tagVariantForModule(rep, self.module, name);
    }

    fn tagVariantForModule(
        self: *const ProcBodyBuilder,
        rep: Plan.TypeRepresentation,
        requested_module: ProcedureModuleView,
        name: names.TagNameId,
    ) TagVariantLookup {
        const variants = self.parent.plan.tagVariantSlice(rep.tag_variants);
        for (variants, 0..) |variant, index| {
            if (!self.tagVariantNameMatches(variant, requested_module, name)) continue;
            if (index > std.math.maxInt(u16)) {
                boxyLowerInvariant("tag variant index exceeded LIR variant range");
            }
            return .{
                .index = @intCast(index),
                .name = variant.name,
                .name_module = variant.name_module,
                .payloads = variant.payloads,
            };
        }
        boxyLowerInvariant("tag expression referenced a variant outside its checked type representation");
    }

    fn tagVariantNameMatches(
        self: *const ProcBodyBuilder,
        variant: Plan.TagVariant,
        requested_module: ProcedureModuleView,
        requested_name: names.TagNameId,
    ) bool {
        return std.mem.eql(
            u8,
            self.tagVariantNameText(variant),
            requested_module.canonical_names.tagLabelText(requested_name),
        );
    }

    fn tagVariantNameText(self: *const ProcBodyBuilder, variant: Plan.TagVariant) []const u8 {
        const module = procedureModuleById(self.parent.modules, variant.name_module);
        return module.canonical_names.tagLabelText(variant.name);
    }

    fn lirTagName(
        self: *ProcBodyBuilder,
        tag_name: names.TagNameId,
    ) Allocator.Error!base.StringLiteral.Idx {
        return try self.parent.result.store.insertString(self.module.canonical_names.tagLabelText(tag_name));
    }

    fn lirTagNameForRep(
        self: *ProcBodyBuilder,
        rep_id: Plan.TypeRepId,
        tag_name: names.TagNameId,
    ) Allocator.Error!base.StringLiteral.Idx {
        const rep = self.parent.plan.representations.items[@intFromEnum(rep_id)];
        const module = procedureModuleById(self.parent.modules, rep.source_type.module);
        return try self.parent.result.store.insertString(module.canonical_names.tagLabelText(tag_name));
    }

    fn lirTagNameForVariant(
        self: *ProcBodyBuilder,
        variant: Plan.TagVariant,
    ) Allocator.Error!base.StringLiteral.Idx {
        return try self.parent.result.store.insertString(self.tagVariantNameText(variant));
    }

    fn lirTagNameForLookup(
        self: *ProcBodyBuilder,
        variant: TagVariantLookup,
    ) Allocator.Error!base.StringLiteral.Idx {
        const module = procedureModuleById(self.parent.modules, variant.name_module);
        return try self.parent.result.store.insertString(module.canonical_names.tagLabelText(variant.name));
    }

    fn boolVariantIndex(self: *const ProcBodyBuilder, name: names.TagNameId) u16 {
        const tag_name = self.module.canonical_names.tagLabelText(name);
        if (std.mem.eql(u8, tag_name, "False")) return 0;
        if (std.mem.eql(u8, tag_name, "True")) return 1;
        boxyLowerInvariant("builtin Bool tag expression referenced a non-Bool tag");
    }

    fn tagUnionPayloadLayout(self: *const ProcBodyBuilder, tag_union_layout_idx: layout.Idx, variant_index: u16) layout.Idx {
        const tag_union_layout = self.parent.result.layouts.getLayout(tag_union_layout_idx);
        return switch (tag_union_layout.tag) {
            .tag_union => blk: {
                const data = self.parent.result.layouts.getTagUnionData(tag_union_layout.getTagUnion().idx);
                const variants = self.parent.result.layouts.getTagUnionVariants(data);
                if (variant_index >= variants.len) {
                    boxyLowerInvariant("tag payload variant exceeded committed tag-union layout");
                }
                break :blk variants.get(@intCast(variant_index)).payload_layout;
            },
            .zst, .scalar => .zst,
            .box, .box_of_zst, .erased_box, .list, .list_of_zst, .struct_, .closure, .erased_callable, .ptr => boxyLowerInvariant("tag payload operation expected tag-union layout"),
        };
    }

    fn localListElemLayout(self: *const ProcBodyBuilder, local: LIR.LocalId) layout.Idx {
        const list_layout_idx = self.parent.result.store.getLocal(local).layout_idx;
        const list_layout = self.parent.result.layouts.getLayout(list_layout_idx);
        return switch (list_layout.tag) {
            .list => list_layout.getIdx(),
            .list_of_zst => .zst,
            .scalar, .box, .box_of_zst, .erased_box, .struct_, .closure, .erased_callable, .zst, .tag_union, .ptr => boxyLowerInvariant("list expression target was not a list layout"),
        };
    }

    fn layoutIsBoxyDynamicStorage(self: *const ProcBodyBuilder, layout_idx: layout.Idx) bool {
        return self.parent.result.layouts.getLayout(layout_idx).tag == .erased_box;
    }

    fn isZstLocal(self: *const ProcBodyBuilder, local: LIR.LocalId) bool {
        return self.parent.result.layouts.isZeroSized(
            self.parent.result.layouts.getLayout(self.parent.result.store.getLocal(local).layout_idx),
        );
    }
};

fn constListElemType(module: ProcedureModuleView, checked_ty: checked.CheckedTypeId) checked.CheckedTypeId {
    const nominal = resolvedNominalPayload(module, checked_ty);
    if (nominal.builtin != .list or nominal.args.len != 1) {
        boxyLowerInvariant("ConstStore list restored with a non-list checked type");
    }
    return nominal.args[0];
}

/// Decode one element of a packed scalar constant list into the same
/// `ConstScalar` a `.scalar` child node would have carried. Multi-byte values
/// use the little-endian encoding recorded by the ConstStore writer; vector
/// elements are read as their 16-byte value into `u128`, matching how the
/// writer stores a standalone vector scalar.
fn packedConstListElementScalar(
    element: check.ConstStore.ConstPackedScalar,
    bytes: []const u8,
) checked.ConstScalar {
    return switch (element) {
        .i8 => .{ .i8 = @bitCast(bytes[0]) },
        .u8 => .{ .u8 = bytes[0] },
        .i16 => .{ .i16 = std.mem.readInt(i16, bytes[0..2], .little) },
        .u16 => .{ .u16 = std.mem.readInt(u16, bytes[0..2], .little) },
        .i32 => .{ .i32 = std.mem.readInt(i32, bytes[0..4], .little) },
        .u32 => .{ .u32 = std.mem.readInt(u32, bytes[0..4], .little) },
        .i64 => .{ .i64 = std.mem.readInt(i64, bytes[0..8], .little) },
        .u64 => .{ .u64 = std.mem.readInt(u64, bytes[0..8], .little) },
        .i128 => .{ .i128 = std.mem.readInt(i128, bytes[0..16], .little) },
        .u128 => .{ .u128 = std.mem.readInt(u128, bytes[0..16], .little) },
        .f32 => .{ .f32_bits = std.mem.readInt(u32, bytes[0..4], .little) },
        .f64 => .{ .f64_bits = std.mem.readInt(u64, bytes[0..8], .little) },
        .dec => .{ .dec_bits = std.mem.readInt(i128, bytes[0..16], .little) },
        .u8x16,
        .i8x16,
        .u16x8,
        .i16x8,
        .u32x4,
        .i32x4,
        .u64x2,
        .i64x2,
        => .{ .u128 = std.mem.readInt(u128, bytes[0..16], .little) },
    };
}

fn constBoxPayloadType(module: ProcedureModuleView, checked_ty: checked.CheckedTypeId) checked.CheckedTypeId {
    const nominal = resolvedNominalPayload(module, checked_ty);
    if (nominal.builtin != .box or nominal.args.len != 1) {
        boxyLowerInvariant("ConstStore box restored with a non-Box checked type");
    }
    return nominal.args[0];
}

fn checkedFunctionPayload(module: ProcedureModuleView, checked_ty: checked.CheckedTypeId) checked.CheckedFunctionType {
    return switch (resolvedTypePayload(module, checked_ty)) {
        .function => |function| function,
        .pending, .err, .flex, .rigid, .alias, .record, .record_unbound, .tuple, .nominal, .empty_record, .tag_union, .empty_tag_union => boxyLowerInvariant("checked intrinsic wrapper did not have a function type"),
    };
}

fn dispatchPlanForGeneratedRuntime(
    module: ProcedureModuleView,
    expr_id: checked.CheckedExprId,
) static_dispatch.StaticDispatchCallPlan {
    const expr = module.checked_bodies.expr(expr_id);
    const plan_id = switch (expr.data) {
        .dispatch_call => |maybe| maybe orelse
            boxyLowerInvariant("stored serialization dispatch expression had no dispatch plan"),
        .type_dispatch_call => |maybe| maybe orelse
            boxyLowerInvariant("stored serialization type dispatch expression had no dispatch plan"),
        .pending,
        .numeral,
        .str_from_quote,
        .str_segment,
        .str,
        .bytes_literal,
        .lookup_local,
        .lookup_external,
        .lookup_required,
        .list,
        .empty_list,
        .tuple,
        .match_,
        .if_,
        .call,
        .record,
        .empty_record,
        .block,
        .tag,
        .nominal,
        .zero_argument_tag,
        .closure,
        .lambda,
        .binop,
        .unary_minus,
        .unary_not,
        .field_access,
        .interpolation,
        .structural_eq,
        .structural_hash,
        .method_eq,
        .tuple_access,
        .runtime_error,
        .crash,
        .dbg,
        .expect_err,
        .expect,
        .ellipsis,
        .anno_only,
        .break_,
        .return_,
        .for_,
        .hosted_lambda,
        .run_low_level,
        => boxyLowerInvariant("stored serialization runtime function did not reference a dispatch expression"),
    };
    const raw = @intFromEnum(plan_id);
    if (raw >= module.static_dispatch_plans.plans.len) {
        boxyLowerInvariant("stored serialization dispatch plan was outside its checked table");
    }
    return module.static_dispatch_plans.plans[raw];
}

fn checkedTypeUsesBuiltinStructuralEquality(module: ProcedureModuleView, checked_ty: checked.CheckedTypeId) bool {
    return switch (resolvedTypePayload(module, checked_ty)) {
        .nominal => |nominal| nominal.builtin != null,
        .record,
        .record_unbound,
        .tuple,
        .empty_record,
        .tag_union,
        .empty_tag_union,
        => true,
        .pending,
        .err,
        .flex,
        .rigid,
        .alias,
        .function,
        => false,
    };
}

fn constTupleItemTypes(module: ProcedureModuleView, checked_ty: checked.CheckedTypeId) []const checked.CheckedTypeId {
    return switch (resolvedTypePayload(module, checked_ty)) {
        .tuple => |items| items,
        .pending, .err, .flex, .rigid, .alias, .record, .record_unbound, .nominal, .function, .empty_record, .tag_union, .empty_tag_union => boxyLowerInvariant("ConstStore tuple restored with a non-tuple checked type"),
    };
}

fn constRecordFields(allocator: Allocator, module: ProcedureModuleView, checked_ty: checked.CheckedTypeId) Allocator.Error![]checked.CheckedRecordField {
    var fields = std.ArrayList(checked.CheckedRecordField).empty;
    errdefer fields.deinit(allocator);

    var seen = collections.DenseMap(checked.CheckedTypeId, void).init(allocator);
    defer seen.deinit();

    var current: ?checked.CheckedTypeId = checked_ty;
    while (current) |ty| {
        const entry = try seen.getOrPut(ty);
        if (entry.found_existing) {
            current = null;
            break;
        }

        switch (resolvedTypePayload(module, ty)) {
            .record => |record| {
                try fields.appendSlice(allocator, record.fields);
                current = record.ext;
            },
            .record_unbound => |tail_fields| {
                try fields.appendSlice(allocator, tail_fields);
                current = null;
            },
            .empty_record => current = null,
            .alias => |alias| current = alias.backing,
            .flex, .rigid => |variable| {
                if (variable.row_default != .empty_record) {
                    boxyLowerInvariant("ConstStore record restored with an open checked row");
                }
                current = null;
            },
            .pending, .err, .tuple, .nominal, .function, .tag_union, .empty_tag_union => boxyLowerInvariant("ConstStore record restored with a non-record checked type"),
        }
    }

    const SortContext = struct {
        names: *const names.CanonicalNameStore,

        fn lessThan(context: @This(), lhs: checked.CheckedRecordField, rhs: checked.CheckedRecordField) bool {
            return context.names.recordFieldLabelTextLessThan(lhs.name, rhs.name);
        }
    };
    std.mem.sort(checked.CheckedRecordField, fields.items, SortContext{ .names = module.canonical_names }, SortContext.lessThan);
    return try fields.toOwnedSlice(allocator);
}

fn constRowExtensionIsClosed(module: ProcedureModuleView, checked_ty: checked.CheckedTypeId, expected: checked.RowDefault) void {
    if (!constRowExtensionIsClosedInner(module, checked_ty, expected, 0)) {
        boxyLowerInvariant("ConstStore value restored with an open checked row");
    }
}

fn constRowExtensionIsClosedInner(module: ProcedureModuleView, checked_ty: checked.CheckedTypeId, expected: checked.RowDefault, depth: u16) bool {
    if (depth == 1024) {
        boxyLowerInvariant("ConstStore row extension chain exceeded boxy lowering limit");
    }
    return switch (resolvedTypePayload(module, checked_ty)) {
        .empty_record => expected == .empty_record,
        .empty_tag_union => expected == .empty_tag_union,
        .alias => |alias| constRowExtensionIsClosedInner(module, alias.backing, expected, depth + 1),
        .flex, .rigid => |variable| variable.row_default == expected,
        .record => |record| if (expected == .empty_record) constRowExtensionIsClosedInner(module, record.ext, expected, depth + 1) else false,
        .tag_union => |tag_union| if (expected == .empty_tag_union) constRowExtensionIsClosedInner(module, tag_union.ext, expected, depth + 1) else false,
        .pending, .err, .record_unbound, .tuple, .nominal, .function => boxyLowerInvariant("ConstStore record restored with a non-record checked type"),
    };
}

fn constRecordFieldIndex(fields: []const checked.CheckedRecordField, label: names.RecordFieldLabelId) ?usize {
    for (fields, 0..) |field, index| {
        if (field.name == label) return index;
    }
    return null;
}

fn checkedRecordFieldByName(module: ProcedureModuleView, checked_ty: checked.CheckedTypeId, field_name: []const u8) checked.CheckedRecordField {
    var current = checked_ty;
    var depth: u16 = 0;
    while (true) {
        if (depth == 1024) boxyLowerInvariant("generated record field lookup exceeded the checked row limit");
        depth += 1;

        switch (resolvedTypePayload(module, current)) {
            .record => |record| {
                for (record.fields) |field| {
                    if (std.mem.eql(u8, module.canonical_names.recordFieldLabelText(field.name), field_name)) return field;
                }
                current = record.ext;
            },
            .record_unbound => |fields| {
                for (fields) |field| {
                    if (std.mem.eql(u8, module.canonical_names.recordFieldLabelText(field.name), field_name)) return field;
                }
                break;
            },
            .empty_record => break,
            .pending, .err, .flex, .rigid, .alias, .tuple, .nominal, .function, .tag_union, .empty_tag_union => boxyLowerInvariant("generated record field lookup received a non-record type"),
        }
    }
    boxyLowerInvariant("generated record field lookup was missing a required field");
}

const ConstTagPayloadTypes = struct {
    name: names.TagNameId,
    payload_tys: []const checked.CheckedTypeId,
};

fn constTagPayloadTypes(
    module: ProcedureModuleView,
    checked_ty: checked.CheckedTypeId,
    tag_name: []const u8,
) ConstTagPayloadTypes {
    const tag_union = switch (resolvedTypePayload(module, checked_ty)) {
        .tag_union => |tag_union| tag_union,
        .pending, .err, .flex, .rigid, .alias, .record, .record_unbound, .tuple, .nominal, .function, .empty_record, .empty_tag_union => boxyLowerInvariant("ConstStore tag restored with a non-tag-union checked type"),
    };
    constRowExtensionIsClosed(module, tag_union.ext, .empty_tag_union);
    for (tag_union.tags) |tag| {
        if (std.mem.eql(u8, module.canonical_names.tagLabelText(tag.name), tag_name)) {
            return .{
                .name = tag.name,
                .payload_tys = tag.argsSlice(module.checked_types),
            };
        }
    }
    boxyLowerInvariant("ConstStore tag name was missing from checked tag-union type");
}

/// Like `constTagPayloadTypes`, but for restoration into a dynamic (open-row)
/// representation, where openness is fine: the named tag is searched through
/// the row's extension chain instead of demanding a closed row.
fn constTagPayloadTypesAllowOpen(
    module: ProcedureModuleView,
    checked_ty: checked.CheckedTypeId,
    tag_name: []const u8,
) ConstTagPayloadTypes {
    var current = checked_ty;
    var depth: u16 = 0;
    while (true) {
        if (depth == 1024) {
            boxyLowerInvariant("ConstStore row extension chain exceeded boxy lowering limit");
        }
        depth += 1;
        const tag_union = switch (resolvedTypePayload(module, current)) {
            .tag_union => |tag_union| tag_union,
            .pending, .err, .flex, .rigid, .alias, .record, .record_unbound, .tuple, .nominal, .function, .empty_record, .empty_tag_union => boxyLowerInvariant("ConstStore tag name was missing from checked tag-union row"),
        };
        for (tag_union.tags) |tag| {
            if (std.mem.eql(u8, module.canonical_names.tagLabelText(tag.name), tag_name)) {
                return .{
                    .name = tag.name,
                    .payload_tys = tag.argsSlice(module.checked_types),
                };
            }
        }
        current = tag_union.ext;
    }
}

fn resolvedNominalPayload(module: ProcedureModuleView, checked_ty: checked.CheckedTypeId) checked.CheckedNominalType {
    return switch (resolvedTypePayload(module, checked_ty)) {
        .nominal => |nominal| nominal,
        .pending, .err, .flex, .rigid, .alias, .record, .record_unbound, .tuple, .function, .empty_record, .tag_union, .empty_tag_union => boxyLowerInvariant("ConstStore nominal child lookup reached a non-nominal checked type"),
    };
}

fn resolvedNominalBacking(module: ProcedureModuleView, checked_ty: checked.CheckedTypeId) checked.CheckedTypeId {
    const nominal = resolvedNominalPayload(module, checked_ty);
    return module.checked_types.nominalBackingTemplateForPayload(nominal) orelse
        boxyLowerInvariant("boxy lowering requested the backing of an opaque nominal type");
}

fn checkedBuiltinNominalForType(
    module: ProcedureModuleView,
    checked_ty: checked.CheckedTypeId,
) ?checked.CheckedBuiltinNominal {
    return switch (resolvedTypePayload(module, checked_ty)) {
        .nominal => |nominal| nominal.builtin,
        .pending, .err, .flex, .rigid, .alias, .record, .record_unbound, .tuple, .function, .empty_record, .tag_union, .empty_tag_union => null,
    };
}

fn generatedEncoderKeyMethodForType(
    module: ProcedureModuleView,
    checked_ty: checked.CheckedTypeId,
) ?[]const u8 {
    return switch (checkedBuiltinNominalForType(module, checked_ty) orelse return null) {
        .bool => "encode_key_bool",
        .str => "encode_key_str",
        .u8 => "encode_key_u8",
        .i8 => "encode_key_i8",
        .u16 => "encode_key_u16",
        .i16 => "encode_key_i16",
        .u32 => "encode_key_u32",
        .i32 => "encode_key_i32",
        .u64 => "encode_key_u64",
        .i64 => "encode_key_i64",
        .u128 => "encode_key_u128",
        .i128 => "encode_key_i128",
        .dec => "encode_key_dec",
        .f32 => "encode_key_f32",
        .f64 => "encode_key_f64",
        .try_, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2, .list, .box, .dict, .set, .iter, .parse_tag_union_spec, .fields, .field, .crypto_sha256_digest, .crypto_sha256_hasher, .crypto_blake3_digest, .crypto_blake3_hasher => null,
    };
}

fn resolvedTypePayload(module: ProcedureModuleView, checked_ty: checked.CheckedTypeId) checked.CheckedTypePayload {
    var current = checked_ty;
    var depth: u16 = 0;
    while (true) {
        if (depth == 1024) boxyLowerInvariant("checked type alias chain exceeded boxy const lowering limit");
        depth += 1;

        const payload = module.checked_types.payload(current);
        switch (payload) {
            .pending => boxyLowerInvariant("pending checked type reached boxy const lowering"),
            .err => boxyLowerInvariant("checked error type reached boxy const lowering"),
            .alias => |alias| {
                current = alias.backing;
                continue;
            },
            .flex, .rigid, .record, .record_unbound, .tuple, .nominal, .function, .empty_record, .tag_union, .empty_tag_union => return payload,
        }
    }
}

fn appendRequestedLayouts(
    allocator: Allocator,
    modules: Common.CheckedModules,
    roots: Common.RootRequests,
    plan: *const Plan.ProgramPlan,
    layout_plan: *const Layouts.LayoutPlan,
    procedure_builder: *ProcedureBuilder,
    result: *LirProgram.Result,
) Allocator.Error!void {
    const request_count = roots.layout_requests.len + roots.static_data_requests.len;
    if (request_count == 0) return;
    const root_rep_start = plan.roots.items.len;
    if (plan.root_reps.items.len < root_rep_start + request_count) {
        boxyLowerInvariant("boxy plan root representations did not cover requested layouts");
    }

    var const_plans = try ConstPlanBuilder.init(allocator, modules, plan, layout_plan, procedure_builder, result);
    defer const_plans.deinit();

    const root_types = modules.root.module.checked_types.view();
    for (roots.layout_requests, 0..) |checked_type, index| {
        const rep_id = plan.root_reps.items[root_rep_start + index];
        try result.requested_layouts.append(allocator, .{
            .ty = root_types.rootKey(checked_type),
            .checked_type = checked_type,
            .layout_idx = layout_plan.rep_layouts[@intFromEnum(rep_id)].host.layoutIdx(),
            .plan = try const_plans.constPlanForRep(rep_id),
        });
    }
    for (roots.static_data_requests, 0..) |request, index| {
        const checked_type = request.checked_type;
        const rep_id = plan.root_reps.items[root_rep_start + roots.layout_requests.len + index];
        try result.requested_layouts.append(allocator, .{
            .ty = root_types.rootKey(checked_type),
            .checked_type = checked_type,
            .layout_idx = layout_plan.rep_layouts[@intFromEnum(rep_id)].host.layoutIdx(),
            .plan = try const_plans.constPlanForRep(rep_id),
        });
    }
}

const ConstPlanBuilder = struct {
    allocator: Allocator,
    modules: Common.CheckedModules,
    plan: *const Plan.ProgramPlan,
    layout_plan: *const Layouts.LayoutPlan,
    procedure_builder: *ProcedureBuilder,
    result: *LirProgram.Result,
    by_rep: []?LirProgram.ConstPlanId,

    /// Shared read-only queries over the representation plan.
    fn repQuery(self: *const ConstPlanBuilder) Plan.RepQuery {
        return .{ .plan = self.plan, .allocator = self.allocator };
    }

    fn init(
        allocator: Allocator,
        modules: Common.CheckedModules,
        plan: *const Plan.ProgramPlan,
        layout_plan: *const Layouts.LayoutPlan,
        procedure_builder: *ProcedureBuilder,
        result: *LirProgram.Result,
    ) Allocator.Error!ConstPlanBuilder {
        const by_rep = try allocator.alloc(?LirProgram.ConstPlanId, plan.representations.items.len);
        @memset(by_rep, null);
        return .{
            .allocator = allocator,
            .modules = modules,
            .plan = plan,
            .layout_plan = layout_plan,
            .procedure_builder = procedure_builder,
            .result = result,
            .by_rep = by_rep,
        };
    }

    fn deinit(self: *ConstPlanBuilder) void {
        self.allocator.free(self.by_rep);
        self.* = undefined;
    }

    fn constPlanForRep(self: *ConstPlanBuilder, rep_id: Plan.TypeRepId) Allocator.Error!LirProgram.ConstPlanId {
        const index = @intFromEnum(rep_id);
        if (self.by_rep[index]) |existing| return existing;

        const rep = self.plan.representations.items[index];
        switch (rep.kind) {
            .alias => {
                const child = try self.constPlanForChild(rep_id, .alias_backing);
                self.by_rep[index] = child;
                return child;
            },
            .in_progress, .dynamic, .primitive, .bool_tag_union, .erased_callable, .record, .record_unbound, .tuple, .nominal, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => {},
        }

        const id: LirProgram.ConstPlanId = @enumFromInt(@as(u32, @intCast(self.result.const_plans.items.len)));
        try self.result.const_plans.append(self.allocator, .pending);
        self.by_rep[index] = id;

        const built = try self.buildConstPlan(rep_id);
        self.result.const_plans.items[@intFromEnum(id)] = built;
        return id;
    }

    fn buildConstPlan(self: *ConstPlanBuilder, rep_id: Plan.TypeRepId) Allocator.Error!LirProgram.ConstPlan {
        const rep = self.plan.representations.items[@intFromEnum(rep_id)];
        return switch (rep.kind) {
            .in_progress => boxyLowerInvariant("in-progress boxy representation reached const plan output"),
            .dynamic => boxyLowerInvariant("dynamic boxy value reached const plan output before descriptor support"),
            .erased_callable => .{ .erased_fn = try self.erasedFnsForRep(rep_id) },
            .generated_field,
            .generated_field_names,
            .generated_tag_union_spec,
            => boxyLowerInvariant("compiler-owned encoding evidence reached const planning before generated codec restoration"),
            .primitive => |primitive| switch (primitive) {
                .str => .str,
                .bool, .u8, .i8, .u16, .i16, .u32, .i32, .u64, .i64, .u128, .i128, .f32, .f64, .dec, .u8x16, .i8x16, .u16x8, .i16x8, .u32x4, .i32x4, .u64x2, .i64x2 => .scalar,
            },
            .bool_tag_union => .{ .named = .{
                .named_type = .{
                    .module = moduleDigestFromId(rep.source_type.module),
                    .ty = rep.source_type.ty,
                },
                .backing = try self.appendLeafPlan(try self.boolTagUnionConstPlan(rep)),
            } },
            .empty_record,
            .empty_tag_union,
            => .zst,
            .alias => boxyLowerInvariant("alias representation was not redirected before const plan output"),
            .list => .{ .list = try self.constPlanForChild(rep_id, .list_elem) },
            .box => .{ .box = try self.constPlanForChild(rep_id, .box_payload) },
            .record,
            .record_unbound,
            => try self.structConstPlan(rep, .record_field, .record),
            .tuple => try self.structConstPlan(rep, .tuple_elem, .tuple),
            .tag_union => try self.tagUnionConstPlan(rep),
            .nominal => |kind| switch (kind) {
                .transparent, .builtin_other => .{ .named = .{
                    .named_type = .{
                        .module = moduleDigestFromId(rep.source_type.module),
                        .ty = rep.source_type.ty,
                    },
                    .backing = try self.constPlanForChild(rep_id, .nominal_backing),
                } },
                .opaque_nominal => boxyLowerInvariant("opaque nominal reached const plan output before opaque static-data support"),
            },
        };
    }

    fn appendLeafPlan(self: *ConstPlanBuilder, plan: LirProgram.ConstPlan) Allocator.Error!LirProgram.ConstPlanId {
        const id: LirProgram.ConstPlanId = @enumFromInt(@as(u32, @intCast(self.result.const_plans.items.len)));
        try self.result.const_plans.append(self.allocator, plan);
        return id;
    }

    fn boolTagUnionConstPlan(self: *ConstPlanBuilder, rep: Plan.TypeRepresentation) Allocator.Error!LirProgram.ConstPlan {
        const module = procedureModuleById(self.modules, rep.source_type.module);
        const nominal = resolvedNominalPayload(module, rep.source_type.ty);
        const backing = module.checked_types.nominalBackingTemplateForPayload(nominal) orelse
            boxyLowerInvariant("boxy const planning requested the backing of an opaque nominal type");
        const tag_union = switch (resolvedTypePayload(module, backing)) {
            .tag_union => |tag_union| tag_union,
            .pending, .err, .flex, .rigid, .alias, .record, .record_unbound, .tuple, .nominal, .function, .empty_record, .empty_tag_union => boxyLowerInvariant("Bool nominal backing was not a checked tag union"),
        };
        const variants = try self.allocator.alloc(LirProgram.ConstTagVariant, tag_union.tags.len);
        var initialized: usize = 0;
        errdefer {
            for (variants[0..initialized]) |variant| self.allocator.free(variant.name);
            self.allocator.free(variants);
        }
        for (tag_union.tags, variants) |tag, *variant| {
            if (tag.argsSlice(module.checked_types).len != 0) {
                boxyLowerInvariant("Bool checked tag carried a payload");
            }
            const name_text = module.canonical_names.tagLabelText(tag.name);
            const discriminant: u16 = if (std.mem.eql(u8, name_text, "False"))
                0
            else if (std.mem.eql(u8, name_text, "True"))
                1
            else
                boxyLowerInvariant("Bool checked tag union contained a non-boolean tag");
            variant.* = .{
                .name = try self.allocator.dupe(u8, name_text),
                .checked_name = tag.name,
                .discriminant = discriminant,
            };
            initialized += 1;
        }
        return .{ .tag_union = variants };
    }

    fn erasedFnsForRep(self: *ConstPlanBuilder, rep_id: Plan.TypeRepId) Allocator.Error!LirProgram.ErasedFnsId {
        var entries = std.ArrayList(LirProgram.ErasedFn).empty;
        errdefer {
            for (entries.items) |entry| {
                if (entry.captures.len != 0) self.allocator.free(entry.captures);
            }
            entries.deinit(self.allocator);
        }

        for (self.plan.static_fns.items) |static_fn| {
            if (static_fn.rep != rep_id) continue;
            const entry_proc = try self.procedure_builder.emitErasedWorker(static_fn.worker);
            var duplicate = false;
            for (entries.items) |entry| {
                if (entry.entry == entry_proc) {
                    duplicate = true;
                    break;
                }
            }
            if (duplicate) continue;

            const worker = self.plan.workers.items[@intFromEnum(static_fn.worker)];
            const worker_captures = self.plan.erasedCaptureSlice(worker.erased_captures);
            const store_module = procedureModuleById(self.modules, static_fn.store_module);
            const fn_value = store_module.const_store.getFn(static_fn.fn_id);

            var value_capture_count: usize = 0;
            for (worker_captures) |capture| {
                switch (capture.kind) {
                    .captured_value => value_capture_count += 1,
                    .hidden_desc, .hidden_dict => boxyLowerInvariant("static erased callable required hidden descriptor or dictionary captures"),
                }
            }
            if (value_capture_count != fn_value.captures.len) {
                boxyLowerInvariant("static erased callable capture plan disagreed with ConstStore captures");
            }

            const slots = try self.allocator.alloc(LirProgram.CaptureSlot, value_capture_count);
            var slots_owned = true;
            errdefer if (slots_owned) self.allocator.free(slots);
            var slot_count: usize = 0;
            for (worker_captures, 0..) |capture, field_index| {
                if (capture.kind != .captured_value) continue;
                const capture_id = capture.capture_id orelse
                    boxyLowerInvariant("static erased callable value capture had no checked capture id");
                var stored_capture: ?check.ConstStore.ConstCapture = null;
                for (fn_value.captures) |candidate| {
                    if (std.meta.eql(candidate.id, capture_id)) {
                        stored_capture = candidate;
                        break;
                    }
                }
                const source_capture = stored_capture orelse
                    boxyLowerInvariant("static erased callable capture was absent from ConstStore function");
                slots[slot_count] = .{
                    .id = source_capture.id,
                    .slot = @intCast(field_index),
                    .ty = source_capture.ty,
                    .plan = try self.constPlanForRep(capture.rep),
                    .storage = .value,
                };
                slot_count += 1;
            }

            try entries.append(self.allocator, .{
                .entry = entry_proc,
                .capture_layout = self.layout_plan.workerLayoutFor(static_fn.worker).erased_capture_layout,
                .template = .{
                    .fn_def = fn_value.fn_def,
                    .source_fn_ty = fn_value.source_fn_ty,
                    .source_fn_key = fn_value.source_fn_key,
                },
                .captures = slots,
            });
            slots_owned = false;
        }
        if (entries.items.len == 0) {
            boxyLowerInvariant("erased callable const plan had no explicitly planned static function entries");
        }

        const owned_entries = try entries.toOwnedSlice(self.allocator);
        const id: LirProgram.ErasedFnsId = @enumFromInt(@as(u32, @intCast(self.result.erased_fns.items.len)));
        try self.result.erased_fns.append(self.allocator, .{
            .layout = self.layout_plan.rep_layouts[@intFromEnum(rep_id)].host.layoutIdx(),
            .entries = owned_entries,
        });
        return id;
    }

    fn constPlanForChild(self: *ConstPlanBuilder, rep_id: Plan.TypeRepId, role: Plan.ChildRole) Allocator.Error!LirProgram.ConstPlanId {
        return try self.constPlanForRep(self.repQuery().requiredSingleChild(rep_id, role).rep);
    }

    const StructPlanKind = enum {
        tuple,
        record,
    };

    fn structConstPlan(
        self: *ConstPlanBuilder,
        rep: Plan.TypeRepresentation,
        comptime role_tag: std.meta.Tag(Plan.ChildRole),
        comptime kind: StructPlanKind,
    ) Allocator.Error!LirProgram.ConstPlan {
        var count: usize = 0;
        for (self.plan.childSlice(rep.children)) |child| {
            if (std.meta.activeTag(child.role) == role_tag) count += 1;
        }

        const plans = try self.allocator.alloc(LirProgram.ConstPlanId, count);
        errdefer self.allocator.free(plans);
        var cursor: usize = 0;
        for (self.plan.childSlice(rep.children)) |child| {
            if (std.meta.activeTag(child.role) == role_tag) {
                plans[cursor] = try self.constPlanForRep(child.rep);
                cursor += 1;
            }
        }

        return switch (kind) {
            .tuple => .{ .tuple = plans },
            .record => .{ .record = plans },
        };
    }

    fn tagUnionConstPlan(self: *ConstPlanBuilder, rep: Plan.TypeRepresentation) Allocator.Error!LirProgram.ConstPlan {
        const tag_variants = self.plan.tagVariantSlice(rep.tag_variants);

        const variants = try self.allocator.alloc(LirProgram.ConstTagVariant, tag_variants.len);
        var initialized: usize = 0;
        errdefer {
            for (variants[0..initialized]) |variant| {
                self.allocator.free(variant.name);
                self.allocator.free(variant.payloads);
            }
            self.allocator.free(variants);
        }

        for (tag_variants, variants, 0..) |tag_variant, *variant, discriminant| {
            variant.* = try self.buildTagVariant(tag_variant, discriminant);
            initialized += 1;
        }

        return .{ .tag_union = variants };
    }

    fn buildTagVariant(
        self: *ConstPlanBuilder,
        variant: Plan.TagVariant,
        discriminant: usize,
    ) Allocator.Error!LirProgram.ConstTagVariant {
        const root_names = &self.modules.root.module.canonical_names;
        const name = try self.allocator.dupe(u8, root_names.tagLabelText(variant.name));
        errdefer self.allocator.free(name);

        const payload_children = self.plan.childSlice(variant.payloads);
        const payloads = try self.allocator.alloc(LirProgram.ConstPlanId, payload_children.len);
        errdefer self.allocator.free(payloads);
        for (payload_children, payloads, 0..) |child, *payload_plan, index| {
            switch (child.role) {
                .tag_payload => |payload| {
                    if (payload.tag != variant.name or payload.index != index) {
                        boxyLowerInvariant("tag variant payload span did not match its payload child roles");
                    }
                },
                .alias_backing, .alias_arg, .nominal_backing, .nominal_arg, .nominal_padding_field, .record_field, .record_ext, .tuple_elem, .function_arg, .function_ret, .tag_ext, .list_elem, .box_payload => boxyLowerInvariant("tag variant payload span included a non-payload child"),
            }
            payload_plan.* = try self.constPlanForRep(child.rep);
        }

        return .{
            .name = name,
            .checked_name = variant.name,
            .discriminant = @intCast(discriminant),
            .payloads = payloads,
        };
    }
};

fn planTypeRefEql(a: Plan.CheckedTypeIdentity, b: Plan.CheckedTypeIdentity) bool {
    return a.ty == b.ty and checked_moduleKeyEqual(a.module, b.module);
}

fn planExprRefEql(a: Plan.CheckedExprIdentity, b: Plan.CheckedExprIdentity) bool {
    return a.expr == b.expr and checked_moduleKeyEqual(a.module, b.module);
}

fn optionalPlanTypeRefEql(a: ?Plan.CheckedTypeIdentity, b: ?Plan.CheckedTypeIdentity) bool {
    if (a) |a_value| return if (b) |b_value| planTypeRefEql(a_value, b_value) else false;
    return b == null;
}

fn generatedParserScalarMethodForRep(plan: *const Plan.ProgramPlan, rep_id: Plan.TypeRepId) ?[]const u8 {
    const rep = plan.representations.items[@intFromEnum(rep_id)];
    return switch (rep.kind) {
        .alias => generatedParserScalarMethodForRep(
            plan,
            requiredPlanChild(plan, rep_id, .alias_backing).rep,
        ),
        .primitive => |primitive| switch (primitive) {
            .str => "parse_str",
            .u8 => "parse_u8",
            .i8 => "parse_i8",
            .u16 => "parse_u16",
            .i16 => "parse_i16",
            .u32 => "parse_u32",
            .i32 => "parse_i32",
            .u64 => "parse_u64",
            .i64 => "parse_i64",
            .u128 => "parse_u128",
            .i128 => "parse_i128",
            .dec => "parse_dec",
            .f32 => "parse_f32",
            .f64 => "parse_f64",
            .bool => "parse_bool",
            .u8x16,
            .i8x16,
            .u16x8,
            .i16x8,
            .u32x4,
            .i32x4,
            .u64x2,
            .i64x2,
            => null,
        },
        .bool_tag_union => "parse_bool",
        .in_progress, .dynamic, .erased_callable, .record, .record_unbound, .tuple, .nominal, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => null,
    };
}

fn generatedEncoderScalarMethodForRep(plan: *const Plan.ProgramPlan, rep_id: Plan.TypeRepId) ?[]const u8 {
    const rep = plan.representations.items[@intFromEnum(rep_id)];
    return switch (rep.kind) {
        .alias => generatedEncoderScalarMethodForRep(
            plan,
            requiredPlanChild(plan, rep_id, .alias_backing).rep,
        ),
        .primitive => |primitive| switch (primitive) {
            .str => "encode_str",
            .u8 => "encode_u8",
            .i8 => "encode_i8",
            .u16 => "encode_u16",
            .i16 => "encode_i16",
            .u32 => "encode_u32",
            .i32 => "encode_i32",
            .u64 => "encode_u64",
            .i64 => "encode_i64",
            .u128 => "encode_u128",
            .i128 => "encode_i128",
            .dec => "encode_dec",
            .f32 => "encode_f32",
            .f64 => "encode_f64",
            .bool => "encode_bool",
            .u8x16,
            .i8x16,
            .u16x8,
            .i16x8,
            .u32x4,
            .i32x4,
            .u64x2,
            .i64x2,
            => null,
        },
        .bool_tag_union => "encode_bool",
        .in_progress, .dynamic, .erased_callable, .record, .record_unbound, .tuple, .nominal, .list, .box, .generated_field, .generated_field_names, .generated_tag_union_spec, .empty_record, .tag_union, .empty_tag_union => null,
    };
}

fn requiredPlanChild(
    plan: *const Plan.ProgramPlan,
    rep_id: Plan.TypeRepId,
    role: Plan.ChildRole,
) Plan.RepChild {
    const rep = plan.representations.items[@intFromEnum(rep_id)];
    for (plan.childSlice(rep.children)) |child| {
        if (Plan.sameChildRoleKind(child.role, role)) return child;
    }
    boxyLowerInvariant("generated codec representation was missing a required child");
}

fn hiddenDescriptorParamContains(
    params: []const Plan.HiddenDescriptorParam,
    desc: Plan.DescriptorRequirementId,
) bool {
    for (params) |param| {
        if (param.desc == desc) return true;
    }
    return false;
}

fn hiddenDescriptorParamIndex(
    params: []const Plan.HiddenDescriptorParam,
    desc: Plan.DescriptorRequirementId,
) ?u32 {
    for (params, 0..) |param, index| {
        if (param.desc == desc) return @intCast(index);
    }
    return null;
}

fn layoutIsList(value: layout.Layout) bool {
    return value.tag == .list or value.tag == .list_of_zst;
}

fn appendUniqueLocal(allocator: Allocator, list: *std.ArrayList(LIR.LocalId), local: LIR.LocalId) Allocator.Error!void {
    for (list.items) |existing| {
        if (existing == local) return;
    }
    try list.append(allocator, local);
}

fn moduleDigestFromId(key: checked.ModuleId) names.CheckedModuleDigest {
    return .{ .bytes = key.bytes };
}

fn lirSymbol(symbol: Common.Symbol) LIR.Symbol {
    return LIR.Symbol.fromRaw(@intCast(@intFromEnum(symbol)));
}

fn boxyLowerInvariant(comptime message: []const u8) noreturn {
    if (comptime zig_builtin.mode == .Debug and zig_builtin.target.os.tag == .freestanding) {
        @panic("boxy lower invariant violated: " ++ message);
    } else if (comptime zig_builtin.mode == .Debug) {
        std.debug.panic("boxy lower invariant violated: {s}", .{message});
    }
    unreachable;
}

test "boxy call adapters distinguish static templates from runtime descriptors" {
    const static_id: LIR.BoxyTypeDescId = @enumFromInt(fixtureTableIndex(0));
    try std.testing.expectEqual(
        ProcBodyBuilder.DescriptorMaterialization{ .desc = .{ .static = static_id } },
        ProcBodyBuilder.resultDescriptorTemplate(.{ .desc = .{ .static = static_id } }).?,
    );
    try std.testing.expect(ProcBodyBuilder.resultDescriptorTemplate(.{
        .desc = .{ .local = @enumFromInt(fixtureTableIndex(0)) },
        .template = .{ .desc = .{ .runtime = 0 } },
    }) == null);
}

test "descriptor materialization captures close over recursive template graphs" {
    const gpa = std.testing.allocator;
    var result = try LirProgram.Result.init(gpa, .native);
    defer result.deinit();

    const captured = try result.store.addLocal(.{ .layout_idx = .opaque_ptr });
    const target = try result.store.addLocal(.{ .layout_idx = .opaque_ptr });
    try result.boxy_desc_refs.appendSlice(gpa, &.{
        .{ .static = @enumFromInt(1) },
        .{ .static = @enumFromInt(fixtureTableIndex(0)) },
        .{ .local = captured },
    });
    try result.boxy_type_descs.appendSlice(gpa, &.{
        .{
            .payload_layout = .opaque_ptr,
            .contains_refcounted = false,
            .nested_descs = .{ .start = 0, .len = 1 },
        },
        .{
            .payload_layout = .opaque_ptr,
            .contains_refcounted = false,
            .nested_descs = .{ .start = 1, .len = 2 },
        },
    });

    const ret = try result.store.addCFStmt(.{ .ret = .{ .value = target } });
    const materialize = try result.store.addCFStmt(.{ .assign_boxy_desc_ref = .{
        .target = target,
        .desc = .{ .static = @enumFromInt(fixtureTableIndex(0)) },
        .next = ret,
    } });
    _ = try result.store.addProcSpec(.{
        .name = LIR.Symbol.fromRaw(0),
        .args = LIR.LocalSpan.empty(),
        .frame_locals = try result.store.addLocalSpan(&.{ captured, target }),
        .body = materialize,
        .ret_layout = .opaque_ptr,
    });

    var builder = ProcedureBuilder.init(gpa, undefined, undefined, undefined, undefined, &result, .{});
    try builder.finalizeDescriptorMaterializationCaptures();

    const assign = result.store.getCFStmt(materialize).assign_boxy_desc_ref;
    const captures = result.store.getLocalSpan(assign.captures);
    try std.testing.expectEqual(@as(usize, 1), GuardedList.borrowLen(captures));
    try std.testing.expectEqual(captured, GuardedList.at(captures, 0));
}

test "boxy lowerer returns an empty LIR program for an empty plan" {
    const gpa = std.testing.allocator;

    var plan = Plan.ProgramPlan.init(gpa);
    defer plan.deinit();

    var out = try run(gpa, .{ .root = undefined }, .{}, &plan, .{});
    defer out.deinit();

    try std.testing.expectEqual(@as(usize, 0), out.lir_result.store.procSpecCount());
    try std.testing.expectEqual(@as(usize, 0), out.lir_result.root_procs.items.len);
}

fn expectResolvedWorkerCheckedExpr(
    worker: ResolvedWorker,
    expected_body: ?checked.CheckedBodyId,
    expected_root: checked.CheckedExprId,
) error{ TestExpectedEqual, TestUnexpectedResult }!void {
    const body = switch (worker.body) {
        .checked_expr => |checked_body| checked_body,
        .intrinsic, .hosted, .unimplemented, .generated_codec, .generated_field_iterator, .generated_interpolation_step => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(expected_body, body.body_id);
    try std.testing.expectEqual(expected_root, body.root_expr);
}

test "boxy lowerer resolves procedure-template workers to checked bodies" {
    const gpa = std.testing.allocator;

    var checked_module = minimalCheckedArtifact(gpa);
    defer checked_module.canonical_names.deinit();
    defer checked_module.checked_types.deinit(gpa);
    defer checked_module.checked_bodies.deinit(gpa);

    const template_ref = procedureTemplateRef(checked_module.key, 0);
    try checked_module.checked_bodies.bodies.append(gpa, .{
        .id = @enumFromInt(fixtureTableIndex(0)),
        .root_expr = @enumFromInt(3),
        .owner_template = template_ref,
    });
    var templates = [_]checked.CheckedProcedureTemplate{
        checkedTemplate(template_ref, @enumFromInt(9), @enumFromInt(fixtureTableIndex(0))),
    };
    checked_module.checked_procedure_templates = .{ .templates = &templates };

    var plan = Plan.ProgramPlan.init(gpa);
    defer plan.deinit();
    try plan.workers.append(gpa, .{
        .id = @enumFromInt(fixtureTableIndex(0)),
        .root_request = dummyRootRequest(),
        .source = .{ .procedure_template = template_ref },
        .checked_type = .{ .ty = @enumFromInt(9) },
        .rep = @enumFromInt(fixtureTableIndex(0)),
    });

    var resolved = try ResolvedWorkers.init(gpa, .{ .root = .{ .module = &checked_module, .roots = undefined } }, &plan);
    defer resolved.deinit();

    try std.testing.expectEqual(@as(usize, 1), resolved.items.len);
    try std.testing.expectEqual(@as(Plan.WorkerPlanId, @enumFromInt(fixtureTableIndex(0))), resolved.items[0].worker);
    try std.testing.expect(names.procedureTemplateRefEql(
        template_ref,
        resolved.items[0].template_ref orelse return error.TestUnexpectedResult,
    ));
    try expectResolvedWorkerCheckedExpr(resolved.items[0], @enumFromInt(fixtureTableIndex(0)), @enumFromInt(3));
}

test "boxy lowerer resolves top-level direct bindings to checked bodies" {
    const gpa = std.testing.allocator;

    var checked_module = minimalCheckedArtifact(gpa);
    defer checked_module.canonical_names.deinit();
    defer checked_module.checked_types.deinit(gpa);
    defer checked_module.checked_bodies.deinit(gpa);

    const template_ref = procedureTemplateRef(checked_module.key, 0);
    try checked_module.checked_bodies.bodies.append(gpa, .{
        .id = @enumFromInt(fixtureTableIndex(0)),
        .root_expr = @enumFromInt(5),
        .owner_template = template_ref,
    });
    var templates = [_]checked.CheckedProcedureTemplate{
        checkedTemplate(template_ref, @enumFromInt(7), @enumFromInt(fixtureTableIndex(0))),
    };
    checked_module.checked_procedure_templates = .{ .templates = &templates };

    var bindings = [_]checked.TopLevelProcedureBinding{
        .{
            .source_scheme = typeSchemeKey(1),
            .body = .{ .direct_template = .{
                .proc_value = procedureValueRef(template_ref),
                .template = .{ .checked = template_ref },
            } },
        },
    };
    checked_module.top_level_procedure_bindings = .{ .bindings = &bindings };

    var plan = Plan.ProgramPlan.init(gpa);
    defer plan.deinit();
    try plan.workers.append(gpa, .{
        .id = @enumFromInt(fixtureTableIndex(0)),
        .root_request = dummyRootRequest(),
        .source = .{ .procedure_binding = .{ .artifact = checked_module.key, .binding = @enumFromInt(fixtureTableIndex(0)) } },
