    try checked_module.checked_bodies.stored_exprs.append(gpa, .{
        .id = @enumFromInt(1),
        .ty = @enumFromInt(fixtureTableIndex(0)),
        .source_region = base.Region.zero(),
        .data = .{ .structural_hash = .{
            .value = @enumFromInt(2),
            .hasher = @enumFromInt(3),
        } },
    });
    try checked_module.checked_bodies.stored_exprs.append(gpa, .{
        .id = @enumFromInt(2),
        .ty = @enumFromInt(fixtureTableIndex(0)),
        .source_region = base.Region.zero(),
        .data = .{ .numeral = .{ .literal = try testIntNumeral(5), .plan = null } },
    });
    try checked_module.checked_bodies.stored_exprs.append(gpa, .{
        .id = @enumFromInt(3),
        .ty = @enumFromInt(fixtureTableIndex(0)),
        .source_region = base.Region.zero(),
        .data = .{ .numeral = .{ .literal = try testIntNumeral(99), .plan = null } },
    });
    try checked_module.checked_bodies.bodies.append(gpa, .{
        .id = @enumFromInt(fixtureTableIndex(0)),
        .root_expr = @enumFromInt(fixtureTableIndex(0)),
        .owner_template = template_ref,
    });
    var templates = [_]checked.CheckedProcedureTemplate{
        checkedTemplate(template_ref, @enumFromInt(1), @enumFromInt(fixtureTableIndex(0))),
    };
    checked_module.checked_procedure_templates = .{ .templates = &templates };

    const root = checked.RootRequest{
        .order = 0,
        .module_idx = 0,
        .kind = .runtime_entrypoint,
        .source = .{ .def = @enumFromInt(fixtureTableIndex(0)) },
        .checked_type = @enumFromInt(1),
        .abi = .roc,
        .exposure = .private,
        .procedure_template = template_ref,
    };
    var plan = try Plan.analyzeProgram(gpa, .{
        .root_module = .{ .module = &checked_module, .roots = undefined },
        .roots = &.{root},
    }, .{});
    defer plan.deinit();

    var out = try run(
        gpa,
        .{ .root = .{ .module = &checked_module, .roots = undefined } },
        .{},
        &plan,
        .{},
    );
    defer out.deinit();

    const proc = out.lir_result.store.getProcSpec(out.lir_result.root_procs.items[0]);
    const value = out.lir_result.store.getCFStmt(proc.body orelse return error.TestUnexpectedResult).assign_literal;
    switch (value.value) {
        .i128_literal => |literal| try std.testing.expectEqual(@as(i128, 5), literal.value),
        .i64_literal, .f64_literal, .f32_literal, .dec_literal, .str_literal, .boxy_dynamic_num_literal, .boxy_dynamic_frac_literal, .static_data, .bytes_literal, .null_ptr, .proc_ref => return error.TestUnexpectedResult,
    }
    const seed = out.lir_result.store.getCFStmt(value.next).assign_literal;
    switch (seed.value) {
        .i128_literal => |literal| try std.testing.expectEqual(@as(i128, 99), literal.value),
        .i64_literal, .f64_literal, .f32_literal, .dec_literal, .str_literal, .boxy_dynamic_num_literal, .boxy_dynamic_frac_literal, .static_data, .bytes_literal, .null_ptr, .proc_ref => return error.TestUnexpectedResult,
    }
    const hash = out.lir_result.store.getCFStmt(seed.next).assign_low_level;
    try std.testing.expectEqual(@as(LIR.LowLevel, .hasher_write_u64), hash.op);
    const args = out.lir_result.store.getLocalSpan(hash.args);
    try std.testing.expectEqual(@as(usize, 2), args.len);
    try std.testing.expectEqual(seed.target, GuardedList.at(args, 0));
    try std.testing.expectEqual(value.target, GuardedList.at(args, 1));
    try std.testing.expectEqual(LIR.CFStmt{ .ret = .{ .value = hash.target } }, out.lir_result.store.getCFStmt(hash.next));
}

