    try std.testing.expectEqual(@as(u16, 0), final_read.op.field.field_idx);
    try std.testing.expectEqual(LIR.CFStmt{ .ret = .{ .value = final_read.target } }, out.lir_result.store.getCFStmt(final_read.next));
