    defer out.deinit();

    try std.testing.expectEqual(@as(usize, 1), out.lir_result.root_procs.items.len);
    try std.testing.expectEqual(@as(usize, 2), out.lir_result.store.procSpecCount());
    const wrapper_id = out.lir_result.root_procs.items[0];
