fn testIntNumeral(value: u128) Allocator.Error!can.ModuleEnv.NumeralLiteral {
    return recordTestNumeral(value, 0, 0, false, false);
}

fn testSmallDecNumeral(value: can.CIR.SmallDecValue) Allocator.Error!can.ModuleEnv.NumeralLiteral {
    var divisor: u128 = 1;
    for (0..value.denominator_power_of_ten) |_| divisor *= 10;

    const magnitude: u128 = @intCast(if (value.numerator < 0) -@as(i32, value.numerator) else value.numerator);
    return recordTestNumeral(
        magnitude / divisor,
        magnitude % divisor,
        value.denominator_power_of_ten,
        value.numerator < 0,
        true,
    );
}

fn recordTestNumeral(
    before: u128,
    after: u128,
    scale: u8,
    is_negative: bool,
    is_fractional: bool,
) Allocator.Error!can.ModuleEnv.NumeralLiteral {
    var before_buffer: [16]u8 = undefined;
    var after_buffer: [16]u8 = undefined;
    const before_digits = base256Digits(before, &before_buffer);
    const after_digits = if (scale == 0) &.{} else base256Digits(after, &after_buffer);
    const env = testEmptyModuleEnv();
    const node = @as(can.CIR.Node.Idx, @enumFromInt(fixtureTableIndex(0)));
    try env.recordNumeralLiteral(
        node,
        before_digits,
        after_digits,
        scale,
        is_negative,
        is_fractional,
        is_fractional,
        true,
    );
    return env.numeralLiteralForNode(node) orelse unreachable;
}

fn base256Digits(value: u128, buffer: *[16]u8) []const u8 {
    var remaining = value;
    var len: usize = 0;
    while (true) {
        buffer.*[buffer.len - 1 - len] = @truncate(remaining);
        len += 1;
        remaining >>= 8;
        if (remaining == 0) return buffer.*[buffer.len - len ..];
    }
}

const ListMapCanReuseTransformRet = enum {
    u64,
    u8,
    distinct_dynamic,
};

fn lowerListMapCanReuseFixture(
    allocator: Allocator,
    transform_ret: ListMapCanReuseTransformRet,
    options: Options,
) Allocator.Error!Output {
    var checked_module = minimalCheckedArtifact(allocator);
    defer checked_module.canonical_names.deinit();
    defer checked_module.checked_types.deinit(allocator);
    defer checked_module.checked_bodies.deinit(allocator);

    const transform_ret_ty: checked.CheckedTypeId = switch (transform_ret) {
        .u64 => @enumFromInt(fixtureTableIndex(0)),
        .u8, .distinct_dynamic => @enumFromInt(1),
    };

    try checked_module.checked_types.type_id_pool.appendSlice(allocator, &.{
        @as(checked.CheckedTypeId, @enumFromInt(fixtureTableIndex(0))), // List(U64) element.
        @as(checked.CheckedTypeId, @enumFromInt(fixtureTableIndex(0))), // Transform argument.
        @as(checked.CheckedTypeId, @enumFromInt(2)), // Root list argument.
        @as(checked.CheckedTypeId, @enumFromInt(3)), // Root transform argument.
    });
    if (transform_ret == .distinct_dynamic) {
        try checked_module.checked_types.payloads.append(allocator, .{ .flex = .{} });
        try checked_module.checked_types.payloads.append(allocator, .{ .flex = .{} });
    } else {
        try checked_module.checked_types.payloads.append(allocator, .{
            .nominal = builtinNominal(.u64, @enumFromInt(fixtureTableIndex(0)), .{}),
        });
        try checked_module.checked_types.payloads.append(allocator, .{
            .nominal = builtinNominal(.u8, @enumFromInt(1), .{}),
        });
    }
    try checked_module.checked_types.payloads.append(allocator, .{
        .nominal = builtinNominal(.list, @enumFromInt(2), .{ .start = 0, .len = 1 }),
    });
    try checked_module.checked_types.payloads.append(allocator, .{
        .function = .{
            .kind = .pure,
            .args = .{ .start = 1, .len = 1 },
            .ret = transform_ret_ty,
        },
    });
    try checked_module.checked_types.payloads.append(allocator, .{
        .function = .{
            .kind = .pure,
            .args = .{ .start = 2, .len = 2 },
            .ret = @enumFromInt(1),
        },
    });

    try checked_module.checked_bodies.pattern_binders.append(allocator, .{
        .id = @enumFromInt(fixtureTableIndex(0)),
        .pattern = @enumFromInt(fixtureTableIndex(0)),
        .reassignable = false,
    });
    try checked_module.checked_bodies.pattern_binders.append(allocator, .{
        .id = @enumFromInt(1),
        .pattern = @enumFromInt(1),
        .reassignable = false,
    });
    try checked_module.checked_bodies.pattern_binder_by_pattern.appendSlice(allocator, &.{
        @as(?checked.PatternBinderId, @enumFromInt(fixtureTableIndex(0))),
        @as(?checked.PatternBinderId, @enumFromInt(1)),
    });
    try checked_module.checked_bodies.pattern_id_pool.appendSlice(allocator, &.{
        @as(checked.CheckedPatternId, @enumFromInt(fixtureTableIndex(0))),
        @as(checked.CheckedPatternId, @enumFromInt(1)),
    });
    try checked_module.checked_bodies.stored_patterns.append(allocator, .{
        .id = @enumFromInt(fixtureTableIndex(0)),
        .ty = @enumFromInt(2),
        .source_region = base.Region.zero(),
        .data = .{ .assign = @enumFromInt(fixtureTableIndex(0)) },
    });
    try checked_module.checked_bodies.stored_patterns.append(allocator, .{
        .id = @enumFromInt(1),
        .ty = @enumFromInt(3),
        .source_region = base.Region.zero(),
        .data = .{ .assign = @enumFromInt(1) },
    });

    try checked_module.checked_bodies.expr_id_pool.appendSlice(allocator, &.{
        @as(checked.CheckedExprId, @enumFromInt(2)),
        @as(checked.CheckedExprId, @enumFromInt(3)),
    });

    const template_ref = procedureTemplateRef(checked_module.key, 0);
    try checked_module.checked_bodies.stored_exprs.append(allocator, .{
        .id = @enumFromInt(fixtureTableIndex(0)),
        .ty = @enumFromInt(4),
        .source_region = base.Region.zero(),
        .data = .{ .lambda = .{ .args = .{ .start = 0, .len = 2 }, .body = @enumFromInt(1) } },
    });
    try checked_module.checked_bodies.stored_exprs.append(allocator, .{
        .id = @enumFromInt(1),
        .ty = @enumFromInt(1),
        .source_region = base.Region.zero(),
        .data = .{ .run_low_level = .{
            .op = .list_map_can_reuse,
            .args = .{ .start = 0, .len = 2 },
        } },
    });
    try checked_module.checked_bodies.stored_exprs.append(allocator, .{
        .id = @enumFromInt(2),
        .ty = @enumFromInt(2),
        .source_region = base.Region.zero(),
        .data = .{ .lookup_local = .{ .pattern = @enumFromInt(fixtureTableIndex(0)), .resolved = null } },
    });
    try checked_module.checked_bodies.stored_exprs.append(allocator, .{
        .id = @enumFromInt(3),
        .ty = @enumFromInt(3),
        .source_region = base.Region.zero(),
        .data = .{ .lookup_local = .{ .pattern = @enumFromInt(1), .resolved = null } },
    });
    try checked_module.checked_bodies.bodies.append(allocator, .{
        .id = @enumFromInt(fixtureTableIndex(0)),
        .root_expr = @enumFromInt(fixtureTableIndex(0)),
        .owner_template = template_ref,
    });
    var templates = [_]checked.CheckedProcedureTemplate{
        checkedTemplate(template_ref, @enumFromInt(4), @enumFromInt(fixtureTableIndex(0))),
    };
    checked_module.checked_procedure_templates = .{ .templates = &templates };

    const root = checked.RootRequest{
        .order = 0,
        .module_idx = 0,
        .kind = .runtime_entrypoint,
        .source = .{ .def = @enumFromInt(fixtureTableIndex(0)) },
        .checked_type = @enumFromInt(4),
        .abi = .roc,
        .exposure = .private,
        .procedure_template = template_ref,
    };
    var plan = try Plan.analyzeProgram(allocator, .{
        .root_module = .{ .module = &checked_module, .roots = undefined },
        .roots = &.{root},
    }, .{});
    defer plan.deinit();

    return try run(
        allocator,
        .{ .root = .{ .module = &checked_module, .roots = undefined } },
        .{},
        &plan,
        options,
    );
}

fn expectListMapCanReuseFalse(out: *Output) error{ TestExpectedEqual, TestUnexpectedResult }!void {
    const proc = out.lir_result.store.getProcSpec(out.lir_result.root_procs.items[0]);
    const body = skipLeadingDescriptorInitializers(
        &out.lir_result.store,
        proc.body orelse return error.TestUnexpectedResult,
    );
    const literal = out.lir_result.store.getCFStmt(body).assign_literal;
    switch (literal.value) {
        .i64_literal => |value| {
            try std.testing.expectEqual(@as(i64, 0), value.value);
            try std.testing.expectEqual(out.lir_result.store.getLocal(literal.target).layout_idx, value.layout_idx);
        },
        .i128_literal, .f64_literal, .f32_literal, .dec_literal, .str_literal, .boxy_dynamic_num_literal, .boxy_dynamic_frac_literal, .static_data, .bytes_literal, .null_ptr, .proc_ref => return error.TestUnexpectedResult,
    }
    try std.testing.expectEqual(LIR.CFStmt{ .ret = .{ .value = literal.target } }, out.lir_result.store.getCFStmt(literal.next));
}

fn skipLeadingDescriptorInitializers(store: *const LirStore, start: LIR.CFStmtId) LIR.CFStmtId {
    var cursor = start;
    while (true) {
        cursor = switch (store.getCFStmt(cursor)) {
            .assign_boxy_desc_ref => |assign| assign.next,
            .init_uninitialized, .assign_ref, .assign_literal, .assign_call, .assign_call_erased, .assign_packed_erased_fn, .assign_boxy_dict_ref, .assign_boxy_box, .assign_boxy_reuse_box, .assign_boxy_unbox, .assign_boxy_adapt, .assign_boxy_inspect, .assign_boxy_eq, .assign_boxy_tag, .assign_boxy_tag_payload, .boxy_tag_match, .assign_call_dict, .assign_low_level, .assign_list, .assign_struct, .assign_tag, .store_struct, .store_tag, .set_local, .debug, .expect, .expect_err, .runtime_error, .comptime_exhaustiveness_failed, .comptime_branch_taken, .incref, .decref, .decref_if_initialized, .free, .switch_stmt, .switch_initialized_payload, .str_match, .str_match_set, .loop_continue, .loop_break, .join, .jump, .ret, .crash => return cursor,
        };
    }
}

fn procedureTemplateRef(key: checked.CheckedModuleArtifactKey, raw_template_id: u32) names.ProcedureTemplateRef {
    return .{
        .artifact = .{ .bytes = key.bytes },
        .proc_base = @enumFromInt(raw_template_id),
        .template = @enumFromInt(raw_template_id),
    };
}

fn namedProcedureTemplateRef(
    checked_module: *checked.CheckedModuleArtifact,
    raw_template_id: u32,
    proc_name: []const u8,
) Allocator.Error!names.ProcedureTemplateRef {
    const module_name = try checked_module.canonical_names.internModuleName("Test");
    const export_name = try checked_module.canonical_names.internExportName(proc_name);
    const proc_base = try checked_module.canonical_names.internProcBase(.{
        .module_name = module_name,
        .export_name = export_name,
        .kind = .checked_source,
        .ordinal = raw_template_id,
        .source_def_idx = raw_template_id,
    });
    return .{
        .artifact = .{ .bytes = checked_module.key.bytes },
        .proc_base = proc_base,
        .template = @enumFromInt(raw_template_id),
    };
}

fn procedureValueRef(template: names.ProcedureTemplateRef) names.ProcedureValueRef {
    return .{
        .artifact = template.artifact,
        .proc_base = template.proc_base,
