        .static_dispatch_plans = .{},
        .direct_dispatch_plans = .{},
        .dispatch_relations = .{},
        .resolved_value_refs = .{},
        .top_level_value_uses = .{},
        .nested_proc_sites = .{},
        .target = .roc,
    };
}

